window.CONTENT={"books":[{"bookId":"hlm","title":"红楼梦","author":"曹雪芹","dynasty":"清","version":"通行整理电子本（原始数据未标注具体底本版本）","source":"luoxuhai/chinese-novel（GitHub，MIT License）","chapters":[{"chapterId":"hlm-03","number":3,"title":"贾雨村夤缘复旧职　林黛玉抛父进京都"},{"chapterId":"hlm-23","number":23,"title":"西厢记妙词通戏语　牡丹亭艳曲警芳心"},{"chapterId":"hlm-27","number":27,"title":"滴翠亭杨妃戏彩蝶　埋香冢飞燕泣残红"},{"chapterId":"hlm-32","number":32,"title":"诉肺腑心迷活宝玉　含耻辱情烈死金钏"}]},{"bookId":"xyj","title":"西游记","author":"吴承恩","dynasty":"明","version":"通行整理电子本（原始数据未标注具体底本版本）","source":"luoxuhai/chinese-novel（GitHub，MIT License）","chapters":[{"chapterId":"xyj-01","number":1,"title":"灵根育孕源流出　心性修持大道生"},{"chapterId":"xyj-14","number":14,"title":"心猿归正　六贼无踪"},{"chapterId":"xyj-27","number":27,"title":"尸魔三戏唐三藏　圣僧恨逐美猴王"}]},{"bookId":"jstl","title":"警世通言","author":"冯梦龙","dynasty":"明","version":"通行整理电子本（原始数据未标注具体底本版本）","source":"luoxuhai/chinese-novel（GitHub，MIT License）","chapters":[{"chapterId":"jstl-01","number":1,"title":"俞伯牙摔琴谢知音"},{"chapterId":"jstl-28","number":28,"title":"白娘子永镇雷峰塔"},{"chapterId":"jstl-32","number":32,"title":"杜十娘怒沉百宝箱"}]},{"bookId":"ysmy","title":"喻世明言","author":"冯梦龙","dynasty":"明","version":"通行整理电子本（原始数据未标注具体底本版本）","source":"luoxuhai/chinese-novel（GitHub，MIT License）","chapters":[{"chapterId":"ysmy-01","number":1,"title":"蒋兴哥重会珍珠衫"},{"chapterId":"ysmy-16","number":16,"title":"范巨卿鸡黍死生交"}]},{"bookId":"xsh","title":"醒世恒言","author":"冯梦龙","dynasty":"明","version":"通行整理电子本（原始数据未标注具体底本版本）","source":"luoxuhai/chinese-novel（GitHub，MIT License）","chapters":[{"chapterId":"xsh-03","number":3,"title":"卖油郎独占花魁"},{"chapterId":"xsh-11","number":11,"title":"苏小妹三难新郎"},{"chapterId":"xsh-18","number":18,"title":"施润泽滩阙遇友"}]},{"bookId":"liao","title":"聊斋志异","author":"蒲松龄","dynasty":"清","version":"通行整理电子本（原始数据未标注具体底本版本）","source":"luoxuhai/chinese-novel（GitHub，MIT License）","chapters":[{"chapterId":"liao-15","number":15,"title":"劳山道士"},{"chapterId":"liao-48","number":48,"title":"婴宁"},{"chapterId":"liao-49","number":49,"title":"聂小倩"}]},{"bookId":"sgyy","title":"三国演义","author":"罗贯中","dynasty":"元末明初","version":"通行整理电子本（原始数据未标注具体底本版本）","source":"luoxuhai/chinese-novel（GitHub，MIT License）","chapters":[{"chapterId":"sg-21","number":21,"title":"曹操煮酒论英雄　关公赚城斩车胄"},{"chapterId":"sg-37","number":37,"title":"司马徽再荐名士　刘玄德三顾草庐"}]},{"bookId":"shzh","title":"水浒传","author":"施耐庵","dynasty":"元末明初","version":"通行整理电子本（原始数据未标注具体底本版本）","source":"luoxuhai/chinese-novel（GitHub，MIT License）","chapters":[{"chapterId":"sh-02","number":2,"title":"史大郎夜走华阴县　鲁提辖拳打镇关西"},{"chapterId":"sh-10","number":10,"title":"林教头风雪山神庙　陆虞候火烧草料场"}]},{"bookId":"rlws","title":"儒林外史","author":"吴敬梓","dynasty":"清","version":"通行整理电子本（原始数据未标注具体底本版本）","source":"luoxuhai/chinese-novel（GitHub，MIT License）","chapters":[{"chapterId":"rl-01","number":1,"title":"说楔子敷陈大义　借名流隐括全文"},{"chapterId":"rl-03","number":3,"title":"周学道校士拔真才　胡屠户行凶闹捷报"}]},{"bookId":"jhy","title":"镜花缘","author":"李汝珍","dynasty":"清","version":"通行整理电子本（原始数据未标注具体底本版本）","source":"luoxuhai/chinese-novel（GitHub，MIT License）","chapters":[{"chapterId":"jhy-11","number":11,"title":"观雅化闲游君子邦 慕仁风误入良臣府"},{"chapterId":"jhy-25","number":25,"title":"越危垣潜出淑士关 登曲岸闲游两面国"}]}],"passages":[{"passageId":"hlm-03-p1","bookId":"hlm","chapterId":"hlm-03","loc":{"sp":3,"so":200,"ep":3,"eo":287},"cpLength":87,"text":"这黛玉尝听得母亲说他外祖母家与别人家不同，他近日所见的这几个三等的仆妇，吃穿用度，已是不凡，何况今至其家。因此步步留心，时时在意，不多说一句话，不多行一步路，恐被人耻笑了去。","intro":"初到外祖家的黛玉，正学着做一个「客人」。","topics":["情绪与压力"]},{"passageId":"hlm-03-p2","bookId":"hlm","chapterId":"hlm-03","loc":{"sp":8,"so":117,"ep":8,"eo":233},"cpLength":116,"text":"头上戴着金丝八宝攒珠髻，绾着朝阳五凤挂珠钗；项上戴着赤金盘螭缨络圈；身上穿着缕金百蝶穿花大红云缎窄裉袄，外罩五彩刻丝石青银鼠褂；下着翡翠撒花洋绉裙。一双丹凤三角眼，两弯柳叶吊梢眉。身量苗条，体格风骚。粉面含春威不露，丹唇未启笑先闻。","intro":"未见其人，先闻其声——出场的是荣国府里最响亮的人物。","topics":["人性与社会"]},{"passageId":"hlm-03-p3","bookId":"hlm","chapterId":"hlm-03","loc":{"sp":32,"so":78,"ep":32,"eo":174},"cpLength":96,"text":"宝玉看罢，笑道：“这个妹妹，我曾见过的。”贾母笑道：“又胡说了。你何曾见过？”宝玉笑道：“虽没见过，却看着面善，心里倒像是旧相认识，恍若远别重逢的一般。”贾母笑道：“好，好！这么更相和睦了。”","intro":"两个初见的年轻人，都说这场面像是旧相识。","topics":["亲密关系"]},{"passageId":"hlm-03-p4","bookId":"hlm","chapterId":"hlm-03","loc":{"sp":33,"so":0,"ep":33,"eo":106},"cpLength":106,"text":"宝玉听了，登时发作起狂病来，摘下那玉，就狠命摔去，骂道：“什么罕物！人的高下不识，还说灵不灵呢！我也不要这劳什子！”吓的地下众人一拥争去拾玉。贾母急的搂了宝玉，道：“孽障！你生气，要打骂人容易，何苦摔那命根子！”","intro":"一块人人夸赞的玉，成了宝玉当场发作的理由。","topics":["自我认识"]},{"passageId":"hlm-23-p1","bookId":"hlm","chapterId":"hlm-23","loc":{"sp":30,"so":141,"ep":30,"eo":283},"cpLength":142,"text":"只听见墙内笛韵悠扬，歌声婉转，黛玉便知是那十二个女孩子演习戏文。虽未留心去听，偶然两句吹到耳朵内，明明白白，一字不落，道：“原来是姹紫嫣红开遍，似这般，都付与断井颓垣！”黛玉听了，倒也十分感慨缠绵，便止步侧耳细听。又唱道是：“良辰美景奈何天，赏心乐事谁家院？”听了这两句，不觉点头自叹","intro":"墙内排演的戏文，偶然飘进黛玉耳中。","topics":["情绪与压力"]},{"passageId":"hlm-23-p2","bookId":"hlm","chapterId":"hlm-23","loc":{"sp":30,"so":339,"ep":30,"eo":437},"cpLength":98,"text":"再听时，恰唱到：“只为你如花美眷，似水流年。”黛玉听了这两句，不觉心动神摇。又听道“你在幽闺自怜”等句，越发如醉如痴，站立不住，便一蹲身，坐在一块山子石上，细嚼“如花美眷，似水流年”八个字的滋味。","intro":"同一句唱词，她蹲在山石上咂摸了很久。","topics":["孤独与陪伴"]},{"passageId":"hlm-23-p3","bookId":"hlm","chapterId":"hlm-23","loc":{"sp":27,"so":242,"ep":28,"eo":102},"cpLength":136,"text":"宝玉笑道：“我就是个“多愁多病”的身，你就是那“倾国倾城”的貌！”\n黛玉听了，不觉带腮连耳的通红了。登时竖起两道似蹙非蹙的眉，瞪了一双似睁非睁的眼，桃腮带怒，薄面含嗔，指着宝玉道：“你这该死的胡说了！好好儿的把这些淫词艳曲弄了来，说这些混帐话欺负我！我告诉舅舅、舅母去。”","intro":"一句借来的戏词，让两个人都红了脸。","topics":["亲密关系"]},{"passageId":"hlm-27-p1","bookId":"hlm","chapterId":"hlm-27","loc":{"sp":21,"so":131,"ep":21,"eo":227},"cpLength":96,"text":"一年三百六十日，风刀霜剑严相逼。明媚鲜妍能几时？一朝飘泊难寻觅。花开易见落难寻，阶前愁杀葬花人，独把花锄偷洒泪，洒上空枝见血痕。杜鹃无语正黄昏，荷锄归去掩重门。青灯照壁人初睡，冷雨敲窗被未温。","intro":"葬花人的一年三百六十日。","topics":["情绪与压力"]},{"passageId":"hlm-27-p2","bookId":"hlm","chapterId":"hlm-27","loc":{"sp":21,"so":317,"ep":21,"eo":413},"cpLength":96,"text":"未若锦囊收艳骨，一抔净土掩风流。质本洁来还洁去，不教污淖陷渠沟。尔今死去侬收葬，未卜侬身何日丧？侬今葬花人笑痴，他年葬侬知是谁？试看春残花渐落，便是红颜老死时。一朝春尽红颜老，花落人亡两不知！","intro":"葬花吟的最后八句。","topics":["孤独与陪伴"]},{"passageId":"hlm-32-p1","bookId":"hlm","chapterId":"hlm-32","loc":{"sp":10,"so":0,"ep":10,"eo":143},"cpLength":143,"text":"宝玉瞅了半天，方说道：“你放心！”黛玉听了，怔了半天，说道：“我有什么不放心的？我不明白你这个话。你倒说说，怎么放心不放心？”宝玉叹了一口气，问道：“你果然不明白这话？难道我素日在你身上的心都用错了？连你的意思若体贴不着，就难怪你天天为我生气了。”黛玉道：“我真不明白放心不放心的话。”","intro":"说不出口的心事，被两个字接住了。","topics":["亲密关系"]},{"passageId":"hlm-32-p2","bookId":"hlm","chapterId":"hlm-32","loc":{"sp":8,"so":0,"ep":8,"eo":120},"cpLength":120,"text":"黛玉听了这话，不觉又喜又惊，又悲又叹。所喜者：果然自己眼力不错，素日认他是个知己，果然是个知己。所惊者：他在人前，一片私心，称扬于我，其亲热厚密竟不避嫌疑。所叹者，你既为我的知己，自然我亦可为你的知己，既你我为知己，又何必有“金玉”之论呢？","intro":"一句「知己」，让黛玉悲喜交集。","topics":["自我认识"]},{"passageId":"xyj-01-p1","bookId":"xyj","chapterId":"xyj-01","loc":{"sp":5,"so":0,"ep":5,"eo":102},"cpLength":102,"text":"那猴在山中，却会行走跳跃，食草木，饮涧泉，采山花，觅树果；与狼虫为伴，虎豹为群，獐鹿为友，猕猿为亲；夜宿石崖之下，朝游峰洞之中。真是“山中无甲子，寒尽不知年。”一朝天气炎热，与群猴避暑，都在松阴之下顽耍。","intro":"石猴的童年：没有年岁，只有四季。","topics":["成长与选择"]},{"passageId":"xyj-01-p2","bookId":"xyj","chapterId":"xyj-01","loc":{"sp":9,"so":0,"ep":9,"eo":105},"cpLength":105,"text":"众猴拍手称扬道：“好水！好水！原来此处远通山脚之下，直接大海之波。”又道：“那一个有本事的，钻进去寻个源头出来，不伤身体者，我等即拜他为王。”连呼了三声，忽见丛杂中跳出一名石猴，应声高叫道：“我进去！我进去！”","intro":"瀑布后面是什么？总要有猴子第一个跳进去。","topics":["成长与选择"]},{"passageId":"xyj-01-p3","bookId":"xyj","chapterId":"xyj-01","loc":{"sp":21,"so":156,"ep":21,"eo":240},"cpLength":84,"text":"猴王道：“今日虽不归人王法律，不惧禽兽威服，将来年老血衰，暗中有阎王老子管着，一旦身亡，可不枉生世界之中，不得久住天人之内？”众猴闻此言，一个个掩面悲啼，俱以无常为虑。","intro":"王位、宴席都在手上的猴王，忽然想到一件远方的事。","topics":["自我认识"]},{"passageId":"xyj-01-p4","bookId":"xyj","chapterId":"xyj-01","loc":{"sp":22,"so":128,"ep":22,"eo":272},"cpLength":144,"text":"猿猴道：“他只在阎浮世界之中，古洞仙山之内。”猴王闻之，满心欢喜，道：“我明日就辞汝等下山，云游海角，远涉天涯，务必访此三者，学一个不老长生，常躲过阎君之难。”噫！这句话，顿教跳出轮回网，致使齐天大圣成。众猴鼓掌称扬，都道：“善哉！善哉！我等明日越岭登山，广寻些果品，大设筵宴送大王也。”","intro":"为了「不老长生」，他决定下山。","topics":["成长与选择"]},{"passageId":"xyj-14-p1","bookId":"xyj","chapterId":"xyj-14","loc":{"sp":18,"so":150,"ep":18,"eo":274},"cpLength":124,"text":"你是不知，我说与你听：一个唤做眼看喜，一个唤做耳听怒，一个唤做鼻嗅爱，一个唤作舌尝思，一个唤作意见欲，一个唤作身本忧。”悟空笑道：“原来是六个毛贼！你却不认得我这出家人是你的主人公，你倒来挡路。把那打劫的珍宝拿出来，我与你作七分儿均分，饶了你罢！”","intro":"六个拦路的强人，名字都有讲究。","topics":["自我认识"]},{"passageId":"xyj-14-p2","bookId":"xyj","chapterId":"xyj-14","loc":{"sp":1,"so":51,"ep":2,"eo":81},"cpLength":117,"text":"这山旧名五行山，因我大唐王征西定国，改名两界山。先年间曾闻得老人家说：\n‘王莽篡汉之时，天降此山，下压着一个神猴，不怕寒暑，不吃饮食，自有土神监押，教他饥餐铁丸，渴饮铜汁。自昔到今，冻饿不死。’这叫必定是他。长老莫怕，我们下山去看来。","intro":"山脚下石匣中的老猿，已经被压了五百年。","topics":["人性与社会"]},{"passageId":"xyj-14-p3","bookId":"xyj","chapterId":"xyj-14","loc":{"sp":29,"so":340,"ep":29,"eo":448},"cpLength":108,"text":"行者遂脱下旧白布直裰，将绵布直裰穿上，也就是比量着身体裁的一般，把帽儿戴上。三藏见他戴上帽子，就不吃干粮，却默默的念那紧箍咒一遍。行者叫道：“头痛！头痛！”那师父不住的又念了几遍，把个行者痛得打滚，抓破了嵌金的花帽。","intro":"一顶新帽子，让齐天大圣第一次喊「头痛」。","topics":["成长与选择"]},{"passageId":"xyj-27-p1","bookId":"xyj","chapterId":"xyj-27","loc":{"sp":5,"so":114,"ep":6,"eo":77},"cpLength":96,"text":"妖精说：“等我且戏他戏，看怎么说。”\n好妖精，停下阴风，在那山凹里，摇身一变，变做个月貌花容的女儿，说不尽那眉清目秀，齿白唇红，左手提着一个青砂罐儿，右手提着一个绿磁瓶儿，从西向东，径奔唐僧。","intro":"荒山里走来一个提罐的女儿。","topics":["人性与社会"]},{"passageId":"xyj-27-p2","bookId":"xyj","chapterId":"xyj-27","loc":{"sp":25,"so":0,"ep":25,"eo":128},"cpLength":128,"text":"行者连忙接了贬书道：“师父，不消发誓，老孙去罢。”他将书摺了，留在袖中，却又软款唐僧道：“师父，我也是跟你一场，又蒙菩萨指教，今日半途而废，不曾成得功果，你请坐，受我一拜，我也去得放心。”唐僧转回身不睬，口里唧唧哝哝的道：“我是个好和尚，不受你歹人的礼！”","intro":"一场师徒散伙，他坚持拜了这一拜。","topics":["孤独与陪伴"]},{"passageId":"jstl-01-p1","bookId":"jstl","chapterId":"jstl-01","loc":{"sp":2,"so":90,"ep":3,"eo":40},"cpLength":90,"text":"这相知有几样名色：恩德相结者，谓之知己；腹心相照者，谓之知心；声气相求嗜，谓之知音，总来叫做相知。\n今日听在下说一桩俞伯牙的故事。列位看官们，要听者，洗耳而听；不要听者，各随尊便。","intro":"「相知」分几种，说书人先给个定义。","topics":["人性与社会"]},{"passageId":"jstl-01-p2","bookId":"jstl","chapterId":"jstl-01","loc":{"sp":7,"so":249,"ep":7,"eo":358},"cpLength":109,"text":"其意在于高山，抚琴一弄。樵夫赞道：“美哉洋洋乎，大人之意，在高山也！”伯牙不答。又凝神一会，将琴再鼓，其意在于流水。樵夫又赞道：“美哉汤汤乎，志在流水！”只两句，道着了伯牙的心事。伯牙大惊，推琴而起，与子期施宾主之礼。","intro":"两句点评，把琴音说到了他心里。","topics":["孤独与陪伴"]},{"passageId":"jstl-01-p3","bookId":"jstl","chapterId":"jstl-01","loc":{"sp":19,"so":28,"ep":21,"eo":16},"cpLength":74,"text":"用力一摔，摔得玉珍抛残，金徽零乱。钟公大惊，问道：“先生为何摔碎此琴？”伯牙道：\n摔碎瑶琴凤尾寒，子期不在对谁弹！\n春风满面皆朋友，欲觅知音难上难。","intro":"知音已去，琴也就没有听的人了。","topics":["孤独与陪伴"]},{"passageId":"jstl-28-p1","bookId":"jstl","chapterId":"jstl-28","loc":{"sp":64,"so":99,"ep":64,"eo":174},"cpLength":75,"text":"见一条吊桶来大的蟒蛇，睡在床上，伸头在天窗内乘凉，鳞甲内放出白光来，照得房内如同白日。吃了一惊，回身便走。来到房中，不说其事，道：“睡了，不见则声。”","intro":"纸窗舔破一条缝，床上睡的不是娘子。","topics":["情绪与压力"]},{"passageId":"jstl-28-p2","bookId":"jstl","chapterId":"jstl-28","loc":{"sp":66,"so":0,"ep":66,"eo":68},"cpLength":68,"text":"那先生装了一瓶雄黄药水，一直来到黑珠儿巷门，问李募事家。人指道：“前面那楼子内便是。”先生来到门前，揭起帘子，咳嗽一声，并无一个人出来。","intro":"重金请来的捉蛇先生，先吃了半晌闭门羹。","topics":["人性与社会"]},{"passageId":"jstl-28-p3","bookId":"jstl","chapterId":"jstl-28","loc":{"sp":67,"so":301,"ep":68,"eo":47},"cpLength":93,"text":"只见刮起一阵冷风，风过处，只见一条吊桶来大的蟒蛇，连射将来，正是：人无害虎心，虎有伤人意。\n且说那戴先生吃了一惊，望后便倒，雄黄罐儿也打破了，那条大蛇张开血红大口，露出雪白齿，来咬先生。","intro":"冷风过处，答案自己追了出来。","topics":["人性与社会"]},{"passageId":"jstl-28-p4","bookId":"jstl","chapterId":"jstl-28","loc":{"sp":78,"so":12,"ep":79,"eo":16},"cpLength":91,"text":"惟有许宣情愿出家，礼拜禅师为师，就雷峰塔披剃为僧。修行数年，一夕坐化去了。众僧买龛烧化，造一座骨塔，千年不朽，临去世时，亦有诗八句，留以警世，诗曰：\n祖师度我出红尘，铁树开花始见春。","intro":"塔镇住了旧事，也安放了许宣的余生。","topics":["孤独与陪伴"]},{"passageId":"jstl-32-p1","bookId":"jstl","chapterId":"jstl-32","loc":{"sp":32,"so":0,"ep":32,"eo":88},"cpLength":88,"text":"因这风雪阻渡，舟不得开。孙富命艄公移船，泊于李家舟之傍。孙富貂帽狐裘，推窗假作看雪。值十娘梳洗方毕，纤纤玉手揭起舟傍短帘，自泼盂中残水。粉容微露，却被孙富窥见了，果是国色天香。","intro":"风雪拦住的船，也拦来了邻船的眼睛。","topics":["人性与社会"]},{"passageId":"jstl-32-p2","bookId":"jstl","chapterId":"jstl-32","loc":{"sp":41,"so":140,"ep":41,"eo":252},"cpLength":112,"text":"箱中韫藏百宝，不下万金。将润色郎君之装，归见父母，或怜妾有心，收佐中馈，得终委托，生死无憾。谁知郎君相信不深，惑于浮议，中道见弃，负妾一片真心。今日当众目之前，开箱出视，使郎君知区区千金，未为难事。妾椟中有玉，恨郎眼内无珠。","intro":"箱子打开时，话比珠宝先落地。","topics":["亲密关系"]},{"passageId":"jstl-32-p3","bookId":"jstl","chapterId":"jstl-32","loc":{"sp":41,"so":343,"ep":43,"eo":24},"cpLength":100,"text":"十娘抱持宝匣，向江心一跳。众人急呼捞救，但见云暗江心，波涛滚滚，杳无踪影。可惜一个如花似玉的名姬，一旦葬于江鱼之腹！\n三魂渺渺归水府，七魄悠悠入冥途。\n当时旁观之人，皆咬牙切齿，争欲拳殴李甲和那孙富。","intro":"她把最后一箱东西，连人带心还给了江水。","topics":["情绪与压力"]},{"passageId":"ysmy-01-p1","bookId":"ysmy","chapterId":"ysmy-01","loc":{"sp":10,"so":0,"ep":10,"eo":95},"cpLength":95,"text":"且说这里浑家王三巧儿，自从那日丈夫分付了，果然数月之内，目不窥户，足不下楼。光阴似箭，不觉残年将尽，家家户户，闹轰轰的暖火盆，放爆竹，吃合家欢耍子。三巧儿触景伤情，图想丈夫，这一夜好生凄楚！","intro":"除夕的热闹是别人的，楼上只有等待。","topics":["孤独与陪伴"]},{"passageId":"ysmy-01-p2","bookId":"ysmy","chapterId":"ysmy-01","loc":{"sp":31,"so":68,"ep":31,"eo":160},"cpLength":92,"text":"妇人便去开箱，取出一件宝贝，叫做“珍珠衫”，递与陈大郎道：“这件衫儿，是蒋门祖传之物，暑天若穿了他，清凉透骨。此去天道渐热，正用得着。奴家把与你做个记念，穿了此衫，就如奴家贴体一般。”","intro":"一件祖传的衫子，从此穿错了人。","topics":["亲密关系"]},{"passageId":"ysmy-01-p3","bookId":"ysmy","chapterId":"ysmy-01","loc":{"sp":14,"so":94,"ep":14,"eo":201},"cpLength":107,"text":"薛婆蓬着头，正在天井里拣珠子，听得敲门，一头收过珠包，一头问道：“是谁？”才听说出“徽州陈”三字，慌忙开门请进，道：“老身未曾梳洗，不敢为礼了。大官人起得好早！有何贵干？”陈大郎道：“特特而来，若退时，怕不相遇。”","intro":"一个卖珠的婆子，先听懂了客人的来意。","topics":["人性与社会"]},{"passageId":"ysmy-16-p1","bookId":"ysmy","chapterId":"ysmy-16","loc":{"sp":3,"so":0,"ep":3,"eo":105},"cpLength":105,"text":"结义后，朝暮相随，不觉半年。范式思归，张劭与计算房钱，还了店家。二人同行。数日，到分路之处，张劭欲送范式。范式曰：“若如此，某又送回。不如就此一别，约再相会。”二人酒肆共饮，见黄花红叶，妆点秋光，以劭别离之兴。","intro":"重阳一别，两人把来年今日许给了彼此。","topics":["孤独与陪伴"]},{"passageId":"ysmy-16-p2","bookId":"ysmy","chapterId":"ysmy-16","loc":{"sp":6,"so":264,"ep":6,"eo":369},"cpLength":105,"text":"巨卿，信士也，必然今日至矣，安肯误鸡黍之约？入门便见所许之物，足见我之持久。如候巨卿来，而后宰之，不见我倦倦之意。”母曰：“吾儿之友，必是端士。”遂烹炮以持。是曰，天晴曰朗，万里无云。劭整其衣冠，独立庄门而望。","intro":"鸡黍早早备下，人从清晨望到日落。","topics":["孤独与陪伴"]},{"passageId":"ysmy-16-p3","bookId":"ysmy","chapterId":"ysmy-16","loc":{"sp":7,"so":93,"ep":7,"eo":190},"cpLength":97,"text":"小弟自早直候至今，知兄非爽信也，兄果至矣。旧岁所约鸡黍之物，备之己久。路远风尘，别不曾有人同来？”便请至草堂，与老母相见。范式并不答话，径入草堂。张劭指座榻曰：“特设此位，专持兄来，兄当高座。”","intro":"他如约而至，只是这一趟来自五百里外。","topics":["人性与社会"]},{"passageId":"xsh-03-p1","bookId":"xsh","chapterId":"xsh-03","loc":{"sp":9,"so":457,"ep":10,"eo":35},"cpLength":86,"text":"弄出天大的名声出来，不叫他美娘，叫他做花魁娘子。西湖上子弟编出一支《挂枝儿》，单道那花魁娘子的好处：\n小娘中，谁似得王美儿的标致，又会写，又会画，又会做诗，吹弹歌舞都余事。","intro":"西湖边人人会唱她的名字。","topics":["人性与社会"]},{"passageId":"xsh-03-p2","bookId":"xsh","chapterId":"xsh-03","loc":{"sp":28,"so":149,"ep":28,"eo":231},"cpLength":82,"text":"这是有名的粉头，叫做王美娘，人都称为花魁娘子。他原是汴京人，流落在此。吹弹歌舞，琴棋书画，件件皆精。来往的都是大头儿，要十两放光，才宿一夜哩，可知小可的也近他不得。","intro":"十两银子一夜，卖油郎默默记下了。","topics":["亲密关系"]},{"passageId":"xsh-03-p3","bookId":"xsh","chapterId":"xsh-03","loc":{"sp":24,"so":474,"ep":24,"eo":560},"cpLength":86,"text":"一个卖油的，复姓之时，谁人晓得？他有个道理，把盛油的桶儿，一面大大写个“秦”字，一面写“汴梁”二字，将油桶做个标识，使人一览而知。以此临安市上，晓得他本姓，都呼他为秦卖油。","intro":"一只写上姓氏的油桶，就是他的名帖。","topics":["自我认识"]},{"passageId":"xsh-11-p1","bookId":"xsh","chapterId":"xsh-11","loc":{"sp":49,"so":78,"ep":50,"eo":70},"cpLength":109,"text":"第三题是个对儿，我五六岁时便会对句，不足为难。”再拆开第三幅花笺，内出对云：\n闭门推出窗前月。 初看时觉道容易，仔细思来，这对出得尽巧。若对得平常了，不见本事。左思右想，不得其对。听得谯楼三鼓将阑，构思不就，愈加慌迫。","intro":"第三道难题只有七个字的上联。","topics":["成长与选择"]},{"passageId":"xsh-11-p2","bookId":"xsh","chapterId":"xsh-11","loc":{"sp":50,"so":70,"ep":50,"eo":175},"cpLength":105,"text":"却说东坡此时尚未曾睡，且来打听妹夫消息。望见少游在庭中团团而步，口里只管吟哦“闭门推出窗前月”七个字，右手做推窗之势。东坡想道：“此必小妹以此对难之，少游为其所困矣！我不解围，谁为撮合？”急切思之，亦未有好对。","intro":"妹夫在院里绕圈，大舅哥在屋里看懂了一切。","topics":["亲密关系"]},{"passageId":"xsh-11-p3","bookId":"xsh","chapterId":"xsh-11","loc":{"sp":28,"so":36,"ep":28,"eo":138},"cpLength":102,"text":"秦少游到三月初一日五更时分，就起来梳洗，打扮个游方道人模样：头裹青布唐巾，耳后露两个石碾的假玉环儿，身穿皂布道袍，腰系黄绦，足穿净袜草履，项上挂一串拇指大的数珠，手中托一个金漆钵盂，侵早就到东岳庙前伺候。","intro":"为了看未婚妻一眼，他把自己打扮成道人。","topics":["亲密关系"]},{"passageId":"xsh-18-p1","bookId":"xsh","chapterId":"xsh-18","loc":{"sp":15,"so":0,"ep":15,"eo":119},"cpLength":119,"text":"行不上半箭之地，一眼觑见一家街沿之下，一个小小青布包儿。施复趱步向前，拾起袖过，走到一个空处，打开看时，却是两锭银子，又有三四件小块，兼着一文太平钱儿。把手攧一攧，约有六两多重。心中欢喜道：“今日好造化！拾得这些银子，正好将去凑做本钱。”","intro":"六两多银子躺在路边，等一个路过的小机户。","topics":["人性与社会"]},{"passageId":"xsh-18-p2","bookId":"xsh","chapterId":"xsh-18","loc":{"sp":38,"so":90,"ep":38,"eo":208},"cpLength":118,"text":"向日你因失银与我识面，今日我亦因失物，尊嫂见还。方才言及前情，又得相会。”朱恩道：“看起来，我与老哥乃前生结下缘分，才得如此。意欲结为兄弟，不知尊意若何？”施复道：“小子别无兄弟，若不相弃，可知好哩。”当下二人就堂中八拜为交，认为兄弟。","intro":"一包失而复得的银子，牵出一场八拜之交。","topics":["孤独与陪伴"]},{"passageId":"liao-15-p1","bookId":"liao","chapterId":"liao-15","loc":{"sp":0,"so":738,"ep":0,"eo":854},"cpLength":116,"text":"道士笑而允之。乃传一诀，令自咒毕，呼曰：“入之！”王面墙不敢入。又曰：“试入之。”王果从容入，及墙而阻。道士曰：“俯首辄入，勿逡巡！”王果去墙数步奔而入，及墙，虚若无物，回视，果在墙外矣。大喜，入谢。道士曰：“归宜洁持，否则不验。”","intro":"穿墙术学成了，师父只多嘱咐了一句。","topics":["成长与选择"]},{"passageId":"liao-15-p2","bookId":"liao","chapterId":"liao-15","loc":{"sp":0,"so":880,"ep":0,"eo":969},"cpLength":89,"text":"王效其作为，去墙数尺，奔而入；头触硬壁，蓦然而踣。妻扶视之，额上坟起如巨卵焉。妻揶揄之。王渐忿，骂老道士之无良而已。异史氏曰：“闻此事，未有不大笑者，而不知世之为王生者正复不少。","intro":"硬壁没有变，变的只有王生的心。","topics":["自我认识"]},{"passageId":"liao-48-p1","bookId":"liao","chapterId":"liao-48","loc":{"sp":1,"so":40,"ep":1,"eo":122},"cpLength":82,"text":"有女郎携婢，拈梅花一枝，容华绝代，笑容可掬。生注目不移，竟忘顾忌。女过去数武，顾婢子笑曰：“个儿郎目灼灼似贼！”遗花地上，笑语自去。生拾花怅然，神魂丧失，怏怏遂返。","intro":"她丢下一枝梅花，也丢下一个害了相思的人。","topics":["亲密关系"]},{"passageId":"liao-48-p2","bookId":"liao","chapterId":"liao-48","loc":{"sp":2,"so":879,"ep":2,"eo":961},"cpLength":82,"text":"良久，闻户外隐有笑声。媪又唤曰：“婴宁，汝姨兄在此。”户外嗤嗤笑不已。婢推之以入，犹掩其口，笑不可遏。媪逋目曰：“有客在，咤咤叱叱，是何景象？”女忍笑而立，生揖之。","intro":"人还没进门，笑声先到了。","topics":["人性与社会"]},{"passageId":"liao-48-p3","bookId":"liao","chapterId":"liao-48","loc":{"sp":2,"so":1103,"ep":2,"eo":1208},"cpLength":105,"text":"如甥才貌，何十七岁犹未聘？婴宁亦无姑家，极相匹敌。惜有内亲之嫌。”生无语，目注婴宁，不遑他瞬。婢向女小语云：“目灼灼贼腔未改！”女又大笑，顾婢曰：“视碧桃开未？”遽起，以袖掩口，细碎连步而出。至门外，笑声始纵。","intro":"大人们谈亲事，她只顾笑，笑够了就走。","topics":["人性与社会"]},{"passageId":"liao-49-p1","bookId":"liao","chapterId":"liao-49","loc":{"sp":1,"so":93,"ep":1,"eo":170},"cpLength":77,"text":"妾阅人多矣，未有刚肠如君者。君诚圣贤，妾不敢欺。小倩，姓聂氏，十八夭殂，葬于寺侧，被妖物威胁，历役贱务，腆颜向人，实非所乐。今寺中无可杀者，恐当以夜叉来。","intro":"深夜自述：一个被鬼差使的少女。","topics":["情绪与压力"]},{"passageId":"liao-49-p2","bookId":"liao","chapterId":"liao-49","loc":{"sp":2,"so":292,"ep":2,"eo":376},"cpLength":84,"text":"燕曰：“既相知爱，何敢深隐。我剑客也。若非石棂，妖当立毙；虽然，亦伤。”问：“所缄何物？”曰：“剑也。适嗅之有妖气。”宁欲观之。慨出相示，荧荧然一小剑也。于是益厚重燕。","intro":"箧中小剑嗅得出妖气，邻室住着位剑客。","topics":["人性与社会"]},{"passageId":"liao-49-p3","bookId":"liao","chapterId":"liao-49","loc":{"sp":2,"so":598,"ep":2,"eo":675},"cpLength":77,"text":"欢喜谢曰：“君信义，十死不足以报。请从归，拜识姑嫜，媵御无悔。”审谛之，肌映流霞，足翘细笋，白昼端相，娇丽尤绝。遂与俱至斋中。嘱坐少待，先入白母。母愕然。","intro":"从寺侧荒坟，到人间烟火。","topics":["孤独与陪伴"]},{"passageId":"sg-21-p1","bookId":"sgyy","chapterId":"sg-21","loc":{"sp":2,"so":339,"ep":2,"eo":442},"cpLength":103,"text":"操曰：“龙能大能小，能升能隐；大则兴云吐雾，小则隐介藏形；升则飞腾于宇宙之间，隐则潜伏于波涛之内。方今春深，龙乘时变化，犹人得志而纵横四海。龙之为物，可比世之英雄。玄德久历四方，必知当世英雄。请试指言之。”","intro":"一场雨前的对饮，题目却是天下英雄。","topics":["人性与社会"]},{"passageId":"sg-21-p2","bookId":"sgyy","chapterId":"sg-21","loc":{"sp":2,"so":863,"ep":2,"eo":999},"cpLength":136,"text":"操以手指玄德，后自指，曰：“今天下英雄，惟使君与操耳！”玄德闻言，吃了一惊，手中所执匙箸，不觉落于地下。时正值天雨将至，雷声大作。玄德乃从容俯首拾箸曰：“一震之威，乃至于此。”操笑曰：“丈夫亦畏雷乎？”玄德曰：“圣人迅雷风烈必变，安得不畏？”将闻言失箸缘故，轻轻掩饰过了。","intro":"筷子掉了，借一声雷捡了回来。","topics":["自我认识"]},{"passageId":"sg-37-p1","bookId":"sgyy","chapterId":"sg-37","loc":{"sp":2,"so":569,"ep":2,"eo":647},"cpLength":78,"text":"四百年之张子房也。”众皆愕然。徽下阶相辞欲行，玄德留之不住。徽出门仰天大笑曰：“卧龙虽得其主，不得其时，惜哉！”言罢，飘然而去。玄德叹曰：“真隐居贤士也！”","intro":"名士临走时，留下一声长叹。","topics":["成长与选择"]},{"passageId":"sg-37-p2","bookId":"sgyy","chapterId":"sg-37","loc":{"sp":3,"so":86,"ep":3,"eo":188},"cpLength":102,"text":"玄德闻歌，勒马唤农夫问曰：“此歌何人所作？”答曰：“乃卧龙先生所作也。”玄德曰：“卧龙先生住何处？”农夫曰：“自此山之南，一带高冈，乃卧龙冈也。冈前疏林内茅庐中，即诸葛先生高卧之地。”玄德谢之，策马前行。","intro":"第一次拜访，连茅庐的门都没摸到。","topics":["孤独与陪伴"]},{"passageId":"sg-37-p3","bookId":"sgyy","chapterId":"sg-37","loc":{"sp":2,"so":320,"ep":2,"eo":427},"cpLength":107,"text":"孔明与博陵崔州平、颍川石广元、汝南孟公威与徐元直四人为密友。此四人务于精纯，惟孔明独观其大略。尝抱膝长吟，而指四人曰：“公等仕进可至刺史、郡守。众问孔明之志若何，孔明但笑而不答。每常自比管仲、乐毅，其才不可量也。”","intro":"别人读书求甚解，他只观其大略。","topics":["自我认识"]},{"passageId":"sh-02-p1","bookId":"shzh","chapterId":"sh-02","loc":{"sp":133,"so":0,"ep":134,"eo":18},"cpLength":71,"text":"提起拳头来就眼眶际眉梢只一拳，打得眼棱缝裂，乌珠迸出，也似开了个彩帛铺的∶红的，黑的，紫的，都绽将出来。\n两边看的人惧怕鲁提辖，谁敢向前来劝？","intro":"一拳下去，郑屠眼里开了一间彩帛铺。","topics":["人性与社会"]},{"passageId":"sh-02-p2","bookId":"shzh","chapterId":"sh-02","loc":{"sp":135,"so":0,"ep":136,"eo":37},"cpLength":84,"text":"鲁达喝道：“咄！你是个破落户！若只和俺硬到底，酒家便饶你了！你如今对俺讨饶，酒家偏不饶你！”\n又只一拳，太阳上正着，却似做了一全堂水陆的道场∶磐儿，钹儿，铙儿，一齐响。","intro":"讨饶没有用，这一拳是一整场道场。","topics":["人性与社会"]},{"passageId":"sh-02-p3","bookId":"shzh","chapterId":"sh-02","loc":{"sp":138,"so":0,"ep":139,"eo":43},"cpLength":93,"text":"鲁达寻思道：“俺只指望打这厮一顿，不想三拳真个打死了他。酒家须吃官司，又没人送饭，不如及早撒开。”\n拔步便走，回头指着郑屠尸道：“你诈死！酒家和你慢慢理会！”　　一头骂，一头大踏步去了。","intro":"三拳之后，他当场想好了退场。","topics":["成长与选择"]},{"passageId":"sh-10-p1","bookId":"shzh","chapterId":"sh-10","loc":{"sp":7,"so":867,"ep":8,"eo":22},"cpLength":86,"text":"两个取路投草料场来。正是严冬天气，彤云密布，朔风渐起，却早纷纷扬扬卷下一天大雪来。那雪早下得密了。怎见得好雪？有临江仙词为证：\n作阵成团空里下，这回忒杀堪怜，剡溪冻住猷船。","intro":"大雪封路的一天，草料场到了。","topics":["情绪与压力"]},{"passageId":"sh-10-p2","bookId":"shzh","chapterId":"sh-10","loc":{"sp":11,"so":15,"ep":11,"eo":79},"cpLength":64,"text":"飞也似奔到草场门口，开了锁入内看时，只叫得苦。原来天理昭然，佑护善人义士。因这场大雪，救了林冲的性命。那两间草厅，已被雪压倒了。","intro":"压塌草厅的雪，反倒先救了他一命。","topics":["孤独与陪伴"]},{"passageId":"sh-10-p3","bookId":"shzh","chapterId":"sh-10","loc":{"sp":9,"so":540,"ep":9,"eo":618},"cpLength":78,"text":"那雪正下得紧。行不上半里多路，看见一所古庙。林冲顶礼道：“神明庇佑，改日来烧钱纸。”又行了一回，望见一簇人家。林冲住脚看时，见篱笆中挑着一个草帚儿在露天里。","intro":"「那雪正下得紧」，五个字撑起一整回。","topics":["情绪与压力"]},{"passageId":"rl-01-p1","bookId":"rlws","chapterId":"rl-01","loc":{"sp":1,"so":95,"ep":1,"eo":194},"cpLength":99,"text":"儿啊！不是我有心要耽误你，只因你父亲亡后，我一个寡妇人家，只有出去的，没有进来的；年岁不好，柴米又贵，这几件旧衣服和些旧家伙，当的当了，卖的卖了；只靠著我替人家做些针黹生活赚来的钱，如何供得你读书？","intro":"十岁的王冕，听懂了母亲的账本。","topics":["情绪与压力"]},{"passageId":"rl-01-p2","bookId":"rlws","chapterId":"rl-01","loc":{"sp":4,"so":132,"ep":4,"eo":242},"cpLength":110,"text":"湖里有十来枝荷花，苞子上清水滴滴，荷叶上水珠滚来滚去。王冕看了一回，心里想道：“古人说：‘人在图画中’其实不错！可惜我这里没有一个画工，把这荷花画他几枝，也觉有趣！”又心里想道：“天下那有个学不会的事？我何不自画他几枝？","intro":"湖里的荷花看久了，他想自己动手画。","topics":["自我认识"]},{"passageId":"rl-01-p3","bookId":"rlws","chapterId":"rl-01","loc":{"sp":7,"so":14,"ep":7,"eo":119},"cpLength":105,"text":"自此，聚的钱，不买书了；托人向城里买些胭脂铅粉之类，学画荷花。初时画得不好，画到三个月之后，那荷花精神、颜色无一不像：只多著一张纸，就像是湖里长的；又像才从湖里摘下来贴在纸上的。乡间人见画得好，也有拿钱来买的。","intro":"三个月后，纸上的荷花像才从湖里摘的。","topics":["成长与选择"]},{"passageId":"rl-03-p1","bookId":"rlws","chapterId":"rl-03","loc":{"sp":7,"so":115,"ep":7,"eo":233},"cpLength":118,"text":"学道道：“你今年多少年纪了？”范进道：“童生册上写的是三十岁，童生实年五十四岁。”学道道：“你考过多少回了？”范进道：“童生二十岁应考，到今考过二十余次。”学道道：“如何总不进学？”范进道：“总因童生文字荒谬，所以各位大老爷不曾赏取。”","intro":"册上三十岁，实年五十四，考了二十余次。","topics":["情绪与压力"]},{"passageId":"rl-03-p2","bookId":"rlws","chapterId":"rl-03","loc":{"sp":10,"so":76,"ep":10,"eo":181},"cpLength":105,"text":"只见他丈人胡屠户，手里拿著一副大肠和一瓶酒，走了进来。范进向他作揖，坐下。胡屠户道：“我自倒运，把个女儿嫁与你这现世宝穷鬼，历年以来，不知累了我多少；如今不知因我积了甚么德，使你中了个相公，所以带瓶酒来贺你。”","intro":"一副大肠一瓶酒，外加一顿数落。","topics":["人性与社会"]},{"passageId":"rl-03-p3","bookId":"rlws","chapterId":"rl-03","loc":{"sp":13,"so":615,"ep":14,"eo":70},"cpLength":135,"text":"范进不看便罢，看了一遍，又念一遍，自己把两手拍了一下，笑了一声道：“噫！好了！我中了！”说著，往后一跤跌倒，牙关咬紧，不醒人事。\n老太太慌了，忙将几口开水灌了过去；他爬将起来，又怕著手大笑道：“噫！好了！我中了！”笑著，不由分说，就往门外飞跑，把报录人和邻居都吓了一跳。","intro":"喜报送到家，人跟着飞了。","topics":["自我认识"]},{"passageId":"rl-03-p4","bookId":"rlws","chapterId":"rl-03","loc":{"sp":14,"so":70,"ep":15,"eo":25},"cpLength":88,"text":"走出大门不多路，一脚踹在池塘里，爬起来，头发都跌散了，两手黄泥，淋淋漓漓一身的水，众人拉他不住。拍著笑著，一直走到集上去了。\n众人大眼望小眼，一齐道：“原来新贵人欢喜得疯了。”","intro":"一直走到集上，才有人替他下了诊断。","topics":["人性与社会"]},{"passageId":"jhy-11-p1","bookId":"jhy","chapterId":"jhy-11","loc":{"sp":0,"so":46,"ep":0,"eo":118},"cpLength":72,"text":"唐敖见言语可通，因向一位老翁问其何以“好让不争”之故。谁知老翁听了，一毫不懂。又问国以“君子”为名是何缘故，老翁也回不知一连问了几个，都是如此。","intro":"君子国的百姓，连国名来历都不在意。","topics":["人性与社会"]},{"passageId":"jhy-11-p2","bookId":"jhy","chapterId":"jhy-11","loc":{"sp":3,"so":9,"ep":3,"eo":85},"cpLength":76,"text":"只见有一隶卒在那里买物，手中拿著货物道：“老兄如此高货，却讨恁般贱价，教小弟买去，如何能安心！务求将价加增，方好遵教。若再过谦，那是有意不肯赏光交易了。","intro":"在这里，买东西的求着卖家涨价。","topics":["人性与社会"]},{"passageId":"jhy-11-p3","bookId":"jhy","chapterId":"jhy-11","loc":{"sp":1,"so":0,"ep":1,"eo":116},"cpLength":116,"text":"多九公道：“据老夫看来，他这国名以及‘好让不争’四字，大约都是邻邦替他取的，所以他们都回不知。刚才我们一路看来，那些‘耕者让畔，行者让路’光景，已是不争之意。而且士庶人等，无论富贵贫贱，举止言谈，莫不恭而有礼，也不愧‘君子’二字。”","intro":"名字是外人取的，礼让是天天过出来的。","topics":["自我认识"]},{"passageId":"jhy-25-p1","bookId":"jhy","chapterId":"jhy-25","loc":{"sp":7,"so":118,"ep":7,"eo":189},"cpLength":71,"text":"我们别了九公，又走十余里，才有人烟。原要看看两面是何形状，谁知他们个个头戴浩然巾，都把脑后遮住，只露一张正面，却把那面藏了，因此并未看见两面。","intro":"两面国的人，只给你看一张脸。","topics":["人性与社会"]},{"passageId":"jhy-25-p2","bookId":"jhy","chapterId":"jhy-25","loc":{"sp":8,"so":7,"ep":8,"eo":74},"cpLength":67,"text":"他同妹夫说笑，俺也随口问他两句。他掉转头来，把俺上下一望，陡然变了样子：脸上冷冷的，笑容也收了，谦恭也免了。停了半晌，他才答俺半句。”","intro":"换个说话的人，脸也跟着换。","topics":["人性与社会"]},{"passageId":"jhy-25-p3","bookId":"jhy","chapterId":"jhy-25","loc":{"sp":8,"so":251,"ep":8,"eo":368},"cpLength":117,"text":"后来舅兄又同一人说话，小弟暗暗走到此人身后，悄悄把他浩然巾揭起。不意里面藏著一张恶脸，鼠眼鹰鼻，满面横肉。他见了小弟，把扫帚眉一皱，血盆口一张，伸出一条长舌，喷出一股毒气，霎时阴风惨惨，黑雾漫漫，小弟一见，不觉大叫一声：‘吓杀我了！’","intro":"浩然巾后面，藏着另一张脸。","topics":["自我认识"]}],"demo_comments":[{"passageId":"hlm-03-p1","author":"示例读者 A","text":"这篇全是眼睛在替她走路，一个新人进一个大家，谁都不敢错。"},{"passageId":"hlm-03-p1","author":"示例读者 B","text":"与其说是小心，不如说是懂事得太早了。"},{"passageId":"hlm-03-p3","author":"示例读者 A","text":"「我曾见过的」，见面第一句就毫无道理，又特别可信。"},{"passageId":"hlm-03-p3","author":"示例读者 C","text":"贾母在一旁笑着说「好」，这个场面比两句对白更暖。"},{"passageId":"hlm-23-p1","author":"示例读者 B","text":"戏是排给别人看的，词偏偏落进一个不相干的人耳朵里。"},{"passageId":"hlm-23-p1","author":"示例读者 A","text":"「都付与断井颓垣」，好东西和没人看，原来是一句话的事。"},{"passageId":"hlm-27-p2","author":"示例读者 C","text":"「他年葬侬知是谁」，她替花想到最后，也把自己想到了最后。"},{"passageId":"hlm-27-p2","author":"示例读者 B","text":"很少有一首诗，把「干净」两个字写得这么倔。"},{"passageId":"hlm-32-p1","author":"示例读者 A","text":"安慰人的最高级：不解释，只接住。"},{"passageId":"hlm-32-p1","author":"示例读者 C","text":"黛玉追问那么多，其实只是不敢信这两个字。"},{"passageId":"xyj-01-p3","author":"示例读者 B","text":"最怕的不是眼下苦，是欢喜的时候忽然想到尽头。"},{"passageId":"xyj-01-p3","author":"示例读者 A","text":"一屋子猴子替他哭，这一段其实挺温柔。"},{"passageId":"xyj-14-p1","author":"示例读者 C","text":"眼看喜、耳听怒……六贼根本就是六种心情，悟空打的是自己。"},{"passageId":"xyj-27-p2","author":"示例读者 A","text":"被赶走还要坚持拜一拜，这份体面看得人难受。"},{"passageId":"xyj-27-p2","author":"示例读者 B","text":"「不受你歹人的礼」是嘴上的话，躲不开的四拜是真的。"}],"chapters":{"hlm-03":{"chapterId":"hlm-03","bookId":"hlm","fileIndex":2,"number":3,"title":"第三回 贾雨村夤缘复旧职　林黛玉抛父进京都","paragraphs":["却说雨村忙回头看时，不是别人，乃是当日同僚一案参革的张如圭。他系此地人，革后家居。今打听得都中奏准起复旧员之信，他便四下里寻情找门路，忽遇见雨村，故忙道喜。二人见了礼，张如圭便将此信告知雨村。雨村欢喜。忙忙叙了两句，遂作别各自回家。冷子兴听得此言，便忙献计，令雨村央求林如海，转向都中去央烦贾政。","雨村领其意而别，回至馆中，忙寻邸报看真确了。次日，面谋林如海。如海道：“天缘凑巧：因贱荆去世，都中家岳母念及小女无人依傍，前已遣了男女船只来接，因小女未曾大痊，故未及行，此刻正思送女进京。因向蒙教诲之恩，未经酬报，遇此机会，岂有不尽心图报之理！弟已预筹之，修下荐书一封，托内兄务为周全，方可稍尽弟之鄙诚。即有所费，弟于内家信中写明，不劳吾兄多虑。”雨村一面打恭，谢不释口，一面又问：“不知令亲大人现居何职？只怕晚生草率，不敢进谒。”如海笑道：“若论舍亲，与尊兄犹系一家，乃荣公之孙。大内兄现袭一等将军之职，名赦，字恩侯。二内兄名政，字存周，现任工部员外郎。其为人谦恭厚道，大有祖父遗风，非膏粱轻薄之流，故弟致书烦托。否则不但有污尊兄清操，即弟亦不屑为矣。”雨村听了，心下方信了昨日子兴之言，于是又谢了林如海。如海又说：“择了出月初二日小女入都，吾兄即同路而往，岂不两便？”雨村唯唯听命，心中十分得意。如海遂打点礼物并饯行之事，雨村一一领了。","那女学生原不忍离亲而去，无奈他外祖母必欲其往，且兼如海说：“汝父年已半百，再无续室之意；且汝多病，年又极小，上无亲母教养，下无姊妹扶持：今去依傍外祖母及舅氏姊妹，正好减我内顾之忧，如何不去？”黛玉听了，方洒泪拜别，随了奶娘及荣府中几个老妇，登舟而去。雨村另有一只船，带了两个小童，依附黛玉而行。","一日，到了京都，雨村先整了衣冠，带着童仆，拿了“宗侄”的名帖，至荣府门上投了。彼时贾政已看了妹丈之书，即忙请入相会。见雨村像貌魁伟，言谈不俗。且这贾政最喜的是读书人，礼贤下士，拯溺救危，大有祖风，况又系妹丈致意，因此优待雨村，更又不同，便极力帮助。题奏之日，谋了一个复职。不上两月，便选了金陵应天府，辞了贾政，择日到任去了。不在话下。　　且说黛玉自那日弃舟登岸时，便有荣府打发轿子并拉行李的车辆伺候。这黛玉尝听得母亲说他外祖母家与别人家不同，他近日所见的这几个三等的仆妇，吃穿用度，已是不凡，何况今至其家。因此步步留心，时时在意，不多说一句话，不多行一步路，恐被人耻笑了去。自上了轿，进了城，从纱窗向外瞧了一瞧，其街市之繁华，人烟之阜盛，自非别处可比。又行了半日，忽见街北蹲着两个大石狮子，三间兽头大门，门前列坐着十来个华冠丽服之人。正门不开，只东西两角门有人出入。正门之上有一匾，匾上大书“敕造宁国府”五个大字。","黛玉想道：“这是外祖的长房了。”又往西不远，照样也是三间大门，方是荣国府，却不进正门，只由西角门而入。轿子抬着走了一射之地，将转弯时，便歇了轿，后面的婆子也都下来了。另换了四个眉目秀洁十七八岁的小厮上来抬着轿子，众婆子步下跟随。至一垂花门前落下，众小厮俱肃然退出，众婆子上前打起轿帘，扶黛玉下了轿。","黛玉扶着婆子的手，进了垂花门。两边是超手游廊，正中是穿堂，当地放着一个紫檀架子大理石屏风。转过屏风，小小三间厅房，厅后便是正房大院。正面五间上房，皆是雕梁画栋。两边穿山游廊厢房，挂着各色鹦鹉画眉等雀鸟。台阶上坐着几个穿红着绿的丫头，一见他们来了，都笑迎上来，道：“刚才老太太还念着呢，可巧就来了。”于是三四人争着打帘子。一面听得人说：“林姑娘来了！”","黛玉方进房，只见两个人扶着一位鬓发如银的老母迎上来。黛玉知是外祖母，正欲下拜，早被外祖母抱住，搂入怀中，“心肝儿肉”叫着大哭起来。当下侍立之人无不落泪，黛玉也哭个不休。待众人慢慢劝解住了，那黛玉方拜见了外祖母，贾母方一一指与黛玉道：“这是你大舅母。这是二舅母。这是你先前珠大哥的媳妇珠大嫂子。”黛玉一一拜见了。贾母又叫：“请姑娘们来。今日远客来了，可以不必上学去。”众人答应了一声，便去了两个。　　不一时，只见三个奶妈并五六个丫鬟拥着三位姑娘来了：第一个，肌肤微丰，身材合中，腮凝新荔，鼻腻鹅脂，温柔沉默，观之可亲；第二个，削肩细腰，长挑身材，鸭蛋脸儿，俊眼修眉，顾盼神飞，文彩精华，见之忘俗；第三个，身量未足，形容尚小。其钗环裙袄，三人皆是一样的妆束。黛玉忙起身迎上来见礼，互相厮认。归了坐位，丫鬟送上茶来。不过叙些黛玉之母如何得病，如何请医服药，如何送死发丧。不免贾母又伤感起来，因说：“我这些女孩儿，所疼的独有你母亲，今一旦先我而亡，不得见面，怎不伤心！”说着，携了黛玉的手，又哭起来。众人都忙相劝慰，方略略止住。","众人见黛玉年纪虽小，其举止言谈不俗，身体面貌虽弱不胜衣，却有一段风流态度，便知他有不足之症。因问：“常服何药？为何不治好了？”黛玉道：“我自来如此，从会吃饭时便吃药到如今了。经过多少名医，总未见效。那一年，我才三岁，听说来了一个癞头和尚，说要化我去出家，我父母自是不从。他又说：“既舍不得他，但只怕他的病一生也不能好的！若要好时，除非从此以后总不许见哭声，除父母之外，凡有外亲一概不见，方可平安了此一生。”这和尚疯疯癫癫说了这些不经之谈，也没人理他。如今还是吃人参养荣丸。”贾母道：“这正好，我这里正配丸药呢，叫他们多配一料就是了。”","一语未完，只听后院中有笑语声，说：“我来迟了，没得迎接远客！”黛玉思忖道：“这些人个个皆敛声屏气如此，这来者是谁，这样放诞无礼？……”心下想时，只见一群媳妇丫鬟拥着一个丽人从后房门进来。这个人打扮与姑娘们不同：彩绣辉煌，恍若神妃仙子。头上戴着金丝八宝攒珠髻，绾着朝阳五凤挂珠钗；项上戴着赤金盘螭缨络圈；身上穿着缕金百蝶穿花大红云缎窄裉袄，外罩五彩刻丝石青银鼠褂；下着翡翠撒花洋绉裙。一双丹凤三角眼，两弯柳叶吊梢眉。身量苗条，体格风骚。粉面含春威不露，丹唇未启笑先闻。","黛玉连忙起身接见。贾母笑道：“你不认得他。他是我们这里有名的一个“泼辣货”，南京所谓“辣子”你只叫他凤辣子就是了。”黛玉正不知以何称呼，众姊妹都忙告诉黛玉道：“这是琏二嫂子。”黛玉虽不曾识面，听见他母亲说过：“大舅贾赦之子贾琏娶的就是二舅母王氏的内侄女，自幼假充男儿教养，学名叫做王熙凤。”黛玉忙陪笑见礼，以“嫂”呼之。","这熙凤携着黛玉的手，上下细细打量一回，便仍送至贾母身边坐下，因笑道：“天下真有这样标致人儿！我今日才算看见了！况且这通身的气派竟不像老祖宗的外孙女儿，竟是个嫡亲的孙女儿似的。怨不得老祖宗天天嘴里心里放不下。──只可怜我这妹妹这么命苦：怎么姑妈偏就去世了呢！”说着，便用手帕拭泪。贾母笑道：“我才好了，你又来招我。你妹妹远路才来，身子又弱，也才劝住了。快别再提了。”","熙凤听了，忙转悲为喜道：“正是呢。我一见了妹妹，一心都在他身上，又是欢喜，又是伤心，竟忘了老祖宗了。该打，该打。”又忙拉着黛玉的手问道：“妹妹几岁了？可也上过学？现吃什么药？在这里别想家。要什么吃的，什么玩的，只管告诉我。丫头老婆们不好，也只管告诉我。”黛玉一一答应。一面熙凤又问人：“林姑娘的东西可搬进来了？带了几个人来？你们赶早打扫两间下房，让她们去歇歇。”","说话时，已摆了茶果上来。熙凤亲自布让。又见二舅母问他：“月钱放完了没有？”熙凤道：“放完了。刚才带了人到后楼上找缎子，找了半日，也没见昨儿太太说的那个，想必太太记错了。”王夫人道：“有没有，什么要紧！”因又说道：“该随手拿出两个来给你这妹妹裁衣裳啊。等晚上想着再叫人去拿罢。”熙凤道：“我倒先料着了。知道妹妹这两日必到，我已经预备下了，等太太回去过了目好送来。”王夫人一笑，点头不语。","当下茶果已撤，贾母命两个老嬷嬷带黛玉去见两个舅舅去。贾赦之妻邢氏忙起身笑回道：“我带了外甥女儿过去，到底便宜些。”贾母笑道：“正是呢。你也去罢，不必过来了。”","那邢夫人答应了，遂带着黛玉和王夫人作辞。大家送至穿堂垂花门前。早有众小厮拉过一辆翠幄清油车来，邢夫人携了黛玉坐上。众婆子放下车帘，方命小厮们抬起，拉至宽处，驾上驯骡，出了西角门，往东过荣府正门，入一黑油漆大门内，至仪门前，方下了车。邢夫人挽着黛玉的手进入院中。黛玉度其处必是荣府中之花园隔断过来的。进入三层仪门，果见正房厢房游廊，悉皆小巧别致，不似那边的轩峻壮丽，且院中随处之树木山石皆好。及进入正室，早有许多艳妆丽服之姬妾丫鬟迎着。","邢夫人让黛玉坐了，一面令人到外书房中请贾赦。一时回来说：“老爷说了：“连日身上不好，见了姑娘，彼此伤心，暂且不忍相见。劝姑娘不必伤怀想家，跟着老太太和舅母是和家里一样的。姐妹们虽拙，大家一处作伴，也可以解些烦闷。或有委屈之处，只管说，别外道了才是。””","黛玉忙站起身来一一答应了，再坐一刻，便告辞。邢夫人苦留吃过饭才去，黛玉笑回道：“舅母爱惜赐饭，原不应辞，只是还要过去拜见二舅舅，恐去迟了不恭。异日再领，望舅母容谅。”邢夫人笑道：“这倒是了。”遂命两个嬷嬷用方才坐来的车送过去。于是黛玉告辞。邢夫人送至仪门前，又嘱咐了众人几句，眼看着车去了方回来。","一时，黛玉进入荣府，下了车，只见一条大甬路，直接出大门来。众嬷嬷引着，便往东转弯，走过一座东西穿堂，向南大厅之后，至仪门内大院落。上面五间大正房，两边厢房，鹿顶耳门钻山，四通八达，轩昂壮丽，比各处不同。黛玉便知这方是正内室。进入堂屋，抬头迎面先见一个赤金九龙青地大匾，匾上写着斗大三个字是“荣禧堂”。后有一行小字：“某年月日书赐荣国公贾源”，又有“万几宸翰”之宝。大紫檀雕螭案上设着三尺多高青绿古铜鼎，悬着待漏随朝墨龙大画。一边是錾金彝，一边是玻璃盆。地下两溜十六张楠木圈椅。又有一副对联，乃是乌木联牌，镶着錾金字迹，道是：“座上珠玑昭日月，堂前黼黻焕烟霞。”下面一行小字是：“世教弟勋袭东安郡王穆莳拜手书。”","原来王夫人时常居坐宴息也不在这正室中，只在东边的三间耳房内。于是嬷嬷们引黛玉进东房门来。临窗大炕上铺着猩红洋毯，正面设着大红金钱蟒引枕，秋香色金钱蟒大条褥。两边设一对梅花式洋漆小几：左边几上摆着文王鼎，鼎旁匙箸香盒；右边几上摆着汝窑美人觚，里面插着时鲜花卉。地下面，西一溜四张大椅都搭着银红撒花椅搭，底下四副脚踏；两边又有一对高几，几上茗碗瓶花俱备。其余陈设不必细说。","老嬷嬷让黛玉上炕坐。炕沿上却也有两个锦褥对设。黛玉度其位次，便不上炕，只就东边椅上坐了。本房的丫鬟忙捧上茶来。黛玉一面吃茶，一面打量这些丫鬟们，妆饰衣裙，举止行动，果与别家不同。","茶未吃了，只见一个穿红绫袄青缎掐牙背心的丫鬟走来笑道：“太太说，请林姑娘到那边坐罢。”老嬷嬷听了，于是又引黛玉出来，到了东南三间小正房内。正面炕上横设一张炕桌，上面堆着书籍茶具，靠东壁面西设着半旧的青缎靠背引枕。王夫人却坐在西边下首，──亦是半旧青缎靠背坐褥──见黛玉来了，便往东让。黛玉心中料定这是贾政之位，因见挨炕一溜三张椅子上也搭着半旧的弹墨椅袱，黛玉便向椅上坐了。王夫人再三让他上炕，他方挨王夫人坐下。王夫人因说：“你舅舅今日斋戒去了，再见罢。只是有一句话嘱咐你：你三个姐妹倒都极好，以后一处念书，认字，学针线，或偶一顽笑，都有个尽让的。我就只一件不放心：我有一个孽根祸胎，是家里的“混世魔王”，今日因往庙里还愿去，尚未回来，晚上你看见就知道了。你只以后不要睬他，你这些姐姐妹妹都不敢沾惹他的。”","黛玉素闻母亲说过，“有个内侄，乃衔玉而生，顽劣异常，不喜读书，最喜在内帏厮混，外祖母又溺爱，无人敢管。”今见王夫人所说，便知是这位表兄，一面陪笑道：“舅母所说，可是那位衔玉而生的哥哥？在家时记得母亲常说，这位哥哥比我大一岁，小名就叫宝玉，性虽憨顽，说待姊妹们却是极好的。况我来了，自然和姊妹们一处，弟兄们是另院别房，岂有沾惹之理？”王夫人笑道：“你不知道原故。他和别人不同，自幼因老太太疼爱，原系和姐妹们一处娇养惯了的。若姐妹们不理他，他倒还安静些；若一日姐妹们和他多说了一句话，他心上一喜，便生出许多事来：所以嘱咐你别理会他。他嘴里一时甜言蜜语，一时有天没日，疯疯傻傻，只休信他。”　　黛玉一一的都答应着。忽见一个丫鬟来说：“老太太那里传晚饭了。”王夫人忙携了黛玉出后房门，由后廊往西出了角门，是一条南北甬路，南边是倒座三间小小抱厦厅，北边立着一个粉油大影壁，后有一个半大门，小小一所房屋。王夫人笑指向黛玉道：“这是你凤姐姐的屋子，回来你好往这里找他去。少什么东西，只管和他说就是了。”这院门上也有几个才总角的小厮，都垂手侍立。","王夫人遂携黛玉穿过一个东西穿堂，便是贾母的后院了，于是进入后房门。已有许多人在此伺候，见王夫人来，方安设桌椅。贾珠之妻李氏捧杯，熙凤安箸，王夫人进羹。贾母正面榻上独坐，两旁四张空椅。熙凤忙拉黛玉在左边第一张椅子上坐下，黛玉十分推让。贾母笑道：“你舅母和嫂子们是不在这里吃饭的，你是客，原该这么坐。”黛玉方告了坐，就坐了。贾母命王夫人也坐了。迎春姊妹三个告了坐方上来，迎春坐右手第一，探春左第二，惜春右第二。旁边丫鬟执着拂尘漱盂巾帕。李纨凤姐立于案旁布让。外间伺候的媳妇丫鬟虽多，却连一声咳嗽不闻。饭毕，各各有丫鬟用小茶盘捧上茶来。当日林家教女以惜福养身，每饭后必过片时方吃茶，不伤脾胃。今黛玉见了这里许多规矩不似家中，也只得随和着些。接了茶，又有人捧过漱盂来，黛玉也漱了口。又盥手毕，然后又捧上茶来，这方是吃的茶。","贾母便说：“你们去罢，让我们自在说说话儿。”王夫人遂起身，又说了两句闲话儿，方引李凤二人去了。贾母因问黛玉念何书，黛玉道：“刚念了《四书》。”黛玉又问姊妹们读何书，贾母道：“读什么书！不过认几个字罢了。”","一语未了，只听外面一阵脚步响，丫鬟进来报道宝玉来了。黛玉心想：“这个宝玉不知是怎样个惫懒人呢。……”及至进来一看，却是位青年公子。头上戴着束发嵌宝紫金冠，齐眉勒着二龙戏珠金抹额；一件二色金百蝶穿花大红箭袖，束着五彩丝攒花结长穗宫绦，外罩石青起花八团倭缎排穗褂；登着青缎粉底小朝靴。面若中秋之月，色如春晓之花，鬓若刀裁，眉如墨画，鼻如悬胆，睛若秋波。虽怒时而似笑，即瞋视而有情。项上金螭缨络，又有一根五色丝绦，系着一块美玉。","黛玉一见便吃一大惊，心中想道：“好生奇怪！倒像在那里见过的？何等眼熟！……”只见这宝玉向贾母请了安，贾母便命：“去见你娘来。”即转身去了。一回再来时，已换了冠带。头上周围一转的短发，都结成小辫，红丝结束，共攒至顶中胎发，总编一根大辫，黑亮如漆，从顶至梢，一串四颗大珠，用金八宝坠脚。身上穿着银红撒花半旧大袄，仍旧戴着项圈、宝玉、寄名锁、护身符等物；下面半露松绿撒花绫裤，锦边弹墨袜，厚底大红鞋。越显得面如敷粉，唇若施脂，转盼多情，语言若笑。天然一段风韵，全在眉梢；平生万种情思，悉堆眼角。──看其外貌是极好，却难知其底细。后人有《西江月》二词，批的极确。词曰：","无故寻愁觅恨，有时似傻如狂。纵然生得好皮囊，腹内原来草莽。","潦倒不通世务，愚顽怕读文章。行为偏僻性乖张，那管世人诽谤？","又曰：","盎贵不知乐业，贫穷难耐凄凉。可怜辜负好时光，于国于家无望。","天下无能第一，古今不肖无双。寄言纨袴与膏粱：莫效此儿形状！","却说贾母见他进来，笑道：“外客没见就脱了衣裳了？──还不去见你妹妹呢。”宝玉早已看见了一个袅袅婷婷的女儿，便料定是林姑妈之女，忙来见礼。归了座，细看时，真是与众各别。只见：","两弯似蹙非蹙笼烟眉，一双似喜非喜含情目。态生两靥之愁，娇袭一身之病。泪光点点，娇喘微微。闲静似娇花照水，行动如弱柳扶风。心较比干多一窍，病如西子胜三分。　　宝玉看罢，笑道：“这个妹妹，我曾见过的。”贾母笑道：“又胡说了。你何曾见过？”宝玉笑道：“虽没见过，却看着面善，心里倒像是旧相认识，恍若远别重逢的一般。”贾母笑道：“好，好！这么更相和睦了。”　　宝玉便走向黛玉身边坐下，又细细打量一番，因问：“妹妹可曾读书？”黛玉道：“不曾读书，只上了一年学，些须认得几个字。”宝玉又道：“妹妹尊名？”黛玉便说了名。宝玉又道：“表字？”黛玉道：“无字。”宝玉笑道：“我送妹妹一字，莫若“颦颦”二字，极妙。”探春便道：“何处出典？”宝玉道：“《古今人物通考》上说：“西方有石名黛，可代画眉之墨。”况这妹妹，眉尖若蹙，取这个字，岂不甚美？”探春笑道：“只怕又是杜撰！”宝玉笑道：“除了《四书》，杜撰的也太多呢。”因又问黛玉：“可有玉没有？”众人都不解。黛玉便忖度着“因他有玉，所以才问我的”，便答道：“我没有玉。你那玉也是件稀氨物儿，岂能人人皆有？”","宝玉听了，登时发作起狂病来，摘下那玉，就狠命摔去，骂道：“什么罕物！人的高下不识，还说灵不灵呢！我也不要这劳什子！”吓的地下众人一拥争去拾玉。贾母急的搂了宝玉，道：“孽障！你生气，要打骂人容易，何苦摔那命根子！”宝玉满面泪痕，哭道：“家里姐姐妹妹都没有，单我有，我说没趣儿；如今来了这个神仙似的妹妹也没有，可知这不是个好东西。”贾母忙哄他道：“你这妹妹原有玉来着，因你姑妈去世时，舍不得你妹妹，无法可处，遂将他的玉带了去：一则全殉葬之礼，尽你妹妹的孝心；二则你姑妈的阴灵儿也可权作见了你妹妹了。因此，他说没有，也是不便夸张的意思啊。你还不好生带上，仔细你娘知道！”说着，便向丫鬟手中接来，亲与他带上。宝玉听如此说，想了一想，也就不生别论。","当下奶娘来问黛玉房舍。贾母便说：“将宝玉挪出来，同我在套间暖阁里，把林姑娘暂且安置在碧纱橱里。等过了残冬，春天再给他们收拾房屋，另作一番安置罢。”宝玉道：“好祖宗！我就在碧纱橱外的床上很妥当，又何必出来闹的老祖宗不得安静呢？”贾母想一想，说：“也罢了。”每人一个奶娘并一个丫头照管，余者在外间上夜听唤。一面早有熙凤命人送了一顶藕合色花帐并锦被缎褥之类。","黛玉只带了两个人来：一个是自己的奶娘王嬷嬷，一个是十岁的小丫头，名唤雪雁。贾母见雪雁甚小，一团孩气，王嬷嬷又极老，料黛玉皆不遂心，将自己身边一个二等小丫头，名唤鹦哥的，与了黛玉。亦如迎春等一般：每人除自幼乳母外，另有四个教引嬷嬷；除贴身掌管钗钏盥沐两个丫头外，另有四五个洒扫房屋来往使役的小丫头。　　当下王嬷嬷与鹦哥陪侍黛玉在碧纱橱内；宝玉乳母李嬷嬷并大丫头名唤袭人的陪侍在外面大床上。","原来这袭人亦是贾母之婢，本名蕊珠。贾母因溺爱宝玉，恐宝玉之婢不中使，素喜蕊珠心地纯良，遂与宝玉。宝玉因知他本姓花，又曾见旧人诗句有“花气袭人”之句，遂回明贾母，即把蕊珠更名袭人。　　却说这袭人倒有些痴处：伏侍贾母时，心中只有贾母；如今跟了宝玉，心中又只有宝玉了。只因宝玉性情乖僻，每每规谏，见宝玉不听，心中着实忧郁。是晚，宝玉李嬷嬷已睡了。他见里面黛玉鹦哥犹未安歇，他自卸了妆，悄悄的进来，笑问：“姑娘怎么还不安歇？”黛玉忙笑让：“姐姐请坐。”袭人在床沿上坐了。鹦哥笑道：“林姑娘在这里伤心，自己淌眼抹泪的说：“今儿才来了，就惹出你家哥儿的狂病来。倘或摔坏了那玉，岂不是因我之过？”所以伤心。我好容易劝好了。”袭人道：“姑娘快别这么着！将来只怕比这更奇怪的笑话儿还有呢。若为他这种行状，你多心伤感，只怕你还伤感不了呢。快别多心！”黛玉道：“姐姐们说的，我记着就是了。”又叙了一回，方才安歇。","次早起来，省饼贾母，因往王夫人处来。正值王夫人与熙凤在一处拆金陵来的书信，又有王夫人的兄嫂处遣来的两个媳妇儿来说话。黛玉虽不知原委，探春等却晓得是议论金陵城中居住的薛家姨母之子──表兄薛蟠，倚财仗势打死人命，现在应天府案下审理。如今舅舅王子腾得了信，遣人来告诉这边，意欲唤取进京之意。毕竟怎的，下回分解。"],"cpLength":7981},"hlm-23":{"chapterId":"hlm-23","bookId":"hlm","fileIndex":22,"number":23,"title":"第二十三回 西厢记妙词通戏语　牡丹亭艳曲警芳心","paragraphs":["话说贾母次日仍领众人过节。那元妃却自幸大观园回宫去后，便命将那日所有的题咏，命探春钞录妥协，自己编次优劣，又令大观园勒石，为千古风流雅事。因此，贾政命人选拔精工，大观园磨石镌字。贾珍率领贾蓉贾蔷等监工。因贾蔷又管理着文官等十二个女戏子并行头等事，不得空闲，因此又将贾菖、贾菱、贾萍唤来监工。一日烫蜡钉朱，动起手来。这也不在话下。","且说那玉皇庙并达摩庵两处，一班的十二个小沙弥并十二个小道士，如今挪出大观园来，贾政正想发到各庙去分住。不想后街上住的贾芹之母杨氏，正打算到贾政这边谋一个大小事件与儿子管管，也好弄些银钱使用，可巧听见这件事，便坐车来求凤姐。凤姐因见他素日嘴头儿乖滑，便依允了。想了几句话，便回了王夫人，说：“这些小和尚小道士，万不可打发到别处去，一时娘娘出来，就要应承的。倘或散了，若再用时，可又费事。依我的主意：不如将他们都送到家庙铁槛寺去，月间不过派一个人拿几两银子去买柴米就是了。说声用，走去叫一声就来，一点儿不费事。”","王夫人听了，便商之于贾政。贾政听了，笑道：“倒是提醒了我。就是这样。”实时唤贾琏。　　贾琏正同凤姐吃饭，一闻呼唤，放下饭便走。凤姐一把拉住，笑道：“你先站住，听我说话：要是别的事，我不管；要是为小和尚小道士们的事，好歹你依着我这么着。”如此这般，教了一套话。贾琏摇头笑道：“我不管！你有本事你说去。”凤姐听说，把头一梗，把筷子一放，腮上带笑不笑的瞅着贾琏道：“你是真话，还是玩话儿？”贾琏笑道：“西廊下五嫂子的儿子芸儿来求了我两三遭，要件事管管，我应了，叫他等着。好容易出来这件事，你又夺了去。”凤姐儿笑道：“你放心。园子东北角上，娘娘说了，还叫多多的种松柏树；楼底下，还叫种些花草儿。等这件事出来，我包管叫芸儿管这工程就是了。”贾琏道：“这也罢了。”因又悄悄的笑道：“我问你。我昨儿晚上不过要改个样儿，你为什么就那么扭手扭脚的呢？”凤姐听了，把脸飞红，嗤的一笑，向贾琏啐了一口，依旧低下头吃饭。","贾琏笑着一径去了，走到前面，见了贾政，果然是为小和尚的事。贾琏便依着凤姐的话，说道：“看来芹儿倒出息了，这件事竟交给他去管。横竖照里头的规例，每月支领就是了。”贾政原不大理论这些小事，听贾琏如此说，便依允了。贾琏回房，告诉凤姐，凤姐即命人去告诉杨氏。贾芹便来见贾琏夫妻，感谢不尽。凤姐又做情，先支三个月的费用，叫他写了领字，贾琏画了押，登时发了对牌出去。银库上按数发出三个月的供给来──白花花三百两。贾芹随手拈了一块与掌平的人，“叫他们喝了茶罢。”于是命小厮拿了回家，与母亲商议。登时雇车坐上，又雇了几辆车子，至荣国府角门前，唤出二十四个人来，坐上车子，一径往城外铁槛寺去了。当下无话。","如今且说那元妃在宫中编次大观园题咏，忽然想起那园中的景致，自从幸过之后，贾政必定敬谨封锁，不叫人进去，岂不辜负此园？况家中现有几个能诗会赋的姊妹们，何不命他们进去居住？也不使佳人落魄，花柳无颜。却又想宝玉自幼在姊妹丛中长大，不比别的兄弟，若不命他进去，又怕冷落了他，恐贾母王夫人心上不喜，须得也命他进去居住方妥。命太监夏忠到荣府下一道谕：命宝钗等在园中居住，不可封锢；命宝玉也随进去读书。　　贾政王夫人接了谕命，夏忠去后，便回明贾母，遣人进去各处收拾打扫，安设帘幔床帐。别人听了，还犹自可，惟宝玉喜之不胜。正和贾母盘算，要这个，要那个，忽见丫鬟来说：“老爷叫宝玉。”宝玉呆了半晌，登时扫了兴，脸上转了色，便拉着贾母，扭的扭股儿糖似的，死也不敢去。贾母只得安慰他道：“好宝贝，你只管去。有我呢，他不敢委屈了你。况你做了这篇好文章。想必娘娘叫你进园去住，他吩咐你几句话，不过是怕你在里头淘气。他说什么，你只好生答应着就是了。”一面安慰，一面唤了两个老嬷嬷来，吩咐：“好生带了宝玉去，别叫他老子唬着他。”老嬷嬷答应了。","宝玉只得前去，一步挪不了三寸，蹭到这边来。可巧贾政在王夫人房中商议事情，金钏儿、彩云、彩凤、绣鸾、绣凤等众丫鬟都廊檐下站着呢。一见宝玉来，都抿着嘴儿笑他。金钏儿一把拉着宝玉，悄悄的说道：“我这嘴上是才擦的香香甜甜的胭脂，你这会子可吃不吃了？”彩云一把推开金钏儿，笑道：“人家心里发虚，你还怄他！──趁这会子喜欢，快进去罢。”宝玉只得挨门进去。原来贾政和王夫人都在里间呢。赵姨娘打起帘子来，宝玉挨身而入，只见贾政和王夫人对坐在炕上说话儿。地下一溜椅子，迎春、探春、惜春、贾环四人都坐在那里。一见他进来，探春、惜春和贾环都站起来。","贾政一举目见宝玉站在跟前，神彩飘逸，秀色夺人；又看看贾环，人物委琐，举止粗糙；忽又想起贾珠来。再看看王夫人只有这一个亲生的儿子，素爱如珍；自己的胡须将已苍白。因此上，把平日嫌恶宝玉之心不觉减了八九分。半晌，说道：“娘娘吩咐，说你日日在外游嬉，渐次疏懒了工课，如今叫禁管你和姐妹们在园里读书。你可好生用心学习。再不守分安常，你可仔细着！”","宝玉连连答应了几个“是”，王夫人便拉他在身边坐下。他姊弟三人依旧坐下。王夫人摸索着宝玉的脖项，说道：“前儿的丸药都吃完了没有？”宝玉答应道：“还有一丸。”王夫人道：“明儿再取十丸来，天天临睡时候，叫袭人伏侍你吃了再睡。”宝玉道：“从太太吩咐了，袭人天天临睡打发我吃的。”","贾政便问道：“谁叫袭人？”王夫人道：“是个丫头。”贾政道：“丫头不拘叫个什么罢了，是谁起这样刁钻名字？”王夫人见贾政不喜欢了，便替宝玉掩饰道：“是老太太起的。”贾政道：“老太太如何晓得这样的话？一定是宝玉。”宝玉见瞒不过，只得起身回道：“因素日读诗，曾记古人有句诗云：“花气袭人知昼暖”，因这丫头姓花，便随意起的。”王夫人忙向宝玉说道：“你回去改了罢。──老爷也不用为这小事生气。”贾政道：“其实也无妨碍，不用改。只可见宝玉不务正，专在这些浓词艳诗上做工夫。”说毕，断喝了一声：“作孽的畜生！还不出去！”王夫人也忙道：“去罢，去罢。怕老太太等吃饭呢。”","宝玉答应了，慢慢的退出去，向金钏儿笑着，伸伸舌头，带着两个老嬷嬷，一溜烟去了。刚至穿堂门前，只见袭人倚门而立，见宝玉平安回来，堆下笑来，问道：“叫你做什么？”宝玉告诉：“没有什么。不过怕我进园淘气，吩咐吩咐。”一面说，一面回至贾母跟前，回明原委。只见黛玉正在那里，宝玉便问他：“你住在那一处好？”黛玉正盘算这事，忽见宝玉一问，便笑道：“我心里想着潇湘馆好。我爱那几竿竹子，隐着一道曲栏，比别处幽静些。”宝玉听了，拍手笑道：“合了我的主意了！我也要叫你那里住。我就住怡红院。咱们两个又近，又都清幽。”","二人正计议着，贾政遣人来回贾母，说是二月二十二日是好日子，哥儿姐儿们就搬进去罢。这几日便遣人进去分派收拾。宝钗住了蘅芜院，黛玉住了潇湘馆，迎春住了缀锦楼，探春住了秋掩书斋，惜春住了蓼风轩，李纨住了稻香村，宝玉住了怡红院。每一处添两个老嬷嬷，四个丫头。除各人的奶娘亲随丫头外，另有专管收拾打扫的。至二十二日，一齐进去。登时园内花招绣带，柳拂香风，不似前番那等寂寞了。","闲言少叙。且说宝玉自进园来，心满意足，再无别项可生贪求之心。每日只和姊妹丫鬟们一处，或读书，或写字，或弹琴下棋，作画吟诗，以至描鸾刺凤，斗草簪花，低吟悄唱，拆字猜枚，无所不至，倒也十分快意。他曾有几首四时即事诗，虽不算好，却是真情真景。","春夜即事云：","霞绡云幄任铺陈，隔巷蛙声听未真。枕上轻寒窗外雨，眼前春色梦中人。","盈盈烛泪因谁泣？点点花愁为我嗔。自是小鬟娇懒惯，拥衾不耐笑言频。","夏夜即事云：","倦绣佳人幽梦长，金笼鹦鹉唤茶汤。窗明麝月开宫镜，室霭檀云品御香。","琥珀杯倾荷露滑，玻璃槛纳柳风凉。水亭处处齐纨动，帘卷朱楼罢晚妆。","秋夜即事云：","绛芸轩里绝喧哗，桂魄流光浸茜纱。苔锁石纹容睡鹤，井飘桐露湿栖鸦。","抱衾婢至舒金凤，倚槛人归落翠花。静夜不眠因酒渴，沉烟重拨索烹茶。","冬夜即事云：","梅魂竹梦已三更，锦罽鹴衾睡未成。松影一庭惟见鹤，梨花满地不闻莺。","女奴翠袖诗怀冷，公子金貂酒力轻。却喜侍儿知试茗，扫将新雪及时烹。","不说宝玉闲吟。且说这几首诗，当时有一等势利人见是荣国府十二三岁的公子做的，抄录出来，各处称颂；再有等轻薄子弟，爱上那风流妖艳之句，也写在扇头壁上，不时吟哦赏赞：因此上，竟有人来寻诗觅字，倩画求题。这宝玉一发得意了，每日家做这些外务。谁想静中生动，忽一日不自在起来，这也不好，那也不好，出来进去，只是发闷。园中那些女孩子正是混沌世界，天真烂漫之时，坐卧不避，嬉笑无心，那里知宝玉此时的心事？","那宝玉不自在，便懒在园内，只想外头鬼混，却痴痴的，又说不出什么滋味来。茗烟见他这样，因想与他开心。左思右想，皆是宝玉玩烦了的，只有一件，不曾见过。想毕，便走到书坊内，把那古今小说并那飞燕、合德、则天、玉环的外传与那传奇角本买了许多，孝敬宝玉。宝玉一看，如得珍宝。茗烟又嘱咐道：“不可拿进园去，叫人知道了，我就“吃不了兜着走”了！”宝玉那里肯不拿进去？踟蹰再四，单把那文理雅道些的拣了几套进去，放在床顶上，无人时方看；那粗俗过露的都藏于外面书房内。　　那日正当三月中浣，早饭后，宝玉携了一套《会真记》，走到沁芳闸桥那边桃花底下一块石上坐着，展开《会真记》，从头细看。正看到“落红成阵”，只见一阵风过，树上桃花吹下一大斗来，落得满身、满书、满地，皆是花片。宝玉要抖将下来，恐怕脚步践踏了，只得兜了那花瓣儿，来至池边，抖在池内。那花瓣儿浮在水面，飘飘荡荡，竟流出沁芳闸去了。回来，只见地下还有许多花瓣。","宝玉正踟蹰间，只听背后有人说道：“你在这里做什么？”宝玉一回头，却是黛玉来了，肩上担着花锄，花锄上挂着纱囊，手内拿着花帚。宝玉笑道：“来的正好。你把这些花瓣儿都扫起来，撂在那水里去罢。我才撂了好些在那里了。”黛玉道：“撂在水里不好。你看这里的水干凈，只一流出去，有人家的地方儿什么没有？仍旧把花糟蹋了。那畸角儿上，我有一个花冢。如今把他扫了，装在这绢袋里，埋在那里，日久随土化了，岂不干凈？”","宝玉听了，喜不自禁，笑道：“待我放下书，帮你来收拾。”黛玉道：“什么书？”宝玉见问，慌的藏了，便说道：“不过是《中庸》《大学》。”黛玉道：“你又在我跟前弄鬼。趁早儿给我瞧瞧，好多着呢。”宝玉道：“妹妹，若论你，我是不怕的，你看了，好歹别告诉人。真是好文章！你要看了，连饭也不想吃呢！”一面说，一面递过去。黛玉把花具放下，接书来瞧。从头看去，越看越爱，不顿饭时，已看了好几出了。但觉词句警人，余香满口。一面看了，只管出神，心内还默默记诵。宝玉笑道：“妹妹，你说好不好？”黛玉笑着点头儿。宝玉笑道：“我就是个“多愁多病”的身，你就是那“倾国倾城”的貌！”","黛玉听了，不觉带腮连耳的通红了。登时竖起两道似蹙非蹙的眉，瞪了一双似睁非睁的眼，桃腮带怒，薄面含嗔，指着宝玉道：“你这该死的胡说了！好好儿的把这些淫词艳曲弄了来，说这些混帐话欺负我！我告诉舅舅、舅母去。”说到“欺负”二字，就把眼圈儿红了，转身就走。","宝玉急了，忙向前拦住道：“好妹妹，千万饶我这一遭儿罢！要有心欺负你，明儿我掉在池子里，叫个癞头鼋吃了去，变个大忘八，等你明儿做了一品夫人病老归西的时候儿，我往你坟上替你驼一辈子碑去。”说的黛玉扑嗤的一声笑了，一面揉着眼，一面笑道：“一般唬的这么个样儿，还只管胡说。呸！原来也是个银样蜡枪头！”宝玉听了，笑道：“你说说，你这个呢？我也告诉去。”黛玉笑道：“你说你会过目成诵，难道我就不能一目十行了？”宝玉一面收书，一面笑道：“正经快把花儿埋了罢，别提那些个了。”二人便收拾落花。","正才掩埋妥协，只见袭人走来。说道：“那里没找到，摸在这里来了！那边大老爷身上不好，姑娘们都过去请安去了，老太太叫打发你去呢。快回去换衣裳罢。”宝玉听了，忙拿了书，别了黛玉，同袭人回房换衣。不提。　　这里黛玉见宝玉去了，听见众姐妹也不在房中，自己闷闷的，正欲回房，刚走到梨香院墙角外，只听见墙内笛韵悠扬，歌声婉转，黛玉便知是那十二个女孩子演习戏文。虽未留心去听，偶然两句吹到耳朵内，明明白白，一字不落，道：“原来是姹紫嫣红开遍，似这般，都付与断井颓垣！”黛玉听了，倒也十分感慨缠绵，便止步侧耳细听。又唱道是：“良辰美景奈何天，赏心乐事谁家院？”听了这两句，不觉点头自叹，心下自思：“原来戏上也有好文章！可惜世人只知看戏，未必能领略其中的趣味。”想毕，又后悔不该胡想，耽误了听曲子。再听时，恰唱到：“只为你如花美眷，似水流年。”黛玉听了这两句，不觉心动神摇。又听道“你在幽闺自怜”等句，越发如醉如痴，站立不住，便一蹲身，坐在一块山子石上，细嚼“如花美眷，似水流年”八个字的滋味。忽又想起前日见古人诗中有“水流花谢两无情”之句；再词中又有“流水落花春去也，天上人间”之句；又兼方才所见《西厢记》中“花落水流红，闲愁万种”之句：都一时想起来，凑聚在一处。仔细忖度，不觉心痛神驰，眼中落泪。正没个开交处，忽觉身背后有人拍了他一下，及至回头看时───未知是谁，下回分解。"],"cpLength":5270},"hlm-27":{"chapterId":"hlm-27","bookId":"hlm","fileIndex":26,"number":27,"title":"第二十七回 滴翠亭杨妃戏彩蝶　埋香冢飞燕泣残红","paragraphs":["话说黛玉正自悲泣，忽听院门响处，只见宝钗出来了，宝玉袭人一群人都送出来。待要上去问着宝玉，又恐当着众人问，羞了宝玉不便，因而闪过一旁，让宝钗去了，宝玉等进去关了门，方转过来，尚望着门洒了几点泪。自觉无味，转身回来，无精打彩的卸了残妆。","紫鹃雪雁素日知道黛玉的情性：无事闷坐，不是愁眉，便是长叹，且好端端的，不知为着什么，常常的便自泪不干的。先时还有人解劝，或怕他思父母，想家乡，受委屈，用话来宽慰。谁知后来一年一月的，竟是常常如此，把这个样儿看惯了，也都不理论了。所以也没人去理他，由他闷坐，只管外间自便去了。","那黛玉倚着床栏杆，两手抱着膝，眼睛含着泪，好似木雕泥塑的一般，直坐到二更多天，方才睡了。一宿无话。","至次日，乃是四月二十六日。原来这日未时交芒种节。尚古风俗：凡交芒种节的这日，都要设摆各色礼物祭饯花神。言芒种一过便是夏日了，众花皆谢，花神退位，须要饯行。闺中更兴这件风俗，所以大观园中之人都早起来了。那些女孩子们，或用花瓣柳枝，编成轿马的；或用绫锦纱罗，迭成干旄旌幢的；都用彩线系了。每一棵树头，每一枝花上，都系了这些物事。满园里绣带飘飖，花枝招展。更兼这些人打扮的桃羞杏让，燕妒莺惭，一时也道不尽。","且说宝钗、迎春、探春、惜春、李纨、凤姐等并大姐儿、香菱与众丫鬟们，都在园里玩耍，独不见黛玉。迎春因说道：“林妹妹怎么不见？好个懒丫头！这会子难道还睡觉不成？”宝钗道：“你们等着，等我去闹了他来。”说着，便撂下众人，一直往潇湘馆来。正走着，只见文官等十二个女孩子也来了，上来问了好，说了一回闲话儿才走开。宝钗回身指道：“他们都在那里呢，你们找他们去。我找林姑娘去，就来。”说着，逶迤往潇湘馆来。忽然抬头见宝玉进去了，宝钗便站住，低头想了一想：宝玉和黛玉是从小儿一处长大的，他兄妹间多有不避嫌疑之处，嘲笑不忌，喜怒无常；况且黛玉素多猜忌，好弄小性儿：此刻自己也跟进去，一则宝玉不便，二则黛玉嫌疑，倒是回来的妙。想毕，抽身回来。刚要寻别的姊妹去，忽见面前一双玉色蝴蝶，大如团扇，一上一下，迎风翩跹，十分有趣。宝钗意欲扑了来玩耍，遂向袖中取出扇子来向草地下来扑。只见那一双蝴蝶，忽起忽落，来来往往，将欲过河去了。引的宝钗蹑手蹑脚的，一直跟到池边滴翠亭上，香汗淋漓，娇喘细细。宝钗也无心扑了，刚欲回来，只听那亭里边嘁嘁喳喳有人说话。原来这亭子四面俱是游廊曲栏，盖在池中水上，四面雕镂槅子，糊着纸。","宝钗在亭外听见说话，便煞住脚，往里细听。只听说道：“你瞧。这绢子果然是你丢的那一块，你就拿着；要不是，就还芸二爷去。”又有一个说：“可不是我那块？拿来给我罢。”又听道：“你拿什么谢我呢？难道白找了来不成？”又答道：“我已经许了谢你，自然是不哄你的。”又听说道：“我找了来给你，自然谢我；但只是那拣的人，你就不谢他么？”那一个又说道：“你别胡说。他是个爷们家，拣了我们的东西，自然该还的，叫我拿什么谢他呢？”又听说道：“你不谢他，我怎么回他呢？况且他再三再四的和我说了，若没谢的，不许我给你呢。”半晌，又听说道：“也罢，拿我这个给他，算谢他的罢。──你要告诉别人呢？须得起个誓。”又听说道：“我要告诉人，嘴上就长一个疔，日后不得好死！”又听说道：“嗳哟！咱们只顾说，看仔细有人来悄悄的在外头听见！不如把这槅子都推开了，就是人见咱们在这里，他们只当我们说玩话儿呢。走到跟前，咱们也看的见，就别说了。”","宝钗外面听见这话，心中吃惊，想道：“怪道从古至今那些奸淫狗盗的人，心机都不错！这一开了，见我在这里，他们岂不臊了？况且说话的语音，大似宝玉房里的小红，他素昔眼空心大，是个头等刁钻古怪的丫头。今儿我听了他的短儿，“人急造反，狗急跳墙”，不但生事，而且我还没趣。如今便赶着躲了，料也躲不及，少不得要使个“金蝉脱壳”的法子。”犹未想完，只听咯吱一声，宝钗便故意放重了脚步，笑着叫道：“颦儿！我看你往那里藏！”一面说，一面故意往前赶。","那亭内的小红、坠儿刚一推窗，只听宝钗如此说着，往前赶，两个人都唬怔了。宝钗反向他二人笑道：“你们把林姑娘藏在那里了？”坠儿道：“何曾见林姑娘了？”宝钗道：“我才在河那边看着林姑娘在这里蹲着弄水儿呢。我要悄悄的唬他一跳，还没有走到跟前，他倒看见我了，朝东一绕，就不见了。别是藏在里头了？”一面说，一面故意进去寻了一寻，抽身就走，口内说道：“一定又钻在山子洞里去了。遇见蛇，咬一口也罢了！”一面说，一面走，心中又好笑：“这件事算遮过去了，不知他二人怎么样？”","谁知小红听了宝钗的话，便信以为真，让宝钗去远，便拉坠儿，道：“了不得了！林姑娘蹲在这里，一定听了话去了。”坠儿听了，也半日不言语。小红又道：“这可怎么样呢？”坠儿道：“听见了，管谁筋疼，各人干各人的就完了。”小红道：“要是宝姑娘听见，还罢了。那林姑娘嘴里又爱克薄人，心里又细，他一听见了，倘或走露了，怎么样呢？”","二人正说着，只见香菱、臻儿、司棋、侍书等上亭子来了。二人只得掩着这话，且和他们玩笑。只见凤姐儿站在山坡上招手儿。小红便连忙弃了众人，跑至凤姐前，堆着笑问：“奶奶使唤做什么事？”凤姐打量了一回，见他生的干净俏丽，说话知趣，因笑道：“我的丫头们今儿没跟进我来。我这会子想起一件事来，要使唤个人出去，不知你能干不能干？说的齐全不齐全？”小红笑道：“奶奶有什么话，只管吩咐我说去；若说的不齐全，误了奶奶的事，任凭奶奶责罚就是了。”凤姐笑道：“你是那位姑娘屋里的？我使你出去，他回来找你，我好替你说。”小红道：“我是宝二爷屋里的。”凤姐听了，笑道：“嗳哟！你原来是宝玉屋里的，怪道呢。也罢了，等他问，我替你说。你到我们家告诉你平姐姐：外头屋里桌子上汝窑盘子架儿底下放着一卷银子，那是一百二十两，给绣匠的工价，等张材家的来，当面秤给他瞧了，再给他拿去。还有一件事：里头床头儿上有个小荷包儿，拿了来。”","小红听说，答应着，撤身去了。不多时回来，不见凤姐在山坡上了。因见司棋从山洞里出来，站着系带子，便赶来问道：“姐姐，不知道二奶奶往那里去了？”司棋道：“没理论。”小红听了，回身又往四下里一看，只见那边探春宝钗在池边看鱼。小红上来陪笑道：“姑娘们，可知道二奶奶刚才那里去了？”探春道：“往你大奶奶院里找去。”","小红听了，再往稻香村来，顶头见晴雯、绮霞、碧痕、秋纹、麝月、侍书、入画、莺儿等一群人来了。晴雯一见小红，便说道：“你只是疯罢！院子里花儿也不浇，雀儿也不喂，茶炉子也不弄，就在外头逛。”小红道：“昨儿二爷说了，今儿不用浇花儿，过一日浇一回。我喂雀儿的时候儿，你还睡觉呢。”碧痕道：“茶炉子呢？”小红道：“今儿不该我的班儿，有茶没茶，别问我。”绮霞道：“你听听他的嘴！你们别说了，让他逛罢。”小红道：“你们再问问，我逛了没逛。二奶奶才使唤我说话取东西去。”说着，将荷包举给他们看，方没言语了。大家走开。晴雯冷笑道：“怪道呢！原来爬上高枝儿去了，就不服我们说了。不知说了一句话，半句话，名儿姓儿知道了没有，就把他兴头的这个样儿！这一遭半遭儿的也算不得什么；过了后儿，还得听呵！──有本事从今儿出了这园子，长长远远的在高枝儿上才算好的呢。”一面说着，去了。","这里小红听了，不便分证，只得忍气，来找凤姐。到了李氏房中，果见凤姐在这里和李氏说话儿呢。小红上来回道：“平姐姐说，奶奶刚出来了，他就把银子收起来了；才张材家的来取，当面秤了给他拿了去了。”说着，将荷包递上去。又道：“平姐姐叫我来回奶奶：才旺儿进来讨奶奶的示下，好往那家子去，平姐姐就把那话按着奶奶的主意打发他去了。”凤姐笑道：“他怎么按着我的主意打发去了呢？”小红道：“平姐姐说：“我们奶奶问这里奶奶好。我们二爷没在家。虽然迟了两天，只管请奶奶放心。等五奶奶好些，我们奶奶还会了五奶奶来瞧奶奶呢。五奶奶前儿打发了人来说，舅奶奶带了信来了，问奶奶好，还要和这里的姑奶奶寻几丸延年神验万金丹。若有了，奶奶打发人来，只管送在我们奶奶这里。明儿有人去，就顺路给那边舅奶奶带了去。””","小红还未说完，李氏笑道：“嗳哟！这话我就不懂了。什么“奶奶”“爷爷”的一大堆。”凤姐笑道：“怨不得你不懂，这是四五门子的话呢。”说着，又向小红笑道：“好孩子，难为你说的齐全，不像他们扭扭捏捏蚊子似的。──嫂子不知道，如今除了我随手使的这几个丫头老婆之外，我就怕和别人说话。他们必定把一句话拉长了作两三截儿，咬文嚼字，拿着腔儿，哼哼唧唧的，急的我冒火，他们那里知道？我们平儿先也是这么着。我就问着他：难道必定装蚊子哼哼就算美人儿了？说了几遭儿，才好些儿了。”李纨笑道：“都像你泼辣货才好！”凤姐道：“这个丫头就好。刚才这两遭说话虽不多，口角儿就很剪断。”说着，又向小红笑道：“明儿你伏侍我罢，我认你做干女孩儿。我一调理，你就出息了。”","小红听了，扑哧一笑。凤姐道：“你怎么笑？你说我年轻，比你能大几岁，就做你的妈了？你做春梦呢！你打听打听，这些人比你大的赶着我叫妈，我还不理呢。今儿抬举了你了。”小红笑道：“我不是笑这个，我笑奶奶认错了辈数儿了：我妈是奶奶的干女孩儿，这会子又认我做干女孩儿。”凤姐道：“谁是你妈？”李纨笑道：“你原来不认的他？他是林之孝的女孩儿。”凤姐听了，十分诧异，因说道：“哦！是他的丫头啊！”又笑道：“林之孝两口子，都是锥子扎不出一声儿来的。我成日家说，他们倒是配就了的一对儿：一个天聋，一个地哑。那里承望养出这么个伶俐丫头来！──你十几了？”小红道：“十七岁了。”又问名字。小红道：“原叫红玉，因为重了宝二爷，如今只叫小红了。”　　凤姐听说，将眉一皱，把头一回，说道：“讨人嫌的很！得了玉的便宜似的，你也玉，我也玉。”因说：“嫂子不知道。我和他妈说：“赖大家的如今事多，也不知这府里谁是谁，你替我好好儿的挑两个丫头我使。”他只管答应着。他饶不挑，倒把他的女孩儿送给别处去。难道跟我必定不好？”李纨笑道：“你可是又多心了。进来在先，你说在后，怎么怨的他妈？”凤姐也笑道：“既这么着，明儿我和宝玉说，叫他再要人，叫这丫头跟我去。──可不知本人愿意不愿意？”小红笑道：“愿意不愿意，我们也不敢说。只是跟着奶奶，我们学些眉眼高低，出入上下，大小的事儿，也得见识见识。”刚说着，只见王夫人的丫头来请，凤姐便辞了李纨去了。小红自回怡红院去。不在话下。","如今且说林黛玉因夜间失寝，次日起来迟了，闻得众姐妹都在园中做饯花会，恐人笑他痴懒，连忙梳洗了出来。刚到了院中，只见宝玉进门来了，便笑道：“好妹妹，你昨儿告了我没有？我悬了一夜的心。”黛玉便回头叫紫鹃：“把屋子收拾了，下一扇纱屉子。看那大燕子回来，把帘子放下来，拿“狮子”倚住。烧了香，就把炉罩上。”一面说，一面又往外走。　　宝玉见他这样，还认作是昨日晌午的事，那知晚间的这件公案？还打恭作揖的。黛玉正眼儿也不看，各自出了院门，一直找别的姐妹去了。","宝玉心中纳闷，自己猜疑：“看起这样光景来，不像是为昨儿的事。但只昨日我回来的晚了，又没有见他，再没有冲撞了他的去处儿了。”一面想，一面由不得随后跟了来。只见宝钗探春正在那边看鹤舞，见黛玉来了，三个一同站着说话儿。又见宝玉来了，探春便笑道：“宝哥哥，身上好？我整整的三天没见你了。”宝玉笑道：“妹妹身上好？我前儿还在大嫂子跟前问你呢。”探春道：“宝哥哥，你往这里来，我和你说话。”　　宝玉听说，便跟了他，离了钗玉两个，到了一棵石榴树下。探春因说道：“这几天老爷没叫你吗？”宝玉笑道：“没有叫。”探春道：“昨儿我恍惚听见说，老爷叫你出去来着。”宝玉笑道：“那想是别人听错了。并没叫我。”探春又笑道：“这几个月，我又攒下有十来吊钱了。你还拿了去，明儿出门逛去的时候，或是好字画，好轻巧玩意儿，替我带些来。”宝玉道：“我这么逛去，城里城外大廊大庙的逛，也没见个新奇精致东西，总不过是那些金玉铜磁器，没处撂的古董儿；再么就是绸缎吃食衣服了。”探春道：“谁要那些作什么！像你上回买的那柳枝儿编的小篮子儿，竹子根儿挖的香盒儿，胶泥垛的风炉子儿，就好了。我喜欢的了不的，谁知他们都爱上了，都当宝贝儿似的抢了去了。”宝玉笑道：“原来要这个。这不值什么，拿几吊钱出去给小子们，管拉两车来。”探春道：“小厮们知道什么！你拣那有意思儿又不俗气的东西，你多替我带几件来。我还像上回的鞋做一双你穿，比那双还加工夫，如何呢？”","宝玉笑道：“你提起鞋来，我想起个故事来了。一回穿着，可巧遇见了老爷，老爷就不受用，问是谁做的。我那里敢提三妹妹！我就回说是前儿我的生日，舅母给的。老爷听了是舅母给的才不好说什么了，半日还说：“何苦来！虚耗人力，作践绫罗，做这样的东西！”我回来告诉了袭人。袭人说：“这还罢了，赵姨娘气的抱怨的了不得。正经亲兄弟，鞋蹋拉袜蹋拉的，没人看见，且做这些东西！””探春听说，登时沉下脸来道：“你说，这话胡涂到什么田地！怎么我是该做鞋的人么？环儿难道没有分例的？衣裳是衣裳，鞋袜是鞋袜，丫头老婆子一屋子，怎么抱怨这些话？给谁听呢？我不过闲着没事，做一双半双。爱给那个哥哥兄弟，随我的心，谁敢管我不成？这也是他瞎气。”","宝玉听了，点头笑道：“你不知道，他心里自然又有个想头了。”探春听说，益发动了气，将头一扭，说道：“连你也胡涂了！他那想头，自然是有的，不过是那阴微下贱的见识。他只管这么想，我只管认得老爷太太两个人，别人我一概不管！就是姐妹弟兄跟前，谁和我好，我就和谁好，什么偏的、庶的，我也不知道。论理，我不该说他，但他忒昏聩的不像了！──还有笑话儿呢：就是上回我给你那钱，替我买那些玩的东西，过了两天，他见了我，就说是怎么没钱，怎么难过。我也不理。谁知后来丫头们出去了，他就抱怨起我来，说我攒的钱为什么给你使，倒不给环儿使呢。我听见这话，又好笑，又好气，我就出来往太太跟前去了。”","正说着，只见宝钗那边笑道：“说完了，来罢。显见的是哥哥妹妹了，撂下别人，且说体己去。我们听一句儿就使不得了？”说着，探春宝玉二人方笑着来了。","宝玉因不见了黛玉，便知是他躲了别处去了。想了一想，索性迟两日，等他的气息一息再去也罢了。因低头看见许多凤仙石榴等各色落花，锦重重的落了一地，因叹道：“这是他心里生了气，也不收拾这花儿来了。等我送了去，明儿再问着他。”说着，只见宝钗约着他们往后头去。宝玉道：“我就来。”等他二人去远，把那花儿兜起来，登山渡水，过树穿花，一直奔了那日和黛玉葬桃花的去处。将已到了花冢，犹未转过山坡，只听那边有呜咽之声，一面数落着，哭的好不伤心。宝玉心下想道：“这不知是那屋里的丫头，受了委屈，跑到这个地方来哭？”一面想，一面煞住脚步，听他哭道是：","花谢花飞飞满天，红消香断有谁怜？游丝软系飘春榭，落絮轻沾扑绣帘。闺中女儿惜春暮，愁绪满怀无着处，手把花锄出绣帘，忍踏落花来复去？柳丝榆荚自芳菲，不管桃飘与李飞。桃李明年能再发，明年闺中知有谁？三月香巢初垒成，梁间燕子太无情！明年花发虽可啄，却不道人去梁空巢已倾？一年三百六十日，风刀霜剑严相逼。明媚鲜妍能几时？一朝飘泊难寻觅。花开易见落难寻，阶前愁杀葬花人，独把花锄偷洒泪，洒上空枝见血痕。杜鹃无语正黄昏，荷锄归去掩重门。青灯照壁人初睡，冷雨敲窗被未温。怪侬底事倍伤神？半为怜春半恼春：怜春忽至恼忽去，至又无言去不闻。昨宵庭外悲歌发，知是花魂与鸟魂？花魂鸟魂总难留，鸟自无言花自羞。愿侬此日生双翼，随花飞到天尽头！天尽头，何处有香坵？未若锦囊收艳骨，一抔净土掩风流。质本洁来还洁去，不教污淖陷渠沟。尔今死去侬收葬，未卜侬身何日丧？侬今葬花人笑痴，他年葬侬知是谁？试看春残花渐落，便是红颜老死时。一朝春尽红颜老，花落人亡两不知！","正是一面低吟，一面哽咽，那边哭的自己伤心，却不道这边听的早已痴倒了。要知端详，下回分解。"],"cpLength":6395},"hlm-32":{"chapterId":"hlm-32","bookId":"hlm","fileIndex":31,"number":32,"title":"第三十二回 诉肺腑心迷活宝玉　含耻辱情烈死金钏","paragraphs":["话说宝玉见那麒麟，心中甚是欢喜，便伸手来拿，笑道：“亏你拣着了！你是怎么拾着的？”湘云笑道：“幸而是这个。明日倘或把印也丢了，难道也就罢了不成？”宝玉笑道：“倒是丢了印平常；若丢了这个，我就该死了。”","袭人倒了茶来与湘云吃，一面笑道：“大姑娘，我前日听你大喜呀。”湘云红了脸，扭过头去吃茶，一声也不答应。袭人笑道：“这会子又害臊了，你还记得那几年，咱们在西边暖阁上住着，晚上你和我说的话？那会子不害臊，这会子怎么又臊了？”湘云的脸越发红了，勉强笑道：“你还说呢！那会子咱们那么好，后来我们太太没了，我家去住了一程子，怎么就把你配给了他，我来了，你就不那么待我了。”袭人也红了脸，笑道：“罢呦。先头里姐姐长，姐姐短，哄着我替你梳头，洗脸，做这个，弄那个；如今拿出小姐款儿来了。你既拿款，我敢亲近吗？”湘云道：“阿弥陀佛！冤枉，冤哉！我要这么着，就立刻死了。你瞧瞧，这么大热天，我来了，必定先瞧瞧你。你不信，问缕儿。我在家，时时刻刻，那一回不想念你几句？”","袭人和宝玉听了，都笑劝道：“说玩话儿，你又认真了，还是这么性儿急。”湘云道：“你不说你的话咽人，倒说人性急。”一面说，一面打开绢子，将戒指递与袭人。袭人感谢不尽，因笑道：“你前日送你姐姐们的，我已经得了；今日你亲自又送来，可见是没忘了我：就为这个试出你来了。戒指儿能值多少？可见你的心真。”史湘云道：“是谁给你的？”袭人道：“是宝姑娘给我的。”湘云叹道：“我只当林姐姐送你的，原来是宝姐姐给了你。我天天在家里，想着这些姐姐们，再没一个比宝姐姐好的。可惜我们不是一个娘养的。我但凡有这么个亲姐姐，就是没了父母，也没妨碍的！”说着，眼圈儿就红了。宝玉道：“罢，罢，罢！不用提起这个话了。”史湘云道：“提这个便怎么？我知道你的心病：恐怕你的林妹妹听见，又嗔我赞了宝姐姐了。可是为这个不是？”袭人在旁，嗤的一笑，说道：“云姑娘，你如今大了，越发心直嘴快了。”宝玉笑道：“我说你们这几个人难说话，果然不错。”史湘云道：“好哥哥，你不必说话，叫我恶心。只会在我跟前说话，见了你林妹妹，又不知怎么好了。”","袭人道：“且别说玩话，正有一件事要求你呢。”史湘云便问：“什么事？”袭人道：“有一双鞋，抠了垫心子，我这两日身上不好，不得做。你可有工夫替我做做？”史湘云道：“这又奇了。你家放着这些巧人不算，还有什么针在线的，裁剪上的，怎么叫我做起来？你的活计，叫人做，谁好意思不做呢？”袭人笑道：“你又胡涂了。你难道不知道，我们这屋里的针线是不要那些针在线的人做的？”","史湘云听了，便知是宝玉的鞋，因笑道：“既这么说，我就替你做做罢。只是一件：你的我纔做，别人的我可不能。”袭人笑道：“又来了。我是个什么儿，就敢烦你做鞋了？实告诉你，可不是我的。你别管是谁的，横竖我领情就是了。”史湘云道：“论理，你的东西也不知烦我做了多少，今日我倒不做的原故，你必定也知道。”袭人道：“我倒也不知道。”史湘云冷笑道：“前日我听见把我做的扇套儿拿着和人家比，赌气又铰了。我早就听见了；你还瞒我？这会子又叫我做，我成了你们奴才了。”宝玉忙笑道：“前日的那个本不知是你做的。”袭人也笑道：“他本不知是你做的，是我哄他的话，说是新近外头有个会做活的，扎的绝出奇的好花儿，叫他们拿了一个扇套儿试试看好不好。他就信了，拿出去给这个瞧，那个看的。不知怎么又惹恼了那一位，铰了两段，回来他还叫赶着做去，我纔说了是你做的。他后悔的什么似的！”史湘云道：“这越发奇了。林姑娘也犯不上生气。他既会剪，就叫他做！”袭人道：“他不可做呢。饶这么着，老太太还怕他劳碌着了。大夫又说好生静养纔好。谁还肯烦他做呢？旧年好一年的工夫，做了个香袋儿；今年半年，还没见拿针线呢。”","正说着，有人来回说：“兴隆街的大爷来了，老爷叫二爷出去会。”宝玉听了，便知贾雨村来了，心中好不自在。袭人忙去拿衣服。宝玉一面登着靴子，一面抱怨道：“有老爷和他坐着就罢了，回回定要见我！”史湘云一边摇着扇子，笑道：“自然你能迎宾接客，老爷纔叫你出去呢。”宝玉道：“那里是老爷？都是他自己要请我见的。”湘云笑道：““主雅客来勤”，自然你有些警动他的好处，他纔要会你。”宝玉道：“罢，罢！我也不过俗中又俗的一个俗人罢了，并不愿和这些人来往！”湘云笑道：“还是这个性儿，改不了。如今大了，你就不愿意去考举人进士的，也该常会会这些为官作宦的，谈讲谈讲那些仕途经济，也好将来应酬事务，日后也有个正经朋友。让你成年家只在我们队里，搅的出些什么来？”","宝玉听了，大觉逆耳，便道：“姑娘请别的屋里坐坐罢，我这里仔细腌腌了你这样知经济的人！”袭人连忙解说道：“姑娘快别说他。上回也是宝姑娘说过一回，他也不管人脸上过不去，咳了一声，拿起脚来就走了。宝姑娘的话也没说完，见他走了，登时羞的脸通红，说不是，不说又不是。──幸而是宝姑娘，那要是林姑娘，不知又闹的怎么样，哭的怎么样呢。提起这些话来，宝姑娘叫人敬重，──自己过了一会子去了。我倒过不去，只当他恼了，谁知过后还是照旧一样。真真是有涵养，心地宽大的！谁知这一位，反倒和他生分了。那林姑娘见他赌气不理，他后来不知赔多少不是呢。”宝玉道：“林姑娘从来说过这些混账话吗？要是他也说过这些混账话，我早和他生分了！”袭人和湘云都点头笑道：“这原是“混账话”么？”","原来黛玉知道史湘云在这里，宝玉一定又赶来说麒麟的原故。因心下忖度着，近日宝玉弄来的外传野史，多半纔子佳人，都因小巧玩物上撮合，或有鸳鸯，或有凤凰，或玉环金佩，或鲛帕鸾绦，皆由小物而遂终身之愿。今忽见宝玉也有麒麟，便恐借此生隙，同湘云也做出那些风流佳事来。因而悄悄走来，见机行事，以察二人之意。不想刚走进来，正听见湘云说经济一事，宝玉又说：“林妹妹不说这些混账话；要说这话，我也和他生分了！”","黛玉听了这话，不觉又喜又惊，又悲又叹。所喜者：果然自己眼力不错，素日认他是个知己，果然是个知己。所惊者：他在人前，一片私心，称扬于我，其亲热厚密竟不避嫌疑。所叹者，你既为我的知己，自然我亦可为你的知己，既你我为知己，又何必有“金玉”之论呢？既有“金玉”之论，也该你我有之，又何必来一宝钗呢？所悲者，父母早逝，虽有铭心刻骨之言，无人为我主张。况近日每觉神思恍惚，病已渐成，医者更云：“气弱血亏，恐致劳怯之症。”我虽为你的知己，但恐不能久待；你纵为我的知己，奈我薄命何！──想到此间，不禁泪又下来。待要进去相见，自觉无味，便一面拭泪，一面抽身回去了。","这里宝玉忙忙的穿了衣裳出来，忽见黛玉在前面慢慢的走着，似乎有拭泪之状，便忙赶着上来，笑道：“妹妹，往那里去？怎么又哭了？又是谁得罪了你了？”黛玉回头见是宝玉，便勉强笑道：“好好的，我何曾哭来？”宝玉笑道：“你瞧瞧，眼睛上的泪珠儿没干，还撒谎呢。”一面说，一面禁不住抬起手来替他拭泪。黛玉忙向后退了几步，说道：“你又要死了！又这么动手动脚的。”宝玉笑道：“说话忘了情，不觉的动了手，也就顾不得死活。”黛玉道：“死了倒不值什么，只是丢下了什么金，又是什么麒麟，可怎么好呢！”一句话又把宝玉说急了，赶上来问道：“你还说这些话，到底是咒我，还是气我呢？”黛玉见问，方想起前日的事来，遂自悔这话又说造次了，忙笑道：“你别着急，我原说错了。这有什么要紧？筋都迭暴起来，急的一脸汗！”一面说，一面也近前伸手替他拭面上的汗。","宝玉瞅了半天，方说道：“你放心！”黛玉听了，怔了半天，说道：“我有什么不放心的？我不明白你这个话。你倒说说，怎么放心不放心？”宝玉叹了一口气，问道：“你果然不明白这话？难道我素日在你身上的心都用错了？连你的意思若体贴不着，就难怪你天天为我生气了。”黛玉道：“我真不明白放心不放心的话。”宝玉点头叹道：“好妹妹！你别哄我。你真不明白这话，不但我素日白用了心，且连你素日待我的心也都辜负了。你皆因总是不放心的原故，纔弄了一身的病了。但凡宽慰些，这病也不得一日重似一日了！”","黛玉听了这话，如轰雷掣电，细细思之，竟比自己肺腑中掏出来的还觉恳切。竟有万句言语，满心要说，只是半个字也不能吐出，只管怔怔的瞅着他。此时宝玉心中也有万句言词，不知一时从那一句说起，却也怔怔的瞅着黛玉。两个人怔了半天，黛玉只咳了一声，眼中泪直流下来，回身便走。宝玉忙上前拉住道：“好妹妹，且略站住，我说一句话再走。”黛玉一面拭泪，一面将手推开，说道：“有什么可说的？你的话，我都知道了。”口里说着，却头也不回，竟去了。　　宝玉望着只管发起呆来。原来方纔出来忙了，不曾带得扇子，袭人怕他热，忙拿了扇子赶来送给他。猛抬头看见黛玉和他站着，一时，黛玉走了，他还站着不动，因而赶上来说道：“你也不带了扇子去？亏了我看见，赶着送来。”","宝玉正出了神，见袭人和他说话，并未看出是谁，只管呆着脸，说道：“好妹妹！我的这个心，从来也不敢说；今日胆大说出来，就是死了也是甘心的！我为你，也弄了一身的病，又不敢告诉人，只好捱着。等你的病好了，只怕我的病纔得好呢。──睡里梦里也忘不了你！”　　袭人听了，惊疑不止，又是怕，又是急，又是臊，连忙推他道：“这是那里的话？你是怎么着了？还不快去吗？”宝玉一时醒过来，方知是袭人。虽然羞的满面紫涨，却仍是呆呆的，接了扇子，一句话也没有，竟自走去。这里袭人见他去后，想他方纔之言必是因黛玉而起，如此看来，倒怕将来难免不才之事，令人可惊可畏。却是如何处治，方能免此丑祸？想到此间，也不觉呆呆的发起怔来。","谁知宝钗恰从那边走来，笑道：“大毒日头地下，出什么神呢？”袭人见问，忙笑说道：“我纔见两个雀儿打架，倒很有个顽意儿，就看住了。”宝钗道：“宝兄弟纔穿了衣服，忙忙的那里去了？我要叫住问他呢。只是他慌慌张张的走过去，竟像没理会我的，所以没问。”袭人道：“老爷叫他出去的。”宝钗听了，忙说道：“嗳哟！这么大热的天，叫他做什么？别是想起什么来，生了气，叫他出去教训一场罢。”袭人笑道：“不是这个。想必有客要会。”宝钗笑道：“这个客也没意思，这么热天，不在家里凉快，跑什么？”袭人笑道：“你可说么？”","宝钗因问：“云丫头在你们家做什么呢？”袭人笑道：“纔说了会子闲话儿，又瞧了会子我前日粘的鞋帮子，明日还求他做去呢。”宝钗听见这话，便两边回头，看无人来往，笑道：“你这么个明白人，怎么一时半刻的就不会体谅人？我近来看着云姑娘的神情儿，风里言，风里语的，听起来，在家里一点儿做不得主。他们家嫌费用大，竟不用那些针在线的人，差不多儿的东西都是他们娘儿们动手。为什么这几次他来了，他和我说话儿，见没人在跟前，他就说家里累的慌？我再问他两句家常过日子的话，他就连眼圈儿都红了，嘴里含含糊糊，待说不说的。看他的形景儿，自然从小儿没了父母是苦的。我看见他也不觉的伤起心来！”　　袭人见说这话，将手一拍，道：“是了，是了！怪道上月我求他打十根蝴蝶儿结子，过了那些日子纔打发人送来。还说：“这是粗打的，且在别处将就使罢；要匀凈的，等明日来住着，再好生打。”如今听姑娘这话，想来我们求他，他不好推辞。不知他在家里怎么三更半夜的做呢！──可是我也胡涂了！早知道是这么着，我也不该求他。”宝钗道：“上次他告诉我说，在家里做活做到三更天。要是替别人做一点半点儿，那些奶奶太太们还不受用呢。”袭人道：“偏我们那个牛心的小爷，凭着小的大的活计，一概不要家里这些活计上的人做；我又弄不开这些。”宝钗笑道：“你理他呢，只管叫人做去就是了。”袭人道：“那里哄的过他？他纔是认得出来呢！说不得我只好慢慢的累去罢了。”宝钗笑道：“你不必忙，我替你做些就是了。”袭人笑道：“当真的？这可就是我的造化了！晚上我亲自过来。”","一句话未了，忽见一个老婆子忙忙走来，说道：“这是那里说起！金钏儿姑娘好好儿的投井死了！”袭人听得，唬了一跳，忙问：“那个金钏儿？”那老婆子道：“那里还有两个金钏儿呢？就是太太屋里的。前日不知为什么撵出去，在家里哭天抹泪的，也都不理会他。谁知找不着他。纔有打水的人说，那东南角上井里打水，见一个尸首，赶着叫人打捞起来，谁知是他！他们还只管乱着要救，那里中用了呢！”宝钗道：“这也奇了！”袭人听说，点头赞叹，想素日同气之情，不觉流下泪来。宝钗听见这话，忙向王夫人处来。这里袭人自回去了。","宝钗来至王夫人房里，只见鸦雀无闻，独有王夫人在里间房内坐着垂泪。宝钗便不好提这事，只得一旁坐下。王夫人便问：“你打那里来？”宝钗道：“打园里来。”王夫人道：“你打园里来，可曾见你宝兄弟？”宝钗道：“纔倒看见他了。穿着衣裳出去了，不知那里去。”王夫人点头叹道：“你可知道一件奇事？金钏儿忽然投井死了！”宝钗见说，道：“怎么好好儿的投井？这也奇了！”王夫人道：“原是前日他把我一件东西弄坏了，我一时生气，打了他两下子，撵了下去。我只说气他几天，还叫他上来，谁知他这么气性大，就投井死了。岂不是我的罪过！”宝钗笑道：“姨娘是慈善人，固然是这么想。据我看来，他并不是赌气投井，多半他下去住着，或是在井旁边儿玩，失了脚掉下去的。他在上头拘束惯了，这一出去，自然要到各处去玩玩逛逛儿，岂有这样大气的理？纵然有这样大气，也不过是个胡涂人，也不为可惜。”王夫人点头叹道：“虽然如此，到底我心里不安！”","宝钗笑道：“姨娘也不劳关心。十分过不去，不过多赏他几两银子发送他，也就尽了主仆之情了。”王夫人道：“刚纔我赏了五十两银子给他妈。原要还把你姐妹们的新衣裳给他两件妆裹，谁知可巧都没有什么新做的衣裳，只有你林妹妹做生日的两套。我想你林妹妹那个孩子，素日是个有心的；况且他也三灾八难的，既说了给他作生日，这会子又给人去妆裹，岂不忌讳？因这么着，我纔现叫裁缝赶着做一套给他。要是别的丫头，赏他几两银子，也就完了。金钏儿虽然是个丫头，素日在我跟前，比我的女孩儿差不多儿！”口里说着，不觉流下泪来。宝钗忙道：“姨娘这会子何用叫裁缝赶去？我前日倒做了两套，拿来给他，岂不省事？况且他活的时候儿也穿过我的旧衣裳，身量也相对。”王夫人道：“虽然这样，难道你不忌讳？”宝钗笑道：“姨娘放心，我从来不计较这些。”一面说，一面起身就走。王夫人忙叫了两个人跟宝钗去。","一时，宝钗取了衣服回来，只见宝玉在王夫人旁边坐着垂泪。王夫人正纔说他，因见宝钗来了，就掩住口不说了。宝钗见此景况，察言观色，早知觉了七八分。于是将衣服交明王夫人。王夫人便将金钏儿的母亲叫来拿了去了。后事如何，下回分解。"],"cpLength":5844},"jhy-11":{"chapterId":"jhy-11","bookId":"jhy","fileIndex":10,"number":11,"title":"第十一回 观雅化闲游君子邦 慕仁风误入良臣府","paragraphs":["话说唐、多二人把匾看了，随即进城。只见人烟辏集，作买作卖，接连不断。衣冠言谈，都与天朝一样。唐敖见言语可通，因向一位老翁问其何以“好让不争”之故。谁知老翁听了，一毫不懂。又问国以“君子”为名是何缘故，老翁也回不知一连问了几个，都是如此。","多九公道：“据老夫看来，他这国名以及‘好让不争’四字，大约都是邻邦替他取的，所以他们都回不知。刚才我们一路看来，那些‘耕者让畔，行者让路’光景，已是不争之意。而且士庶人等，无论富贵贫贱，举止言谈，莫不恭而有礼，也不愧‘君子’二字。”唐敖道：","“话虽如此，仍须慢慢观玩，方能得其详细。","说话间，来到闹市。只见有一隶卒在那里买物，手中拿著货物道：“老兄如此高货，却讨恁般贱价，教小弟买去，如何能安心！务求将价加增，方好遵教。若再过谦，那是有意不肯赏光交易了。唐敖听了，因暗暗说道：“九公，凡买物，只有卖者讨价，买者还价。今卖者虽讨过价，那买者并不还价，却要添价。此等言谈，倒也罕闻。据此看来那‘好让不争’四字，竞有几分意思了。”只听卖货人答道：“既承照顾，敢不仰体！但适才妄讨大价，已觉厚颜；不意老兄反说货高价贱，岂不更教小弟惭愧？况敝货并非‘言无二价’，其中颇有虚头。俗云：“漫天要价，就地还钱’。今老兄不但不减，反要加增，如此克已，只好请到别家交易，小弟实难遵命。”唐敖道：“漫天要价，就地还钱’，原是买物之人向来俗谈； 至‘并非言无二价，其中颇有虚头’，亦是买者之话。不意今皆出于卖者之口，倒也有趣。","”只听隶卒又说道：“老兄以高货讨贱价，反说小弟克己，岂不失了‘忠恕之道’？凡事总要彼此无欺，方为公允。试问那个腹中无算盘，小弟又安能受人之愚哩。谈之许久，卖货人执意不增。隶卒赌气，照数付价，拿了一半货物，刚要举步，卖货人那里肯依，只说“价多货少”，拦住不放。路旁走过两个老翁，作好作歹，从公评定，今隶卒照价拿了八折货物，这才交易而去。唐、多二人不觉暗暗点头。走未数步，市中有个小军，也在那里买物。小军道：“刚才请教贵价若干，老兄执意吝教，命我酌量付给。及至尊命付价，老兄又怪过多。","其实小弟所付业已刻减。若说过多，不独太偏，竟是‘违心之论’了。”卖货人道：“小弟不敢言价，听兄自讨者，因敝货既欠新鲜，而且平常，不如别家之美。若论价值，只照老兄所付减半，已属过分，何敢谬领大价。”唐敖道：“‘货色平常’，原是买者之话；‘付价刻减’，本系卖者之话，那知此处却句句相反，另是一种风气。”只听小军又道：“老兄说那里话来！小弟于买卖虽系外行，至货之好丑，安有不知，以丑为好，亦愚不至此。第以高货只取半价，不但欺人过甚，亦失公平交易之道了。”卖货人道：“老兄如真心照顾，只照前价减半，最为公平。若说价少，小弟也不敢辩，惟有请向别处再把价钱谈谈，才知我家并非相欺哩。”小军说之至再，见他执意不卖，只得照前减半付价，将货略略选择，拿了就走。卖货人忙拦住道：“老兄为何只将下等货物选去？难道留下好的给小弟自用么？我看老兄如此讨巧，就是走遍天下，也难交易成功的。”小军发急道：“小弟因老兄定要减价，只得委曲认命，略将次等货物拿去，于心庶可稍安。不意老兄又要责备，且小弟所买之物，必须次等，方能合用，至于上等，虽承美意，其实倒不适用了。”卖货人道：“老兄既要低货方能合用，这也不妨。但低货自有低价，何能付大价而买丑货呢？”小军听了，也不答言，拿了货物，只管要走。那过路人看见，都说小军欺人不公。小军难违众论，只得将上等货物，下等货物，各携一半而去。","二人看罢，又朝前进，只见那边又有一个农人买物。原来物已买妥，将银付过，携了货物要去。那卖货的接过银子仔细一看，用戥秤了一秤，连忙上前道：“老兄慢走。银子平水都错了。此地向来买卖都是大市中等银色，今老兄既将上等银子付我，自应将色扣去。刚才小弟秤了一秤，不但银水未扣，而且戥头过高。此等平色小事，老兄有余之家，原不在此； 但小弟受之无因。请照例扣去。”农人道：“些须银色小事，何必锱铢较量。既有多余，容小弟他日奉买宝货，再来扣除，也是一样。”说罢，又要走。卖货人拦住道：“这如何使得！去岁有位老兄照顾小弟，也将多余银子存在我处，留言后来买货再算。谁知至今不见，各处寻他，无从归还。岂非欠了来生债么？今老兄又要如此。倘一去不来，到了来生，小弟变驴变马归还先前那位老兄，业已尽够一忙，那里还有工夫再还老兄，岂非下一世又要变驴变马归结老兄？据小弟愚见，与其日后买物再算，何不就在今日？况多余若干，日子久了，倒恐难记。”彼此推让许久，农人只得将货拿了两样，作抵此银而去。卖货人仍口口声声只说“银多货少，过于偏枯”。奈农人业已去远，无可如何。忽见有个乞丐走过，卖货人自言自语道：“这个花子只怕就是讨人便宜的后身，所以今生有这报应。”一面说著，却将多余平色，用戥秤出，尽付乞丐而去。","唐敖道：“如此看来，这几个交易光景，岂非‘好让不争’一幅行乐图么？我们还打听甚么！且到前面再去畅游。如此美地，领略领略风景，广广识见，也是好的。”","只见路旁走过两个老者，都是鹤发童颜，满面春风，举止大雅。唐敖看罢，知非下等之人，忙侍立一旁。四人登时拱手见礼，问了名姓。原来这两个老者都姓吴，乃同胞弟兄。一名吴之和，一名吴之祥。唐敖道：“不意二位老丈都是秦伯之后，失敬，失敬！”吴之和道：“请教二位贵乡何处？来此有何贵干？”多九公将乡贯来意说了。吴之祥躬身道：“原来贵邦天朝！小子向闻天朝乃圣人之国，二位大贤荣列胶庠，为天朝清贵，今得幸遇，尤其难得。第不知驾到，有失迎迓，尚求海涵！”唐、多二人连道：“岂敢！…”吴之和道：“二位大贤由天朝至此，小子谊属地主，意欲略展杯茗之敬，少叙片时，不知可肯枉驾？如蒙赏光，寒舍就在咫尺，敢劳玉趾一行。”二人听了，甚觉欣然，于是随著吴氏弟兄一路行来。","不多时，到了门前。只见两扇柴扉，周围篱墙，上面盘著许多青藤薜荔；门前一道池塘，塘内俱是菱莲。进了柴扉，让至一间敞厅，四人重复行礼让坐。厅中悬著国正赐的小额，写著“渭川别墅”。再向厅外一看，四面都是翠竹，把这敞厅团团围住，甚觉清雅。小童献茶。","唐敖问起吴氏昆仲事业，原来都是闲散进士。多九公忖道：“他两个既非公卿大宦，为何国王却替他题额？看来此人也就不凡了。”唐敖道：“小弟才同敝友瞻仰贵处风景，果然名不虚传，真不愧‘君子’二字！”吴之和躬身道：“敝乡僻处海隅，略有知识，莫非天朝文章教化所致，得能不致陨越，已属草野之幸，何敢遽当‘君子’二字。至于天朝乃圣人之邦，自古圣圣相传，礼乐教化，久为八荒景仰，无须小子再为称颂。但贵处向有数事，愚弟兄草野固陋，似多未解。今日虽得二位大贤到此。意欲请示，不知可肯赐教？”唐敖道：“老丈所问，还是国家之事，还是我们世俗之事？”吴之和道：“如今天朝圣人在位，政治纯美，中外久被其泽，所谓‘巍巍荡荡，惟天为大，惟天朝则之’。国家之事，小子僻处海滨，毫无知识，不惟不敢言，亦无可言。今日所问，却是世俗之事。”唐敖道：“既如此，请道其详。倘有所知，无不尽言。”吴之和听罢，随即说出一番话来。","未知如何，下四分解。"],"cpLength":2882},"jhy-25":{"chapterId":"jhy-25","bookId":"jhy","fileIndex":24,"number":25,"title":"第二十五回 越危垣潜出淑士关 登曲岸闲游两面国","paragraphs":["话说徐承志因唐敖问他婚姻之事，不觉垂泪道：“伯伯若问妻室，侄儿今生只好鳏居一世了。”唐敖道：“此话怎讲？”徐承志走到门外望了一望，仍旧归位道：“此处这个驸马，性最多疑。自从侄儿进府，见我膂力过人，虽极喜爱，恐是外国奸细，时刻堤防，甚至住房夜间亦有兵役把守，亏得众同事暗暗通知，处处谨慎，始保无虞。后来驸马意欲作他膀臂，收为心腹，故将宫娥司徒妩儿许配为婚，以安侄儿之心。众同事都道：驸马如此优待，一切更要留神，将来设或婚配，宫娥面前，凡有言谈，亦须仔细。诚恐人心难测，一经疏忽，性命不保。谁知今春夜间，妩儿忽来外厢，再三劝我及早远走，此非久恋之乡，莫要耽搁自己之事，说罢去了。侄儿足足筹画一夜；次日告知众同事，众人都说：‘明系驸马教他探你口气，若不禀明，必有大祸。’侄儿因将此话禀知。后来闻得妩儿被责，因内外相隔，不知真假。不意数日前此女又来劝我急急改图。侄儿忖度一夜，次日又同众人商议，仍须禀知为是。不料禀过后，驸马竟将妩儿著实毒打，发媒变卖。这才晓得此女竟是一片血心待我。兼且春天为我被责；今不记前仇，不避祸患，又来苦口相劝。所谓‘生我者父母，知我者妩儿’。如此贤德，侄儿既不知感，反去恩将仇报，仍有何颜活在人世！侄儿在此投军，原因一时穷乏，走头无路，暂图糊口。那知误入罗网。近来屡要逃归，面投血书，设计勤王，以承父志。无如此处关口盘查甚严，向例在官人役，毋许私自出关，如有不遵，枭首示众。侄儿在府将及三年，关上人役，无不熟识，用此更难私逃。连年如入笼中，行动不能自主。前者贤德妻子虽盗令旗一枝，彼时适值昏愤，亦呈驸马，后悔无及，此时妻子不知卖在何处！”","不觉哽咽起来。唐敖道：“此事侄媳虽是一片血心，亲贤侄处此境界，不能不疑，无怪有此一番举动。幸喜侄媳无恙。”因将妩儿各话说知。徐承志这才止泪，拜谢救拔妻子之恩。 唐敖道：“关上如此严紧，贤侄不能出去，这却怎好？”徐承志道：“侄儿连年费尽心机，实无良策。此时难得伯伯到此，务望垂救！倘出此关，不啻恩同再造。将来如有出头之日，莫非伯伯所赐了。”多九公道：“老夫每见灵枢出关，从不搜检，此处虽严，谅无开棺之理。为今之计，何不假充灵枢，混出关去，岂不是好？”徐承志道：“此计虽善，倘关役生疑禀知，定要开棺，那时从何措手？此事非同儿戏，仍须另想善策。况驸马稽查最严，稍有不妥，必致败露。”唐敖道：“关上见了令旗，既肯放出，莫若贤侄仍将令旗盗出，倒觉省事。”徐承志道：“伯伯！谈何容易！他这令旗素藏内室，非紧急大事，不肯轻发。前者侄媳不知怎样费力才能盗出。此时既无内应，侄儿又难入内，令旗从何到手？”林之洋道：","“据俺主意：到了夜晚，妹夫把公子驼到背上，将身一纵，跳出关外，人不知，鬼不觉，又简便，又爽快，这才好哩。”多九公道：“唐兄只能撺高，岂能负重？若背上驼人，只怕连他自己也难上高了。”林之洋道：“前在鳞凤山，俺闻妹夫说身上负重也能撺高，难道九公忘了么？”唐敖道：“负重固然无碍，惟恐城墙过高，也难上去。”多九公道：“只要肩能驼人，其余都好商量。若虑墙高，好在内外墙根都是大树，如果过高，唐兄先撺树上，随后再撺墙上，分两次撺去，岂不大妙？”唐敖道：“此事必须夜晚方能举行。莫若贤侄领我们到彼，先将道路看在眼内，以便晚上易于下手。“徐承志道：“不知伯伯何以学得此技？”","唐敖把蹑空草之话告知。当时算还茶钱，出了茶馆。徐承志由僻径把三人暗暗领到城角下。 唐敖看那城墙不过四五丈高，四顾寂然，夜间正好行事。林之洋道：“如今这里无人，墙又不高，妹夫就同公子操练操练，省得晚上费手。”唐敖道：“舅兄之言甚善。”于是驼了徐承志，将身一纵，并不费力，轻轻撺在城上。四处一望，惟见梅树丛杂，城外并无一人。因说道：“贤侄寓处可有紧要之物？如无要物，我们就此出城，岂不更觉省事？”徐承志道：","“小侄自从前岁被人撬开房门，惟恐血书遗失，因此紧藏在身，时刻不离，此时房中别无要物，就求伯伯速速走罢。”唐敖随向多、林二人招手，二人会意，即向城外走来。唐敖将身一纵，撺下城去。徐承志随即跳下。走了多时，恰好多、林二人也都赶到，一齐登舟扬帆。","徐承志再三叩谢。唐敖进内把徐承志前后各话说了，妩儿才知丈夫却是如此用意，于是转悲为喜。唐敖即将卖契烧毁。来到外舱，与徐承志商量回乡之事。多九公道：“此时公子只好暂往前进，俟有熟船，再回故乡，彼此才能放心。”徐承志点头。","走了几日，到了两面国。唐敖要去走走。徐承志恐驸马差人追赶，设或遇见，又费唇舌，因此不去。多九公道：“此国离海甚远，向来路过，老夫从未至彼，唐兄今既高兴，倒奉陪一走。但老夫自从东口山赶那肉芝，跌了一交，被石块垫了脚胫，虽已痊愈，无如上了年纪，气血衰败，每每劳碌，就觉疼痛，近来只顾奉陪畅游，连日竟觉步履不便。此刻上去，倘道路过远，竟不能奉陪哩。”唐敖道：“我们且去走走。九公如走得动，同去固妙；倘走不动，半路回来，未为不可。”于是约了林之洋，别了徐承志，一齐登岸。走了数里，远远望去，并无一些影响。多九公道：“再走一二十里，原可支持，惟恐回来费力，又要疼痛，老夫只好失陪了。”林之洋道：“俺闻九公带有跌打妙药，逢人施送，此时自己有病，为甚倒不多服？”多九公道：“这怪彼时少吃两服药，留下病根，今已日久，服药恐亦无用。” 林之洋道：“俺今日匆忙上来，未曾换衣，身穿这件布衫，又旧又破。刚才三人同行，还不理会。如今九公回去，俺同妹夫一路行走，他是儒巾绸衫，俺是旧帽破衣，倒象一穷一富。 若教势利人看见，还肯睬俺么？”多九公笑道：“他不睬你，你就对他说：‘俺也有件绸衫，今日匆忙，未曾穿来。’他必另眼相看了。”林之洋道：“他果另眼相看，俺更要摆架子说大话了。”多九公道：“你说甚么？”林之洋道：“俺说：‘俺不独有件绸衣，俺家中还开过当铺，还有亲戚做过大官。’这样一说，只怕他们还有酒饭款待哩。”说著，同唐敖去了。","多儿公回船，腿脚甚痛，只得服药歇息，不知不觉，睡了一觉。及至睡醒，疼痛已止，足疾竟自平复，心中著实畅快。正在前舱同徐承志用谈，只见唐、林二人回来，因问道：“这两面国是何风景？为何唐兄忽穿林兄衣帽，林兄又穿唐兄衣帽？这是何意？”唐敖道：“我们别了九公，又走十余里，才有人烟。原要看看两面是何形状，谁知他们个个头戴浩然巾，都把脑后遮住，只露一张正面，却把那面藏了，因此并未看见两面。小弟上去问问风俗，彼此一经交谈，他们那种和颜悦色、满面谦恭光景，令人不觉可爱可亲，与别处迥不相同。","”林之洋道：“他同妹夫说笑，俺也随口问他两句。他掉转头来，把俺上下一望，陡然变了样子：脸上冷冷的，笑容也收了，谦恭也免了。停了半晌，他才答俺半句。”多九公道：“说话只有一句，两句，怎么叫做半句？”林之洋道：“他的说话虽是一句，因他无情无绪，半吞半吐，及至到俺耳中，却只半句。俺因他们个个把俺冷淡，后来走开，俺同妹夫商量，俺们彼此换了衣服，看他可还冷淡。登时俺就穿起绸衫，妹夫穿了布衫，又去找他闲话。那知他们忽又同俺谦恭，却把妹夫冷淡起来。”多九公叹道：“原来所谓两面，却是如此！” 唐敖道：“岂但如此！后来舅兄又同一人说话，小弟暗暗走到此人身后，悄悄把他浩然巾揭起。不意里面藏著一张恶脸，鼠眼鹰鼻，满面横肉。他见了小弟，把扫帚眉一皱，血盆口一张，伸出一条长舌，喷出一股毒气，霎时阴风惨惨，黑雾漫漫，小弟一见，不觉大叫一声：‘吓杀我了！’再向对面一望，谁知舅兄却跪在地下。”多九公道：“唐兄吓的喊叫也罢了，林兄忽然跪下，这却为何？”林之洋道：“俺同这人正在说笑，妹夫猛然揭起浩然巾，识破他的行藏，登时他就露出本相，把好好一张脸变成青面獠牙，伸出一条长舌，犹如一把钢刀，忽隐忽现。俺怕他暗处示人，心中一吓，不因不由腿就软了，望著他磕了几个头，这才逃回。九公！你道这事可怪？”多九公道：“诸如此类，也是世间难免之事，何足为怪！老大痴长几岁，却经历不少。揆其所以，大约二位语不择人，失于检点，以致如此，幸而知觉尚早，未遭其害。此后择人而语，诸凡留神，可免此患了。”","当时唐、林二人换了衣服，四人闲谈。因落雨不能开船。到晚，雨虽住了，风仍不止。","正要安歇，忽听邻船有妇女哭声，十分惨切。 未知如何，下回分解。"],"cpLength":3333},"jstl-01":{"chapterId":"jstl-01","bookId":"jstl","fileIndex":0,"number":1,"title":"第一卷 俞伯牙摔琴谢知音","paragraphs":["浪说曾分鲍叔金，谁人辨得伯牙琴！","干今交道好如鬼，湖海空悬一片心。","古来论文情至厚，莫如管鲍。管是管夷吾，鲍是鲍叔牙。他两个同为商贾，得利均分。时管夷吾多取其利，叔牙不以为贪，知其贫也，后来管夷吾被囚，叔牙脱之，荐为齐相。这样朋友，才是个真正相知。这相知有几样名色：恩德相结者，谓之知己；腹心相照者，谓之知心；声气相求嗜，谓之知音，总来叫做相知。","今日听在下说一桩俞伯牙的故事。列位看官们，要听者，洗耳而听；不要听者，各随尊便。正是，“知音说与知音听，不是知音不与谈，”话说春秋战国时，有一名公，姓俞名瑞字伯牙，楚国郢都人氏，即今猢广荆州府之地也。那俞伯牙身虽楚人，官星却落于晋国，仕至上大夫之位。因奉晋主之命，来楚国修聘。伯牙讨这个差使，一来是个大才，下辱君命；二来就便省视乡里，一举两得。当时从陆路至于郢都，朝见了楚王，致了晋主之命，楚王设宴款待，十分相敬。那郢都乃是桑梓之地，少不得去看一看坟墓，会一会亲友。然虽如此，各事其主，君命在身，不敢迟留。公事已毕，拜辞楚王。楚王赠以黄金采缎，高车驷马。伯牙离楚一十二年，思想故国江山之胜，欲得恣情观览，要打从水路大宽转而回。乃假奏楚王道：“臣不幸有犬马之疾，不胜车马驰骤。乞假臣舟揖，以便医药。”楚王准奏，命水师拨大船二只，一正一副。正船单坐晋国来使，副船安顿仆从行李。都是兰桡画桨，锦帐高帆，甚是齐整。群臣直送至江头而别。","只因览胜探奇，不顾山遥水远。伯牙是个风流才子，那江山之胜，正投其怀。张一片风帆，凌千层碧浪，看不尽遥山叠翠，远水澄清。不一日，行至汉阳江口。时当八月十五日中秋之夜，偶然风狂浪涌，大雨如注。舟楫不能前进，泊于山崖之下。不多时，风恬浪静，雨止云开，现出一轮明月。那雨后之月，其光倍常。伯牙在船舱中，独坐无聊，命童子焚香炉内，“待我抚琴一操，以遣情怀。”童子焚香罢，捧琴囊置于案间。伯牙开囊取琴，调弦转轸，弹出一曲。曲犹未终，指下“刮刺”的一声响，琴弦断了一根。伯牙大惊，叫童子去问船头：“这住船所在是甚么去处？”船头答道：“偶因风雨，停泊于山脚之下，虽然有些草树，并无人家。”伯牙惊讶，想道：“是荒山了。若是城郭村庄，或有聪明好学之人，盗听吾琴，所以琴声忽变，有弦断之异。这荒山下，那得有听琴之人？哦，我知道了，想是有仇家差来刺客；不然，或是贼盗伺候更深，登舟劫我财物。”叫左右：“与我上崖搜检一番。不在柳阴深处，定在芦苇丛中！”左右领命，唤齐众人，正欲搭跳上崖。忽听岸上有人答应道：“舟中大人，不必见疑。小子并非奸盗之流，乃樵夫也。因打柴归晚，值骤雨狂风，雨具不能遮蔽，潜身岩畔。闻君雅操，少住听琴。”伯牙大笑道：“山中打柴之人，也敢称‘听琴’二字！此言未知真伪，我也不计较了。左右的，叫他去罢。”那人不去，在崖上高声说道：“大人出言谬矣！岂不闻‘十室之邑，必有忠信。’‘门内有君子，门外君子至。’大人若欺负山野中没有听琴之人，这夜静更深，荒崖下也不该有抚琴之客了。”","伯牙见他出言不俗，或者真是个听琴的，亦未可知。止住左右不要罗唣，走近舱门，回嗔作喜的问道：“崖上那位君子，既是听琴，站立多时，可知道我适才所弹何曲？”那人道：“小子若不知，却也下来听琴了。方才大人所弹，乃孔仲尼叹颜回，谱入琴声。其词云：‘可惜颜回命蚤亡，教人思想鬓如霜。只因陋巷箪瓢乐，……’到这一句，就断了琴弦，不曾抚出第四句来，小子也还记得：‘留得贤名万古扬。’”怕牙闻言大喜道：“先生果非俗士，隔崖遥远，难以问答。”命左右：“掌跳，看扶手，请那位先生登舟细讲。”左右掌跳，此人上船，果然是个樵夫：头戴箬笠，身披蓑衣，手持尖担，腰插板斧，脚踏芒鞋。手下人那知言谈好歹，见是樵夫，下眼相看：“咄！那樵夫下舱去，见我老爷叩头，问你甚么言语，小心答应。官尊着哩！”樵大却是个有意思的，道：“列位不须粗鲁，待我解衣相见。”除了斗笠，头上是青布包巾；脱了蓑衣，身上是蓝布衫儿；搭膊拴腰，露出布棍下截。那时不慌不忙，将蓑衣、斗笠、尖担、板斧，俱安放舱门之外。脱下芒鞋，骊去泥水，重复穿上，步入舱来。官舱内公座上灯烛辉煌。樵夫长揖而不跪，道：“大人施礼了。”俞伯牙是晋国大臣，眼界中那有两接的布衣。下来还礼，恐失了官体，既请下船，又不好叱他回去。伯牙没奈何，微微举手道：“贤友免礼罢。”叫童子看坐的。童子取一张杌坐儿置于下席。怕牙全无客礼，把嘴向樵夫一弩，道：“你且坐了。”你我之称，怠慢可知。那樵大亦不谦让，俨然坐下。","伯牙见他不告而坐，微有嗔怪之意，因此不问姓名，亦不呼手下人看茶。默坐多时，怪而问之：“适才崖上听琴的，就是你么？”樵夫答言：“不敢。”伯牙道：“我且问你，既来听琴，必知琴之出处。此琴何人所造？抚他有甚好处？”正问之时，船头来禀话：“风色顺了，月明如昼，可以开船。”伯牙分付：“且慢些！”樵夫道，“承大人下问，小子若讲话絮烦，恐担误顺风行舟。”伯牙笑道：“惟恐你不知琴理。若讲得有理，就不做官，亦非大事，何况行路之迟速乎！”樵夫道：“既如此，小子方敢僭谈。此琴乃伏羲氏所琢，见五星之精，飞坠梧桐，凤皇来仪。凤乃百鸟之王，非竹实不食，非悟桐不栖，非醴泉不饮。伏羲以知梧桐乃树中之良材，夺造化之精气，堪为雅乐，令人伐之。其树高三丈三尺，按三十三天之数，截为三段，分天、地、人三才。取上一段叩之，其声太清，以其过轻而废之；取下一段叩之，其声太浊，以其过重而废之；取中一段叩之，其声清浊相济，轻重相兼。送长流水中，浸七十二日，按七十二候之数。取起阴干，选良时吉日，用高手匠人刘子奇制成乐器。此乃瑶池之乐，故名瑶琴。长三尺六寸一分，按周天三百六十一度；前阔八寸，按八节；后阔四寸，按四时；厚二寸，按两仪。有金童头，玉女腰，仙人背，龙池，凤沼，玉轸，金徽。那徽有十二，按十二月；又有一中徽，按闰月。先是五条弦在上，外按五行：金、木、水、火、土；内按五音：宫、商、角、徵、羽。尧舜时操五弦琴，歌‘南风’诗，天下大治。后因周文王被囚于羡里，吊子伯邑考，添弦一根，清幽哀怨，谓之文弦。后武王伐纣，前歌后舞，添弦一根，激烈发扬，谓之武弦。先是宫、商、角、徵、羽五弦，后加二弦，称为文武七弦琴。此琴有六忌，七不弹，八绝。何为六忌？一忌大寒，二忌大暑，三忌大风，四忌大雨，五忌迅雷，六忌大雪。何为七不弹？闻丧者不弹，奏乐不弹，事冗不弹，不净身不弹，衣冠不整不弹，不焚香不弹，不遇知音者不弹。何为八绝？总之，清奇幽雅，悲壮悠长。此琴抚到尽美尽善之处，啸虎闻而不吼，哀猿听而不啼。乃雅乐之好处也。”","伯牙听见他对答如流，犹恐是记问之学。又想道：“就是记问之学，也亏他了。我再试他一试。”此时已不似在先你我之称了，又问道：“足下既知乐理，当时孔仲尼鼓琴于室中，颜回自外入，闻琴中有幽沉之声，疑有贪杀之意，怪而问之。仲尼曰：‘吾适鼓琴，见猫方捕鼠，欲其得之，又恐其失之。此贪杀之意，遂露于丝桐。”始知圣门音乐之理，入于微妙。假如下官抚琴，心中有所思念，足下能闻而知之否？”樵夫道：“《毛诗》云：‘他人有心，予忖度之。’大人试抚弄一过，小子任心猜度。若猜不着时，大人休得见罪。”伯牙将断弦重整，沉思半晌。其意在于高山，抚琴一弄。樵夫赞道：“美哉洋洋乎，大人之意，在高山也！”伯牙不答。又凝神一会，将琴再鼓，其意在于流水。樵夫又赞道：“美哉汤汤乎，志在流水！”只两句，道着了伯牙的心事。伯牙大惊，推琴而起，与子期施宾主之礼。连呼：“失敬！失敬！石中有美玉之藏，若以衣貌取人，岂不误了天下贤士！先生高名雅姓？”樵大欠身而答：“小子姓钟，名徽，贱字子期。”伯牙拱手道：“是钟子期先生。”子期转问：“大人高姓？荣任何所？”伯牙道：”下官俞瑞，仕于晋朝，因修聘上国而来。”子期道：“原来是伯牙大人。”伯牙推子期坐于客位，自己主席相陪，命童子点茶。茶罢，又命童子取酒共酌。伯牙道：“借此攀话，休嫌简亵。”子期称：“不敢。”","童子取过瑶琴，二人入席饮酒。伯牙开言又问：“先生声口是楚人了，但不知尊居何处？”子期道：“离此不远，地名马安山集贤村，便是荒居。”伯牙点头道：“好个集贤村。”又问：“道艺何为？”子期道：“也就是打柴为生。”伯牙微笑道：“子期先生，下官也不该僭言，似先生这等抱负，何不求取功名，立身于廊庙，垂名于竹帛；却乃资志林泉，混迹樵牧，与草木同朽？窃为先生不取也。”子期道：“实不相瞒，舍间上有年迈二亲，下无手足相辅。采樵度日，以尽父母之余年。虽位为三公之尊，不忍易我一日之养也。”伯牙道：“如此大孝，一发难得。”二人杯酒酬酢一会。子期宠辱无惊，伯牙愈加爱重。又问子期：“青春多少？”子期道：“虚度二十有七。”伯牙道：“下官年长一旬。子期若不见弃，结为兄弟相称，不负知音契友。”子期笑道：“大人差矣！大人乃上国名公，钟徽乃穷乡贱子，怎敢仰扳，有辱俯就。”伯牙道：“相识满天下，知心能几人？下官碌碌风尘，得与高贤结契，实乃生平之万幸。若以富贵贫贱为嫌，觑俞瑞为何等人乎！”遂命童子重添炉火，再熟名香，就船舱中与子期顶礼八拜。伯牙年长为兄，子期为弟。今后兄弟相称，生死不负。拜罢，复命取暖酒再酌。子期让伯牙上坐，伯牙从其言。换了杯箸，子期下席，兄弟相称，彼此谈心叙话。正是：“合意客来心不厌，知音人听话偏长。”","谈论正浓，不觉月淡星稀，东方发白。船上水手都起身收拾篷索，整备开船。子期起身告辞，伯牙捧一杯酒递与子期，把子期之手，叹道：“贤弟，我与你相见何太迟，相别何太早！”子期闻言，不觉泪珠滴于杯中。子期一饮而尽，斟酒回敬伯牙。二人各有眷恋不舍之意。伯牙道：“愚兄余情不尽，意欲曲延贤弟同行数日，未知可否？”子期道：“小弟非不欲相从。怎奈二亲年老，‘父母在，不远游。’”伯牙道：“既是二位尊人在堂，回去告过二亲，到晋阳来看愚兄一看，这就是“游必有方’了。”子期道：“小弟不敢轻诺而寡信，许了贤兄，就当践约。万一禀命于二亲，二亲不允，使仁兄悬望于数千里之外，小弟之罪更大矣。”伯牙道：“贤弟真所谓至诚君于。也罢，明年还是我来看贤弟。”子期道：“仁兄明岁何时到此？小弟好伺候尊驾。”伯牙屈指道：“昨夜是中秋节，今日天明，是八月十六日了。贤弟，我来仍在仲秋中五六日奉访。若过了中旬，迟到季秋月分，就是爽信，不为君子，”叫童子：“分付记室将钟贤弟所居地名及相会的日期，登写在日记簿上。”子期道：“既如此，小弟来年仲秋中五六日，准在江边侍立拱候，不敢有误。天色已明，小弟告辞了。”伯牙道：“贤弟且住。”命童子取黄金二笏，不用封帖，双手捧定道：“贤弟，些须薄礼，权为二位尊人甘旨之费。斯文骨肉，勿得嫌轻。”子期不敢谦让，即时收下。再拜告别，含泪出舱，取尖担挑了蓑衣、斗笠，插板斧于腰问，掌跳搭扶手上崖。伯牙直送至船头，各各洒泪而别。","不题子期回家之事。再说俞伯牙点鼓开船，一路江山之胜，无心观览，心心念念，只想着知音之人。又行了几日，舍舟登岸。经过之地，知是晋国上大夫，不敢轻慢，安排车马相送。直至晋阳，回复了晋主，不在话下。","光阴迅速，过了秋冬，不觉春去夏来。伯牙心怀子期。无日忘之。想着中秋节近，奏过晋主，给假还乡。晋主依允。伯牙收拾行装，仍打大宽转，从水路而行。下船之后，分付水手，但是湾泊所在，就来通报地名。事有偶然，刚刚八月十五夜，水手禀复，此去马安山不远。伯牙依稀还认得去年泊船相会子期之处。分付水手，将船湾泊，水底抛锚，崖边钉橛。其夜晴明，船舱内一线月光，射进朱帘。伯牙命童子将帘卷起，步出舱门，立于船头之上，仰观斗柄。水底天心，万顷茫然，照如白昼。思想去岁与知己相逢，而止月明。今夜重来，又值良夜。他约定江边相候，如何全无踪影，莫非爽信？又等了一会，想道：“我理会得了。江边来往船只颇多。我今日所驾的，不是去年之船了。吾弟急切如何认得？去岁我原为抚琴惊动知音。今夜仍将瑶琴抚弄一曲，吾弟闻之，必来相见。”命童子取琴桌安放船头，焚香设座。伯牙开囊，调弦转轸，才泛音律，商弦中有哀怨之声。伯牙停琴不操：“呀！商弦哀声凄切，吾弟必遭忧在家。去岁曾言父母年高。若非父丧，必是母亡。他为人至孝，事有轻重，宁失信于我，不肯失礼于亲，所以不来也。来日天明，我亲上崖探望。”叫童子收拾琴桌，下舱就寝。 伯牙一夜不睡，真个巴明不明，盼晓不晓。看看月移帘影，日出山头。伯牙起来梳洗整衣，命童子携琴相随，又取黄金十镒带去：“傥吾弟居丧，可为赠礼。”踹跳登崖，行于樵径，约莫十数里，出一谷口，伯牙站住。童子禀道：“老爷为何不行？”伯牙道：“山分南北，路列东西。从山谷出来，两头都是大路，都去得。知道那一路在集贤村去？等个识路之人，问明了他，方才可行。”伯牙就石上少憩，童儿退立于后。不多时，左手官路上有一老叟，髯垂玉线，发挽银丝，箬冠野服，左手举藤杖，右手携竹篮，徐步而来。伯牙起身整衣，向前施礼。那老者不慌不忙，将右手竹篮轻轻放下，双手举藤杖还礼，道：“先生有何见教？”伯牙道：“请问两头路，那一条路，往集贤村去的？”老者道：“那两头路，就是两个集贤村。左于是上集贤村，右手是下集贤村，通衢三十里官道。先生从谷出来，正当其半。东去十五里，西去也是十五里。不知先生要往那一个集贤村？”","伯牙默默无言，暗想道：“吾弟是个聪明人，怎么说话这等糊涂！相会之日，你知道此问有两个集贤村，或上或下，就该说个明白了。”伯牙却才沈吟，那老者道：“先生这等吟想，一定那说路的，不曾分上下，总说了个集贤村，教先生没处抓寻了。”伯牙道：“便是。”老者道：“两个集贤村中，有一二十家庄户，大抵都是隐遁避世之辈。老夫在这山里，多住了几年，正是‘土居二十载，无有不亲人’。这些庄户，不是舍亲，就是敝友。先生到集贤村必是访友，只说先生所访之友，姓甚名谁，者夫就知他住处了。”伯牙道：“学生要往钟家庄去。”老者闻“钟家庄”二字，一双昏花眼内，扑簌簌掉下泪来，道：”先生别家可去，若说钟家庄，不必去了。”伯牙惊问：“却是为何？”老者道：“先生到钟家庄，要访何人？”伯牙道：“要访子期。”老者闻言，放声大哭道：“子期钟徽，乃吾儿也。去年八月十五采樵归晚，遇晋国上大夫俞伯牙先生。讲论之间，意气相投。临行赠黄金二笏。吾儿买书攻读，老拙无才，不曾禁止。旦则采樵负重，暮则育读辛勤，心力耗废，染成怯疾，数月之间，已亡故了。”","伯牙闻言，五内崩裂，泪如涌泉，大叫一声，傍山崖跌倒，昏绝于地。钟公用手搀扶，回顾小童道，“此位先生是谁？”小童低低附耳道：“就是俞伯牙老爷。”钟公道：“元来是吾儿好友。”扶起伯牙苏醒。伯牙坐于地下，口吐痰涎，双手捶胸，恸哭不已。道：“贤弟呵，我昨夜泊舟，还说你爽信，岂知已为泉下之鬼！你有才无寿了！”钟公拭泪相劝。伯牙哭罢起来，重与钟公施礼，不敢呼老丈，称为老伯，以见通家兄弟之意。伯牙道：“老伯，令郎还是停枢在家，还是出瘗郊外了？”钟公道：“一言难尽！亡儿临终，老夫与拙荆坐于卧榻之前。亡儿遗语瞩付道：‘修短由天，儿生前不能尽人子事亲之道，死后乞葬于马安山江边。与晋大夫俞伯牙有约，欲践前言耳。”老夫不负亡儿临终之言。适才先生来的小路之右，一丘新土，即吾儿钟徽之家。今日是百日之忌，老夫提一陌纸钱，往坟前烧化，何期与先生相遇！”伯牙道：“既如此，奉陪老怕，就坟前一拜。”命小童代太公提了竹蓝。","钟公策杖引路，伯牙随后，小童跟定，复进谷口。果见一丘新土，在于路左。伯牙整衣下拜：“贤弟在世为人聪明，死后为神灵应。愚兄此一拜，诚永别矣！”拜罢，放声又哭。惊动山前山后，山左山右黎民百姓，不问行的住的，远的近的，闻得朝中大臣来祭钟子期，回绕坟前，争先观看。伯牙却不曾摆得祭礼，无以为情。命童子把瑶琴取出囊来，放于祭石台上，盘膝坐于坟前，挥泪两行，抚琴一操。那些看者，闻琴韵铿锵，鼓掌大笑而散。伯牙问：“老伯，下官抚琴，吊令郎贤弟，悲不能已，众人为何而笑？”钟公道：“乡野之人，不知音律。闻琴声以为取乐之具，故此长笑。”伯牙道：“原来如此。老伯可知所奏何曲？”钟公道：“老夫幼年也颇习。如今年迈，五官半废，模糊不懂久矣。”伯牙道：“这就是下官随心应手一曲短歌，以吊令郎者，口诵于老伯听之。”钟公道：“老夫愿闻。”伯牙诵云： 忆昔去年春，江边曾会君。今日重来访，不见知音人。","但见一杯土，惨然伤我心！","伤心伤心复伤心，不忍泪珠纷。","来欢去何苦，江畔起愁云。","子期子期兮，你我千金义，历尽天涯无足语，此曲终兮不复弹，三尺瑶琴为君死！”","伯牙于衣夹间取出解手刀，割断琴弦，双手举琴，向祭石台上，用力一摔，摔得玉珍抛残，金徽零乱。钟公大惊，问道：“先生为何摔碎此琴？”伯牙道：","摔碎瑶琴凤尾寒，子期不在对谁弹！","春风满面皆朋友，欲觅知音难上难。","钟公道：“原来如此，可怜！可怜！”伯牙道：“老伯高居，端的在上集贤村，还是下集贤村？”钟公道：“荒居在上集贤村第八家就是。先生如今又问他怎的？”伯牙道：“下官伤感在心，下敢随老伯登堂了。随身带得有黄金二镒，一半代令郎甘旨之奉，一半买几亩祭田，为令郎春秋扫墓之费。待下官回本朝时，上表告归林下。那时却到上集贤村，迎接老伯与老伯母，同到寒家，以尽天年。吾即子期，子期即吾也。老伯勿以下官为外人相嫌。”说罢，命小僮取出黄金，亲手递与钟公，哭拜于地。钟公答拜，盘桓半晌而别。 这回书，题作《俞伯牙摔琴谢知音》。后人有诗赞云： 　　　　　　　　　　　势利交怀势利心，斯文谁复念知音！","伯牙不作钟期逝，千古令人说破琴。"],"cpLength":7061},"jstl-28":{"chapterId":"jstl-28","bookId":"jstl","fileIndex":27,"number":28,"title":"第二十八卷　白娘子永镇雷峰塔","paragraphs":["山外青山楼外楼，西湖歌舞几时休？","暖风薰得游人醉，直把杭州作汴州。","话说西湖景致，山水鲜明。晋朝咸和年间，山水大发，汹涌流入西门。忽然水内有牛一头见，深身金色。后水退，其牛随行至北山，不知去向，哄动杭州市上之人，皆以为显化。所以建立一寺，名曰金牛寺。西门，即今之涌金门，立一座庙，号金华将军。当时有一番僧，法名浑寿罗，到此武林郡云游，玩其山景，道：“灵鸳山前小峰一座，忽然不见，原来飞到此处。”当时人皆不信。僧言：“我记得灵鸳山前峰岭，唤做灵骛岭。这山洞里有个白猿，看我呼出为验。”果然呼出白猿来。山前有一亭，今唤做冷泉亭。又有一座孤山，生在西湖中。先曾有林和靖先生在此山隐居，使人搬挑泥石，砌成一条走路，东接断桥，西接栖霞岭，因此唤作孤山路。又唐时有刺史白乐天，筑一条路， 南至翠屏山，北至栖霞岭，唤做白公堤，不时被山水冲倒，不只一番，用官钱修理。后宋时，苏东坡来做太守，因见有这两条路被水冲坏，就买木石，起人夫，筑得坚固。六桥上朱红栏杆，堤上栽种桃柳，到春景融和，端的十分好景，堪描入画。后人因此只唤做苏公堤。又孤山路畔，起造两条石桥，分开水势，东边唤做断桥，西边唤做西宁桥。真乃：隐隐山藏三百寺，依稀云锁二高峰。","说话的，只说西湖美景，仙人古迹。俺今日且说一个俊俏后生，只因游玩西湖，遇着两个妇人，直惹得几处州城，闹动了花街柳巷。有分教才人把笔，编成一本风流话本。单说那子弟，姓甚名谁？遇着甚般样的妇人？惹出甚般样事？","“有诗为证： 　　　 　清明时节雨纷纷，路上行人欲断魂。","借问酒家何处有，牧童遥指杏花村。","话说宋高宗南渡，绍兴年间，杭州临安府过军桥黑珠巷内，有一个宦家，姓李名仁。见做南廊阁子库募事官，又与邵太尉管钱粮。家中妻子有一个兄弟许宣，排行小乙。他爹曾开生药店，自幼父母双亡，却在表叔李将仕家生药铺做主管，年方二十二岁。那生药店开在官巷口。忽一日，许宣在铺内做买卖，只见一个和尚来到门首，打个 问讯道：“贫僧是保叔塔寺内僧，前日已送馒头并卷子在宅上。今清明节近，追修祖宗，望小乙官到寺烧香，勿误！”许宣道：“小子准来。”","和尚相别去了。许宣至晚归姐夫家去。原来许宣无有老小，只在姐姐家住，当晚与姐姐说：“今日保叔塔和尚来请烧香，明日要荐祖宗，走一遭了来。”次日早起买了纸马、蜡烛、经幡、钱垛一应等项，吃了饭，换了新鞋袜衣服，把答子钱马，使条袱子包了， 径到官巷口李将仕家来。李将仕见了，间许宣何处去。许宣道：“我今日要去保叔塔烧香，追荐祖宗，乞叔叔容暇一日。”李将仕道：“你去便回。” 许宣离了铺中，入寿安坊、花市街，过井亭桥，往清河街后铁塘门，行石函桥，过放生碑，迁到保叔塔寺。寻见送馒头的和尚，仟悔过疏头，烧了等于，到佛殿上看众僧念经，吃斋罢，别了和尚，离寺迄逞闲走，过西宁桥、孤山路、四圣观，来看林和靖坟，到六一泉闲走。不期云生西北，雾锁东南，落下微微细雨，渐大起来。正是清明时节，少不得天公应时，催花雨下，那阵雨下得绵绵不绝。许宣见脚下湿，脱下了新鞋袜，走出四圣观来寻船，不见一只。正没摆布处，只见一个者儿，摇着一只船过来。许宣暗喜，认时正是张阿公。叫道：“张阿公，搭我则个！”老儿听得叫，认时，原来是许小乙，将船摇近岸来，道：“小乙官，着了雨，不知要何处上岸？许宣道：“涌金门上岸。”这老儿扶许宣下船，离了岸，摇近丰乐楼来。","摇不上十数丈水面，只见岸上有人叫道：“公公，搭船则个！”许宣看时，是一个妇人，头戴孝头巾，乌云畔插着些素钡梳，穿一领白绢衫儿，下穿一条细麻布裙。这妇人肩下一个丫鬓，身上穿着青衣服，头上一双角害，戴两条大红头须，插着两件首饰，手中捧着一个包儿要搭船。那老张对小乙官 道：“因风吹火，用力不多’，一发搭了他去。”许宣道：“你便叫他下来。”者儿见说，将船傍了岸边。那妇人同丫鬟下船，见了许宣，起一点朱唇，露两行碎玉，深深道一个万福。许宣慌忙起身答礼。那娘子和丫 鬟舱中坐定了。娘子把秋波频转，瞧着许宣。许宣平生是个老实之人，见了此等如花似玉的美妇人，傍边又是个俊俏美女样的丫鬟，也不免动念。那妇人道：“不敢动问官人，高姓尊讳？”许宣答道：“在下姓许名宣，排行第一。”妇人道：“宅上何处？”许宣道：“寒舍住在过军桥黑珠儿巷，生药铺内做买卖。”那娘子问了一 回，许宣寻思道：“我也问他一问。”起身道：“不敢拜问娘子高姓，潭府何处？”那妇人答道：“奴家是白三班白殿直之妹，嫁了张官人，不幸亡过了，见葬在这雷岭。为因清明节近，今日带了丫鬟，往坟上祭扫了方 回 ，不想值雨。若不是搭得官人便船，实是狼狈。”又闲讲了一回。迄迟船摇近岸，只见那妇人道：“奴家一时心忙，不曾带得盘缠在身边，万望官人处借些船钱还了，并不有负。”许宣道：“娘子自便，不妨，些须船钱不必计较。”还罢船钱上岸 ，那妇人道：“奴家只在箭桥双茶坊巷口。若不弃时，可到寒舍拜茶，纳还船钱。”许宣道：“小事何消挂怀。天色晚了，改日拜望。说罢，妇人共丫鬓自去。","许宣入涌金门，从人家屋檐下到三桥街，见一个生药铺，正是李将仕兄弟的店，许宣走到铺前，正见小将仕在门前。小将仕道：“小乙哥晚了，那里去？”许宣道：“便是去保叔塔烧 香，着了雨，望借一把伞则个！”将仕见说叫道：“老陈把伞来，与小乙官去。”不多时，老陈将一把雨伞撑开道：“小乙官，这伞是清湖八字桥老实舒家做的。八十四骨，紫竹柄的好伞，不曾有一些儿破，将去休坏了！仔细，仔细！”许宣道：“不必分付。”接了伞，谢了将仕，出羊坝头来。到后市街巷口，（愈是荒唐事愈描画得仔细 ） 只听得有人叫道：“小乙官人。”许宣回头看时，只见沈公井巷口小茶坊檐下，立着一个妇人，认得正是搭船的白娘子。许宣道：“娘子如何在此？”白娘子道：“便是雨不得住，鞋儿都踏湿了，教青青回家，取伞和脚下。又见晚下来。 望官人搭几步则个！”许宣和白娘子合伞到坝头道：“娘子到那里去？”白娘子道：“过桥投箭桥去。”许宣道：“小娘子，小人自往过军桥去，路又近了。不若娘子把伞将去，明日小人自来 取。”白娘子道：“却是不当，感谢官人厚意！”许宣沿人家屋檐下冒雨回来，只见姐夫家当直王安，拿着钉靴雨伞来接不着，却好归来。到家内吃了饭。当夜思量那妇人，翻来覆去睡不着。梦中共日间见的一般，情意相浓，不想金鸡叫一声，却是南柯一梦。正是：心猿意马驰千里，浪蝶狂蜂闹五更。","到得天明，起来梳洗罢，吃了饭，到铺中心忙意乱，做些买卖也没心想。到午时后，思量道：“不说一谎，如何得这伞来还人？”当时许宣见老将仕坐在柜上，向将仕说道：“姐夫叫许宣归早些，要送人情，请假半日。”将仕道：“去了，明日早些来！”许宣唱个喏，径来箭桥双茶坊巷口，寻问白娘子家里，问了半日，没一个认得。（没一个认得）正踌躇间，只见白娘子家丫鬟青青，从东边走来。许宣道：“姐姐，你家何处住？讨伞则个。”青青道：“官人随我来。”许宣跟定青青，走不多路，道：“只这里便是。”","许宣看时，见一所楼房，门前两扇大门，中间四扇看街桐子眼，当中挂顶细密朱红帘子，四下排着十二把黑漆交椅，挂四幅名人山水古画。对门乃是秀王府墙。那丫头转入帘子内道：“官人请入里面坐。”许宣随步入到里面，那青青低低悄悄叫道：“娘子，许小乙官人在此。”白娘子里面应道：“请官人进里面拜茶。”许宣心下迟疑。青青三回五次，催许宣进去。许宣转到里面，只见四扇暗 格子窗，揭起青布幕，一个坐起。卓上放一盆虎须葛蒲，两边也挂四幅美人，中间挂一幅神像，卓上放一个古铜香炉花瓶。那小娘子向前深深的道一个万福，道：“夜来多蒙小乙官人应付周全，识荆之初 ，甚是感激不浅。”许宣：“些微何足挂齿！”白娘子道：“少坐拜茶。”茶罢，又道：“片时薄酒三杯，表意而已。”许宣方欲推辞，青青已自把菜蔬果品流水排将出来。许宣道：“感谢娘子置酒，不当厚扰 。饮至数杯，许宣起身道：“今日天色将晚，路远，小子告回。”娘子道：“官人的伞，舍亲昨夜转借去了，再饮几杯，着人取来。”许宣道：“日晚，小子要回。”","娘子道：“再饮一杯。”许宣道：“饮撰好了，多感，多感！”白娘子道：“既是官人要回，这伞相烦明日来取则个。”许宣只得相辞了回家。","至次日，又来店中做些买卖，又推个事故，却来白娘子家取伞。娘子见来，又备三杯相款。许宣道：“娘子还了小子的伞罢，不必多扰。”那娘子道：“既安排了，略饮一杯。”许宣只得坐下。那白娘子筛一杯酒，递与许宣，启樱桃口，露榴子牙，娇滴滴声音，带着满面春风，告道：","“ 小官人在上，真人面前说不得假话。奴家亡了丈夫，想必和官人有宿世姻缘，一见便蒙错爱，正是你有心，我有意。 烦小乙官人寻一个媒证，与你共成百年姻眷，不在天生一对，却不是好！”许宣听那妇人说罢，自己寻思：“真个好一段姻缘。若取得这个浑家，也不在了。我自十分肯了，只是一件不谐：思量我日间在李将仕家做主管，夜间在姐夫家安歇，虽有些少东西，只好办身上衣服。如何得钱来娶老小？”自沉吟不答。只见白娘子道：“官人何故不回言语？”许宣道：“多感过爱，实不相瞒，只为身边窘迫，不敢从命！”娘子道：“这个容易！我 囊中自有余财，不必挂念。”　便叫青青道：“你去取一锭白银下来。”只见青青手扶栏杆，脚踏胡梯，取下一个包儿来，递与白娘子。娘子道：“小乙官人，这东西将去使用，少欠时再来 取。”亲手递与许宣。","许宣接得包儿，打开看时，却是五十两雪花银子。藏于袖中，起身告回，青青把伞来还了许宣。许宣接得相别，一径回家，把银子藏了。当夜无话。","明日起来，离家到官巷口，把伞还了李将仕。许宣将些碎银子买了一只肥好烧鹅、鲜鱼精肉、嫩鸡果品之类提回家来，又买了一搏酒，分付养娘丫鬟安排整下。那日却好姐夫李募事在家。饮撰俱已完备，来请姐夫和姐姐吃酒。李募事却见许宣请他，到吃了一惊，道：“今日做甚么子坏钞？日常不曾见酒盏儿面，今朝作怪！”三人依次坐定饮酒。酒至数杯，李募事道：“尊舅，没事教你坏钞做甚么？”许宣道：“多谢姐夫，切莫笑话，轻微何足挂齿。感谢姐夫姐姐管雇多时。","一客不烦二主人，许宣如今年纪长成，恐虑后无人养育，不是了处。今有一头亲事在此说起，望姐夫姐姐与许宣主张，结果了一生终身，也好。姐夫姐姐听得说罢，肚内暗自寻思道：“许宣日常一毛不拔，今日坏得些钱钞，便要我替他讨老小？”夫妻二人，你我相看，只不回话。吃酒了，许宣自做买卖。","过了三两日，许宣寻思道：“姐姐如何不说起？”忽一日，见姐姐问道：“曾向姐夫商量也不曾？”姐姐道：“不曾。”许宣道：“如何不曾商量？”姐姐道：“这个事不比别样的事，仓卒不得。又见姐夫这几日面色心焦，我怕他烦恼，不敢问他。”","许宣道：“姐姐你如何不上紧？这个有甚难处，你只怕我教姐夫出钱，故此不理。”许宣便起身到卧房中开箱，取出白娘子的银来，把与姐姐道：“不必推故。只要姐夫做主。”姐姐道：“吾弟多时在叔叔家中做主管，积趟得这些私房，可知道要娶老婆。你且去，我安在此。”","却说李募事归来，姐姐道：“丈夫，可知小舅要娶老婆，原来自攒得些私房，如今教我倒换些零碎使用。我们只得与他完就这亲事则个。”李募事听得，说道：“原来如此，得他积得些私房也好。拿来我看。”做妻的连忙将出银子递与丈夫。李募事接在手中，翻来复去，看了上面凿的字号，大叫一声：“苦！不好了，全家是死！”那妻吃了一惊，问道：“丈夫有甚么利害之事？”李募事道：“数日前邵太尉库内封记锁押俱不动，又无地穴得入，平空不见了五十锭大银。见今着落临安府提捉贼人，十分紧急，没有头路得获，累害了多少人。出榜缉捕，写着字号锭数，‘有人捉获贼人银子者，赏银五十两；知而不首，及窝藏贼人者，除正犯外，全家发边远充军。’这银子与榜上字号不差，正是邵太尉库内银子。即今捉捕十分紧急，正是‘火到身边，顾不得亲眷， 只可去拨’。明日事露，实难分说：不管他偷的借的，宁可苦他，不要累我。只得将银子出首，免了一家之害。”老婆见说了，合口不得，目睁口呆。当时拿了这锭银子，径到临安府出首。 那大尹闻知这话，一夜不睡。次日，火速差缉捕使臣何立。何立带了伙伴，并一班眼明手快的公人，径到官巷口李家生药店，提捉正贼许宣。到得柜边，发声喊，把许宣一条绳子绑缚了，一声锣，一声鼓，解上临安府来。正值韩大尹升厅，押过许宣当厅跪下，喝声：“打！”许宣道：“告相公不必用刑，不知许宣有何罪？”大尹焦躁道：“真赃正贼，有何理说，还说无罪？邵太尉府中不动封锁，不见了一号大银五十锭。见有李募事出首，一定这四十九锭也在你处。想不动封皮，不见了银子，你也是个妖人！不要打？”喝教：“拿些秽血来！”许宣方知是这事，大叫道：“不是妖人，待我分说！”大尹道：“且住，你且说这银子从何而来？”许宣将借伞讨伞的上项事，一一细说一遍。大尹道“白娘 子是甚么人？见住何处？”许宣道：“凭他说是白三班白殿直的亲妹子，如今见住箭桥边，双茶坊巷口，秀王墙对黑楼子高坡儿内”那大尹随即便叫缉捕使臣何立，押领许宣，去双茶坊巷口捉拿本妇前来。","何立等领了钧旨，一阵做公的径到双茶坊巷口秀王府墙对黑楼子前看时：门前四扇看阶，中间两扇大门，门外狼藉，坡前却是垃圾，一条竹子横夹着。何立等见了这个模佯，到都呆了。当时就叫捉了邻人，上首是做花的丘大，下首是做皮匠的孙公。那孙公摆忙的吃他一惊，小肠气发，跌倒在地。众邻舍都走来道：“这里不曾有甚么白娘子。这屋在五六年前有一个毛巡检，合家时病死了。青天白日，常有鬼出来买东西，无人敢在里头住，几日前，有个疯子立在门前唱暗。何立教众人解下横门竹竿，里面冷清清地，起一阵风，卷出一道腥气来。众人都吃了一惊，倒退几步。许宣看了，则声不得，一似呆的。做公的数中，有一个能胆大，排行第二，姓王，专好酒吃，都叫他做好酒王二。王二道：“都跟我来！”发声喊一齐哄将入去，看时板壁、坐起、卓凳都有。来到胡梯边，教王二前行，众人跟着，一齐上楼。楼上灰尘三寸厚。众人到房 门前，推开房门一望，床上挂着一张帐子，箱笼都有。只见一个如花似玉穿着白的美貌娘子，坐在床上。众人看了，不敢向前。众人道：“不知娘子是神是鬼？我等奉临安大尹钧旨，唤你去与许宣执证公事。”那娘子端然不动。好酒王二道：“众人都不敢向前，怎的是了？你可将一坛酒来，与我吃了，做我不着，捉他去见大尹。”众人连忙叫两三个下去提一坛酒来与王二吃。王二开了坛口，将一坛酒吃尽了，道：“做我不着！”将那空坛望着帐子内打将去。不打万事皆休，才然打去，只听得一声响，却是青天里打一个霹雳，众人都惊倒了！起来看时，床上不见了那娘子，只见明晃晃一堆银子。众人向前看了道：“好了。”计数四十九锭。众人道：“我们将银子去见大尹也罢。”扛了银子，都到临安府。","何立将前事禀复了大尹。大尹道：“定是妖怪了。也罢，邻人无罪回家。”差人送五十锭银子与邵大尉处，开个缘由，一一禀复过了。许宣照“不应得为而为之事。理重者决杖兔刺，配牢城营做工，满日疏放，牢城营乃苏州府管下。李募事因出首许宣，心上不安，将邵太尉给赏的五十两银子尽数付与小舅作为盘费。李将仕与书二封，一封与押司范院长，一封与吉利桥下开客店的王主人。","许宣痛哭一场，拜别姐夫姐姐，带上行枷，两个防送人押着，离了杭州到东新桥，下了航船。 不一日，来到苏州。先把书会见了范院长井王主人。王主人与他官府上下使了钱，打发两个公人去苏州府，下了公文，交割了犯人，讨了回文，防送人自回。范院长、王主人保领许宣不入牢中，就在王主人门前楼上歇了。许宣心中愁问，壁上题诗一首： 　　　 　独上高楼望故乡，愁看斜日照纱窗。","平生自是真诚士，谁料相逢妖媚娘。","白白不知归甚处？青青那识在何方？","抛离骨肉来苏地，思想家中寸断肠！","有话即长，无话即短，不觉光阴似箭，日月如梭，又在王主人家住了半年之上。忽遇九月下旬，那王主人正在门首闲立，看街上人来人往。只见远远一乘轿子，傍边一个丫鬟跟着，道：“借问一声，此间不是王主人家么？”王主人汪忙起身道：“此间便是。你寻谁人？丫鬟道：“我寻临安府来的许小乙官人。”主人道：“你等一等，我便叫他出来。”这乘轿子便歇在门前。王主人便入去，叫道：“小乙哥，有人寻你。”许宣听得，急走出来，同主人到门前看时，正是青青跟着，轿 子里坐着白娘子。许宣见了，连声叫道：“死冤家！自被你盗了官库银子，带累我吃了多少苦，有屈无伸。如今到此地位，又赶来做甚么？可羞死人！”那白娘子道：“小乙官人不要怪我，今番特来与你分辩这件事。我且到主人家里面与你说。”","白娘子叫青青取了包裹下轿。许宣道：“你是鬼怪，不许入来！”挡住了门不放他。那白娘子与主人深深道了个万福，道：“奴家不相瞒，主人在上，我怎的是鬼怪？衣裳有缝，对日有影。不幸先夫去世，教我如此被人欺负。做下的事，是先 夫日前所为，非干我事。如今怕你怨怪我，特地来分说明白了，我去也甘心。”","主人道：“且教娘子人来坐了说。”那娘子道：“我和你到里面对主人家的妈妈说。”门前看的人，自都散了。","许宣入到里面，对主人家并妈妈道：“我为他偷了官银子事。如此如此，因此教我吃场官司。如今又赶到此，有何理说？”白娘子道：“先夫留下银子，我好意把你，我也不知怎的来的？”许宣道：“如何做公的捉你之时，门 前都是垃圾，就帐子里一响不见了你？”白娘子道：“我听得人说你为这银子捉了去，我怕你说出我来，捉我到官，妆幌子羞人不好看。我无奈何，只得走去华藏寺前姨娘家躲了；使人担垃圾堆在门前，把银子安在床上，央邻舍与我说谎。”许宣道：“你却走了去，教我吃官事！”白娘子道：“我将银子安在床上，只指望要好，那里晓得有许多事情？我见你配在这里，我便带了些盘缠，搭船到这里寻你。如今分说都明白了，我去也。敢是我和你前生没有夫妻之分！”那王主人道：“娘子许多路来到这里，难道就去？且在此间住几日，却理会。”青青道：“既是主人家再三劝解，娘子且住两日，当初也曾许嫁小乙官人。”白娘子随口便道：“羞杀人，终不成奴家没人要？只为分别是非而来。”王主人道：“既然当初许嫁小乙哥，却又回去？且留娘子在此。”打发了轿子，不在话下。","过了数日、白娘子先自奉承好了主人的妈妈。那妈妈劝主人与许宣说合，还定十一月十一日成亲，共百年谐老。光阴一瞬，早到吉日良时。白娘子取出银两，央王主人办备喜筵，二人拜堂结亲。酒席散后，共 入纱楚。白娘子放出迷人声态，颠鸾倒凤，百媚千娇，喜得许宣如遇神仙，只恨相见之晚。正好欢娱，不觉金鸡三唱，东方渐白。正是：欢娱嫌夜短，寂寞恨更长。","自此日为始，夫妻二人如鱼似水，终日在王主人家快乐昏迷缠定。日往月来，又早半年光景，时临春气融和，花开如锦，车马往来，街坊热闹。许宣问主人家道：“今日如何人人出去闲游，如此喧嚷？”主人道：“今日是二月半，男子妇人，都去看卧佛，你也好去承天寺里闲走一遭。”许宣见说，道：“我和妻子说一声，也去看一看。”许宣上楼来，和白娘子说：“今日二月半，男子妇人都去看卧佛，我也看一看就来。有人寻说话，回说不在家，不可出来见人。”白娘子道：“有甚好看；只在家中却不好？看他做甚么？”许宣道：“我去闲耍一遭就回。不妨。”","许宣离了店内，有几个相识，同走到寺里看卧佛。绕廊下各处殿上观看了一遭，方出寺来，见一个先生，穿着道袍，头戴逍遥中，腰系黄丝绦，脚着熟麻鞋，坐在寺前卖药，散施符水。许宣立定了看。那先生道：“贫道是终南山道士，到处云游，散施符水，救人病患灾厄，有事的向前来。”那先生在人丛中看见许宣头上一道黑气，必有妖怪缠他，叫道：“你近来有一妖怪缠你，其害非轻！我与你二道灵符，救你性命。一道符三更烧，一道符放在自头发内”许宣接了符，纳头便拜，肚内道：“我也八九分疑惑那妇人是妖怪，真个是实。”谢了先生，径回店中。","至晚，白娘子与青青睡着了，许宣起来道：“料有三更了！”将一道符放在自头发内，正欲将一道符烧化，只见白娘子叹一口气道：“小乙哥和我许多时夫妻，尚兀自不把我亲热，却信别人言语，半夜三更，烧符来压镇我！你且把符来烧看！”就夺过符来，一时烧化，全无动静。白娘子道：“却如何？说我是妖怪！”许宣道：“不干我事。卧佛寺前一云游先生，知你是妖怪。”白娘子道：“明日同你去看他一看，如何模样的先生。”","次日，白娘子清早起来，梳妆罢，戴了钡环，穿上素净衣服，分付青青看管楼上。夫妻二人，来到卧佛寺前。只见一簇人，团团围着那先生，在那里散符水。","只见白娘子睁一双妖眼，到先生面前，喝一声：“你好无礼！出家人在在我丈夫面前说我是一个妖怪，书符来捉我！”那先生回言：“我行的是五雷天心正法，凡有妖怪，吃了我的符，他即变出真形来。”那白娘子道：“众人在此，你且书符来我吃看！”那先生书一道符，递与白娘子。白娘子接过符来，便吞下去。众人都看，没些动静。众人道：“这等一个妇人，如何说是妖怪？”众人把那先生齐骂。那先生骂得口睁眼呆，半晌无言，惶恐满面。白娘子道：“众位官人在此，他捉我不得。我自小学得个戏术，且把先生试来与众人看。”只见白娘子口内哺哺的，不知念些甚么，把那先生却似有人擒的一般，缩做一堆，悬空而起。众人看了齐吃一惊。许宣呆了。娘子道：“若不是众位面上，把这先生吊他一年。”白娘子喷口气，只见那先生依然放下，只恨爹娘少生两翼，飞也似走了。众人都散了。夫妻依旧回来，不在话下。日逐盘缠，都是白娘子将出来用度。正是夫唱妇随，朝欢暮乐。","不觉光阴似箭，又是四月初八日，释迦佛生辰。只见街市上人抬着柏亭浴佛，家家布施。许宣对王主人道：“此间与杭州一般。”只见邻舍边一个小的，叫做铁头，道：“小乙官人，今日承天寺里做佛会，你去看一看。”许宣转身到里面，对白娘子说了。白娘子道：“甚么好看，休去！”许宣道：“去走一遭，散闷则个。”","娘子道：“你要去，身上衣服旧了不好看，我打扮你去。”叫青青取新鲜时样衣服来。许宣着得不长不短，一似像体裁的。戴一顶黑漆头巾，脑后一双白玉环，穿一领青罗道袍，脚着一双皂靴，手中拿一把细巧百招描金美人珊甸坠上样春罗扇，打扮得上下齐整。那 娘子分付一声，如茸声巧啃道：“丈夫早早回来，切勿教奴记挂！”许宣叫了铁头相伴，径到承天寺来看佛会。人人喝采，好个官人。只听得有人说道：“昨夜周将仕典当库内，不见了四五千贯金珠细软物件。见今开单告官，挨查，没捉人处。”许宣听得，不解其意，自同铁头在寺。其日烧香官人子弟男女人等往往来来，十分热闹。许宣道：“娘子教我 早回，去罢。”转身人丛中，不见了铁头，独自个走出寺门来。只见五六个人似公人打扮，腰里挂着牌儿。数中一个看了许宣，对众人道：“此人身上穿的，手中拿的，好似那话儿”数中一个认得许宣的道：“小乙官，扇子借我一看。”许宣不知是计，将扇递与公人。那公人道：“你们看这扇子坠，与单上开的一般！”众人喝声：“拿了！”就把许宣一索子绑了，好似：数只皂雕追紫燕，一群饿虎咬羊羔。","许宣道：“众人休要错了，我是无罪之人。”众公人道：“是不是，且去府前周将仕家分解！他店中失去五千贯金珠细软、白玉绦环、细巧百招扇、珊瑚坠子，你还说无罪？真赃正贼，有何分说！实是大胆汉子，把我们公人作等闲看成。见今头上、身上、脚上，都是他家物件，公然出外，全无忌惮！”许宣方才呆了，半晌不则声。许宣道：“原来如此。不妨，不妨，自有人偷得。”众人道：“你自去苏州府厅上分说。”","次日大尹升厅，押过许宣见了。大尹审问：“盗了周将仕库内金珠宝物在于何处？从实供来，免受刑法拷打。”许宣道：“禀上相公做主，小人穿的衣服物件皆是妻子白娘子的，不知从何而来，望相公明镜详辨则个！”大尹喝道：“你妻子今在何处？”许宣道：“见在吉利桥下王主人楼上。”大尹即差缉捕使臣袁子明押了许宣火速捉来。","差人袁子明来到王主人店中，主人吃了一惊，连忙问道：“做甚么？”许宣道：“白娘子在楼上么？”主人道：“你同铁头早去承天寺里，去不多时，白娘子对我说道：‘丈夫去寺中闲耍，教我同青青照管楼上；此时不见回来，我与青青去寺前寻他去也，望乞主人替我照管。出门去了，到晚不见回来。我只道与你去望亲戚，到今日不见回来。”众公人要王主人寻白娘子，前前后后遍寻不见。袁子明将主人捉了，见大尹回话。大尹道：“白娘子在何处？王主人细细禀复了，道：“白 娘子是妖怪。”大尹一问了，道：“且把许宣监了！”王主人使用了些钱，保出在外，伺候归结。","且说周将仕正在对门茶坊内闲坐，只见家人报道：“金珠等物都有了，在库阁头空箱子内。”周将仕听了，慌忙回家看时，果然有了，只不见了头巾、绦环、扇子并扇坠。周将仕道：“明是屈了许宣，平白地害了一个人，不好。”暗地里到与该房说了，把许宣只 问个小罪名。","却说邵太尉使李募事到苏州干事，来王主人家歇。主人家把许宣来到这里，又吃官事，一一从头说了一遍。李募事寻思道：“看自家面上亲眷，如何看做落？只得与他央人情，上下使钱。”一日，大尹把许宣一一供招明白，都做在白娘子身上，只做“不合不出首妖怪等事”，杖一百，配三百六十里，押发镇江府牢城营做工。李募事道：“镇江去便不妨，我有一个结拜的叔叔，姓李名克用，在针子桥下开生药店。我写一封书，你可去投托他。”许宣只得问姐夫借了些盘缠，拜谢了王主人并姐夫，就买酒饭与两个公人吃，收拾行李起程。王主人并姐夫送了一程，各自回去了。","且说许宣在路，饥食渴饮，夜住晓行，不则一日，来到镇江。先寻李克用家，来到针子桥生药铺内。只见主管正在门前卖生药，老将仕从里面走出来。两个公人同许宣慌忙唱个暗道：“小人是杭州李募事家中人，有书在此。”主管接了，递与老将仕。老将仕拆开看了道：“你便是许宣？”许宣道：“小人便是。”李克用教三人吃了饭，分付当直的同到府中，下了公文，使用了钱，保领回家。防送人讨了口文，自归苏州去了。","许宜与当直一同到家中，拜谢了克用，参见了老安人。克用见李募事书，说道：“许宜原是生药店中主管。”因此留他在店中做买卖，夜间教他去五条巷卖豆腐的王公楼上歇。克用见许宣药店中十分精细，心中欢喜。原来药铺中有两个主管，一个张主管，一个赵主管。赵主管一生老实本分。张主管一生克剥奸诈，倚着自老了，欺侮后辈。见又添了许宣，心中不悦，恐怕退了他；反生好计，要嫉妒他。","忽一日，李克用来店中闲看，问：“新来的做买卖如何？”张主管听了心中道：“中我机谋了！”应道：“好便好了，只有一件，……”克用道：“有甚么一件？”","老张道：“他大主买卖肯做，小主儿就打发去了，因此人说他不好。我几次劝他，不肯依我。”老员外说：“这个容易，我自分付他便了，不怕他不依。”赵主管在傍听得此言，私对张主管说道：“我们都要和气。许宣新来，我和你 衬管他才是。有不是宁可当面讲，如何背后去说他？他得知了，只道我们嫉妒。”老张道：“你们后生家，晓得甚么！”天已晚了，各回下处。赵主管来许宣下处道：“张主管在员外面前嫉妒你，你如今要愈加用心，大主小主儿买卖，一般样做。”许宣道：“多承指数。我和你去闲酌一杯。”二人同到店中，左右坐下。酒保将要饭果碟摆下，二人吃了几杯。赵主管说：“老员外最性直，受不得触。你便依随他生性，耐心做买卖。”许宣道：“多谢老兄厚爱，谢之不荆”又饮了两杯，天色晚了。赵主管道：“晚了路黑难行，改日再会。”许宣还了酒钱，各自散了。 许宣觉道有杯酒醉了，恐怕冲撞了人，从屋檐下回去。正走之间，只见一家楼上推开窗，将熨斗播灰下来，都倾在许宣头上。立住脚，便骂道：“淮家泼男女，不生眼睛，好没道理！”只见一个妇人，慌忙走下来道：“官人休要骂，是奴家不是，一时失误了，休怪！”许宣半醉，抬头一看，两眼相观，正是白娘子。许宣怒从心上起，恶向胆边生，无明火焰腾腾高起三千丈，掩纳不住，便骂道：“你这贼贱妖精，连累得我好苦！吃了两场官事！”恨小非君于，无毒不丈夫。正是：踏破铁鞋无觅处，得来全不费工夫。 许宣道：“你如今又到这里，却不是妖怪？”赶将人去，把白娘子一把拿住道：“你要官休私休！”白娘子陪着笑面道：“丈夫，‘一夜夫妻百日恩”和你说来事长。你听我说：当初这衣服，都是我先夫留下的。我与你恩爱深重，教你穿在身上，恩将仇报，反成吴、越？许宣道：“那日我回来寻你，如何不见了”主人都说你同青青来寺前看我，因何又在此间？”白 娘子道：“我到寺前，听得说你被捉了去，教青青打听不着，只道你脱身走了。怕来捉我，教青青连忙讨了一只船，到建康府娘舅家去，昨日才到这里。我也道连累你两场官事，还有何面目见你！你怪我也无用了。情意相投，做了夫妻，如今好端端难道走开了？我与你情似太山，恩同东海，誓同生死，可看日常夫妻之面，取我到下处，和你百年偕老，却不是好！”许宣被白娘子一骗，回嗔作喜，沉吟了半晌，被色迷了心胆，留连之意，不回下处，就在白娘子楼上歇了。 次日，来上河五条巷王公楼家，对王公说：“我的妻子同丫鬟从苏州来到这里。”一一说了，道：“我如今搬回来一处过活。”王公道：“此乃好事，如何用说。”","当日把白娘子同青青撒来王公楼上。次日，点茶请邻舍。第三日，邻舍又与许宣接风。酒筵散了，邻舍各自回去，不在话下。第四日，许宣早起梳洗已罢，对白娘子说：“我去拜谢东西邻舍，去做买卖去也；你同青青只在楼上照管，切勿出门！”分付已了，自到店中做买卖，早去晚回。不觉光阴迅速，日月如梭，又过一月。","忽一日，许宣与白娘商量，去见主人李员外妈妈家眷。白娘子道：“你在他家做主管，去参见了他，也好日常走动。到次日，雇了轿子，径进里面请白娘子上了轿，叫王公挑了盒儿，丫鬟青青跟随，一齐来到李员外家。下了轿于。进轰卜里面，请员外出来。李克用连忙来见，白娘子深深道个万福，拜了两拜，妈妈也拜了两拜，内眷都参见了。原来李克用年纪虽然高大，却专一好色，见了白娘子有倾国之姿，正是：三魂不附体，七魄在他身。","那员外目不转睛，看白娘子。当时安排酒饭管待。妈妈对员外道：“好个伶俐的娘子！十分容貌，温柔和气，本分老成。”员外道：“便是杭州娘子生得俊俏。”饮酒罢了，白娘子相谢自回。李克用心中思想：“如何得这妇人共宿一宵？”眉头一簇，计上心来，道：“六月十三是我寿诞之日，不要慌，教这妇人着我一个道儿。”","不觉乌飞兔走，才过端午，又是六月初间。那员外道：“妈妈，十三日是我寿诞，可做一个筵席，请亲眷朋友闲耍一臼，也是一生的快乐。”当日亲眷邻友主管人等，都下了请帖。次日，家家户户都送烛面手帕物件来。十三日都来赴筵，吃了一日。次日是女眷们来贺寿，也有甘来个。且说白娘子也来，十分打扮，上着青织金衫儿，下穿大红纱裙，戴一头百巧珠翠金银首饰。带了青青，都到里面拜了生日，参见了老安人。东阁下排着筵席。原来李克用是吃虱子留后腿的人，因见白 娘子容貌，设此一计，大排筵席。各各传杯弄盏。酒至半酣，却起身脱衣净手。李员外原来预先分付腹心养娘道：“若是白娘子登东，他要进去，你可另引他到后面僻净房内去。”李员外设计已定，先自躲在后面。正是：不劳钻穴逾墙事，稳做偷香窃玉人。","只见白娘子真个要去净手，养娘便引他到后面一间僻净房内去，养娘自回。那员外心中淫乱，捉身不住，不敢便走进去，却在门缝里张。不张万事皆休，则一张那员外大吃一惊，回身便走，来到后边，往后倒了：不知一命如何，先觉四肢不举！","那员外眼中不见如花似玉体态，只见房中幡着一条吊桶来粗大白蛇，两眼一似灯盏，放出金光来。惊得半死，回身便走，一绊一交。众养娘扶起看时，面青口白。主管慌忙用安魂定魄丹服了，方才醒来。老安人与众人都来看了：道：“你为何大惊小怪做甚么？”李员外不说其事，说道“我今日起得早了，连日又辛苦了些，头风病发，晕倒了。扶去房里睡了。众亲眷再人席饮了几杯，酒筵散罢，众人作谢回家。","白娘子回到家中思想，恐怕明日李员外在铺中对许宣说出本相来，便生一条计，一头脱衣服，一头叹气。许宣道：“今同出去吃酒，因何回来叹气？”白娘子道：“丈夫，说不得！李员外原来假做生日，其心不善。因见我起身登东，他躲在里面，欲要好骗我，扯裙扯裤，来调戏我。欲待叫起来，众人都在那里，怕妆幌子。　被我一推倒地，他怕羞没意思，假说晕倒了。这惶恐那里出气＂许宣道：“既不曾好骗你，他是我主人家，出于无奈，只得忍了。这遭休去便了。”白 娘子道：“你不与我做主，还要做人？”许宣道：“先前多承姐夫写书，教我投奔他家。亏他不阻，收留在家做主管，如今教我怎的好？”白娘子道：“男于汉！我被他这般欺负，你还去他家做主管？”许宣道：“你教我何处去安身？做何生理？”白娘子道：“做人家主管，也是下贱之事，不如自开一个生药铺。”许宣道：“亏你说，只是那讨本钱？白娘子道：“你放心，这个容易。我明日把些银子，你先去赁了 间房子却又说话。” 且说“今是古，古是今”，各处有这般出热的。间壁有一个人，姓蒋名和，一生出热好事。次日，许宣问白娘子讨了些银子，教蒋和去镇江渡口马头上，赁了一间房子，买下一付生药厨柜，陆续收买生药，十月前后，俱已完备，选日开张药店，不去做主管。那李员外也自知惶恐，不去叫他。 许宣自开店来，不觉买卖一日兴一日，普得厚利。正在门前卖生药，只见一个和尚将着一个募缘簿子道：“小僧是金山寺和尚，如今七月初七日是英烈龙王生日，伏望官人到寺烧香，布施些香钱。”许宣道：“不必写名。我有一块好降香，舍与你拿去烧罢。即便开柜取出递与和尚。和尚接了道：“是日望官人来烧香！”打一个问讯去了。白娘子看见道：“你这杀才，把这一块好香与那贼秃去换酒肉吃！”许宣道：“我一片诚心舍与他，花费了也是他的罪过。” 不觉又是七月初七日，许宣正开得店，只见街上闹热，人来人往。帮闲的蒋和道：“小乙官前日布施了香，今日何不去寺内闲走一遭？”许宣道：“我收拾了，略待略待。和你同去。”蒋和道：“小人当得相伴。”许宣连忙收拾了，进去对白娘子道：“我去金山寺烧香，你可照管家里则个。”白娘子道：“无事不登三宝殿’，去做甚么？”许宣道：“一者不曾认得金山寺，要去看一看；二者前日布施了，要去烧香。”白娘子道：“你既要去，我也挡你不得，也要依我三件事。”许宣道：“那三件？”白娘子道：“一件，不要去方丈内去；二件，不要与和尚说话：三件，去了就回，来得迟，我便来寻你也。”许宣道：“这个何妨，都依得。”当时换了新鲜衣服鞋袜，袖了香盒，同蒋和径到江边，搭了船，投金山寺来。先到龙王堂烧了香，绕寺闲走了一遍，同众人信步来到方丈门前。许宣猛省道：“妻子分付我休要进方丈内去。立住了脚，不进去。蒋和道：“不妨事，他自在家中，回去只说不曾去便了。”说罢，走入去，看了一回，便出来。 且说方丈当中座上，坐着一个有德行的和尚，眉清目秀，圆顶方袍，看了模样，确是真僧。一见许宣走过，便叫侍者：“快叫那后生进来。”恃者看了一回，人千人万，乱滚滚的，又不认得他，回说：“不知他走那边去了？”和尚见说，持了掸杖，自出方丈来，前后寻不见，复身出寺来看，只见众人都在那里等风浪静了落船。那风浪越大了，道：“去不得。”正看之间，只见江心里一只船飞也似来得快。","许宣对蒋和道：“这船大风浪过不得渡，那只船如何到来得快！”正说之间，船已将近。看时，一个穿白的妇人，一个穿青的女子来到岸边。仔细一认，正是白娘子和青青两个。许宣这一惊非校白娘子来到岸边，叫道：“你如何不归？快来上船！”许宣却欲上船，只听得有人在背后喝道：“业畜在此做甚么？”许宣回头看时，人说道：“法海禅师来了！”禅师道：“业畜，敢再来无礼，残害生灵！老僧为你特来。”白娘子见了和尚，摇开船，和青青把船一翻，两个都翻下水底去了。许宣回身看着和尚便拜：“告尊师，救弟子一条草命！”禅师道：“你如何遇着这妇人？”许宣把前项事情从头说了一遍。禅师听罢，道：“这妇人正是妖怪，汝可速回杭州去，如再来缠汝，可到湖南净慈寺里来寻我。有诗四句：","本是妖精变妇人，西湖岸上卖娇声。","汝国不识这他计，有难湖南见老憎。","许宣拜谢了法海禅师，同蒋和下了渡船，过了江，上岸归家。白娘子同青青都不见了，方才信是妖精。到晚来，教蒋和相伴过夜，心中昏闷，一夜不睡。次日早起，叫蒋和看着家里，却来到针子桥李克用家，把前项事情告诉了一遍。李克用道：“我生日之时，他登东，我撞将去，不期见了这妖怪，惊得我死去；我又不敢与你说这话。既然如此，你且搬来我这里住着，别作道理。许宣作谢了李员外，依旧搬到他家。不觉住过两月有余。","忽一日立在门前，只见地方总甲分付排门人等，俱要香花灯烛迎接朝廷恩赦。原来是宋高宗策立孝宗，降赦通行天下，只除人命大事，其余小事，尽行赦放回家。许宣遇赦，欢喜不胜，吟诗一首，诗云：","感谢吾皇降赦文，网开三面许更新。","死时不作他邦鬼，生日还为旧土人。","不幸逢妖愁更甚，何期遇宵罪除根。","归家满把香焚起，拜谢乾坤再造恩。 许宣吟诗已毕，央李员外衙门上下打点使用了钱，见了大尹，给引还乡。拜谢东邻西舍，李员外妈妈合家大孝二位主管，俱拜别了。央帮闲的蒋和买了些土物带回杭州。来到家中，见了姐夫姐姐，拜了四拜。李募事见了许宣，焦躁道：“你好生欺负人！我两遭写书教你投托人，你在李员外家娶了老小，不直得寄封书来教我知道，直恁的无仁无义！”许宣说：“我不曾娶妻 小”姐夫道：“见今两日前，有一个妇人带着一个丫鬟，道是你的妻子。说你七月初七日去金山寺烧香，不见回来。那里不寻到？直到如今，打听得你回杭州，同丫鬟先到这里等你两日了。教人叫出那妇人和丫鬟见了许宣。许宣看见，果是白 娘子、青青。许宣见了，目睁口呆，吃了一惊，不在姐夫姐姐面前说这话本，只得任他埋怨了一通。李募事教许宣共白娘子去一间房内去安身。许宣见晚了，怕这白娘子，心中慌了，不敢向前，朝着白娘子跪在地下道：“不知你是何神何鬼，可饶我的性命！”白娘子道：“小乙哥，是何道理？我和你许多时夫妻，又不曾亏负你，如何说这等没力气的话。”许宣道：“自从和你相识之后，带累我吃了两场官司。我到镇江府，你又来寻我。前日金山寺烧香，归得迟了，你和青青又直赶来。见了禅师，便跳下江里去了。我只道你死了，不想你又先到此。望乞可怜见，饶我则个！”白 娘子圆睁怪眼道：“小乙官，我也只是为好，谁想到成怨本！我与你平生夫妇，共枕同衾许多恩爱，如今却信别人闲言语，教我夫妻不睦。我如今实对你说，若听我言语喜喜欢欢，万事皆休；若生外心，教你满城皆为血水，人人手攀洪浪，脚踏浑波，皆死于非命。”惊得许宣战战兢兢，半晌无言可答，不敢走近前去。青青劝道：“官人，娘子爱你杭州人生得好，又喜你恩情深重。听我说，与娘子和睦了，休要疑虑。”许宣吃两个缠不过，叫道：“却是苦那！”只见姐姐在天井里乘凉，听得叫苦，连忙来到房前，只道他两个儿厮闹，拖了许宣出来。白娘子关上房门自睡。","许宣把前因后事，一一对姐姐告诉了一遍。却好姐夫乘凉归房，姐姐道：“他两口儿厮闹了，如今不知睡了也未，你且去张一张了来。”李募事走到房前看时，里头黑了，半亮不亮，将舌头舔破纸窗，不张万事皆休，一张时，见一条吊桶来大的蟒蛇，睡在床上，伸头在天窗内乘凉，鳞甲内放出白光来，照得房内如同白日。吃了一惊，回身便走。来到房中，不说其事，道：“睡了，不见则声。”许宣躲在姐姐房中，不敢出头，姐夫也不问他。过了一夜。","次日，李募事叫许宣出去，到僻静处问道：“你妻子从何娶来？实实的对我说，不要瞒我，昨夜亲眼看见他是一条大白蛇，我怕你姐姐害怕，不说出来。” 许宣把从头事，一一对姐夫说了一遍。李募事道：“既是这等，白马庙前一个呼蛇戴先生，如法捉得蛇，我问你去接他。”二人取路来到白马庙前，只见戴先生正立在门口。二人道：“先生拜揖。”先生道：“有何见谕？”许宣道：“家中有一条大蟒蛇，想烦一捉则个！”先生道：“宅上何处”许宣道：“过军将桥黑珠儿巷内李募事家便是。”取出一两银子道：“先生收了银子，待捉得蛇另又相谢。”先生收了道：“二位先回，小子便来。”李募事与许宣自回。","那先生装了一瓶雄黄药水，一直来到黑珠儿巷门，问李募事家。人指道：“前面那楼子内便是。”先生来到门前，揭起帘子，咳嗽一声，并无一个人出来。","敲了半晌门，只见一个小娘子出来问道：“寻谁家？”先生道：“此是李募事家么？”小娘子道：“便是。”先生道：“说宅上有一条大蛇，却才二位官人来请小子捉蛇。”小娘子道：“我家那有大蛇？你差了。”先生道：“官人先与我一两银子，说捉了蛇后，有重谢。”白娘子道：“没有，休信他们哄你。先生道：“如何作耍？”白 娘子三回五次发落不去，焦躁起来，道：“你真个会捉蛇？只怕你捉他不得！”戴先生道：“我祖宗七八代呼蛇捉蛇，量道一条蛇有何难捉！”娘子道，“  你说捉得，只怕你见了要走！”先生道：“不走，不走！如走，罚一锭白银。”娘子道：“随我来。”到天井内，那娘子转个湾，走进去了。那先生手中提着瓶儿，立在空地上，不多时，只见刮起一阵冷风，风过处，只见一条吊桶来大的蟒蛇，连射将来，正是：人无害虎心，虎有伤人意。","且说那戴先生吃了一惊，望后便倒，雄黄罐儿也打破了，那条大蛇张开血红大口，露出雪白齿，来咬先生。先生慌忙爬起来，只恨爹娘少生两脚，一口气跑过桥来，正撞着李募事与许宣。许宣道：“如何？”那先生道：“好教二位得知，……”把前项事，从头说了一遍，取出那一两银子付还李募事道：“若不生这双脚，连性命都没了。二位自去照顾别人。”急急的去了。许宣道：“姐夫，如今怎么处？”李募事道：“眼见实是妖怪了。如今赤山埠前张成家欠我一千贯钱，你去那里静处，讨一间房儿住下。那怪物不见了你，自然去了。”许宣无计可奈，只得应承。同姐夫到家时，静悄悄的没些动静。李募事写了书贴，和票子做一封，教许宣往赤山埠去。只见白娘子叫许宣到房中道：“你好大胆，又叫甚么捉蛇的来！ 你若和我好意，佛眼相看；若不好时，带累一城百姓受苦，都死于非命！”许宣听得，心寒胆战，不敢则声。将了票子，闷闷不已。来到赤山埠前，寻着了张成。随即袖中取票时，不见了，只叫得苦。慌忙转步，一路寻回来时，那里见！","正闷之间，来到净慈寺前，忽地里想起那金山寺长老法海禅师曾分付来：“倘若那妖怪再来杭州缠你，可来净慈寺内来寻我。”如今不寻，更待何时？急入寺中，问监寺道：“动问和尚，法海禅师曾来上刹也未？”那和尚道：“不曾到来。”","许宣听得说不在，越闷，折身便回来长桥堍下，自言自语道：“‘时衰鬼弄人，我要性命何用？看着一湖清水，却待要跳！正是：阎王判你三更到，定不容人到四更。”","许宣正欲跳水，只听得背后有人叫道：“男子汉何故轻生？死了一万口，只当五千双，有事何不问我！”许宣回头看时，正是法海禅师，背驮衣钵，手提禅杖，原来真个才到。也是不该命尽，再迟一碗饭时，性命也休了。许宣见了禅师，纳头便拜，道：“救弟子一命则个！”禅师道：“这业畜在何处？”许宣把上项事一一诉了，道：“如今又直到这里，求尊师救度一命。”禅师于袖中取出一个钵孟，递与许宣道：“你若到家，不可教妇人得知，悄悄的将此物劈头一罩，切勿手轻，紧紧的按住，不可心慌，你便回去。”","且说许宣拜谢了禅师，回家。只见白娘子正坐在那里，口内喃喃的骂道：“不知甚人挑拨我丈夫和我做冤家，打听出来，和他理会！”正是有心等了没心的，许宣张得他眼慢，背后悄悄的，望白娘子头上一罩，用尽平生气力 便不见了女子之形，随着钵盂慢慢的按下，不敢手松，紧紧的按住。只听得钵盂内道：“和你数载夫妻，好没一些儿人情！略放一放！”许宣正没了结处，报道：“有一个和尚，说道：‘要收妖怪。’”许宣听得，连忙教李募事请禅师进来。来到里面，许宣道：“救弟子则个！”不知禅师口里念的甚么。念毕，轻轻的揭起钵盂，只见白娘子缩做七八寸长，如傀儡人像，双眸紧闭，做一堆儿，伏在地下。禅师喝道：“是何业畜妖怪，怎敢缠人？可说备细！”白 娘子答道：“禅师，我是一条大蟒蛇。因为风雨大作，来到西湖上安身，同青青一处。不想遇着许宣，春心荡漾，按纳不住一时冒犯天条，却不曾杀生害命。望禅师慈悲则个！”禅师又问：“青青是何怪？”白娘子道：“青青是西湖内第三桥下潭内千年成气的青鱼。一时遇着，拖他为伴。他不曾得一日欢娱，并望禅师怜悯！”禅师道：“念你千年修炼，免你一死，可现本相！”白娘子不肯。禅师勃然大怒，口中念念有词，大喝道：“揭谛何在？快与我擒青鱼怪来，和白蛇现形，听吾发落！”须臾庭前起一阵狂风。风过处，只闻得豁刺一声响，半空中坠下一个青鱼，有一丈多长，向地拨刺的连跳几跳，缩做尺余长一个小青鱼。看那白娘子时，也复了原形，变了三尺长一条白蛇，兀自昂头看着许宣。禅师将二物置于钵盂之内，扯下相衫一幅，封了钵盂口。拿到雷峰寺前，将钵盂放在地下，令人搬砖运石，砌成一塔。后来许宣化缘，砌成了七层宝塔，千年万载，白蛇和青鱼不能出世。","且说禅师押镇了，留偈四句： 　　　 　西湖水干，江潮不起，雷峰塔倒，白蛇出世。","法海禅师言渴毕。又题诗八句以劝后人： 　　　　　 奉劝世人休爱色，爱色之人被色迷。","心正自然邪不扰，身端忽有恶来欺？","但看许宣因爱色，带累官司惹是非。","不是老憎来救护，白蛇吞了不留些。","法海禅师吟罢，各人自散。惟有许宣情愿出家，礼拜禅师为师，就雷峰塔披剃为僧。修行数年，一夕坐化去了。众僧买龛烧化，造一座骨塔，千年不朽，临去世时，亦有诗八句，留以警世，诗曰：","祖师度我出红尘，铁树开花始见春。","化化轮回重化化，生生转变再生生。","欲知有色还无色，须识无形却有形。","色即是空空即色，空空色色要分明。"],"cpLength":18304},"jstl-32":{"chapterId":"jstl-32","bookId":"jstl","fileIndex":31,"number":32,"title":"第三十二卷　杜十娘怒沉百宝箱","paragraphs":["扫荡残胡立帝畿，龙翔凤舞势崔嵬。","左环沧海天一带，右拥太行山万围。","戈戟九边雄绝塞，衣冠万国仰垂衣。","太平人乐华胥世，永永金瓯共日辉。","这首诗单夸我朝燕京建都之盛。说起燕都的形势，北倚雄关，南压区夏，真乃金城天府，万年不拔之基。当先洪武爷扫荡胡尘，定鼎金陵，是为南京。到永乐爷从北平起兵靖难，迁于燕都，是为北京。只因这一迁，把个苦寒地而变作花锦世界。自永乐爷九传至于万历爷，此乃我朝第十一代的天了。这位天子，聪明神武，德福兼全，十岁登基，在位四十八年，削平了三处寇乱。那三处？","日本关白平秀吉，西夏承恩，播州杨应龙。 平秀吉侵犯朝鲜，承恩、杨应龙是土官谋叛，先后削平。远夷莫不畏服，争来朝贡。真个是：","一人有庆民安乐，四海无虞国太平。","话中单表万历二十年间，日本国关白作乱，侵犯朝鲜。朝鲜国王上表告急，天朝发兵泛海往救。有户部官奏准：目今兵兴之际，粮饷未充，暂开纳粟入监之例。原来纳粟入监的，有几般便宜：好读书，好科举，好中，结末来又有个小小前程结果。以此宦家公子、富室子弟，到不愿做秀才，都去援例做太学生。自开了这例，两京太学生各添至千人之外。内中有一人，姓李名甲，字子先，浙江绍兴府人氏。父亲李布政所生三儿，惟甲居长，自幼读书在庠，未得登科，援例入于北雍。因在京坐监，与同乡柳遇春监生同游教坊司院内，与一个名姬相遇。那名姬姓杜名媺，排行第十，院中都称为杜十娘，生得： 浑身雅艳，遍体娇香，两弯眉画远山青，一对眼明秋水润。脸如莲萼，分明卓氏文君；唇似樱桃，何减白家樊素。可怜一片无瑕玉，误落风尘花柳中。","那杜十娘自十三岁破瓜，今一十九岁，七年之内，不知历过了多少公子王孙。一个个情迷意荡，破家荡产而不惜。院中传出四句口号来，道是：","坐中若有杜十娘，斗筲之量饮千觞。","院中若识杜老媺，千家粉面都如鬼。","却说李公子风流年少，未逢美色，自遇了杜十娘，喜出望外，把花柳情怀，一担儿挑在他身上。那公子俊俏庞儿，温存性儿，又是撒漫的手儿，帮衬的勤儿，与十娘一双两好，情投意合。十娘因见鸨儿贪财无义，久有从良之志，又见李公子忠厚志诚，甚有心向他。奈李公子惧怕老爷，不敢应承。虽则如此，两下情好愈密，朝欢暮乐，终日相守，如夫妇一般。海誓山盟，各无他志。真个：","恩深似海恩无底，义重如山义更高。 再说杜妈妈，女儿被李公子占住，别的富家巨室，闻名上门，求一见而不可得。初时李公子撒漫用钱，大差大使，妈妈胁肩诌笑，奉承不暇。日往月来，不觉一年有余，李公子囊箧渐渐空虚，手不应心，妈妈也就怠慢了。老布政在家闻知儿子嫖院，几遍写字来唤他回去。他迷恋十娘颜色，终日延捱。后来闻知老爷在家发怒，越不敢回。古人云：“以利相交者，利尽而疏。”那杜十娘与李公子真情相好，见他手头愈短，心头愈热。妈妈也几遍教女儿打发李甲出院，见女儿不统口，又几遍将言语触突李公子，要激怒他起身。公子性本温克，词气愈和。妈妈没奈何，日逐只将十娘叱骂道：“我们行户人家，吃客穿客，前门送旧，后门迎新，门庭闹如火，钱帛堆成垛。自从那李甲在此，混帐一年有余，莫说新客，连旧主顾都断了。分明接了个锺馗老，连小鬼也没得上门，弄得老娘一家人家，有气无烟，成什么模样！”","杜十娘被骂，耐性不住，便回答道：“那李公子不是空手上门的，也曾费过大钱来。”妈妈道：“彼一时，此一时，你只教他今日费些小钱儿，把与老娘办些柴米，养你两口也好。别人家养的女儿便是摇钱树，千生万活，偏我家晦气，养了个退财白虎！开了大门七件事，般般都在老身心上。到替你这小贱人白白养着穷汉，教我衣食从何处来？你对那穷汉说：“有本事出几两银子与我，到得你跟了他去，我别讨个丫头过活却不好？”十娘道：“妈妈，这话是真是假？”妈妈晓得李甲囊无一钱，衣衫都典尽了，料他没处设法，便应道：“老娘从不说谎，当真哩。”十娘道：“娘，你要他许多银子？”妈妈道：“若是别人，千把银子也讨了。可怜那穷汉出不起，只要他三百两，我自去讨一个粉头代替。只一件，须是三日内交付与我，左手交银，右手交人。”若三日没有银时，老身也不管三十二十一，公子不公子，一顿孤拐，打那光棍出去。那时莫怪老身！”十娘道：“公子虽在客边乏钞，谅三百金还措办得来。只是三日忒近，限他十日便好。”妈妈想道：“这穷汉一双赤手，便限他一百日，他那里来银子？没有银子，便铁皮包脸，料也无颜上门。那时重整家风，媺儿也没得话讲。”答应道：“看你面，便宽到十日。第十日没有银子，不干老娘之事。”十娘道：“若十日内无银，料他也无颜再见了。只怕有了三百两银子，妈妈又翻悔起来。”妈妈道：“老身年五十一岁了，又奉十斋，怎敢说谎？不信时与你拍掌为定。若翻悔时，做猪做狗！”","从来海水斗难量，可笑虔婆意不良。","料定穷儒囊底竭，故将财礼难娇娘。","是夜，十娘与公子在枕边，议及终身之事。公子道：“我非无此心。但教坊落籍，其费甚多，非千金不可。我囊空如洗，如之奈何！”十娘道：“妾已与妈妈议定只要三百金，但须十日内措办。郎君游资虽罄，然都中岂无亲友可以借贷？倘得如数，姜身遂为君之所有，省受虔婆之气。”公子道：“亲友中为我留恋行院，都不相顾。明日只做束装起身，各家告辞，就开口假贷路费，凑聚将来，或可满得此致。”起身梳洗，别了十娘出门。十娘道：用心作速，专听佳音。”公子道：“不须分付。”","公子出了院门，来到三亲四友处，假说起身告别，众人到也欢喜。后来叙到路费欠缺，意欲借贷。常言道：“说着钱，便无缘。”亲友们就不招架。他们也见得是，道李公子是风流浪子，迷恋烟花，年许不归，父亲都为他气坏在家。他今日抖然要回，未知真假，倘或说骗盘缠到手，又去还脂粉钱，父亲知道，将好意翻成恶意，始终只是一怪，不如辞了干净。便回道：“目今正值空乏，不能相济，惭愧，惭愧！”人人如此，个个皆然，并没有个慷慨丈夫，肯统口许他一十二十两。李公子一连奔走了三日，分毫无获，又不敢回决十娘，权且含糊答应。到第四日又没想头，就羞回院中。平日间有了杜家，连下处也没有了，今日就无处投宿。只得往同乡柳监生寓所借歇。","柳遇春见公子愁容可掬，问其来历。公子将杜十娘愿嫁之情，备细说了。遇春摇首道：“未必，未必。那杜媺曲中第一名姬，要从良时，怕没有十斛明珠，千金聘礼。那鸨儿如何只要三百两？想鸨儿怪你无钱使用，白白占住他的女儿，设计打发你出门。那妇人与你相处已久，又碍却面皮，不好明言。明知你手内空虚，故意将三百两卖个人情，限你十日；若十日没有，你也不好上门。便上门时，他会说你笑你，落得一场亵渎，自然安身不牢，此乃烟花逐客之计。足下三思，休被其惑。据弟愚意，不如早早开交为上。”公子听说，半晌无言，心中疑惑不定。遇春又道：“足下莫要错了主意。你若真个还乡，不多几两盘费，还有人搭救；若是要三百两时，莫说十日，就是十个月也难。如今的世情，那肯顾缓急二字的！那烟花也算定你没处告债，故意设法难你。”公子道：“仁兄所见良是。”口里虽如此说，心中割舍不下。依旧又往外边东央西告，只是夜里不进院门了。","公子在柳监生寓中，一连住了三日，共是六日了。杜十娘连日不见公子进院，十分着紧，就教小厮四儿街上去寻。四儿寻到大街，恰好遇见公子。四儿叫道：“李姐夫，娘在家里望你。”公子自觉无颜，回复道：“今日不得功夫，明日来罢。”四儿奉了十娘之命，一把扯住，死也不放，道：“娘叫咱寻你，是必同去走一遭。”李公子心上也牵挂看婊子，没奈何，只得随四儿进院，见了十娘，嘿嘿无言。十娘问道：“所谋之事如何？”公子眼中流下泪来。十娘道：“莫非人情淡薄，不能足三百之数么？”分子含泪而言，道出二句：","“不信上山擒虎易，果然开口告人难。","一连奔走六日，并无铢两，一双空手，羞见芳卿，故此这几日不敢进院。今日承命呼唤，忍耻而来。非某不用心，实是世情如此。”十娘道：“此言休使虔婆知道。郎君今夜且住，妾别有商议。”十娘自备酒肴，与公子欢饮。睡至半夜，十娘对公子道：“郎君果不能办一钱耶？妾终身之事，当如何也？”公子只是流涕，不能答一语。渐渐五更天晓。十娘道：“妾所卧絮褥内藏有碎银一百五十两，此妾私蓄，郎君可持去。三百金，妾任其半，郎君亦谋其半，庶易为力。限只四日，万勿迟误！”十娘起身将褥付公子，公子惊喜过望。唤童儿持褥而去。径到柳遇春寓中，又把夜来之情与遇春说了。将褥拆开看时，絮中都裹着零碎银子，取出兑时果是一百五十两。遇春大惊道：“此妇真有心人也。既系真情，不可相负，吾当代为足下谋之。”公子道：“倘得玉成，决不有负。”当下柳遇春留李公子在寓，自出头各处去借贷。两日之内，凑足一百五十两交付公子道：“吾代为足下告债，非为足下，实怜杜十娘之情也。” 李甲拿了三百两银子，喜从天降，笑逐颜开，欣欣然来见十娘，刚是第九日，还不足十日。十娘问道：“前日分毫难借，今日如何就有一百五十两？”公子将柳监生事情，又述了一遍。十娘以手加额道：“使吾二人得遂其愿者，柳君之力也！两个欢天喜地，又在院中过了一晚。","次日十娘早起，对李甲道：“此银一交，便当随郎君去矣。舟车之类，合当预备。妾昨日于姊妹中借得白银二十两，郎君可收下为行资也。”公子正愁路费无出，但不敢开口，得银甚喜。说犹未了，鸨儿恰来敲门叫道：“媺儿，今日是第十日了。”公子闻叫，启门相延道：“承妈妈厚意，正欲相请。”便将银三百两放在桌上。鸨儿不料公子有银，嘿然变色，似有悔意。十娘道：“儿在妈妈家中八年，所致金帛，不下数千金矣。今日从良美事，又妈妈亲口所订，三百金不欠分毫，又不曾过期。倘若妈妈失信不许，郎君持银去，儿即刻自尽。恐那时人财两失，悔之无及也。”鸨儿无词以对。腹内筹画了半晌，只得取天平兑准了银子，说道：“事已如此，料留你不住了。只是你要去时，即今就去。平时穿戴衣饰之类，毫厘休想！”说罢，将公子和十娘推出房门，讨锁来就落了锁。此时九月天气。十娘才下床，尚未梳洗，随身旧衣，就拜了妈妈两拜。李公子也作了一揖。一夫一妇，离了虔婆大门：","鲤鱼脱却金钩去，摆尾摇头再不来。","公子教十娘且住片时：“我去唤个小轿抬你，权往柳荣卿寓所去，再作道理。”十娘道：“院中诸姊妹平昔相厚，理宜话别。况前日又承他借贷路费，不可不一谢也。”乃同公子到各姊妹处谢别。姊妹中惟谢月朗、徐素素与杜家相近，尤与十娘亲厚：十娘先到谢月朗家。月朗见十娘秃髻旧衫，惊问其故。十娘备述来因，又引李甲相见。十娘指月朗道：“前日路资，是此位姐姐所贷，郎君可致谢。”李甲连连作揖。月朗便教十娘梳洗，一面去请徐素素来家相会。十娘梳洗已毕，谢、徐二美人各出所有，翠钿金钏，瑶簪宝珥，锦袖花裙，鸾带绣履，把杜十娘装扮得焕然一新，备酒作庆贺筵席。月朗让卧房与李甲、杜媺二人过宿。次日，又大排筵席，遍请院中姊妹。凡十娘相厚者，无不毕集，都与他夫妇把盏称喜。吹弹歌舞，各逞其长，务要尽欢，直饮至夜分。十娘向众姊妹一一称谢。众姊妹道：“十姊为风流领袖，今从郎君去，我等相见无日。何日长行，姊妹们尚当奉送。”月朗道：“候有定期，小妹当来相报。但阿姊千里间关，同郎君远去，囊箧萧条，曾无约束，此乃吾等之事。当相与共谋之，勿令姊有穷途之虑也。”众姊妹各唯唯而散。 是晚，公子和十娘仍宿谢家。至五鼓，十娘对公子道：“吾等此去，何处安身？郎君亦曾糀E议有定着否？”公子道：“老父盛怒之下，若知娶妓而归，必然加以不堪，反致相累。展转寻思，尚未有万全之策。”十娘道：“父子天性，岂能终绝？既然仓卒难犯，不若与郎君于苏、杭胜地，权作浮居。郎君先回，求亲友于尊大人面前劝解和顺，然后携妾于归，彼此安妥。”公子道：“此言甚当。”次日，二人起身辞了谢月朗，暂往柳监生寓中，整顿行装。杜十娘见了柳遇春，倒身下拜，谢其周全之德：“异日我夫妇必当重报。”遇春慌忙答礼道：“十娘钟情所欢，不以贫窭易心，此乃女中豪杰。仆因风吹火，谅区区何足挂齿！”三人又饮了一日酒。次早，择了出行吉日，雇倩轿马停当。十娘又遣童儿寄信，别谢月朗。临行之际，只见肩舆纷纷而至，乃谢月朗与徐素素拉众姊妹来送行。月朗道：“十姊从郎君千里间关，囊中消索，吾等甚不能忘情。今合具薄赆，十姊可检收，或长途空乏，亦可少助。”说罢，命从人挈一描金文具至前，封锁甚固，正不知什么东西在里面。十娘也不开看，也不推辞，但殷勤作谢而已。须臾，舆马齐集，仆夫催促起身。柳监生三杯别酒，和众美人送出崇文门外，各各垂泪而别。正是：","他日重逢难预必，此时分手最堪怜。","再说李公子同杜十娘行至潞河，舍陆从舟。却好有瓜州差使船转回之便，讲定船钱，包了舱口。比及下船时，李公子囊中并无分文余剩。你道杜十娘把二十两银子与公子，如何就没了？公子在院中嫖得衣衫蓝缕，银子到手，未免在解库中取赎几件穿着，又制办了铺盖，剩来只勾轿马之费。公子正当愁闷，十娘道：“郎君勿忧，众姊妹合赠，必有所济。”及取钥开箱。公子有傍自觉惭愧，也不敢窥觑箱中虚实。只见十娘在箱里取出一个红绢袋来，掷于桌上道：“郎君可开看之。”公子提在手中，觉得沉重，启而观之，皆是白银，计数整五十两。十娘仍将箱子下锁，亦不言箱中更有何物。但对公子道：“承众姊妹高情，不惟途路不乏，即他日浮寓吴、越间，亦可稍佐吾夫妻山水之费矣。”公子且惊且喜道：“若不遇恩卿，我李甲流落他乡，死无葬身之地矣。此情此德，白头不敢忘也！”自此每谈及往事，公子必感激流涕，十娘亦曲意抚慰。一路无话。","不一日，行至瓜州，大船停泊岸口，公子别雇了民船，安放行李。约明日侵晨，剪江而渡。其时仲冬中旬，月明如水，公子和十娘坐于舟首。公子道：“自出都门，困守一舱之中，四顾有人，未得畅语。今日独据一舟，更无避忌。且已离塞北，初近江南，宜开怀畅饮，以舒向来抑郁之气。恩卿以为何如？”十娘道：“妾久疏谈笑，亦有此心，郎君言及，足见同志耳。”公子乃携酒具于船首，与十娘铺毡并坐，传杯交盏。饮至半酣，公子执卮对十娘道：“恩卿妙音，六院推首。某相遇之初，每闻绝调，辄不禁神魂之飞动。心事多违，彼此郁郁，鸾鸣凤奏，久矣不闻。今清江明月，深夜无人，肯为我一歌否？”十娘兴亦勃发，遂开喉顿嗓，取扇按拍，呜呜咽咽，歌出元人施君美《拜月亭》杂剧上“状元执盏与婵娟”一曲，名《小桃红》。真个：","声飞霄汉訟E皆驻，响入深泉鱼出游。","却说他舟有一少年，姓孙名富，字善赉，徽州新安人氏。家资巨万，积祖扬州种盐。年方二十，也是南雍中朋友。生性风流，惯向青楼买笑，红粉追欢，若嘲风弄月，到是个轻薄的头儿。事有偶然，其夜亦泊舟瓜州渡口，独酌无聊，忽听得歌声嘹亮，风吟鸾吹，不足喻其美。起立船头，伫听半晌，方知声出邻舟。正欲相访，音响倏已寂然，乃遣仆者潜窥踪迹，访于舟人。但晓得是李相公雇的船，并不知歌者来历。孙富想道：“此歌者必非良家，怎生得他一见？”展转寻思，通宵不寐。捱至五更，忽闻江风大作。及晓，彤云密布，狂雪飞舞。怎见得，有诗为证：","千山云树灭，万径人踪绝。","扁舟蓑笠翁，独钓寒江雪。","因这风雪阻渡，舟不得开。孙富命艄公移船，泊于李家舟之傍。孙富貂帽狐裘，推窗假作看雪。值十娘梳洗方毕，纤纤玉手揭起舟傍短帘，自泼盂中残水。粉容微露，却被孙富窥见了，果是国色天香。魂摇心荡，迎眸注目，等候再见一面，杳不可得。沉思久之，乃倚窗高吟高学士《梅花诗》二句，道： 　　雪满山中高士卧，月明林下美人来。 李甲听得邻舟吟诗，舒头出舱，看是何人。只因这一看，正中了孙富之计。孙富吟诗，正要引李公子出头，他好乘机攀话。当下慌忙举手，就问：“老兄尊姓何讳？”李公子叙了姓名乡贯，少不得也问那孙富。孙富也叙过了。又叙了些太学中的闲话，渐渐亲熟。孙富便道：“风雪阻舟，乃天遣与尊兄相会，实小弟之幸也。舟次无聊，欲同尊兄上岸，就酒肆中一酌，少领清诲，万望不拒。”公子道：“萍水相逢，何当厚扰？”孙富道：“说那里话！‘四海之内，皆兄弟也’。”喝教艄公打跳，童儿张伞，迎接公子过船，就于船头作揖。然后让公子先行，自己随后，各各登跳上涯。","行不数步，就有个酒楼。二人上楼，拣一副洁净座头，靠窗而坐。酒保列上酒肴。孙富举杯相劝，二人赏雪饮酒。先说些斯文中套话，渐渐引入花柳之事。二人都是过来之人，志同道合，说得入港，一发成相知了。孙富屏去左右，低低问道：“昨夜尊舟清歌者，何人也？”李甲正要卖弄在行，遂实说道：“此乃北京名姬杜十娘也。”孙富道：“既系曲中姊妹，何以归兄？”公子遂将初遇杜十娘，如何相好，后来如何要嫁，如何借银讨他，始末根由，备细述了一遍。孙富道：“兄携丽人而归，固是快事，但不知尊府中能相容否？”公子道：“贱室不足虑，所虑者老父性严，尚费踌躇耳！”孙富将机就机，便问道：“既是尊大人未必相容，兄所携丽人，何处安顿？亦曾通知丽人，共作计较否？”公子攒眉而答道：“此事曾与小妾议之。”孙富欣然问道：“尊宠必有妙策。”公子道：“他意欲侨居苏杭，流连山水。使小弟先回，求亲友宛转于家君之前，俟家君回嗔作喜，然后图归。高明以为何如？”孙富沉吟半晌，故作愀然之色，道：“小弟乍会之间，交浅言深，诚恐见怪。”公子道：“正赖高明指教，何必谦逊？”孙富道：“尊大人位居方面，必严帷薄之嫌，平时既怪兄游非礼之地，今日岂容兄娶不节之人？况且贤亲贵友，谁不迎合尊大人之意者？兄枉去求他，必然相拒。就有个不识时务的进言于尊大人之前，见尊大人意思不允，他就转口了。兄进不能和睦家庭，退无词以回复尊宠。即使留连山水，亦非长久之计。万一资斧困竭，岂不进退两难！”","公子自知手中只有五十金，此时费去大半，说到资斧困竭，进退两难，不觉点头道是。孙富又道：“小弟还有句心腹之谈，兄肯俯听否？”公子道：“承兄过爱，更求尽言。”孙富道：“疏不间亲，还是莫说罢。”公子道：“但说何妨！”孙富道：“自古道：‘妇人水性无常。’况烟花之辈，少真多假。他既系六院名姝，相识定满天下；或者南边原有旧约，借兄之力，挈带而来，以为他适之地。”公子道：“这个恐未必然。”孙富道：“既不然，江南子弟，最工轻薄。兄留丽人独居，难保无逾墙钻穴之事。若挈之同归，愈增尊大人之怒。为兄之计，未有善策。况父子天伦，必不可绝。若为妾而触父，因妓而弃家，海内必以兄为浮浪不经之人。异日妻不以为夫，弟不以为兄，同袍不以为友，兄何以立于天地之间？兄今日不可不熟思也！”","公子闻言，茫然自失，移席问计：“据高明之见，何以教我？”孙富道：“仆有一计，于兄甚便。只恐兄溺枕席之爱，未必能行，使仆空费词说耳！”公子道：“兄诚有良策，使弟再睹家园之乐，乃弟之恩人也。又何惮而不言耶？”孙富道：“兄飘零岁余，严亲怀怒，闺阁离心。设身以处兄之地，诚寝食不安之时也。然尊大人所以怒兄者，不过为迷花恋柳，挥金如土，异日必为弃家荡产之人，不堪承继家业耳！兄今日空手而归，正触其怒。兄倘能割衽席之爱，见机而作，仆愿以千金相赠。兄得千金以报尊大人，只说在京授馆，并不曾浪费分毫，尊大人必然相信。从此家庭和睦，当无间言。须臾之间，转祸为福。兄请三思，仆非贪丽人之色，实为兄效忠于万一也！”李甲原是没主意的人，本心惧怕老子，被孙富一席话，说透胸中之疑，起身作揖道：“闻兄大教，顿开茅塞。但小妾千里相从，义难顿绝，容归与商之。得妾心肯，当奉复耳。”孙富道：“说话之间，宜放婉曲。彼既忠心为兄，必不忍使兄父子分离，定然玉成兄还乡之事矣。”二人饮了一回酒，风停雪止，天色已晚。孙富教家僮算还了酒钱，与公子携手下船。正是：","逢人且说三分话，未可全抛一片心。","却说杜十娘在舟中，摆设酒果，欲与公子小酌，竟日未回，挑灯以待。公子下船，十娘起迎。见公子颜色匆匆，似有不乐之意，乃满斟热酒劝之。公子摇首不饮，一言不发，竟自床上睡了。十娘心中不悦，乃收拾杯盘为公子解衣就枕，问道：“今日有何见闻，而怀抱郁郁如此？”公子叹息而已，终不启口。问了三四次，公子已睡去了。十娘委决不下，坐于床头而不能寐。到夜半，公子醒来，又叹一口气。十娘道：“郎君有何难言之事，频频叹息？”公子拥被而起，欲言不语者几次，扑簌簌掉下泪来。十娘抱持公子于怀间，软言抚慰道：“妾与郎君情好，已及二载，千辛万苦，历尽艰难，得有今日。然相从数千里，未曾哀戚。今将渡江，方图百年欢笑，如何反起悲伤？必有其故。夫妇之间，死生相共，有事尽可商量，万勿讳也。”","公子再四被逼不过，只得含泪而言道：“仆天涯穷困，蒙恩卿不弃，委曲相从，诚乃莫大之德也。但反复思之，老父位居方面，拘于礼法，况素性方严，恐添嗔怒，必加黜逐。你我流荡，将何底止？夫妇之欢难保，父子之伦又绝。日间蒙新安孙友邀饮，为我筹及此事，寸心如割！”十娘大惊道：“郎君意将如何？”公子道：“仆事内之人，当局而迷。孙友为我画一计颇善，但恐恩卿不从耳！”十娘道：“孙友者何人？计如果善，何不可从？”公子道：“孙友名富，新安盐商，少年风流之士也。夜间闻子清歌，因而问及。仆告以来历，并谈及难归之故，渠意欲以千金聘汝。我得千金，可借口以见吾父母，而恩卿亦得所耳。但情不能舍，是以悲泣。”说罢，泪如雨下。","十娘放开两手，冷笑一声道：“为郎君画此计者，此人乃大英雄也！郎君千金之资既得恢复，而妾归他姓，又不致为行李之累，发乎情，止乎礼，诚两便之策也。那千金在那里？”公子收泪道：“未得恩卿之诺，金尚留彼处，未曾过手。”十娘道：“明早快快应承了他，不可挫过机会。但千金重事，须得兑足交付郎君之手，妾始过舟，勿为贾竖子所欺。”时已四鼓，十娘即起身挑灯梳洗道：“今日之妆，乃迎新送旧，非比寻常。”于是脂粉香泽，用意修饰，花钿绣袄，极其华艳，香风拂拂，光采照人。装束方完，天色已晓。","孙富差家童到船头候信。十娘微窥公子，欣欣似有喜色，乃催公子快去回话，及早兑足银子。公子亲到孙富船中，回复依允。孙富道：“兑银易事，须得丽人妆台为信。”公子又回复了十娘，十娘即指描金文具道：“可便抬去。”孙富喜甚。即将白银一千两，送到公子船中。十娘亲自检看，足色足数，分毫无爽，乃手把船舷，以手招孙富。孙富一见，魂不附体。十娘启朱唇，开皓齿道：“方才箱子可暂发来，内有李郎路引一纸，可检还之也。”孙富视十娘已为瓮中之鳖，即命家童送那描金文具，安放船头之上。十娘取钥开锁，内皆抽替小箱。十娘叫公子抽第一层来看，只见翠羽明彆，瑶簪宝珥，充牣于中，约值数百金。十娘遽投之江中。李甲与孙富及两船之人，无不惊诧。又命公子再抽一箱，乃玉箫金管；又抽一箱，尽古玉紫金玩器，约值数千金。十娘尽投之于大江中。岸上之人，观者如堵。齐声道：“可惜，可惜！”正不知什么缘故。最后又抽一箱，箱中复有一匣。开匣视之，夜明之珠约有盈把。其他祖母绿、猫儿眼，诸般异宝，目所未睹，莫能定其价之多少。众人齐声喝采，喧声如雷。十娘又欲投之于江。李甲不觉大悔，抱持十娘恸哭，那孙富也来劝解。","十娘推开公子在一边，向孙富骂道：“我与李郎备尝艰苦，不是容易到此。汝以奸淫之意，巧为谗说，一旦破人姻缘，断人恩爱，乃我之仇人。我死而有知，必当诉之神明，尚妄想枕席之欢乎！”又对李甲道：“妾风尘数年，私有所积，本为终身之计。自遇郎君，山盟海誓，白首不渝。前出都之际，假托众姊妹相赠，箱中韫藏百宝，不下万金。将润色郎君之装，归见父母，或怜妾有心，收佐中馈，得终委托，生死无憾。谁知郎君相信不深，惑于浮议，中道见弃，负妾一片真心。今日当众目之前，开箱出视，使郎君知区区千金，未为难事。妾椟中有玉，恨郎眼内无珠。命之不辰，风尘困瘁，甫得脱离，又遭弃捐。今众人各有耳目，共作证明，妾不负郎君，郎君自负妾耳！”于是众人聚观者，无不流涕，都唾骂李公子负心薄倖。公子又羞又苦，且悔且泣，方欲向十娘谢罪。十娘抱持宝匣，向江心一跳。众人急呼捞救，但见云暗江心，波涛滚滚，杳无踪影。可惜一个如花似玉的名姬，一旦葬于江鱼之腹！","三魂渺渺归水府，七魄悠悠入冥途。","当时旁观之人，皆咬牙切齿，争欲拳殴李甲和那孙富。慌得李、孙二人手足无措，急叫开船，分途遁去。李甲在舟中，看了千金，转忆十娘，终日愧悔，郁成狂疾，终身不痊。孙富自那日受惊，得病卧床月余，终日见杜十娘在傍诟骂，奄奄而逝。人以为江中之报也。","却说柳遇春在京坐监完满，束装回乡，停舟瓜步。偶临江净脸，失坠铜盆于水，觅渔人打捞。及至捞起，乃是个小匣儿。遇春启匣观看，内皆明珠异宝，无价之珍。遇春厚赏渔人，留于床头把玩。是夜梦见江中一女子，凌波而来，视之，乃杜十娘也。近前万福，诉以李郎薄倖之事，又道：“向承君家慷概，以一百五十金相助。本意息肩之后，徐图报答，不意事无终始。然每怀盛情，悒悒未忘。早间曾以小匣托渔人奉致，聊表寸心，从此不复相见矣。”言讫，猛然惊醒，方知十娘已死，叹息累日。","后人评论此事，以为孙富谋夺美色，轻掷千金，固非良士；李甲不识杜十娘一片苦心，碌碌蠢才，无足道者。独谓十娘千古女侠，岂不能觅一佳侣，共跨秦楼之凤，乃错认李公子。明珠美玉，投于盲人，以致恩变为仇，万种恩情，化为流水，深可惜也！有诗叹云：","不会风流莫妄谈，单单情字费人参。","若将情字能参透，唤作风流也不惭。"],"cpLength":10077},"liao-15":{"chapterId":"liao-15","bookId":"liao","fileIndex":14,"number":15,"title":"卷一 劳山道士","paragraphs":["邑有王生，行七，故家子。少慕道，闻劳山多仙人，负笈往游。登一顶，有观宇甚幽。一道士坐蒲团上，素发垂领，而神光爽迈。叩而与语，理甚玄妙。请师之，道士曰：“恐娇情不能作苦。”答言：“能之。”其门人甚众，薄暮毕集，王俱与稽首，遂留观中。 凌晨，道士呼王去，授一斧，使随众采樵。王谨受教。过月余，手足重茧，不堪其苦，阴有归志。一夕归，见二人与师共酌，日已暮，尚无灯烛。师乃剪纸如镜粘壁间，俄顷月明辉室，光鉴毫芒。诸门人环听奔走。一客曰：“良宵胜乐，不可不同。”乃于案上取酒壶分赉诸徒，且嘱尽醉。王自思：七八人，壶酒何能遍给？遂各觅盎盂，竞饮先釂，惟恐樽尽，而往复挹注，竟不少减。心奇之。俄一客曰：“蒙赐月明之照，乃尔寂饮，何不呼嫦娥来？”乃以箸掷月中。见一美人自光中出，初不盈尺，至地遂与人等。纤腰秀项，翩翩作“霓裳舞”。已而歌曰：“仙仙乎！而还乎！而幽我于广寒乎！”其声清越，烈如箫管。歌毕，盘旋而起，跃登几上，惊顾之间，已复为箸。三人大笑。又一客曰：“今宵最乐，然不胜酒力矣。其饯我于月宫可乎？”三人移席，渐入月中。众视三人，坐月中饮，须眉毕见，如影之在镜中。移时月渐暗，门人燃烛来，则道士独坐，而客杳矣。几上肴核尚存；壁上月，纸圆如镜而已。道士问众：“饮足乎？”曰：“足矣。”“足，宜早寝，勿误樵苏。”众诺而退。王窃欣慕，归念遂息。 又一月，苦不可忍，而道士并不传教一本。心不能待，辞曰：“弟子数百里受业仙师，纵不能得长生术，或小有传习，亦可慰求教之心。今阅两三月，不过早樵而暮归。弟子在家，未谙此苦。”道士笑曰：“吾固谓不能作苦，今果然。明早当遣汝行。”王曰：“弟子操作多日，师略授小技，此来为不负也。”道士问：“何术之求？”王曰：“每见师行处，墙壁所不能隔，但得此法足矣。”道士笑而允之。乃传一诀，令自咒毕，呼曰：“入之！”王面墙不敢入。又曰：“试入之。”王果从容入，及墙而阻。道士曰：“俯首辄入，勿逡巡！”王果去墙数步奔而入，及墙，虚若无物，回视，果在墙外矣。大喜，入谢。道士曰：“归宜洁持，否则不验。”遂助资斧遣归。抵家，自诩遇仙，坚壁所不能阻，妻不信。王效其作为，去墙数尺，奔而入；头触硬壁，蓦然而踣。妻扶视之，额上坟起如巨卵焉。妻揶揄之。王渐忿，骂老道士之无良而已。异史氏曰：“闻此事，未有不大笑者，而不知世之为王生者正复不少。今有伧父，喜痰毒而畏药石，遂有舐吮痈痔者，进宣威逞暴之术，以迎其旨，绐之曰：‘执此术也以往，可以横行而无碍。’初试未尝不小效，遂谓天下之大，举可以如是行矣，势不至触硬壁而颠蹶不止也。”"],"cpLength":1061},"liao-48":{"chapterId":"liao-48","bookId":"liao","fileIndex":47,"number":48,"title":"卷二 婴宁","paragraphs":["王子服，莒之罗店人，早孤，绝慧，十四入泮。母最爱之，寻常不令游郊野。聘萧氏，未嫁而夭，故求凰未就也。","会上元，有舅氏子吴生邀同眺瞩，方至村外，舅家仆来招吴去。生见游女如云，乘兴独游。有女郎携婢，拈梅花一枝，容华绝代，笑容可掬。生注目不移，竟忘顾忌。女过去数武，顾婢子笑曰：“个儿郎目灼灼似贼！”遗花地上，笑语自去。生拾花怅然，神魂丧失，怏怏遂返。至家，藏花枕底，垂头而睡，不语亦不食。母忧之，醮禳益剧，肌革锐减。医师诊视，投剂发表，忽忽若迷。母抚问所由，默然不答。适吴生来，嘱秘诘之。吴至榻前，生见之泪下，吴就榻慰解，渐致研诘，生具吐其实，且求谋画。吴笑曰：“君意亦痴！此愿有何难遂？当代访之。徒步于野，必非世家，如其未字，事固谐矣，不然，拚以重赂，计必允遂。但得痊瘳，成事在我。”生闻之不觉解颐。吴出告母，物色女子居里。而探访既穷，并无踪迹。母大忧，无所为计。然自吴去后，颜顿开，食亦略进。数日吴复来，生问所谋。吴绐之曰：“已得之矣。我以为谁何人，乃我姑之女，即君姨妹，今尚待聘。虽内戚有婚姻之嫌，实告之无不谐者。”生喜溢眉宇，问：“居何里？”吴诡曰：“西南山中，去此可三十余里。”生又嘱再四，吴锐身自任而去。","生由是饮食渐加，日就平复。探视枕底，花虽枯，未便雕落，凝思把玩，如见其人。怪吴不至，折柬招之，吴支托不肯赴招。生恚怒，悒悒不欢。母虑其复病，急为议姻，略与商榷，辄摇首不愿，惟日盼吴。吴迄无耗，益怨恨之。转思三十里非遥，何必仰息他人？怀梅袖中，负气自往，而家人不知也。伶仃独步，无可问程，但望南山行去。约三十余里，乱山合沓，空翠爽肌、寂无人行，止有鸟道。遥望谷底丛花乱树中，隐隐有小里落。下山入村，见舍宇无多，皆茅屋，而意甚修雅。北向一家，门前皆丝柳，墙内桃杏尤繁，间以修竹，野鸟格磔其中。意其园亭，不敢遽入。回顾对户，有巨石滑洁，因坐少憩。俄闻墙内有女子长呼：“小荣！”其声娇细。方伫听间，一女郎由东而西，执杏花一朵，俯首自簪；举头见生，遂不复簪，含笑拈花而入。审视之，即上元途中所遇也。心骤喜，但念无以阶进。欲呼姨氏，顾从无还往，惧有讹误。门内无人可问，坐卧徘徊，自朝至于日昃，盈盈望断，并忘饥渴。时见女子露半面来窥，似讶其不去者。忽一老媪扶杖出，顾生曰：“何处郎君，闻自辰刻来，以至于今。意将何为？得勿饥也？”生急起揖之，答云：“将以探亲。”媪聋聩不闻。又大言之。乃问：“贵戚何姓？”生不能答。媪笑曰：“奇哉！姓名尚自不知，何亲可探？我视郎君亦书痴耳。不如从我来，啖以粗粝，家有短榻可卧。待明朝归，询知姓氏，再来探访。”生方腹馁思啖，又从此渐近丽人，大喜。从媪入，见门内白石砌路，夹道红花片片坠阶上，曲折而西，又启一关，豆棚花架满庭中。肃客入舍，粉壁光如明镜，窗外海棠枝朵，探入室中，裀藉几榻，罔不洁泽。甫坐，即有人自窗外隐约相窥。媪唤：“小荣！可速作黍。”外有婢子嗷声而应。坐次，具展宗阀。媪曰：“郎君外祖，莫姓吴否？”曰：“然。”媪惊曰：“是吾甥也！尊堂，我妹子。年来以家屡贫，又无三尺之男，遂至音问梗塞。甥长成如许，尚不相识。”生曰：“此来即为姨也，匆遽遂忘姓氏。”媪曰：“老身秦姓，并无诞育，弱息亦为庶产。渠母改醮，遗我鞠养。颇亦不钝，但少教训，嬉不知愁。少顷，使来拜识。”未几婢子具饭，雏尾盈握。媪劝餐已，婢来敛具。媪曰：“唤宁姑来。”婢应去。良久，闻户外隐有笑声。媪又唤曰：“婴宁，汝姨兄在此。”户外嗤嗤笑不已。婢推之以入，犹掩其口，笑不可遏。媪逋目曰：“有客在，咤咤叱叱，是何景象？”女忍笑而立，生揖之。媪曰：“此王郎，汝姨子。一家尚不相识，可笑人也。”生问：“妹子年几何矣？”媪未能解；生又言之。女复笑，不可仰视。媪谓生曰：“我言少教诲，此可见矣。年已十六，呆痴如婴儿。”生曰：“小于甥一岁。”曰：“阿甥已十七矣，得非庚午属马者耶？”生首应之。又问：“甥妇阿谁？”答曰：“无之。”曰：“如甥才貌，何十七岁犹未聘？婴宁亦无姑家，极相匹敌。惜有内亲之嫌。”生无语，目注婴宁，不遑他瞬。婢向女小语云：“目灼灼贼腔未改！”女又大笑，顾婢曰：“视碧桃开未？”遽起，以袖掩口，细碎连步而出。至门外，笑声始纵。媪亦起，唤婢襆被，为生安置。曰：“阿甥来不易，宜留三五日，迟迟送汝归。如嫌幽闷，舍后有小园，可供消遣；有书可读。”次日至舍后，果有园半亩，细草铺毡，杨花糁径。有草舍三楹，花木四合其所。穿花小步，闻树头苏苏有声，仰视，则婴宁在上，见生来，狂笑欲堕。生曰：“勿尔，堕矣！”女且下且笑，不能自止。方将及地，失手而堕，笑乃止。生扶之，阴捘其腕。女笑又作，倚树不能行，良久乃罢。生俟其笑歇，乃出袖中花示之。女接之，曰：“枯矣！何留之？”曰：“此上元妹子所遗，故存之。”问：“存之何益？”曰：“以示相爱不忘。自上元相遇，凝思成病，自分化为异物；不图得见颜色，幸垂怜悯。”女曰：“此大细事，至戚何所靳惜？待郎行时，园中花，当唤老奴来，折一巨捆负送之。”生曰：“妹子痴耶？”女曰：“何便是痴？”生曰：“我非爱花，爱拈花之人耳。”女曰：“葭莩之情，爱何待言。”生曰：“我所为爱，非瓜葛之爱，乃夫妻之爱。”女曰：“有以异乎？”曰：“夜共枕席耳。”女俯首思良久，曰：“我不惯与生人睡。”语未已，婢潜至，生惶恐遁去。少时会母所，母问：“何往？”女答以园中共话。媪曰：“饭熟已久，有何长言，周遮乃尔。”女曰：“大哥欲我共寝。”言未已，生大窘，急目瞪之。女微笑而止。幸媪不闻，犹絮絮究诘。生急以他词掩之，因小语责女。女曰：“适此语不应说耶？”生曰：“此背人语。”女曰：“背他人，岂得背老母？且寝处亦常事，何讳之？”生恨其痴，无术可悟之。","食方竟，家人捉双卫来寻生。先是，母待生久不归，始疑。村中搜觅已遍，竟无踪兆，因往寻吴。吴忆曩言，因教于西南山村寻觅。凡历数村，始至于此。生出门，适相值，便入告媪，且请偕女同归。媪喜曰：“我有志，匪伊朝夕。但残躯不能远涉，得甥携妹子去，识认阿姨，大好！”呼婴宁，宁笑至。媪曰：“大哥欲同汝去，可装束。”又饷家人酒食，始送之出，曰：“姨家田产丰裕，能养冗人。到彼且勿归，小学诗礼，亦好事翁姑。即烦阿姨择一良匹与汝。”二人遂发。至山坳回顾，犹依稀见媪倚门北望也。","抵家，母睹姝丽，惊问为谁。生以姨妹对。母曰：“前吴郎与儿言者，诈也。我未有姊，何以得甥？”问女，女曰：“我非母出。父为秦氏，没时儿在褓中，不能记忆。”母曰：“我一姊适秦氏良确。然殂谢已久，那得复存？”因审诘面庞、志赘，一一符合。又疑曰：“是矣！然亡已多年，何得复存？”疑虑间，吴生至，女避入室。吴询得故，惘然久之，忽曰：“此女名婴宁耶？”生然之。吴极称怪事。问所自知，吴曰：“秦家姑去世后，姑丈鳏居，祟于狐，病瘠死。狐生女名婴宁，绷卧床上，家人皆见之。姑丈没，狐犹时来。后求天师符粘壁上，狐遂携女去。将勿此耶？”彼此疑参，但闻室中嗤嗤，皆婴宁笑声。母曰：“此女亦太憨。”吴生请面之。母入室，女犹浓笑不顾。母促令出，始极力忍笑，又面壁移时方出。才一展拜。翻然遽入，放声大笑。满室妇女，为之粲然。","吴请往觇其异，就便执柯。寻至村所，庐舍全无，山花零落而已。吴忆葬处仿佛不远，然坟垅湮没，莫可辨识，诧叹而返。母疑其为鬼，入告吴言，女略无骇意。又吊其无家，亦殊无悲意，孜孜憨笑而已。众莫之测，母令与少女同寝止，昧爽即来省问，操女红糖巧绝伦。但善笑，禁之亦不可止。然笑处嫣然，狂而不损其媚，人皆乐之。邻女少妇，争承迎之。母择吉为之合卺，而终恐为鬼物，窃于日中窥之，形影殊无少异。","至日，使华装行新妇礼，女笑极不能俯仰，遂罢。生以憨痴，恐泄漏房中隐事，而女殊密秘，不肯道一语。每值母忧怒，女至一笑即解。奴婢小过，恐遭鞭楚，辄求诣母共话，罪婢投见恒得免。而爱花成癖，物色遍戚党；窃典金钗，购佳种，数月，阶砌藩溷无非花者。庭后有木香一架，故邻西家，女每攀登其上，摘供簪玩。母时遇见辄诃之，女卒不改。一日西人子见之，凝注倾倒。女不避而笑。西人子谓女意属己，心益荡。女指墙底笑而下，西人子谓示约处，大悦。及昏而往，女果在焉，就而淫之，则阴如锥刺，痛彻于心，大号而踣。细视非女，则一枯木卧墙边，所接乃水淋窍也。邻父闻声，急奔研问，呻而不言；妻来，始以实告。爇火烛窥，见中有巨蝎如小蟹然，翁碎木，捉杀之。负子至家，半夜寻卒。邻人讼生，讦发婴宁妖异。邑宰素仰生才，稔知其笃行士，谓邻翁讼诬，将杖责之，生为乞免，遂释而出。母谓女曰：“憨狂尔尔，早知过喜而伏忧也。邑令神明，幸不牵累。设鹘突官宰，必逮妇女质公堂，我儿何颜见戚里？”女正色，矢不复笑。母曰：“人罔不笑，但须有时。”而女由是竟不复笑，虽故逗之亦终不笑，然竟日未尝有戚容。","一夕，对生零涕。异之。女哽咽曰：“曩以相从日浅，言之恐致骇怪。今日察姑及郎，皆过爱无有异心，直告或无妨乎？妾本狐产。母临去，以妾托鬼母，相依十余年，始有今日。妾又无兄弟，所恃者惟君。老母岑寂山阿，无人怜而合厝之，九泉辄为悼恨。君倘不惜烦费，使地下人消此怨恫，庶养女者不忍溺弃。”生诺之，然虑坟冢迷于荒草。女言无虑。刻日夫妇舆榇而往。女于荒烟错楚中，指示墓处，果得媪尸，肤革犹存。女抚哭哀痛。舁归，寻秦氏墓合葬焉。是夜生梦媪来称谢，寤而述之。女曰：“妾夜见之，嘱勿惊郎君耳。”生恨不邀留。女曰：“彼鬼也。生人多，阳气胜，何能久居？”生问小荣，曰：“是亦狐，最黠。狐母留以视妾，每摄饵相哺，故德之常不去心；昨问母，云已嫁之。”由是岁值寒食，夫妇登秦墓，拜扫无缺。女逾年生一子，在怀抱中，不畏生人，见人辄笑，亦大有母风云。","异史氏曰：“观其孜孜憨笑，似全无心肝者。而墙下恶作剧，其黠孰甚焉！至凄恋鬼母，反笑为哭，我婴宁何常憨耶。窃闻山中有草，名‘笑矣乎’，嗅之则笑不可止。房中植此一种，则合欢、忘忧，并无颜色矣。若解语花，正嫌其作态耳。”"],"cpLength":4017},"liao-49":{"chapterId":"liao-49","bookId":"liao","fileIndex":48,"number":49,"title":"卷二 聂小倩","paragraphs":["宁采臣，浙人，性慷爽，廉隅自重。每对人言：“生平无二色。”适赴金华，至北郭，解装兰若。寺中殿塔壮丽，然蓬蒿没人，似绝行踪。东西僧舍，双扉虚掩，惟南一小舍，扃键如新。又顾殿东隅，修竹拱把，阶下有巨池，野藕已花。意甚乐其幽杳。会学使案临，城舍价昂，思便留止，遂散步以待僧归。日暮有士人来启南扉，宁趋为礼，且告以意。士人曰：“此间无房主，仆亦侨居。能甘荒落，旦暮惠教，幸甚！”宁喜，藉藁代床，支板作几，为久客计。是夜月明高洁，清光似水，二人促膝殿廊，各展姓字。士人自言燕姓，字赤霞。宁疑为赴试者，而听其音声，殊不类浙。诘之，自言秦人，语甚朴诚。既而相对词竭，遂拱别归寝。 宁以新居，久不成寐。闻舍北喁喁，如有家口。起，伏北壁石窗下微窥之，见短墙外一小院落，有妇可四十余；又一媪衣绯，插蓬沓，鲐背龙钟，偶语月下。妇曰：“小倩何久不来？”媪曰：“殆好至矣。”妇曰：“将无向姥姥有怨言否？”曰：“不闻；但意似蹙蹙。”妇曰：“婢子不宜好相识。”言未已，有十七八女子来，仿佛艳绝。媪笑曰：“背地不言人，我两个正谈道，小妖婢悄来无迹响，幸不訾着短处。”又曰：“小娘子端好是画中人，遮莫老身是男子，也被摄去。”女曰：“姥姥不相誉，更阿谁道好？”妇人女子又不知何言。宁意其邻人眷口，寝不复听；又许时始寂无声。 方将睡去，觉有人至寝所，急起审顾，则北院女子也。惊问之，女笑曰：“月夜不寐，愿修燕好。”宁正容曰：“卿防物议，我畏人言。略一失足，廉耻道丧。”女云：“夜无知者。”宁又咄之。女逡巡若复有词。宁叱：“速去！不然，当呼南舍生知。”女惧，乃退。至户外忽返，以黄金一锭置褥上。宁掇掷庭墀，曰：“非义之物，污我囊囊！”女惭出，拾金自言曰：“此汉当是铁石。”","诘旦有兰溪生携一仆来候试，寓于东厢，至夜暴亡。足心有小孔，如锥刺者，细细有血出，俱莫知故。经宿一仆死，症亦如之。向晚燕生归，宁质之，燕以为魅。宁素抗直，颇不在意。宵分女子复至，谓宁曰：“妾阅人多矣，未有刚肠如君者。君诚圣贤，妾不敢欺。小倩，姓聂氏，十八夭殂，葬于寺侧，被妖物威胁，历役贱务，腆颜向人，实非所乐。今寺中无可杀者，恐当以夜叉来。”宁骇求计。女曰：“与燕生同室可免。”问：“何不惑燕生？”曰：“彼奇人也，固不敢近。”又问：“迷人若何？”曰：“狎昵我者，隐以锥刺其足，彼即茫若迷，因摄血以供妖饮。又惑以金，非金也，乃罗刹鬼骨，留之能截取人心肝。二者，凡以投时好耳。”宁感谢，问戒备之期，答以明宵。临别泣曰：“妾堕玄海，求岸不得。郎君义气干云，必能拔生救苦。倘肯囊妾朽骨，归葬安宅，不啻再造。”宁毅然诺之。因问葬处，曰：“但记白杨之上，有乌巢者是也。”言已出门，纷然而灭。","明日恐燕他出，早诣邀致。辰后具酒馔，留意察燕。既约同宿，辞以性癖耽寂。宁不听，强携卧具来，燕不得已，移榻从之，嘱曰：“仆知足下丈夫，倾风良切。要有微衷，难以遽白。幸勿翻窥箧襆，违之两俱不利。”宁谨受教。既各寝，燕以箱箧置窗上，就枕移时，齁如雷吼。宁不能寐。近一更许，窗外隐隐有人影。俄而近窗来窥，目光睒闪。宁惧，方欲呼燕，忽有物裂箧而出，耀若匹练，触折窗上石棂，飙然一射，即遽敛入，宛如电灭。燕觉而起，宁伪睡以觇之。燕捧箧检征，取一物，对月嗅视，白光晶莹，长可二寸，径韭叶许。已而数重包固，仍置破箧中。自语曰：“何物老魅，直尔大胆，致坏箧子。”遂复卧。宁大奇之，因起问之，且告以所见。燕曰：“既相知爱，何敢深隐。我剑客也。若非石棂，妖当立毙；虽然，亦伤。”问：“所缄何物？”曰：“剑也。适嗅之有妖气。”宁欲观之。慨出相示，荧荧然一小剑也。于是益厚重燕。 明日，视窗外有血迹。遂出寺北，见荒坟累累，果有白杨，乌巢其颠。迨营谋既就，趣装欲归。燕生设祖帐，情义殷渥，以破革囊赠宁，曰：“此剑袋也。宝藏可远魑魅。”宁欲从受其术。曰：“如君信义刚直，可以为此，然君犹富贵中人，非此道中人也。”宁托有妹葬此，发掘女骨，敛以衣衾，赁舟而归。宁斋临野，因营坟葬诸斋外，祭而祝曰：“怜卿孤魂，葬近蜗居，歌哭相闻，庶不见凌于雄鬼。一瓯浆水饮，殊不清旨，幸不为嫌！”祝毕而返，后有人呼曰：“缓待同行！”回顾，则小倩也。欢喜谢曰：“君信义，十死不足以报。请从归，拜识姑嫜，媵御无悔。”审谛之，肌映流霞，足翘细笋，白昼端相，娇丽尤绝。遂与俱至斋中。嘱坐少待，先入白母。母愕然。时宁妻久病，母戒勿言，恐所骇惊。言次，女已翩然入，拜伏地下。宁曰：“此小倩也。”母惊顾不遑。女谓母曰：“儿飘然一身，远父母兄弟。蒙公子露覆，泽被发肤，愿执箕帚，以报高义。”母见其绰约可爱，始敢与言，曰：“小娘子惠顾吾儿，老身喜不可已。但生平止此儿，用承祧绪，不敢令有鬼偶。”女曰：“儿实无二心。泉下人既不见信于老母，请以兄事，依高堂，奉晨昏，如何？”母怜其诚，允之。即欲拜嫂，母辞以疾，乃止。女即入厨下，代母尸饔。入房穿榻，似熟居者。","日暮母畏惧之，辞使归寝，不为设床褥。女窥知母意，即竟去。过斋欲入，却退，徘徊户外，似有所惧。生呼之。女曰：“室有剑气畏人。向道途中不奉见者，良以此故。”宁悟为革囊，取悬他室。女乃入，就烛下坐；移时，殊不一语。久之，问：“夜读否？妾少诵《楞严经》，今强半遗忘。浼求一卷，夜暇就兄正之。”宁诺。又坐，默然，二更向尽，不言去。宁促之。愀然曰：“异域孤魂，殊怯荒墓。”宁曰：“斋中别无床寝，且兄妹亦宜远嫌。”女起，颦蹙欲啼，足儴而懒步，从容出门，涉阶而没。宁窃怜之，欲留宿别榻，又惧母嗔。女朝旦朝母，捧匜沃盥，下堂操作，无不曲承母志。黄昏告退，辄过斋头，就烛诵经。觉宁将寝，始惨然出。 先是，宁妻病废，母劬不堪；自得女，逸甚，心德之。日渐稔，亲爱如己出，竟忘其为鬼，不忍晚令去，留与同卧起。女初来未尝饮食，半年渐啜稀酡。母子皆溺爱之，讳言其鬼，人亦不知辨也。无何，宁妻亡，母隐有纳女意，然恐于子不利。女微知之，乘间告曰：“居年余，当知肝膈。为不欲祸行人，故从郎君来。区区无他意，止以公子光明磊落，为天人所钦瞩，实欲依赞三数年，借博封诰，以光泉壤。”母亦知无恶意，但惧不能延宗嗣。女曰：“子女惟天所授。郎君注福籍，有亢宗子三，不以鬼妻而遂夺也。”母信之，与子议。宁喜，因列筵告戚党。或请觌新妇，女慨然华妆出，一堂尽眙，反不疑其鬼，疑为仙。由是五党诸内眷，咸执贽以贺，争拜识之。女善画兰、梅，辄以尺幅酬答，得者藏之什袭以为荣。一日俯颈窗前，怊怅若失。忽问：“革囊何在？”曰：“以卿畏之，故缄致他所。”曰：“妾受生气已久，当不复畏，宜取挂床头。”宁诘其意，曰：“三日来，心怔忡无停息，意金华妖物，恨妾远遁，恐旦晚寻及也。”宁果携革囊来。女反复审视，曰：“此剑仙将盛人头者也。敝败至此，不知杀人几何许！妾今日视之，肌犹粟栗。”乃悬之。次日又命移悬户上。夜对烛坐，欻有一物，如飞鸟至。女惊匿夹幕间。宁视之，物如夜叉状，电目血舌，睒闪攫拿而前，至门却步，逡巡久之，渐近革囊，以爪摘取，似将抓裂。囊忽格然一响，大可合篑，恍惚有鬼物突出半身，揪夜叉入，声遂寂然，囊亦顿索如故。宁骇诧，女亦出，大喜曰：“无恙矣！”共视囊中，清水数斗而已。","后数年，宁果登进士。举一男。纳妾后，又各生一男，皆仕进有声。"],"cpLength":2939},"rl-01":{"chapterId":"rl-01","bookId":"rlws","fileIndex":1,"number":1,"title":"第一回　说楔子敷陈大义　借名流隐括全文","paragraphs":["“人生南北多歧路，将相神仙，也要凡人做。百代兴亡朝复暮，江风吹倒前朝树。功名富贵无凭据，费尽心情，总把流光误。浊酒三杯沈醉去，水流花谢知何处？”这一首词，也是个老生长谈。不过说：人生富贵功名，是身外之物；但世人一见了功名，便舍著性命去求他。及至到手之后，味同嚼蜡。自古及今，那一个是看得破的？","虽然如此说，元朝末年，也曾出了一个嵌□磊落的人。人姓王名冕，在诸暨县乡村居住；七岁时死了父亲，他母亲做些针黹，供给他到村学堂里去读书。看看三个年头，王冕已是十岁了。母亲唤他到面前来，说道：“儿啊！不是我有心要耽误你，只因你父亲亡后，我一个寡妇人家，只有出去的，没有进来的；年岁不好，柴米又贵，这几件旧衣服和些旧家伙，当的当了，卖的卖了；只靠著我替人家做些针黹生活赚来的钱，如何供得你读书？如今没奈何，把你雇在隔壁人家放牛，每月可以得他几钱银子，你又有现成饭吃，只在明日就要去了。”王冕道：“娘说的是。我在学堂里坐著，心里也闷；不如往他家放牛，倒快活些。假如我要读书，依旧可以带几本去读。”当夜商议定了。","第二日，母亲同他到隔壁秦老家，秦老留著他母子两个吃了早饭，牵出一条水牛来交给王冕。指著门外道：“就在我这大门过去两箭之地，便是七柳湖，湖边一带绿草，各家的牛都在那里打睡。又有几十棵合抱的垂杨树，十分阴凉；牛要渴了，就在湖边上饮水。小哥，你只在这一带玩耍。我老汉每日两餐小菜饭是不少的；每日早上，还折两个与你买点心吃。只是百事勤谨些，休嫌怠慢。”他母亲谢了扰要回家去，王冕送出门来，母亲替他理理衣。说道：“你在此须要小心，休惹人说不是；早出晚归，免我悬望。”王冕应诺，母亲含著两眼眼泪去了。","王冕自此在秦家放牛，每到黄昏，回家跟著母亲歇宿。或遇秦家煮些腌鱼腊肉给他吃，他便拿块荷叶包了回家，递与母亲。每日点心钱，他也不买了吃；聚到一两个月，便偷个空，走到村学堂里，见那闯学堂的书客，就买几本旧书。逐日把牛栓了，坐在柳荫树下看。","弹指又过了三四年。王冕看书，心下也著实明白了。那日，正是黄梅时候，天气烦躁。王冕放牛倦了，在绿草地上坐著。须臾，浓云密布，一阵大雨过了。那黑云边上，镶著白云，渐渐散去，透出一派日光来，照耀得满湖通红。湖边山上，青一块，紫一块。树枝上都像水洗过一番的，尤其绿得可爱。湖里有十来枝荷花，苞子上清水滴滴，荷叶上水珠滚来滚去。王冕看了一回，心里想道：“古人说：‘人在图画中’其实不错！可惜我这里没有一个画工，把这荷花画他几枝，也觉有趣！”又心里想道：“天下那有个学不会的事？我何不自画他几枝？……”正存想间，只见远远的一个夯汉，挑了一担食盒来；手里提著一瓶酒，食盒上挂著一条毡条，来到柳树下。将毡条铺了，食盒打开。那边走过三个人来，头带方巾，一个穿宝蓝夹纱直裰，两人穿元色直裰，都是四五十岁光景，手摇白纸扇，缓步而来。那穿宝蓝直裰的是个胖子，来到树下，尊那穿元色的一个胡子坐在上面，那一个瘦子坐在对席。他想是主人了，坐在下面把酒来斟。","吃了一回，那胖子开口道：“危老先生回来了。新买了住宅，比京里钟楼街的房子还大些，值得二千两银子。","因老先生要买，房主人让了几十两银卖了，图个名望体面。前月初十搬家，大尊县父母都亲自到门来贺，留著吃酒到二三更天。街上的人，那一个不敬！”那瘦子道：“县尊是壬午举人，乃危老先生门生，这是该来贺的。”那胖子道：“敝亲家也是危老先生门生，而今在河南做知县；前日小婿来家，带二斤乾鹿肉来赠予，这一盘就是了。这一回小婿再去，托敝亲家写一封字来，去晋谒危老先生。他若肯下乡回拜，也免得这些乡户人家，放了驴和猪在你我田里吃粮食。”那瘦子道：“危老先生要算一个学者了。”那胡子说道：“听见前日出京时，皇上亲自送出城外，携著手走了十几步，危老先生再三打躬辞了，方才上轿回去。看这光景，莫不是就要做官？”三人你一句，我一句，说个不了。","王冕见天色晚了，牵了牛回去。自此，聚的钱，不买书了；托人向城里买些胭脂铅粉之类，学画荷花。初时画得不好，画到三个月之后，那荷花精神、颜色无一不像：只多著一张纸，就像是湖里长的；又像才从湖里摘下来贴在纸上的。乡间人见画得好，也有拿钱来买的。王冕得了钱，买些好东西孝敬母亲。一传两，两传三，诸暨一县都晓得是一个画没骨花卉的名笔，争著来买。到了十七八岁，不在秦家了。每日画几笔画，读古人的诗文，渐渐不愁衣食，母亲心里欢喜。这王冕天性聪明，年纪不满二十岁，就把那天文地理，经史上的大学问，无一不贯通。但他性情不同：既不求官爵，又不交朋友，终日闭户读书。又在楚辞图上看见画的屈原衣冠，他便自造一顶极高的帽子，一件极阔的衣服，遇著花明柳媚的时节，乘一辆牛车载了母亲，戴了高帽，穿了阔衣，执著鞭子，口里唱著歌曲，在乡村镇上，以及湖边，到处玩耍。惹的乡下孩子们三五成群跟著他笑，他也不放在意下。只有隔壁秦老，虽然务农，却是个有意思的人；因自小看见他长大的如此不俗，所以敬他、爱他，时常和他亲热地邀在草堂里坐著说话儿。一日，正和秦老坐著，只见外边走进一个人，头带瓦楞帽，身穿青布衣服。秦老迎接，叙礼坐下。这人姓翟，是诸暨县一个头役，又是买办。因秦老的儿子秦大汉拜在他名下，叫他乾爷，所以时常下乡来看亲家。秦老慌忙叫儿子烹茶、杀鸡、煮肉款留他，并要王冕相陪。彼此道过姓名，那翟买办道：“这位王相公，可就是会画没骨花的么？”秦老道：“便是了。亲家，你怎得知道？”翟买办道：“县里人那个不晓得？因前日本县吩咐要书二十四副花卉册页送上司，此事交在我身上。我闻有王相公的大名，故此一迳来寻亲家。今日有缘，遇著王相公，是必费心画一画。在下半个月后下乡来取。老爷少不得还有几两润笔的银子，一并送来。”秦老在旁，再三怂恿。王冕屈不过秦老的情，只得应诺了。回家用心用意，画了二十四副花卉题了诗在上面。翟头役禀过了本官，那知县时仁，发出二十四两银子来。翟买办扣克了十二两，只拿十二两银子送与王冕，将册页取去。时知县又办了几样礼物，送与危素，作候问之礼。危素受了礼物，只把这本册页看了又看，爱玩不忍释手；次日，备了一席酒，请时知县来家致谢。当下寒暄已毕，酒过数巡，危素道：“前日承老父台所惠册页花卉，还是古人的呢，还是现在人画的？”时知县不敢隐瞒，便道：“这就是门生治下一个乡下农民，叫做王冕，年纪也不甚大。想是才学画几笔，难入老师的法眼。”危素叹道：“我学生出门久了，故乡有如此贤士，竟然不知，可为惭愧！此兄不但才高，胸中见识，大是不同，将来名位不在你我之下，不知老父台可以约他来此相会一会么？”时知县道：“这个何难！门生回去，即遣人相约；他听见老师相爱，自然喜出望外了。”说罢，辞了危素，回到衙门，差翟买办持个侍生帖子去约王冕。翟买办飞奔下乡，到秦老家，邀王冕过来，一五一十向他说了。王冕笑道：“却是起动头翁，上覆县主老爷，说王冕乃一介农夫，不敢求见；这尊帖也不敢领。”翟买办变了脸道：“老爷将帖请人，谁敢不去！况这件事原是我照顾你的；不然，老爷如何得知你会画花？照理，见过老爷还该重重的谢我一谢才是！如何走到这里，茶也不见你一杯，却是推三阻四，不肯去见，是何道理！叫我如何去回覆老爷？难道老爷一县之主，叫不动一个百姓么？”王冕道：“头翁，你有所不知。假如我为了事，老爷拿票子传我，我怎敢不去？如今将帖来请，原是不逼迫我的意思了，我不愿去，老爷也可以相谅。”翟买办道：“你这说的都是甚么话！票子传著，倒要去；帖子请著，倒不去！这下是不识怡举了！”秦老劝道：“王相公，也罢；老爷拿帖子请你，自然是好意，你同亲家去走一回罢。自古道：‘灭门的知县。’你和他拗些什么？”王冕道：“秦老爷，头翁不知，你是听见我说过的。不见那段干木、泄柳的故事么？我是不愿去的。”翟买办道：“你这是难题目与我做，叫我拿甚么话去回老爷？”秦老道：“这个果然也是两难。若要去时，王相公又不肯；若要不去，亲家又难回话。我如今倒有一法：亲家回县里，不要说王相公不肯；只说他抱病在家，不能就来。一两日间好了就到。”翟买办道：“害病，就要取四邻的甘结！”彼此争论一番，秦老整治晚饭与他吃了；又暗叫了王冕出去向母亲要了三钱二分银子，送与翟买办做差事，方才应诺去了，回覆知县。","知县心里想道：“这小斯那里害什么病！想是翟家这奴才，走下乡，狐假虎威，著实恐吓了他一场；他从来不曾见过官府的人，害怕不敢来了。老师既把这个人托我，我若不把他就叫了来见老师，也惹得老师笑我做事疲软；我不如竟自己下乡去拜他。他看见赏他脸面，断不是难为他的意思，自然大著胆见我。我就顺便带了他来见老师，却不是办事勤敏？”又想道：“堂堂一个县令，屈尊去拜一个乡民，惹得衙役们笑话。···”又想到：“老师前日口气，甚是敬他；老师敬他十分，我就该敬他一百分。况且屈尊敬贤，将来志书上少不得称赞一篇；这是万古千年不朽的勾当，有甚么做不得？”","当下定了主意，次早传齐轿夫，不用全副执事，只带八个红黑帽夜役军牢。翟买办扶著轿子，一直下乡来。乡里人听见锣声，一个个扶老携幼，挨挤了看。轿子来到王冕门首，只见七八间草屋，一扇白板门紧紧关著。翟买办抢上几步，忙去敲门。敲了一会，里面一个婆婆，拄著拐杖，出来说道：“不在家了。从清早里牵牛出去饮水，尚未回来。”翟买办道：“老爷亲自在这里传你家儿子说话，怎的慢条斯理，快快说在那里，我好去传！”那婆婆道：“其实不在家了，不知在那里。”说毕，关著门进去了。说话之间，知县轿子已到；翟买办跪在轿前禀道：“小的传王冕，不在家里；请老爷龙驾到公馆里略坐一坐，小的再去传。”扶著轿子，过王冕屋后来。","屋后横七竖八条田埂，远远的一面大塘，塘边都栽满了榆树、桑树。塘边那一望无际的几顷田地，又有一座山，虽不甚大，却青葱树木，堆满山上。约有一里多路，彼此叫呼，还听得见。知县正走著，远远的有个牧童，倒骑水牯牛，从山嘴边转了过来。翟买办赶将上去，问道：“秦小二汉，你看见你隔壁的王老大牵了牛在那里饮水哩？”小二道：“王大叔么？他在二十里路外王家集亲家那里吃酒去了。这牛就是他的，央及我替他赶了来家。”翟买办如此这般禀了知县。知县变著脸道：“既然如此，不必进公馆了！即回衙门去罢：”时知县此时心中十分恼怒，本要立即差人拿了王冕来责惩一番，又恐怕危老师说他暴躁，且忍口气回去，慢慢向老师说明此人不中抬举，再处治他也不迟。知县去了。 王冕并不曾远行，即时走了来家；秦老过来抱怨他道：“你方才也太执意了。他是一县之主，你怎的怠慢他？”王冕道：“老爹请坐，我告诉你。时知县倚著危素的势，要在这里酷虐小民，无所不为；这样的人，我为甚么要结交他？但他这一番回去必定向危素说；危素老羞变怒，恐要和我计较起来。我如今辞别老爹，收拾行李，到别处去躲避几时。──只是母亲在家，放心不下。”母亲道：“我儿！你历年卖诗卖画，我也积聚下三五十两银子，柴米不愁没有；我虽年老，又无疾病，你自放心出去，躲避些时不妨。你又不曾犯罪，难道官府来拿你的母亲去不成？”秦老道：“这也说得有理。况你埋没在这乡村镇上，虽有才学，谁人是识得你的？此番到大邦去处，或者走出些机遇来也不可知，你尊堂家下大小事故，一切部在我老汉身上，替你扶持便了。”王冕拜谢了秦老。","秦老又走回家去取了些酒肴来，替王冕送行。吃了半夜酒回去。次日五更，王冕天明起来收拾行李，吃了早饭，恰好秦老也到。王冕拜辞了母亲，又拜了秦老两拜，母子洒泪分手。王冕穿上麻鞋，背上行李。秦老手提一个小白灯笼，直送出村口，洒泪而别。秦老手拿灯笼，站著看著他走，走得望不著了，方才回去。","王冕一路风餐露宿，九十里大站，七十里小站，一迳来到山东济南府地方。这山东虽是近北省分，这会城却也人物富庶，房舍稠密。王冕到了此处，盘费用尽了，只得租个小奄门面屋，卖卜测字，也画两张没骨的花卉贴在那里，卖与过往的人。每日问卜卖画，倒也挤个不开。","弹指间，过了半年光景。济南府里有几个俗财主，也爱王冕的画，时常要买；又自己不来，遣几个粗夯小斯，动不动大呼小叫，闹的王冕不得安稳。王冕不耐烦，就画了一条大牛贴在那里；又题几句诗在上，含著讥刺。也怕从此有口舌，正思量搬移一个地方。 那日清早，才坐在那里，只见许多男女，啼啼哭哭，在街上过，──也有挑著锅的，也有箩担内挑著孩子的，──一个个面黄饥瘦，衣裳褴褛。过去一阵，又是一阵，把街上都塞满了。也有坐在地上求化钱的。问其所以，都是黄河沿上的州县，被河水淹了。田庐房舍，尽行漂没。这是些逃荒的百姓，官府又不管，只得四散觅食。王冕见此光景，过意不去，叹了一口气道：“河水北流，天下自此将大乱了。我还在这里做甚么！”将些散碎银子收拾好了，栓束行李，仍旧回家。入了浙江境，才打听得危素已还朝了。时知县也升任去了。因此放心回家，拜见母亲。看见母亲健康如常，心中欢喜。母亲又向他说秦老许多好处。他慌忙打开行李，取出一匹茧绸，一包柿饼，拿过去谢了秦老。秦老又备酒与他洗尘。","自此，王冕依旧吟诗作画，奉养母亲。又过了六年，母亲老病卧床，王冕百方延医调治，总不见效。一日，母亲吩咐王冕道：“我眼见不济事了。但这几年来，人都在我耳根前说你的学问有了，该劝你出去作官。作官怕不是荣宗耀祖的事？我看见那些作官的，都不得有甚好收场。况你的性情高傲，倘若弄出祸来，反为不美。我儿可听我的遗言，将来娶妻生子，守著我的坟墓，不要出去作官。我死了，口眼也闭！”王冕哭著应诺。他母亲奄奄一息，归天去了。王冕擗踊哀号，哭得那邻舍之人，无不落泪。又亏秦老一力帮衬，制备衣衾棺椁。王冕负土成坟，三年苫块，不必细说。 到了服阕之后，不过一年有余，天下就大乱了。方国珍据了浙江，张士诚据了苏州，陈友谅据了湖广，都是些草窃的英雄。只有太祖皇帝起兵滁阳，得了金陵，立为吴王，乃是王者之师；提兵破了方国珍，号令全浙，乡村都市，并无骚扰。","一日，日中时分，王冕正从母亲坟上拜扫回来，只见十几骑马竟投他村里来。为头一人，头戴武巾，身穿团花战袍，白净面皮，三绺髭须，真有龙凤之表。那人到门首下了马，向王冕施礼道：“动问一声，那里是王冕先生家？”王冕道：“小人王冕，这里便是寒舍。”那人喜道：“如此甚妙，特来晋谒。”吩咐从人下马，屯在外边，把马都系在湖边柳树上；那人独和王冕携手进到屋里，分宾主施礼坐下。 王冕道：“不敢！拜问尊官尊姓大名，因甚降临这乡僻所在？”那人道：“我姓朱，先在江南起兵，号滁阳王，而今据有金陵，称为吴王的便是；因平方国珍到此，特来拜访先生。”王冕道：“乡民肉眼不识，原来就是王爷。但乡民一介愚人，怎敢劳王爷贵步？”吴王道：“孤是一个粗卤汉子，今得见先生儒者气象，不觉功利之见顿消。孤在江南，即慕大名，今来拜访，要先生指示：浙人久反之后，何以能服其心？”王冕道：“大王是高明远见的，不消乡民多说。若以仁义服人，何人不服，岂但浙江？若以兵力服人，浙人虽弱，恐亦义不受辱。不见方国珍么？”吴王叹息，点头称善！两人促膝谈到日暮。那些从者都带有乾粮，王冕自到厨下，烙了一斤面饼，炒了一盘韭菜，自捧出来陪著。吴王吃了，称谢教诲，上马去了。这日，秦老进城回来，问及此事，王冕也不曾说就是吴王，只说是军中一个将官，向年在山东相识的，故此来看我一看。说著就罢了。 不数年间，吴王削平祸乱，定鼎应天，天下统一，建国号大明，年号洪武。乡村人个个安居乐业。到了洪武四年，秦致又进城里，回来向王冕道：“危老爷已自问了罪，发在和州去了；我带了一本邸钞来给你看。”王冕接过来看，才晓得危素归降之后，妄自尊大；在太祖面前自称老臣。太祖大怒，发往和州守余阙墓去了。此一条之后，便是礼部议定取士之法：三年一科，用五经、四书、八股文。王冕指与秦老看道：“这个法却定的不好。将来读书人既有此一条荣身之路，把那文行出处都看得轻了。”说著，天色晚了下来。","此时正是初夏，天时乍热。秦老在打麦场上放下一张桌子，两人小饮。须臾，东方月上，照耀得如同万顷玻璃一般。那些眠鸥宿鹭，阒然无声。王冕左手持杯，右手指著天上的星，向秦老道：“你看贯索犯文昌，一代文人有厄！”话犹未了，忽然起一阵怪风，刮得树木都飕飕的响；水面上的禽鸟，格格惊起了许多。王冕同秦老吓的将衣袖蒙了脸。少顷，风声略定，睁眼看时，只见天上纷纷有百十个小星，都坠向东南角上去了。王冕道：“天可怜见，降下这一伙星君去维持文运，我们是不及见了！”当夜收拾家伙，各自歇息。","自此以后，时常有人传说：朝廷行文到浙江布政司，要征聘王冕出来作官。初时不在意里，后来渐渐说的多了，王冕并不通知秦老，私自收拾，连夜逃往会稽山中。","半年之后，朝廷果然遣一员官，捧著诏书，带领许多人，将著彩缎表里，来到秦老门首；见秦老八十多岁，须鬓皓然，手扶拄杖。那官与他施礼，秦老让到草堂坐下；那官问道：“王冕先生就在这庄上么？而今皇恩授他咨议参军之职，下官特地捧诏而来。”秦老道：“他虽是这里人，只是久已不知去向了。”秦老献过了茶，领那官员走到王冕家，推开了门，见□蛸满室，蓬莴蔽径，知是果然去得久了。那官咨嗟叹息了一回，仍旧捧诏回旨去了。","王冕隐居在会稽山中，并不自言姓名；后来得病去世，山邻敛些钱财，葬于会稽山下。是年，秦老亦寿终于家。可笑近来文人学士，说著王冕，都称他做王参军，究竟王冕何曾做过一日官？所以表白一番。","这不过是个“楔子”，下面还有正文。"],"cpLength":7004},"rl-03":{"chapterId":"rl-03","bookId":"rlws","fileIndex":3,"number":3,"title":"第三回　周学道校士拔真才　胡屠户行凶闹捷报","paragraphs":["话说周进在省城要看贡院，金有余见他真切，只得用几个小钱同他去看。不想才到‘天’字号，就撞死在地下。众人都慌了，只道一时中了邪。行主人道：“想是这贡院里久没有人到，阴气重了。故此周客人中了邪。”金有余道：“贤东！我扶著他，你且到做工的那里借口开水灌他一灌。”行主人应诺，取了水来，三四个客人一齐扶著，灌了下去。喉咙里咯咯的响了一声，吐出一口稠涎来。众人道：“好了。”扶著立了起来。周进看看号板，又是一头撞了去；这回不死了，放声大哭起来。众人劝也劝不住。金有余道：“你看，这不是疯了么？好好到贡院来耍，你家又不曾死了人，为甚么号淘痛哭？”周进也不听见，只管伏著号板，哭个不住；一号哭过，又哭到二号、三号，满地打滚，哭了又哭，滚的众人心里都凄惨起来。金有余见不是事，同行主人一左一右，架著他的膀子。他那里肯起来，哭了一阵，又是一阵，直哭到口里吐出鲜血来。众人七手八脚，将他扛抬了出来，在贡院前一个茶棚子里坐下，劝他吃了一碗茶；犹自索鼻涕，弹眼泪，伤心不止。","内中一个客人道：“周客人有甚心事，为甚到了这里这等大哭起来？”金有余道：“列位老客有所不知，我这舍舅，本来原不是生意人。因他苦读了几十年的书，秀才也不曾做得一个，今日看见贡院，就不觉伤心起来。”只因这一句话道著周进的真心事，于是不顾众人，又放声大哭起来。又一个客人道：“论这事，只该怪我们金老客；周相父既是斯文人，为甚么带他出来做这样的事？”金有余道：“也只为赤贫之士，又无馆做，没奈何上了这一条路。”又一个客人道：“看令舅这个光景，毕竟胸中才学是好的；因没有人识得他，所以受屈到此田地。”金有余道：“他才学是有的，怎奈时运不济！”","那客人道：“监生也可以进场。周相公既有才学，何不捐他一个监？进场中了，也不枉了今日这番心事。”金有余道：“我也是这般想，只是那里有一笔钱子？”此时周进哭的住了。那客人道：“这也不难，现放著我这几个兄弟在此，每人拿出几十两银子，借与周相公纳监进场；若中了官，那在我们这几两银子？就是周相公不还，我们走江湖的人，那里不破掉了几两银子？何况这是好事，你众位意下如何？”众人一齐道：“‘君子成人之美’。”又道：“‘见义不为，是为无勇。’俺们有甚么不肯？只不知周相公可肯俯就？”周进道：“若得如此，便是重生父母，我周进变驴变马，也要报效！”爬到地下，就磕了几个头；众人还下礼去。金有余也称谢了众人，又吃了几碗茶。周进不再哭了，同众人说说笑笑，回到行里。","次日，四位客人果然备了二百两银子，交与金有余；一切多的使费，都是金有余包办。周进又谢了众人和金有余，行主人替周进准备一席酒，请了众位。金有余将著银子，上了藩库，讨出库收来。正值宗师来省录遗，周进就录了个贡监首卷。到了八月初八日进头场，见了自己哭的所在，不觉喜出望外。","自古道：‘人逢喜事精神爽。’那七篇文字，做的花团锦簇一般；出了场，仍旧住在行里。金有余同那几个客人，还不曾买完了货。直到放榜那日，巍然中了。众人个个喜欢，一齐回到汶上县拜县父母、学师。那典史拿晚生帖子上门来贺。汶上县的人，不是亲的，也来认亲；不认识的，也来相认。忙了个把月，申祥甫听见这事，在薛家集聚了分子，买了四只鸡、五十个蛋，和些炒米饭团之类，亲自上门来贺喜。周进留他吃了酒饭去。荀老爷贺礼是不消说了。看看上京会试，盘费衣服，都是金有余替他设处。到京会试，又中了进士，殿试三甲，授了部属。","荏苒三年，升了御史，钦点广东学道。这周学道虽也请了几个看文章的相公，却自己心里想道：“我在这里面吃苦久了，如今自己当权，须要把卷子都细细看过，不可听著幕客，屈了真才。”主意定了，到广州上了任。","次日，行香挂牌，先考了两场生员。第三场是南海、番禺两县童生。周学道坐在堂上，见那些童生纷纷进来，也有小的，也有老的，仪表端正的，獐头鼠目的，衣冠齐楚的，褴褛破烂的。最后点进一个童生来，面黄肌瘦，花白胡须，头上戴一顶破毡帽。广东虽是气候温暖，这时已是十二月上旬；那童生还穿著麻布直裰，冻得乞乞缩缩，接了卷子，下去归号。","周学道看在心里，封门进去。出来放头牌的时节，坐在上面，只见那穿麻布的童生上来交卷，那衣服因是朽烂了，在号里又扯破了几块。周学道看看自己身上，绯袍锦带，何等辉煌？因翻一翻点名册，问那童生道：“你就是范进？”范进跪下道：“童生就是”。学道道：“你今年多少年纪了？”范进道：“童生册上写的是三十岁，童生实年五十四岁。”学道道：“你考过多少回了？”范进道：“童生二十岁应考，到今考过二十余次。”学道道：“如何总不进学？”范进道：“总因童生文字荒谬，所以各位大老爷不曾赏取。”周学道道：“这也未必尽然。你且出去，卷子待本道细看。”范进磕头下去了。","那时天色尚早，并无童生交卷，周学道将范进卷子用心用意看了一遍。心里不喜道：“这样的文字，都说的是些甚么话！怪不得不进学。”丢过一边不看了。又坐了一会，还不见一个人来交卷，心里想道：“何不把范进的卷子再看一遍？倘有一线之明，也可怜他苦志。”从头至尾，又看了一遍，觉得有些意思；正要再看看，却有一个童生来交卷。","那童生跪下道：“求大老爷面试。”学道和颜道：“你的文字已在这里了，又面试些甚么？”那童生道：“童生诗、词、歌、赋都会，求大老爷出题面试。”学道变了脸道：“当今天子重文章，足下何须讲汉唐？像你做童生的人，只该用心做文章；那些杂览，学他做甚么？况且本道奉旨到此衡文，难道是来此同你谈杂学的么？看你这样务名而不务实，那正务自然荒废，都是些粗心浮气的话，看不得了！左右的！赶了出去！”一声吩咐过了，两旁走过几个如狼似虎的公人，把那童生叉著膊子，一路跟头，叉到大门外。周学道虽然赶他出去，却也把卷子取来看看。那童生叫做魏好古，文字也还清通。学道道：“把他低低的进了学罢。”因取过笔来，在卷子尾上点了一点，做个记认。又取过范进卷子来看，看罢，不觉叹息道：“这样文字，连我看一两遍也不能解，直到三遍之后，才晓得是天地间之至文，真乃一字一珠！可见世上糊涂试官，不知屈煞了多少英才！”忙取笔细细圈点，卷面上加了三圈，即填了第一名；又把魏好古的卷子取过来，填了第二十名。将各卷汇齐，带了进去。发山案来，范进是第一。谒见那日，著实赞扬了一回。点到二十名，魏好古上去，又勉励了几句‘用心举业，休学杂览’的话，鼓吹送了出去。次日起马，范进独自送在三十里之外，轿前打恭。周学道又叫到跟前，说道：“‘龙头属老成。’本道看你的文字，火候到了；即在此科，一定发达。我复命之后，在京专候。”范进又磕头谢了，起来立著。学道轿子，一拥而去。范进立著，直望见门影子抹过前山，看不见了，方才回到下处，谢了房主人。他家离城还有四十五里路，连夜回来，拜见母亲。","家里住著一间草屋，一扇披子。门外是个茅草棚。正屋是母亲住著，妻子住在披房里。他妻子乃是集上胡屠户的女儿。范进进学回家，母亲妻子，俱各欢喜；正待烧锅做饭，只见他丈人胡屠户，手里拿著一副大肠和一瓶酒，走了进来。范进向他作揖，坐下。胡屠户道：“我自倒运，把个女儿嫁与你这现世宝穷鬼，历年以来，不知累了我多少；如今不知因我积了甚么德，使你中了个相公，所以带瓶酒来贺你。”范进唯唯连声，叫太太把肠子煮了，烫起酒来，在茅棚下坐著。母亲和媳妇在厨下做饭。胡屠户又吩咐女婿道：“你如今既中了相公，凡事要立起个体统来。比如我这行业里，都是些正经有脸面的人，又是你的长亲，你怎敢在我们面前装大？若是家门口这些种田的、扒粪的，不过是平头百姓，你若同他拱手作揖，平起平坐，这就是坏了学校规矩，连我脸上都无光了。你是个烂忠厚没用的人，所以这些话我不得不教导你，免得惹人笑话。”范进道：“岳父见教的是。”胡屠户又道：“亲家母也来这里坐著吃饭。老人家每日小菜饭想也难过。我女儿也吃些；自从进了你家门，这几十年，不知猪油可曾吃过两三回哩？可怜！可怜！”说罢，婆媳雨个，都来坐著吃了饭。吃到日西时分，胡屠户吃的醉醺醺的，这里母子两个，千恩万谢。屠户横披了衣服，挺著肚子去了。","次日，范进少不得拜访拜访乡邻。魏好古又约了一个同案的朋友，彼此来往。因是乡试年，做了几个文会。不觉到了六月尽头，这些同案的人约范进去乡试。范进因没有盘费，走去同丈人商议，被胡屠户一口啐在脸上，骂了一个狗血喷头：“不要得意忘形了！你自己只觉得中了一个相公，就‘癞虾蟆想吃起天鹅屁！’我听见人说，就是中相公时，也不是你的文章，还是宗师看见你老，过意不去，舍给你的，如今疑心就想起老爷来！这些中老爷的，都是天上的文曲星；你不看见城里张府上那些老爷，都有万贯家私，一个个方面大耳。像你这尖嘴猴腮，也该撒泡尿自己照照；不三不四，就想天鹅屁吃！趁早收了这心，明年在我们行事里，替你寻一个馆，每年赚几两银子，养活你那老不死的娘和你老婆才是正经！你问我借盘缠，我一天杀一个猪，还赚不到钱把银子，都给你去丢在水里，叫我一家老小喝西北风？”一顿夹七夹八，骂得范进摸门不著。","辞了丈人回来，自己心里想：“宗师说我火候已到。自古无场外的举人，如不进去考他一考，如何甘心？”因向几个同案商议，瞒著丈人，到城里乡试。出了场，即刻回家。家里已是饿了两三天；被胡屠户知道，又骂了一顿。","到出榜那日，家里没有早饭米，母亲吩咐范进道：“我有一只生蛋的母鸡，你快拿到集上卖了，买几升米来煮餐粥吃。我已是饿的两眼都看不见了！”范进慌忙抱了鸡，走出门去。才去了不到两个时辰，只听得一片声的锣响，三匹马闯了来；那三个人下了马，把马栓在茅草棚上，一片声叫道：“快请范老爷出来，恭喜高中了！”母亲不知是甚么事，吓得躲在屋里；听见中了，方敢伸出头来说道：“诸位请坐，小儿方才出去了。”那些报录人道：“原来是老太太。”大家簇拥著要喜钱。正在吵闹，又是几匹马，二报、三报到了，挤了一屋的人，茅草棚地下都坐满了。邻居都来挤著看。老太太没奈何，只得请一个邻居去找他儿子。那邻居飞奔到集上，到处找不到；直寻到集东头，见范进抱著鸡，手里插个草标，一步一踱的，东张西望，在那里寻人买。邻居道：“范相公快些回去！恭喜你中了举人，报喜人挤了一屋哩。”范进道是哄他，只装不听见，低著头往前走。邻居见他不理，走上来就要夺他手里的鸡。范进道：“你夺我的鸡怎的？你又不买。”邻居道：“你中了举人，叫你回家去打报子哩。”范进道：“高邻，你晓得我今日没有米，要卖这只鸡去救命，为甚么拿这话来哄我？我又不同你玩，你自己回去罢，莫误了我卖鸡。”邻居见他不信，劈手把鸡夺了，掼在地下，一把拉了回来。报录人见了道：“好了，新贵人回来了！”正要拥著他说话，范进三两步进屋里来，见中间报帖已经升挂起来，上写道：“捷报贵府老爷范讳进，高中广东乡试第七名‘亚元’，京报连登黄甲。”范进不看便罢，看了一遍，又念一遍，自己把两手拍了一下，笑了一声道：“噫！好了！我中了！”说著，往后一跤跌倒，牙关咬紧，不醒人事。","老太太慌了，忙将几口开水灌了过去；他爬将起来，又怕著手大笑道：“噫！好了！我中了！”笑著，不由分说，就往门外飞跑，把报录人和邻居都吓了一跳。走出大门不多路，一脚踹在池塘里，爬起来，头发都跌散了，两手黄泥，淋淋漓漓一身的水，众人拉他不住。拍著笑著，一直走到集上去了。","众人大眼望小眼，一齐道：“原来新贵人欢喜得疯了。”老太太哭道：“怎生这样苦命的事！中了一个甚么‘举人’就得了这个拙病！这一疯了，几时才得好！”娘子胡氏道：“早上好好出去，怎的就得了这样的病，却是如何是好？”众邻居劝道：“老太太不要心慌，而今我们且派两个人跟定了范老爷。这里众人家里拿些鸡蛋、酒、米，且款待了报子上的老爷们，再为商酌。”当下众邻居，有拿鸡蛋来的，有拿白酒来的，也有背了斗米来的，也有捉两只鸡来的。娘子哭哭啼啼，在厨下收拾齐了，拿在草棚下。邻居又搬些桌凳，请报录的坐著吃酒，商议：“他这疯了，如何是好？”报录的内中有一个人道：“在下倒有一个主意，不知可以行得行不得？”众人问：“如何主意？”那人道：“范老爷平日可有最怕的人？只因他欢喜得很，痰涌上来，迷了心窍；如今只消他怕的这个人来打他一个嘴巴，说：‘这报录的话都是哄你，你并不曾中。’他吃了这一惊，把痰吐了出来，就明白了。”众人都拍手道：“这个主意好得紧！妙得紧！范老爷怕的，莫过于肉案上胡老爹。好了！快寻胡老爹来！他想是还不知道，在集上卖肉哩。”又一个人道：“在集上卖肉，他倒好知道了。他从五更鼓就往东头集上迎猪，还不曾回来，快些迎著去寻他！”","一个人飞奔去迎，走到半路，遇著胡屠户来；后面跟著一个烧汤的二汉，提著七八斤肉，四五千钱，正来贺喜。进门见了老太太，老太太哭著告诉了一番；胡屠户诧异道：“难道这等没福！”外边人一片声：“请胡老爹说话。”胡屠户把肉和钱交与女儿，走了出来，众人如此这般，同他商议。胡屠户作难道：“虽然是我女婿，如今却做了老爷，就是天上的星宿；天上的星宿是打不得的。我听得斋公们说：‘打了天上的星宿，□王就要捉去打一百铁棍，发在十八层地狱，永不得翻身。’我不敢做这样的事。”邻居内一个尖酸人说道：“罢了！胡老爹！你每日杀猪的营生，白刀子进去，红刀子出来，□王也不知叫判官在簿子上记了你几千条铁棍，就是添上这一百棍，又打什么要紧？只恐把铁棍子打完了，也算不到这笔帐上来！或者你救好了女婿的病，□王叙功，从地狱里把你提上第十七层来，也不可知！”","报录的人道：“不要只管讲笑话。胡老爹这个事必须这般样，你没法子权变一权变？”屠户被众人拗不过，只得连斟两碗酒喝了，壮一壮胆，把方才这些小心收起，将平日的凶恶样子拿出来，卷一卷那油晃晃的衣袖，走上集去，众邻居五六个都跟著走。老太太赶出来叫道：“亲家，你只可吓他一吓，却不要把他打伤了！”众邻居道：“这个自然，何消吩咐？”说著，一直去了。","来到集上，见范进正在一个庙门口站著，散著头发，满脸污泥，鞋都跑掉了一只，兀自拍著掌，口里叫道：“中了！中了！”胡屠户凶神般走到跟前，说道：“该死的畜生！你中了甚么？”一个嘴巴打过去，众人和邻居见这模样，忍不住的笑。不想胡屠户虽然大著胆子打了一下，心里到底还是怕的，那手早颤起来，不敢打第二下。范进因这一个嘴巴，却也打晕了，昏倒于地，众邻居齐上前，替他抹胸口，捶背心。","弄了半日，渐渐喘息过来，眼睛明亮，不疯了。众人扶起，借庙门口一个外科郎中姚驼子的板凳上坐著，胡屠户站在一边，不觉那只手隐隐的疼了起来。自己看时，把个巴掌仰著，再也弯不过来；自己心里懊恼道：“果然天上文曲星是打不得的，而今菩萨计较起来了！”想一想，更疼得狠了，连忙问郎中讨了个膏药贴著。","范进看了众人，说道：“我怎么坐在这里？”又道：“我这半日昏昏沉沉，如在梦里一般。”众邻居道：“老爷，恭喜高中了！适才欢喜的有些引动了痰，方才吐出几口痰来，好了。快请回家去打发报录人。”众邻居道：“是了。我也记得是中的第七名。”范进一面自绾了头发，一面问郎中借了一盆水洗洗脸。一个邻居早把那一只鞋寻了来，替他穿上。见丈人在跟前，恐怕又要来骂。胡屠户上前道：“贤婿老爷！方才不是我敢大胆，是你老太太的主意，央我来劝你的。”邻居一个人道：“胡老爷方才这个嘴巴打的亲切，少顷范老爷洗脸，还要洗下半盆猪油来！”又一个道：“老爹，你这手，明日杀不得猪了。”胡屠户道：“我那里还杀猪！有我这贤婿老爷，还怕后半世靠不著么？我时常说：我的这个贤婿才学又高，品貌又好；就是城里头那张府这些老爷，也没有我女婿这样一个体面的相貌。你们不知道，我小这一双眼睛，却是认得人的！想著先年我小女在家里，长到三十多岁，多少有钱的富户要和我结亲，我自己觉得女儿像有些福气的，毕竟要嫁与个老爷。今日果然不错！”说罢，哈哈大笑。众人都笑起来，看看范进洗了脸，郎中又拿茶来吃了，一同回家。范举人先走，胡屠户和邻居跟在后面；屠户见女婿衣裳后襟滚皱了许多，一路低著头替他扯了几十回。到了家门，屠户高声叫道：“老爷回府了！”老太太迎著出来，见儿子不疯，喜从天降。众人问报录的，已是家里把屠户送来的几千钱，打发他们去了。","范进见了母亲，复拜谢丈人。胡屠户再三不安道：“些须几个钱，还不够让你赏人哩！”范进又谢了邻居，正待坐下，早看见一个体面的管家，手里拿著一个大红全帖，飞跑了进来道：“张老爷来拜新中的范老爷。”说毕，轿子已是到了门口。胡屠户忙躲进女儿房里，不敢出来，邻居各自散了。","范进迎了出去，只见那张乡绅下了轿进来，头戴纱帽，身穿葵花色圆领，金带皂靴。他是举人出生，做过一任知县的，别号静斋。同范进让了进来，到堂屋内平磕了头，分宾主坐下。张乡绅先攀谈道：“世先生同在桑梓，一向有失亲近”范进道：“晚生久仰老先生，只是无缘，不曾拜会。”张乡绅道：“适才看见题名录，贵房师高要县汤公，就是先祖的门生；我和你是亲切的世兄弟”范进道：“晚生侥幸，实是有愧；却幸得出老先生门下，可为欣喜。”","张乡绅将眼睛四面望了一望，说道：“世先生果是清贫。”接著，在家人手里拿过一封银子来，说道：“小弟却无以为敬，谨具贺仪五十两，世先生权且收看。这华居，其实住不得，将来当事拜往，俱不甚方便；弟有空房一所，就在东门大街上，三进三间，虽不轩敞，也还还净，就送与世先生，搬到那里去住，早晚也好请教些。”范进再三推辞，张乡绅急了道：“你我年谊世好，就如至亲骨肉一般；若要如此，就是见外了！”范进方才把银子收下，作揖谢了。又说了一会，打躬作别。","胡屠尸直等他上了轿，才敢走出堂屋来。范进即将银子交给太太打开看，一封一封雪白的细丝银子；顺便包了两锭，叫胡屠户进来，递给他道：“方才费老爷的心，拿了五千钱来，这六两多银子，老爷拿了去。”屠户把银子置在手里，紧紧的把拳头伸过来道：“这个，你且收著；我原是贺你的，怎好又拿了回去？”范进道：“眼见得我这里还有这几两银子；若用完了，再来问老爷讨来用。”屠户连忙把拳头缩了回去，往腰里揣。口里说道：“也罢，你如今结交了这个张老爷，何愁没有银了用？他家里的银子，比皇帝家还多哩！他家就是我卖肉的主顾，一年就是无事，肉也要用四五千斤，银子何足为奇：”又转回头来望著女儿说道：“我早上拿了钱来，你那该死的兄弟还不肯。我说：‘姑老爷今非昔比，少不得有人把银子送上门去给他用，只怕姑老爷还不希罕哩。今日果不然！如今拿了银子家去，骂这死砍头短命的奴才！’说了一会，千恩万谢，低著头笑眯眯的去了。 自此以后，果然有许多人来奉承他；有送田产的，有人送店房的，还有那些破落户，两口子来投身为仆，图荫庇的。到两三个月，范进家奴仆丫鬟都有了，钱米是不消说了。张乡绅家又来催著搬家。搬到新房子里，唱戏、摆酒、请客，一连三日。 到第四日上，老太太起来吃过点心，走到第三进房子内，见范进的娘子胡氏，家常戴著银丝髻；此时是十月中旬，天气尚暖，穿著天青缎套，官绿的缎裾；督率著家人、媳妇、丫鬟，洗碗盏杯箸。老太太看了，说道：“你们嫂嫂姑娘们要仔细些，这都是别人家的东西，不要弄坏了。”家人媳妇道：“老太太，那里是别人的，都是你老人家的。”老太太笑道：“我家怎的有这些东西？”丫鬟和媳妇一齐都说道：“怎么不是？岂但这个东西是，连我们这些人和这房子都是你老太太家的！”老太太听了，把细磁碗盏和银镶的杯箸，逐件看了一遍，哈哈大笑道：“这都是我的了！”大笑一声，往后便跌倒；忽然痰涌上来，不省一事。只因这一番，有分教：‘会试举人，变作秋风之客；多事贡生，长为兴讼之人。’","不知老太太性命如何？且听下回分解。"],"cpLength":7867},"sg-21":{"chapterId":"sg-21","bookId":"sgyy","fileIndex":20,"number":21,"title":"第二十一回　曹操煮酒论英雄　关公赚城斩车胄","paragraphs":["却说董承等问马腾曰：“公欲用何人？”马腾曰：“见有豫州牧刘玄德在此，何不求之？”承曰：“此人虽系皇叔，今正依附曹操，安肯行此事耶？”腾曰：“吾观前日围场之中，曹操迎受众贺之时，云长在玄德背后，挺刀欲杀操，玄德以目视之而止。玄德非不欲图操，恨操牙爪多，恐力不及耳。公试求之，当必应允。”吴硕曰：“此事不宜太速，当从容商议。”众皆散去。次日黑夜里，董承怀诏，径往玄德公馆中来。门吏入报，玄德迎出，请入小阁坐定。关、张侍立于侧。玄德曰：“国舅夤夜至此，必有事故。”承曰：“白日乘马相访，恐操见疑，故黑夜相见。”玄德命取酒相待。承曰：“前日围场之中，云长欲杀曹操，将军动目摆头而退之，何也？”玄德失惊曰：“公何以知之？”承曰：“人皆不见，某独见之。”玄德不能隐讳，遂曰：“舍弟见操僭越，故不觉发怒耳。”承掩面而哭曰：“朝廷臣子，若尽如云长，何忧不太平哉！”玄德恐是曹操使他来试探，乃佯言曰：“曹丞相治国，为何忧不太平？”承变色而起曰：“公乃汉朝皇叔，故剖肝沥胆以相告，公何诈也？”玄德曰：“恐国舅有诈，故相试耳。”于是董承取衣带诏令观之，玄德不胜悲愤。又将义状出示，上止有六位：一，车骑将军董承；二，工部侍郎王子服；三，长水校尉种辑；四，议郎吴硕；五，昭信将军吴子兰；六，西凉太守马腾。玄德曰：“公既奉诏讨贼，备敢不效犬马之劳。”承拜谢，便请书名。玄德亦书“左将军刘备”，押了字，付承收讫。承曰：“尚容再请三人，共聚十义，以图国贼，”玄德曰：“切宜缓缓施行，不可轻泄。”共议到五更，相别去了。","玄德也防曹操谋害，就下处后园种菜，亲自浇灌，以为韬晦之计。关、张二人曰：“兄不留心天下大事，而学小人之事，何也？”玄德曰：“此非二弟所知也。”二人乃不复言。","一日，关、张不在，玄德正在后园浇菜，许褚、张辽引数十人入园中曰：“丞相有命，请使君便行。”玄德惊问曰：“有甚紧事？”许褚曰：“不知。只教我来相请。”玄德只得随二人入府见操。操笑曰：“在家做得好大事！”？得玄德面如土色。操执玄德手，直至后园，曰：“玄德学圃不易！”玄德方才放心，答曰：“无事消遣耳。”操曰：“适见枝头梅子青青，忽感去年征张绣时，道上缺水，将士皆渴；吾心生一计，以鞭虚指曰：‘前面有梅林。’军士闻之，口皆生唾，由是不渴。今见此梅，不可不赏。又值煮酒正熟，故邀使君小亭一会。”玄德心神方定。随至小亭，已设樽俎：盘置青梅，一樽煮酒。二人对坐，开怀畅饮。酒至半酣，忽阴云漠漠，聚雨将至。从人遥指天外龙挂，操与玄德凭栏观之。操曰：“使君知龙之变化否？”玄德曰：“未知其详。”操曰：“龙能大能小，能升能隐；大则兴云吐雾，小则隐介藏形；升则飞腾于宇宙之间，隐则潜伏于波涛之内。方今春深，龙乘时变化，犹人得志而纵横四海。龙之为物，可比世之英雄。玄德久历四方，必知当世英雄。请试指言之。”玄德曰：“备肉眼安识英雄？”操曰：“休得过谦。”玄德曰：“备叨恩庇，得仕于朝。天下英雄，实有未知。”操曰：“既不识其面，亦闻其名。”玄德曰：“淮南袁术，兵粮足备，可为英雄？”操笑曰：“冢中枯骨，吾早晚必擒之！”玄德曰：“河北袁绍，四世三公，门多故吏；今虎踞冀州之地，部下能事者极多，可为英雄？“操笑曰：“袁绍色厉胆薄，好谋无断；干大事而惜身，见小利而忘命：非英雄也。玄德曰：“有一人名称八俊，威镇九州：刘景升可为英雄？”操曰：“刘表虚名无实，非英雄也。”玄德曰：“有一人血气方刚，江东领袖——孙伯符乃英雄也？”操曰：“孙策藉父之名，非英雄也。”玄德曰：“益州刘季玉，可为英雄乎？”操曰：“刘璋虽系宗室，乃守户之犬耳，何足为英雄！”玄德曰：“如张绣、张鲁、韩遂等辈皆何如？”操鼓掌大笑曰：“此等碌碌小人，何足挂齿！”玄德曰：“舍此之外，备实不知。”操曰：“夫英雄者，胸怀大志，腹有良谋，有包藏宇宙之机，吞吐天地之志者也。”玄德曰：“谁能当之？”操以手指玄德，后自指，曰：“今天下英雄，惟使君与操耳！”玄德闻言，吃了一惊，手中所执匙箸，不觉落于地下。时正值天雨将至，雷声大作。玄德乃从容俯首拾箸曰：“一震之威，乃至于此。”操笑曰：“丈夫亦畏雷乎？”玄德曰：“圣人迅雷风烈必变，安得不畏？”将闻言失箸缘故，轻轻掩饰过了。操遂不疑玄德。后人有诗赞曰：“勉从虎穴暂趋身，说破英雄惊杀人。巧借闻雷来掩饰，随机应变信如神。”","天雨方住，见两个人撞入后园，手提宝剑，突至亭前，左右拦挡不住。操视之，乃关、张二人也。原来二人从城外射箭方回，听得玄德被许褚、张辽请将去了，慌忙来相府打听；闻说在后园，只恐有失，故冲突而入。却见玄德与操对坐饮酒。二人按剑而立。操问二人何来。云长曰：“听知丞相和兄饮酒，特来舞剑，以助一笑。”操笑曰：“此非鸿门会，安用项庄、项伯乎？”玄德亦笑。操命：“取酒与二樊哙压惊。”关、张拜谢。须臾席散，玄德辞操而归。云长曰：“险些惊杀我两个！”玄德以落箸事说与关、张。关、张问是何意。玄德曰：“吾之学圃，正欲使操知我无大志；不意操竟指我为英雄，我故失惊落箸。又恐操生疑，故借惧雷以掩饰之耳。”关、张曰：“兄真高见！”","操次日又请玄德。正饮间，人报满宠去探听袁绍而回。操召入问之。宠曰：“公孙瓒已被袁绍破了。”玄德急问曰：“愿闻其详。”宠曰：“瓒与绍战不利，筑城围圈，圈上建楼，高十丈，名曰易京楼，积粟三十万以自守。战士出入不息，或有被绍围者，众请救之。瓒曰：‘若救一人，后之战者只望人救，不肯死战矣。’遂不肯救。因此袁绍兵来，多有降者。瓒势孤，使人持书赴许都求救，不意中途为绍军所获。瓒又遗书张燕，暗约举火为号，里应外合。下书人又被袁绍擒住，却来城外放火诱敌。瓒自出战，伏兵四起，军马折其大半。退守城中，被袁绍穿地直入瓒所居之楼下，放起火来。瓒无走路，先杀妻子，然后自缢，全家都被火焚了。今袁绍得了瓒军，声势甚盛。绍弟袁术在淮南骄奢过度，不恤军民，众皆背反。术使人归帝号于袁绍。绍欲取玉玺，术约亲自送至，见今弃淮南欲归河北。若二人协力，急难收复。乞丞相作急图之。”玄德闻公孙瓒已死，追念昔日荐己之恩，不胜伤感；又不知赵子龙如何下落，放心不下。因暗想曰：“我不就此时寻个脱身之计，更待何时？”遂起身对操曰：“术若投绍，必从徐州过，备请一军就半路截击，术可擒矣。”操笑曰：“来日奏帝，即便起兵。”次日，玄德面奏君。操令玄德总督五万人马，又差朱灵、路昭二人同行。玄德辞帝，帝泣送之。","玄德到寓，星夜收拾军器鞍马，挂了将军印，催促便行。董承赶出十里长亭来送。玄德曰：“国舅宁耐。某此行必有以报命。”承曰：“公宜留意，勿负帝心。”二人分别。关、张在马上问曰：“兄今番出征，何故如此慌速？”玄德曰：“吾乃笼中鸟、网中鱼，此一行如鱼入大海、鸟上青霄，不受笼网之羁绊也！”因命关、张催朱灵、路昭军马速行。","时郭嘉、程昱考较钱粮方回，知曹操已遣玄德进兵徐州，慌入谏曰：“丞相何故令刘备督军？”操曰：“欲截袁术耳。”程昱曰：“昔刘备为豫州牧时，某等请杀之，丞相不听；今日又与之兵：此放龙入海，纵虎归山也。后欲治之，其可得乎？”郭嘉曰：“丞相纵不杀备，亦不当使之去。古人云：一日纵敌，万世之患。望丞相察之。”操然其言，遂令许褚将兵五百前往，务要追玄德转来。许褚应诺而去。","却说玄德正行之间，只见后面尘头骤起，谓关、张曰：“此必曹兵追至也。”遂下了营寨，令关、张各执军器，立于两边。许褚至，见严兵整甲，乃下马入营见玄德。玄德曰：“公来此何干？”褚曰：“奉丞相命，特请将军回去，别有商议。”玄德曰：“将在外，君命有所不受。吾面过君，又蒙丞相钧语。今别无他议，公可速回，为我禀覆丞相。”许褚寻思：“丞相与他一向交好，今番又不曾教我来厮杀，只得将他言语回覆，另候裁夺便了。”遂辞了玄德，领兵而回。回见曹操，备述玄德之言。操犹豫未决。程昱、郭嘉曰：“备不肯回兵，可知其心变矣。”操曰：“我有朱灵、路昭二人在彼，料玄德未必敢心变。况我既遣之，何可复悔？”遂不复追玄德。后人有诗叹玄德曰：“束兵秣马去匆匆，心念天言衣带中。撞破铁笼逃虎豹，顿开金锁走蛟龙。”却说马腾见玄德已去，边报又急，亦回西凉州去了。玄德兵至徐州，刺史车胄出迎。公宴毕，孙乾、糜竺等都来参见。玄德回家探视老小，一面差人探听袁术。探子回报：“袁术奢侈太过，雷薄、陈兰皆投嵩山去了。术势甚衰，乃作书让帝号于袁绍。绍命人召术，术乃收拾人马、宫禁御用之物，先到徐州来。”玄德知袁术将至，乃引关、张、朱灵、路昭五万军出，正迎着先锋纪灵至。张飞更不打话，直取纪灵。斗无十合，张飞大喝一声，刺纪灵于马下，败军奔走。袁术自引军来斗。玄德分兵三路：朱灵、路昭在左，关、张在右，玄德自引兵居中，与术相见，在门旗下责骂曰：“汝反逆不道，吾今奉明诏前来讨汝！汝当束手受降，免你罪犯。”袁术骂曰：“织席编屦小辈，安敢轻我！”麾兵赶来。玄德暂退，让左右两路军杀出。杀得术军尸横遍野，血流成渠；兵卒逃亡，不可胜计。又被嵩山雷薄、陈兰劫去钱粮草料。欲回寿春，又被群盗所袭，只得住于江亭。止有一千余众，皆老弱之辈。时当盛暑，粮食尽绝，只剩麦三十斛，分派军士。家人无食，多有饿死者。术嫌饭粗，不能下咽，乃命庖人取蜜水止渴。庖人曰：“止有血水，安有蜜水！”术坐于床上，大叫一声，倒于地下，吐血斗余而死。时建安四年六月也。后人有诗曰：汉末刀兵起四方，无端袁术太猖狂，不思累世为公相，便欲孤身作帝王。强暴枉夸传国玺，骄奢妄说应天祥。渴思蜜水无由得，独卧空床呕血亡。”袁术已死，侄袁胤将灵柩及妻子奔庐江来，被徐璆尽杀之。璆夺得玉玺，赴许都献于曹操。操大喜，封徐璆为高陵太守。此时玉玺归操。　　却说玄德知袁术已丧，写表申奏朝廷，书呈曹操，令朱灵、路昭回许都，留下军马保守徐州；一面亲自出城，招谕流散人民复业。","且说朱灵、路昭回许都见曹操，说玄德留下军马。操怒，欲斩二人。荀彧曰：“权归刘备，二人亦无奈何。”操乃赦之。彧又曰：“可写书与车胄就内图之。”操从其计，暗使人来见车胄，传曹操钧旨。胄随即请陈登商议此事。登曰：“此事极易。今刘备出城招民，不日将还；将军可命军士伏于瓮城边，只作接他，待马到来，一刀斩之；某在城上射住后军，大事济矣。”胄从之。陈登回见父陈珪，备言其事。珪命登先往报知玄德。登领父命，飞马去报，正迎着关、张，报说如此如此。原来关、张先回，玄德在后。张飞听得，便要去厮杀。云长曰：“他伏瓮城边待我，去必有失。我有一计，可杀车胄：乘夜扮作曹军到徐州，引车胄出迎，袭而杀之。”飞然其言。那部下军原有曹操旗号，衣甲都同。当夜三更，到城边叫门。城上问是谁，众应是曹丞相差来张文远的人马。报知车胄，胄急请陈登议曰：“若不迎接，诚恐有疑；若出迎之，又恐有诈。”胄乃上城回言：“黑夜难以分辨，平明了相见。”城下答应：“只恐刘备知道，疾快开门！”车胄犹豫未定，城外一片声叫开门。车胄只得披挂上马，引一千军出城；跑过吊桥，大叫：“文远何在？”火光中只见云长提刀纵马直迎车胄，大叫曰：“匹夫安敢怀诈，欲杀吾兄！”车胄大惊，战未数合，遮拦不住，拨马便回。到吊桥边，城上陈登乱箭射下，车胄绕城而走。云长赶来，手起一刀，砍于马下，割下首级提回，望城上呼曰：“反贼车胄，吾已杀之；众等无罪，投降免死！”诸军倒戈投降，军民皆安。云长将胄头去迎玄德，具言车胄欲害之事，今已斩首。玄德大惊曰：“曹操若来。如之奈何？”云长曰：“弟与张飞迎之。”玄德懊悔不已，遂入徐州。百姓父老，伏道而接。玄德到府，寻张飞，飞已将车胄全家杀尽。玄德曰：“杀了曹操心腹之人，如何肯休？”陈登曰：“某有一计，可退曹操。”正是：既把孤身离虎穴，还将妙计息狼烟。不知陈登说出甚计来，且听下文分解。"],"cpLength":4733},"sg-37":{"chapterId":"sg-37","bookId":"sgyy","fileIndex":36,"number":37,"title":"第三十七回　司马徽再荐名士　刘玄德三顾草庐","paragraphs":["却说徐庶趱程赴许昌。曹操知徐庶已到，遂命荀彧、程昱等一班谋士往迎之。庶入相府拜见曹操。操曰：“公乃高明之士，何故屈身而事刘备乎？”庶曰：“某幼逃难，流落江湖，偶至新野，遂与玄德交厚，老母在此，幸蒙慈念，不胜愧感。”操曰：“公今至此，正可晨昏侍奉令堂，吾亦得听清诲矣。”庶拜谢而出。急往见其母，泣拜于堂下。母大惊曰：“汝何故至此？”庶曰：“近于新野事刘豫州；因得母书，故星夜至此。”徐母勃然大怒，拍案骂曰：“辱子飘荡江湖数年，吾以为汝学业有进，何其反不如初也！汝既读书，须知忠孝不能两全。岂不识曹操欺君罔上之贼？刘玄德仁义布于四海，况又汉室之胄，汝既事之，得其主矣，今凭一纸伪书，更不详察，遂弃明投暗，自取恶名，真愚夫也！吾有何面目与汝相见！汝玷辱祖宗，空生于天地间耳！”骂得徐庶拜伏于地，不敢仰视，母自转入屏风后去了。少顷，家人出报曰：“老夫人自缢于梁间。”徐庶慌入救时，母气已绝。后人有《徐母赞》曰：“贤哉徐母，流芳千古：守节无亏，于家有补；教子多方，处身自苦；气若丘山，义出肺腑；赞美豫州，毁触魏武；不畏鼎镬，不惧刀斧；唯恐后嗣，玷辱先祖。伏剑同流，断机堪伍；生得其名，死得其所：贤哉徐母，流芳千古！”徐虑见母已死，哭绝于地，良久方苏。曹操使人赍礼吊问，又亲往祭奠。徐庶葬母柩于许昌之南原，居丧守墓。凡曹操所赐，庶俱不受。","时操欲商议南征。荀彧谏曰：“天寒未可用兵；姑待春暖，方可长驱大进。”操从之，乃引漳河之水作一池，名玄武池，于内教练水军，准备南征。","却说玄德正安排礼物，欲往隆中谒诸葛亮，忽人报：“门外有一先生，峨冠博带，道貌非常，特来相探。”玄德曰：“此莫非即孔明否？”遂整衣出迎。视之，乃司马徽也。玄德大喜，请入后堂高坐，拜问曰：“备自别仙颜，因军务倥偬，有失拜访。今得光降，大慰仰慕之私。”徽曰：“闻徐元直在此，特来一会。”玄德曰：“近因曹操囚其母，似母遣人驰书，唤回许昌去矣。”徽曰：“此中曹操之计矣！吾素闻徐母最贤，虽为操所囚，必不肯驰书召其子；此书必诈也。元直不去，其母尚存；今若去，母必死矣！”玄德惊问其故，徽曰：“徐母高义，必羞见其子也。”玄德曰：“元直临行，荐南阳诸葛亮，其人若何？”徽笑曰：“元直欲去，自去便了，何又惹他出来呕心血也？”玄德曰：“先生何出此言？”徽曰：“孔明与博陵崔州平、颍川石广元、汝南孟公威与徐元直四人为密友。此四人务于精纯，惟孔明独观其大略。尝抱膝长吟，而指四人曰：“公等仕进可至刺史、郡守。众问孔明之志若何，孔明但笑而不答。每常自比管仲、乐毅，其才不可量也。”玄德曰：“何颍川之多贤乎！”徽曰：“昔有殷馗善观天文，尝谓群星聚于颍分，其地必多贤士。”时云长在侧曰：“某闻管仲、乐毅乃春秋、战国名人，功盖寰宇；孔明自比此二人，毋乃太过？”徽笑曰：“以吾观之，不当比此二人；我欲另以二人出之。”云长问：“那二人？”徽曰：“可比兴周八百年之姜子牙、旺汉四百年之张子房也。”众皆愕然。徽下阶相辞欲行，玄德留之不住。徽出门仰天大笑曰：“卧龙虽得其主，不得其时，惜哉！”言罢，飘然而去。玄德叹曰：“真隐居贤士也！”","次日，玄德同关、张并从人等来隆中。遥望山畔数人，荷锄耕于田间，而作歌曰：“苍天如圆盖，陆地似棋局；世人黑白分，往来争荣辱：荣者自安安，辱者定碌碌。南阳有隐居，高眠卧不足！”玄德闻歌，勒马唤农夫问曰：“此歌何人所作？”答曰：“乃卧龙先生所作也。”玄德曰：“卧龙先生住何处？”农夫曰：“自此山之南，一带高冈，乃卧龙冈也。冈前疏林内茅庐中，即诸葛先生高卧之地。”玄德谢之，策马前行。不数里，遥望卧龙冈，果然清景异常。后人有古风一篇，单道卧龙居处。诗曰：“襄阳城西二十里，一带高冈枕流水：高冈屈曲压云根，流水潺潺飞石髓；势若困龙石上蟠，形如单凤松阴里；柴门半掩闭茅庐，中有高人卧不起。修竹交加列翠屏，四时篱落野花馨；床头堆积皆黄卷，座上往来无白丁；叩户苍猿时献果，守门老鹤夜听经；囊里名琴藏古锦，壁间宝剑挂七星。庐中先生独幽雅，闲来亲自勤耕稼：专待春雷惊梦回，一声长啸安天下。”玄德来到庄前，下马亲叩柴门，一童出问。玄德曰：“汉左将军宜城亭侯领豫州牧皇叔刘备，特来拜见先生。”童子曰：“我记不得许多名字。”玄德曰：“你只说刘备来访。”童子曰：“先生今早少出。”玄德曰：“何处去了？”童子曰：“踪迹不定，不知何处去了。”玄德曰：“几时归？”童子曰：“归期亦不定，或三五日，或十数日。”玄德惆怅不已。张飞曰：”既不见，自归去罢了。”玄德曰：“且待片时。”云长曰：“不如且归，再使人来探听。”玄德从其言，嘱付童子：“如先生回，可言刘备拜访。”遂上马，行数里，勒马回观隆中景物，果然山不高而秀雅，水不深而澄清；地不广而平坦，林不大而茂盛；猿鹤相亲，松篁交翠。观之不已，忽见一人，容貌轩昂，丰姿俊爽，头戴逍遥巾，身穿皂布袍，杖藜从山僻小路而来。玄德曰：“此必卧龙先生也！”急下马向前施礼，问曰：“先生非卧龙否？”其人曰：“将军是谁？”玄德曰：“刘备也。”其人曰：“吾非孔明，乃孔明之友博陵崔州平也。”玄德曰：“久闻大名，幸得相遇。乞即席地权坐，请教一言。”二人对坐于林间石上，关、张侍立于侧。州平曰：“将军何故欲见孔明？”玄德曰：“方今天下大乱，四方云扰，欲见孔明，求安邦定国之策耳。”州平笑曰：“公以定乱为主，虽是仁心，但自古以来，治乱无常。自高祖斩蛇起义，诛无道秦，是由乱而入治也；至哀、平之世二百年，太平日久，王莽篡逆，又由治而入乱；光武中兴，重整基业，复由乱而入治；至今二百年，民安已久，故干戈又复四起：此正由治入乱之时，未可猝定也。将军欲使孔明斡旋天地，补缀乾坤，恐不易为，徒费心力耳。岂不闻顺天者逸，逆天者劳；数之所在，理不得而夺之；命之所在，人不得而强之乎？”玄德曰：“先生所言，诚为高见。但备身为汉胄，合当匡扶汉室，何敢委之数与命？”州平曰：“山野之夫，不足与论天下事，适承明问，故妄言之。”玄德曰：“蒙先生见教。但不知孔明往何处去了？”州平曰：“吾亦欲访之，正不知其何往。”玄德曰：“请先生同至敝县，若何？”州平曰：“愚性颇乐闲散，无意功名久矣；容他日再见。”言讫，长揖而去。玄德与关、张上马而行。张飞曰：“孔明又访不着，却遇此腐儒，闲谈许久！”玄德曰：“此亦隐者之言也。”","三人回至新野，过了数日，玄德使人探听孔明。回报曰：“卧龙先生已回矣。”玄德便教备马。张飞曰：“量一村夫，何必哥哥自去，可使人唤来便了。”玄德叱曰：“汝岂不闻孟子云：欲见贤而不以其道，犹欲其入而闭之门也。孔明当世大贤，岂可召乎！”遂上马再往访孔明。关、张亦乘马相随。时值隆冬，天气严寒，彤云密布。行无数里，忽然朔风凛凛，瑞雪霏霏：山如玉簇，林似银妆。张飞曰：“天寒地冻，尚不用兵，岂宜远见无益之人乎！不如回新野以避风雪。”玄德曰：“吾正欲使孔明知我殷勤之意。如弟辈怕冷，可先回去。”飞曰：“死且不怕，岂怕冷乎！但恐哥哥空劳神思。”玄德曰：“勿多言，只相随同去。”将近茅庐，忽闻路傍酒店中有人作歌。玄德立马听之。其歌曰：“壮士功名尚未成，呜呼久不遇阳春！君不见东海者叟辞荆榛，后车遂与文王亲；八百诸侯不期会，白鱼入舟涉孟津；牧野一战血流杵，鹰扬伟烈冠武臣。又不见高阳酒徒起草中，长楫芒砀隆准公；高谈王霸惊人耳，辍洗延坐钦英风；东下齐城七十二，天下无人能继踪。二人功迹尚如此，至今谁肯论英雄？”歇罢，又有一人击桌而歌。其歌曰：“吾皇提剑清寰海，创业垂基四百载；桓灵季业火德衰，奸臣贼子调鼎鼐。青蛇飞下御座傍，又见妖虹降玉堂；群盗四方如蚁聚，奸雄百辈皆鹰扬，吾侪长啸空拍手，闷来村店饮村酒；独善其身尽日安，何须千古名不朽！”","二人歌罢，抚掌大笑。玄德曰：“卧龙其在此间乎！”遂下马入店。见二人凭桌对饮：上首者白面长须，下首者清奇古貌。玄德揖而问曰：“二公谁是卧龙先生？”长须者曰：“公何人？欲寻卧龙何干？”玄德曰：“某乃刘备也。欲访先生，求济世安民之术。”长须者曰：“我等非卧龙，皆卧龙之友也：吾乃颍川石广元，此位是汝南孟公威。”玄德喜曰：“备久闻二公大名，幸得邂逅。今有随行马匹在此，敢请二公同往卧龙庄上一谈。”广元曰：“吾等皆山野慵懒之徒，不省治国安民之事，不劳下问。明公请自上马，寻访卧龙。”","玄德乃辞二人，上马投卧龙冈来。到庄前下马，扣门问童子曰：“先生今日在庄否？”童子曰：“现在堂上读书。”玄德大喜，遂跟童子而入。至中门，只见门上大书一联云：“淡泊以明志。宁静而致远。”玄德正看间，忽闻吟咏之声，乃立于门侧窥之，见草堂之上，一少年拥炉抱膝，歌曰：“凤翱翔于千仞兮，非梧不栖；士伏处于一方兮，非主不依。乐躬耕于陇亩兮，吾爱吾庐；聊寄傲于琴书兮，以待天时。”","玄德待其歌罢，上草堂施礼曰：“备久慕先生，无缘拜会。昨因徐元直称荐，敬至仙庄，不遇空回。今特冒风雪而来。得瞻道貌，实为万幸，”那少年慌忙答礼曰：“将军莫非刘豫州，欲见家兄否？”玄德惊讶曰：“先生又非卧龙耶？”少年曰：“某乃卧龙之弟诸葛均也。愚兄弟三人：长兄诸葛瑾，现在江东孙仲谋处为幕宾；孔明乃二家兄。”玄德曰：“卧龙今在家否？”均曰：“昨为崔州平相约，出外闲游去矣。”玄德曰：“何处闲游？”均曰：“或驾小舟游于江湖之中，或访僧道于山岭之上，或寻朋友于村落之间，或乐琴棋于洞府之内：往来莫测，不知去所。”玄德曰：“刘备直如此缘分浅薄，两番不遇大贤！”均曰：“少坐献茶。”张飞曰：“那先生既不在，请哥哥上马。”玄德曰：“我既到此间，如何无一语而回？”因问诸葛均曰：“闻令兄卧龙先生熟谙韬略，日看兵书，可得闻乎？”均曰：“不知。”张飞曰：“问他则甚！风雪甚紧，不如早归。”玄德叱止之。均曰：“家兄不在，不敢久留车骑；容日却来回礼。”玄德曰：“岂敢望先生枉驾。数日之后，备当再至。愿借纸笔作一书，留达令兄，以表刘备殷勤之意。”均遂进文房四宝。玄德呵开冻笔，拂展云笺，写书曰：“备久慕高名，两次晋谒，不遇空回，惆怅何似！窃念备汉朝苗裔，滥叨名爵，伏睹朝廷陵替，纲纪崩摧，群雄乱国，恶党欺君，备心胆俱裂。虽有匡济之诚，实乏经纶之策。仰望先生仁慈忠义，慨然展吕望之大才，施子房之鸿略，天下幸甚！社稷幸甚！先此布达，再容斋戒薰沐，特拜尊颜，面倾鄙悃。统希鉴原。”玄德写罢，递与诸葛均收了，拜辞出门。均送出，玄德再三殷勤致意而别。方上马欲行，忽见童子招手篱外，叫曰：“老先生来也。”玄德视之，见小桥之西，一人暖帽遮头，狐裘蔽体，骑着一驴，后随一青衣小童，携一葫芦酒，踏雪而来；转过小桥，口吟诗一首。诗曰：“一夜北风寒，万里彤云厚。长空雪乱飘，改尽江山旧。仰面观火虚，疑是玉龙斗。纷纷鳞甲飞，顷刻遍宇宙。骑驴过小桥，独叹梅花瘦！”玄德闻歌曰：“此真卧龙矣！”滚鞍下马，向前施礼曰：“先生冒寒不易！刘备等候久矣！”那人慌忙下驴答礼。","诸葛均在后曰：“此非卧龙家兄，乃家兄岳父黄承彦也。”玄德曰：“适间所吟之句，极其高妙。”承彦曰：“老夫在小婿家观《梁父吟》，记得这一篇；适过小桥，偶见篱落间梅花，故感而诵之。不期为尊客所闻。”玄德曰：“曾见令婿否？”承彦曰：“便是老夫也来看他。”玄德闻言，辞别承彦，上马而归。正值风雪又大，回望卧龙冈，悒怏不已。后人有诗单道玄德风雪访孔明。诗曰：“一天风雪访贤良，不遇空回意感伤。冻合溪桥山石滑，寒侵鞍马路途长。当头片片梨花落，扑面纷纷柳絮狂。回首停鞭遥望处，烂银堆满卧龙冈。”","玄德回新野之后，光阴荏苒，又早新春。乃令卜者揲蓍，选择吉期，斋戒三日，薰沐更衣，再往卧龙冈谒孔明。关、张闻之不悦，遂一齐入谏玄德。正是：高贤未服英雄志，屈节偏生杰士疑。未知其言若何，下文便晓。"],"cpLength":4739},"sh-02":{"chapterId":"sh-02","bookId":"shzh","fileIndex":2,"number":2,"title":"第二回　史大郎夜走华阴县　鲁提辖拳打镇关西","paragraphs":["诗曰：","暑往寒来春复秋，夕阳西下水东流。时来富贵皆因命，运去贫穷亦有由。","事遇机关须进步，人当得意便回头。将军战马今何在？野草闲花满地愁。","话说当时史进道：“却怎生是好？”　　朱武等三个头领跪下道：“哥哥，你是干净的人，休为我等连累了。大郎可把索来绑缚我三个出去请赏，免得负累了你不好看。”","史进道：“如何使得！恁地时，是我赚你们来，捉你请赏，枉惹天下人笑。若是死时，我与你们同死；活时同活。你等起来，放心，别作圆便。且等我问个来历情繇。”","史进上梯子问道：“你两个何故半夜三更来劫我庄上？”","两个都头道：“大郎，你兀自赖哩！见有原告人李吉在这里。”","史进喝道：“李吉，你如何诬告平人？”","李吉应道：“我本不知；林子里拾得王四的回书，一时间yb县前看，因此事发。”","史进叫王四，问道：“你说无回书，如何却又有书？”","王四道：“便是小人一时醉了，忘记了回书。”　　史进大喝道：“畜生！却怎生好！”外面都头人等惧怕史进了得，不敢奔入庄里来捉人。","三个头领把手指道：“且答应外面。”","史进会意，在梯子上叫道：“你两个都头都不必斗动，权退一步，我自绑缚出来解官请赏。”","那两个都头都怕史进，只得应道：“我们都是没事的，等你绑出来，同去请赏。”　　史进下梯子，来到厅前，先将王四带进后园，把来一刀杀了；喝教许多庄客把庄里有的没的细软等物即便收，拾尽教打叠起了；一壁点起三四十个火把。","庄里史进和三个头领全身披挂，枪架上各人跨了腰刀，拿了朴刀，拽扎起，把庄后草屋点着；庄客各自打拴了包裹，外面见里面火起，都奔来后面看。","史进却就中堂又放起火来，大开庄门，呐声喊，杀将出来。","史进当头，朱武，杨春在中，陈达在后，和小喽罗并庄客，冲将出来，正迎着两个都头并李吉，史进见了大怒。　　“仇人见面，分外眼明！”　　两个都头见势头不好，转身便走。","李吉也却得回身。","史进早到，手起一刀，把李吉斩做两段。","两个都头正待走时，陈达，杨春赶上，一个一朴刀，结果了两个性命。　　县尉惊得跑马走回去了。","众士兵那里敢向前，各自逃命散了，不知去向。","史进引着一行人，且杀且走，直到少华山上寨内坐下。","喘息方定，朱武等忙叫小喽罗一面杀牛宰马，贺喜饮宴，不在话下。","一连过了几日，史进寻思：“一时间要救三人，放火烧了庄院。虽是有些细软家财，重杂物，尽皆没了！”","心内踌躇，在此不了，开言对朱武等说道：“我师父王教头在关西经略府勺当，我先要去寻他，只因父亲死了，不曾去得；今来家私庄院废尽，我如今要去寻他。”","朱武三人道：“哥哥休去，只在我寨中且过几日，又作商议。若哥哥不愿落草时，待平静了，小弟们与哥哥重整庄院，再作良民。”","史进道：“虽是你们的好情分，只是我今去意难留。我若寻得师父，也要那里讨个出身，求半世快乐。”　　朱武道：“哥哥便在此间做个寨主，却不快活？只恐寨小不堪歇马。”　　史进道：“我是个清白好汉，如何肯把父母遗体来点污了！你劝我落草，再也休题。”","史进住了几日，定要去。","朱武等苦留不住。","史进带去的庄客都留在山寨；只自收拾了些散碎银两，打拴一个包里，馀者多的尽数寄留在山寨。　　史进头带白范阳毡大帽，上撒一撮红缨；帽儿下裹一顶浑青抓角软头巾。","顶上明黄缕带；身穿一领白丝两上领战袍；腰系一条五指梅红攒线搭；青白间道行缠绞脚，衬着踏山透土多耳麻鞋；跨一口铜钹磐口雁翎刀；背上包裹；提了朴刀；辞别朱武等三人。　　众多小喽罗都送下山来。","朱武等洒泪而别，自回山寨去了。","只说史进提了朴刀，离了少华山，取路投关西正路。","望延安府路上来，免不得饥食渴饮，夜住晓行；独自行了半月之上，来到渭州：“这里也有个经略府，莫非师父王教头在这里？”","史进便入城来看时，依然有六街三市。　　只见一个小小茶坊正在路口。　　史进便入茶坊里来拣一副坐位坐了。","茶博士问道：“这里经略府在何处？”","茶博士道：“只在前面便是。”","史进道：“借问经略府内有个东京来的教头王进么？”","茶博士道：“这府里教头极多，有三四个姓王的，不知那个是王进。”","道犹未了，只见一个大汉大踏步竟进入茶坊里来。","史进看他时，是个军官模样；头里芝麻罗万字顶头巾；脑后两个太原府扭丝金环；上穿一领鹦哥绿丝战袍；腰系一条文武双股鸦青；足穿一双鹰爪皮四缝干黄靴；生得面圆耳大，鼻直口方，腮边一部落腮胡须，身长八尺，腰阔十围。","那人入到茶房里面坐下。","茶博士道：“客官，要寻王教头，只问这位提辖，便都认得。”","史进忙起身施礼道：“客官，请坐，拜茶。”","那人见史进长大魁伟，像条好汉，便来与他施礼。","两个坐下。　　史进道：“小人大胆，敢问官人高姓大名？”那人道：“酒家是经略府提辖，姓鲁，讳个达字。敢问阿哥，你姓什么？”","史进道：“小人是华州华阴县人氏。姓史，名进。请问官人，小人有个师父，是东京八十万禁军教头，姓王，名进，不知在此经略府中有也无？”","鲁提辖道：“阿哥，你莫不是史家村甚么九纹龙史大郎？”","史进拜道：“小人便是。”","鲁提辖连忙还礼，说道：““闻名不如见！见面胜如闻名。”你要寻王教头，莫不是在东京恶了高太尉的王进？”","史进道：“正是那人。”","鲁达道：“俺也闻他名字，那个阿哥不在这里。酒家听得说，他在延安府老种经略相公处勾当。俺这渭州却是小种经略相公镇守。那人不在这里。你即是史大郎时，多闻你的好名字，你且和我上街去吃杯酒。”　　鲁提辖挽了史进的手，便出茶坊来。","鲁达回头道：“茶钱，酒家自还你。”","茶博士应道：“提辖但吃不妨，只顾去。”","两两挽了，出得茶坊来，上街行得三五十步，只见一簇众人围住白地上。史进道：“兄长，我们看一看。”","分开人众看时，中间里一个人，仗着十来条杆棒，地上摊着十数个膏药，一盘子盛着，插y虼b上面，却原来是江湖上使枪棒卖药的。","史进见了，却认得他。","原来是教史进开手的师父，叫做“打虎将”李忠。","史进就人丛中叫道：“师父，多时不见。”","李忠道：“贤弟如何到这里？”","鲁提辖道：“既是史大郎的师父，也和俺去吃三杯。”","李忠道：“待小子卖了膏药，讨了回钱，一同和提辖去。”","鲁达道：“谁奈烦等你！去便同去！”李忠道：“小人的衣饭，无计奈何。提辖先行，小人便寻将来。－－贤弟，你和提辖先行一步。”　　鲁达焦躁，把那看的人一推一交，骂道：“这厮们夹着屁眼撤开！不去的酒家便打！”","众人见是鲁提辖，一开都走了。　　李忠见鲁达凶猛，敢怒而不敢言，只得陪笑道：“好急性的人！”　　当下收拾了行头药囊，寄顿了枪棒。","三个人转弯抹角，来到州桥之下一个潘家有名的酒店，门前挑出望竿，挂着酒旗，漾在空史飘荡。","三人来到潘家酒楼上拣个济楚阁儿里坐下。","提辖坐了主位，李忠对席，史进下首坐了。","酒保唱了喏，认的是鲁提辖便道：“提辖官人，打多少酒？”","鲁达道：“先打四角酒来。”","一面铺下菜蔬果品按酒，又问道：“官人，吃甚下饭？”","鲁达道：“问甚么！但有，只顾卖来，一发算钱还你！这厮！只顾来聒噪！”酒保下去，随即烫酒上来；但是下口肉食，只顾将来摆一桌子。","三个酒至数杯，正说z⒐陧A较量些枪法，说得入港，只听得隔壁阁子里有人哽哽咽咽啼哭。","鲁达焦躁，便把碟儿盏儿都丢在楼板上。","酒保听得，慌忙上来看时，见鲁提辖气愤地。","酒保抄手道：“官人，要甚东西，分付卖来。”","鲁达道：“酒家要甚么！你也须认得酒家！却恁地教甚么人在间壁吱吱的哭，搅俺弟兄们吃酒？酒家须不曾少了你酒钱！”","酒保道：“官人息怒。小人怎敢教人啼哭打搅官人吃酒？这个哭的是绰酒座儿唱的父女两人，不知官人们在此吃酒，一时间自苦了啼哭。”　　鲁提辖道：“可是作怪！你与我唤得他来。”","酒保去叫。","不多时，只见两个到来∶前面一个十八九岁的妇人，背后一个五六十岁的老儿，手里拿串拍板，都来到面前。　　看那妇人，虽无十分的容貌，也有些动人的颜色，拭着泪眼，向前来，深深的道了三个万福。","那老儿也都相见了。","鲁达问道：“你两个是那里人家？为甚么啼哭？”　　那妇人便道：“官人不知，容奴告禀∶奴家是东京人氏，因同父母来渭州投奔亲眷，不想搬移南京去了。母亲在客店里染病身故。父女二人流落在此生受。此间有个财主，叫做“镇关西”郑大官人，因见奴家，便使强媒硬保，要奴作妾。谁想写了三千贯文书，虚钱实契，要了奴家身体。未及三个月，他家大娘子好生利害，将奴赶打出来，不容完聚，着落店主人家追要原典身钱三千贯。父亲懦弱，和他争不得。他又有钱有势。当初不曾得他一文，如今那讨钱来还他？没计奈何，父亲自小教得家些小曲儿，来这里酒楼上赶座子，每日但得些钱来，将大半还他，留些少父女们盘缠。这两日，酒客稀少，违了他钱限，怕他来讨时，受他差耻。父女们想起这苦楚zA无处告诉，因此啼哭。不想误犯了官，望乞恕罪，高抬贵手！”鲁提辖又问道：“你姓甚么？在那个客店里歇？那个镇关西郑大官人在那里住？”","老儿答道：“老汉姓金，排行第二。孩儿小字翠莲。郑大官人便是此间状元桥下卖肉的郑屠，绰号镇关西。老汉父女两个只在前面东门里鲁家客店安下。”　　鲁达听了道：“呸！俺只道那个郑大官人，却原来是杀猪的郑屠！这个腌泼才，投托着俺小种经略相公门下做个肉铺户，却原来这等欺负人！”","必头看着李忠，史进，道：“你两个且在这里，等酒家去打死了那厮便来！”史进，李忠，抱住劝道：“哥哥息怒，明日却理会。”","两个三回五次劝得他住。　　鲁达又道：“老儿，你来。酒家与你些盘缠，明日便回东京去，如何？”　　父女两个告道：“若是能彀回乡去时，便是重生父母，再长爷娘。只是店主人家如何肯放？郑大官人须着落他要钱。这个不妨事，俺自有道理。”","便去身边摸出五两来银子，放在上，看着史进道：“酒家今日不曾多带得些出来；你有银子，借些与俺，酒家明日便送还你。”　　史进道：“值甚么，要哥哥还。”　　去包裹里取出一锭十两银子放在桌上。","鲁达看着李忠道：“你也借些出来与酒家。”　　李忠去身边摸出二两来银子。","鲁提辖看了，见少，便道：“也是个不爽利的人！”","鲁达只把这十五两银子与了金老，分付道：“你父女两个将去做盘缠，面收拾行李。俺明日清早来发付你两个起身，看那个店主人敢留你！”","金老并女儿拜谢去了。","鲁达把这两银子丢还了李忠。","三人再吃了两角酒，下楼来叫道：“主人家酒钱，酒家明日送来还你。”","主人家连声应道：“提辖只顾自去，但吃不妨，只怕提辖不来赊。”","三个人出了潘家酒肆，到街上分手。","史进，李忠，各自投客店去了。","只说鲁提辖回到经略府前下处。","到房里，晚饭也不吃，气愤愤地睡了。","主人家又不敢问他。","再说金老得了这一十五两银子，回到店中，安顿了女儿，先去城外远处觅下一辆车儿；回来收拾了行李，还了房钱，算清了柴米钱，只等来日天明，当夜无事。次早，五更起来，父女两个先打火做饭，吃罢，收拾了，天色微明，只见鲁提辖大脚步走入店里来，高声叫道：“店小二，那里是金老歇处？”","小二道：“金公，鲁提辖在此寻你。”","金老引了女儿，挑了担儿，作谢提辖，便待出门。","店小二拦住道：“金公，那里去？”","鲁达问道：“他少了你房钱？”","小二道：“小人房钱，昨夜都算还了；须欠郑大官人典身钱，着落在小人身上看他哩。”","鲁提辖道：“郑屠的钱，酒家自还他，你放了老儿还乡去！”　　那店小二那里肯放。","鲁达大怒，开五指，去那小二脸上只一掌，打得那店小二口中吐血；再复一拳，打落两个当门牙齿。","小二爬将起来，一道烟跑向店里去躲了。　　店主人那里敢出来拦他。","金老父女两个忙忙离了店中，出城自去寻昨日觅下的车儿去了。","且说鲁达寻思，恐怕店小二赶去拦截他，且向店里掇条凳子坐了两个时辰，约莫金公去得远了，方才起身，迳到状元桥来。　　且说郑屠开着间门面，两副肉案，悬挂着三五片猪肉。　　郑屠正在门前柜身内坐定，看那十来个刀手卖肉。","鲁达走到门前，叫声“郑屠。”","郑屠看时，见是鲁提辖，慌忙出柜身来唱喏，道：“提辖恕罪。”","－－便叫副手掇条凳子来。","－－“提辖请坐。”","鲁达坐下，道：“奉着经略相公钧旨∶要十斤精肉，切做臊子，不要见半点肥的在上面。”　　郑屠道：“使得，你们快选懊的切十斤去。”","鲁提辖道：“不要那等腌厮们动手你自与我切。”","郑屠道：“说得是小人自切便了。”","自去肉案上拣了十斤精肉，细细切做臊子。","那店小二把手帕包了头，正来郑屠家报说金老之事，却见鲁提辖坐在肉案门边，不敢拢来，只得远远的立住，在房檐下望。","这郑屠整整自切了半个时辰，用荷叶包了，道：“提辖，教人送去？”","鲁达道：“送甚么！且住！再要十斤都是肥的，不要见些精的在上面，－－也要切做臊子。”","郑屠道：“却才精的，怕府里要裹馄饨；肥的臊子何用？”","鲁达睁着眼，道：“相公钧旨分付酒家，谁敢问他？”","郑屠道：“是合用的东西，小人切便了。”","又选了十斤实膘的肥肉也细细的切做臊子，把荷叶包了。　　整弄了一早晨，却得饭罢时候。","那店小二那里敢过来，连那正要买肉的主顾也不敢拢来。","郑屠道：“着人与提辖拿了，送将府里去？”","鲁达道：“再要十斤寸金软骨，也要细细地剁做臊子，不要见些肉在上面。”郑屠笑道：“却不是特地来消遗我！”　　鲁达听得，跳起身来，拿着那两包臊子在手，睁着眼，看着郑屠，道：“酒家特地要消遗你！”把两包臊子劈面打将去，却似下了一阵的“肉雨。”郑屠大怒，两条忿气从脚底下直冲到顶门；心头那一把无明业火焰腾腾的按纳不住；从肉案上抢了一把剔骨尖刀，托地跳将下来。","鲁提辖早拔步在当街上。","众邻舍并十来个火家，那个敢向前来劝；两边过路的人都立住了脚；和那店小二也惊得呆了。","郑屠右手拿刀，左手便来要揪鲁达；被这鲁提辖就势按住左手，赶将入去，望小腹上只一脚，腾地倒在当街上。","鲁达再入一步，踏住胸脯，提着醋钵儿大小拳头，看着这郑屠道：“酒家始投老种经略相公，做到关西五路廉访使，也不枉了叫做”郑关西！”　　你是个卖肉的操刀屠户，狗一般的人，也叫做“郑关西！”　　你如何强骗了金翠莲？”","扑的只一拳，正打在鼻子上，打得鲜血迸流，鼻子歪在半边，却便似开了个油铺∶咸的，酸的，辣的，一发都滚出来。","郑屠挣不起来，那把尖刀也丢在一边，口里只叫：“打得好！”","鲁达骂道：“直娘贼！惫敢应口！”","提起拳头来就眼眶际眉梢只一拳，打得眼棱缝裂，乌珠迸出，也似开了个彩帛铺的∶红的，黑的，紫的，都绽将出来。","两边看的人惧怕鲁提辖，谁敢向前来劝？郑屠当不过，讨饶。","鲁达喝道：“咄！你是个破落户！若只和俺硬到底，酒家便饶你了！你如今对俺讨饶，酒家偏不饶你！”","又只一拳，太阳上正着，却似做了一全堂水陆的道场∶磐儿，钹儿，铙儿，一齐响。　　鲁达看时，只见郑屠挺在地上，口里只有出的气，没了入的气，个动掸不得。鲁提辖假意道：“你这厮诈死，，酒家再打！”","只见面皮渐渐的变了。","鲁达寻思道：“俺只指望打这厮一顿，不想三拳真个打死了他。酒家须吃官司，又没人送饭，不如及早撒开。”","拔步便走，回头指着郑屠尸道：“你诈死！酒家和你慢慢理会！”　　一头骂，一头大踏步去了。","街坊邻舍并郑屠的火家，谁敢向前来拦他。","鲁提辖回到下处，急急卷了些衣服盘缠，细软银两；但是旧衣粗重都弃了；提了一条齐眉短棒，奔出南门，一道烟走了。","且说郑屠家中众人和那报信的店小二救了半日，不活，呜呼死了。　　老小邻人迳来州衙告状，候得府尹升厅，接了状子，看罢，道：“鲁达系经略府提辖，不敢擅自迳来捉捕凶身。”","府尹随即上轿，来到经略府前，下了轿子，把门军士入去报知。","经略听得，教请。　　到厅上与府尹施礼罢。","经略道：“何来？”","府尹禀道：“好教相公得知，府中提辖鲁达无故用拳打死市上郑屠。不曾禀过相公，不敢擅自捉拿凶身。”","经略听了，吃了一惊，寻思道：“这鲁达虽好武艺，只见性格卤。今番做出人命事，俺如何护得短？。。。须教推问使得。”　　经略回府尹道：“鲁达这人原是我父亲老经略处的军官。为因俺这里无人帮护，拨他来做个提辖。既然犯了人命罪过，你可拿他依法度取问。如若供招明白，拟罪已定，也须教我父亲知道，方可断决。怕日后父亲处边上要这个人时，却不好看。”","府尹禀道：“下官问了情繇，合行申禀老经略相公知道，方敢断遣。”府尹辞了经略相公，出到府前，上了轿，回到州衙里，升厅坐下，便唤当日揖捕使臣押下文书，捉拿犯人鲁达。","当时王观察领了公文，将带二十来个做公的人迳到鲁提辖下处。","只见房主人道：“却才带了些包裹，提了短棒，出去了。小人只道奉着差使，又不敢问他。”","王观察听了，教打开他房门看时，只有些旧衣旧裳和些被卧在里面。","王观察就带了房主人东西四下里去跟寻，州南走到州北，捉拿不见。","王观察又捉了两家邻舍并房主人同到州衙厅上回话道：“鲁提辖惧罪在逃，不知去向，只拿得房主人并邻舍在此。”","府尹见说，且教监下，一面教拘集郑屠家邻佑人等，点了仵作行人，仰着本地方官人并坊厢里正再三检验，已了，郑屠家自备棺木盛殓，寄在寺院。　　一面叠成文案，一壁差人杖限缉捕凶身。","原告人保领回家。","邻佑杖断有失救应。　　房主人并下处邻舍止得个不应。","鲁达在逃。　　行开个广捕急递的文书，各处追捉；出赏一千贯；写了鲁达的年甲，贯址，形貌，到处张挂。","一干人等疏放听候。　　郑屠家亲人自去做孝，不在话下。　　且说鲁达自离了渭州，东逃西奔，急急忙忙，行过了几处州府，正是“饥不择食，寒不择衣，慌不择路，贫不择妻。”","鲁达心慌抢路，正不知投那里去的是；一连地行了半月之上，却走到代州雁门县；入得城来，见这市井闹热，人烟骤集，车马驰，一百二十行经商买卖行货都有，端的整齐，虽然是个县治，胜如州府，鲁提辖正行之间，却见一簇人围住了十字街口看榜。","鲁达看见挨满，也钻在人丛里听时。","－－鲁达却不识字。","－－只听得众人读道：“代州雁门县依奉太原府指挥使司，该准渭州文字，捕捉打死郑屠犯人鲁达，即系经略府提辖。如有人停藏在家宿食者，与犯人同罪；若有人捕获前来或首到告官，支给赏钱一千贯文。。。。”鲁提辖正听到那里，只听得背后一个人大叫道：“张大哥，你如何在这里？”","拦腰抱住，扯离了十字路口。","不是这个人看见了，横拖倒拽将去，有分教∶鲁提辖剃除头发，削去胡须，倒换过杀人姓名，薅恼杀诸佛罗汉；直教∶禅杖打开危险路，戒刀杀尽不平人。","毕竟扯住鲁提辖的是甚人，且听下回分解。"],"cpLength":7368},"sh-10":{"chapterId":"sh-10","bookId":"shzh","fileIndex":9,"number":10,"title":"第九回　林教头风雪山神庙　陆虞候火烧草料场","paragraphs":["诗曰：","天理昭昭不可诬，莫将奸恶作良图。若非风雪沽村酒，定被焚烧化朽枯。","自谓冥中施计毒，谁知暗里有神扶。最怜万死逃生地，真是瑰奇伟丈夫。","话说当日林冲正闲走间，忽然背后人叫。回头看时，却认得是酒生儿李小二。当初在东京时，多得林冲看顾。这李小二先前在东京时，不合偷了店主人家财，被捉住了，要送官司同罪。却得林冲主张陪话，救了他免送官司。又也陪了些钱财，方得脱免。京中安不得身，又亏林冲赍发他盘缠，于路投奔人。不想今日却在这里撞见。林冲道：“小二哥，你如何也在这里？”李小二便拜道：“自从得恩人救济，赍发小人，一地里投奔人不着。迤B053不想来到沧州，投托一个酒店里姓王，留小人在店中做过卖。因见小人勤谨，安排的好菜蔬，调和的好汁水，来吃的人都喝采，以此买卖顺当。主人家有个女儿，就招了小人做女婿。如今丈人丈母都死了，只剩得小人夫妻两个，权在营前开了个茶酒店。因讨钱过来，遇见恩人。恩人不知为何事在这里？”林冲指着脸上道：“我因恶了高太尉，生事陷害，受了一场官司，刺配到这里。如今叫我管天王堂，未知久后如何。不想今日到此遇见。”李小二就请林冲到家里面坐定，叫妻子出来拜了恩人。两口儿欢喜道：“晚夫妻二人正没个亲眷，今日得恩人到来，便是从天降下。”林冲道：“我是罪囚，恐怕玷辱你夫妻两个。”李小二道：“谁不知恩人大名，休恁地说。但有衣服，便拿来家里浆洗缝补。”当时管待林冲酒食，至晚送回天王堂。次日，又来相请。因此林冲得李小二家来往，不时间送汤送水，来营里与林冲吃。林冲因见他两口儿恭勤孝顺，常把些银两与他做本钱。不在话下。有时为证：","才离寂寞神堂路，又守萧条草料场。李二夫妻能爱客，供茶送酒意偏长。","且把闲话休题，只说正话。迅速光阴，却早冬来。林冲的绵衣裙袄，都是李小二浑身整治缝补。忽一日，李小二正在门前安排菜蔬下饭，只见一个人闪将进来，酒店里坐下，随后又一人入来。看时，前面那个人是军官打扮，后面这个走卒模样。跟着也来坐下。李小二入来问道：“要吃酒？”只见那个人将出一两银子与小二道：“且收放柜上，取三四瓶好酒来。客到时，果品酒馔只顾将来，不必要问。”李小二道：“官人请甚客？”那人道：“烦你与我去营里请管营、差拨两个来说话。问时，你只说有个官人请说话，商议些事务。专等，专等。”李小二应承了，来到牢城里，先请了差拨，同到管营家里，请了管营，都到酒店里。只见那个官人和管营、差拨两个讲了礼。管营道：“素不相识，动问官人高姓大名。”那人道：“有书在此，少刻便知。且取酒来。”李小二连忙开了酒，一面铺下菜蔬果品酒馔。那人叫讨副劝盘来，把了盏，相让坐了。小二独自一个撺梭也似扶侍不暇。那跟来的人，讨了汤桶，自行B023酒。约计吃过十数杯，再讨了按酒，铺放桌上。只见那人说道：“我自有伴当B023酒。不叫，你休来。我等自要说话。”李小二应了，自来门首叫老婆道：“大姐，这两个人来的不尴尬。”老婆道：“怎么的不尴尬？”小二道：“这两个人语言声音是东京人。初时又不认得管营。向后我将按酒入去，只听得差拨口里讷出一句高太尉三个字来。这人莫不与林教头身上有些干碍？我自在门前理会。你且去阁子背后，听说什么。”老婆道：“你去营中寻林教头来认他一认。”李小二道：“你不省得。林教头是个性急的人。摸不着便要杀人放火。倘或叫的他来看了，正是前日说的什么陆虞候，他肯便罢？做出事来，须连累了我和你。你只去听一听再理会。”老婆道：“说的是。”便入去听了一个时辰，出来说道：“他那三四个交头接耳说话，正不听得说什么。只见那一个军官模样的人，去伴当怀里，取出一帕子物事，逃与管营和差拨。帕子里面的莫不是金银。只听差拨口里说道：‘都在我身上，好歹要结果了他性命。’”正说之间，阁子里叫：“将汤来。”李小二急去里面换汤时，看见管营手里拿着一封书。小二换了汤，添些下饭。又吃了半个时辰，算还了酒钱。管营、差拨先去了。次后，那两个低着头也去了。转背没多时，只见林冲走将入店里来，说道：“小二哥，连日好买卖。”李小二慌忙道：“恩人请坐。小人却待正要寻恩人，有些要紧话说。”有诗为证：","潜为奸计害英雄，一线天教把信通。亏杀有情贤李二，暗中回护有奇功。","当下林冲问道：“什么要紧的事？”小二哥请林冲到里面坐下，说道：“却才有个东京来的尴尬人，在我这里请管营、差拨吃了半日酒。差拨口里讷出高太尉三个字来。小人心下疑，又着浑家听了一个时辰。他却交头接耳说话，都不听得。临了只见差拨口里应道：‘都在我两个身上，好歹要结果了他。’那两个把一包金银，都与管营、差拨。又吃一回酒，各自散了。不知什么样人。小人心下疑，只怕恩人身上有些妨碍。”林冲道：“那人生得什么模样？”李小二道：“五短身材，白净面皮，没什髭须。约有三十余岁。那跟的也不长大，紫棠色面皮。”林冲听了，大惊道：“这三十岁的正是陆虞候。那泼贱贼也敢来这里害我！休要撞着我，只教他骨肉为泥！”李小二道：“只要提防他便了。岂不闻古人言：‘吃饭防噎，走路防跌。’”林站大怒，离了李小二家，先去街上买把解腕尖刀，带在身上。前街后巷，一地里去寻。李小二夫妻两个，捏着两把汗。当晚无事。次日，天明起来，早洗漱罢，带了刀又去沧州城里城外，小街夹巷，团团寻了一日。牢城营里都没动静。林冲又来对李小二道：“今日又无事。”小二道：“恩人，只愿如此。只是自放仔细便了。”林冲自回天王堂，过了一夜。街上寻了三五日，不见消耗，林冲也自心下慢了。到第六日，只见管营叫唤林冲到点视厅上，说道：“你来这里许多时，柴大官人面皮不曾抬举的你。此间东门外十五里，有座大军草场，每月但是纳草纳料的，有些常例钱取觅。原是一个老军看管。如今，我抬举你去替那老军来守天王堂。你在那里B270几贯盘缠。你可和差拨便去那里交割。”林冲应道：“小人便去。”当时离了营中，迳到李小二家，对他夫妻两个说道：“今日管营拨我去大军草场管事，却如何？”李小二道：“这个差使，又好似天王堂。那里收草料时，有些常例钱钞。往常不使钱时，不能勾这差使。”林冲道：“却不害我，倒与我好差使，正不知何意？”李小二道：“恩人休要疑心。只要没事便好了。只是小人家离得远了，过几时那工夫来望恩人。”就时家里安排几杯酒，请林冲吃了。话不絮烦，两个相别了。林冲自来天王堂取了包裹，带了尖刀，拿了条花枪，与差拨一同辞了管营。两个取路投草料场来。正是严冬天气，彤云密布，朔风渐起，却早纷纷扬扬卷下一天大雪来。那雪早下得密了。怎见得好雪？有临江仙词为证：","作阵成团空里下，这回忒杀堪怜，剡溪冻住猷船。玉龙鳞甲舞，江海尽平填，宇宙楼台都压倒，长空飘絮飞绵。三千世界玉相连，冰交河北岸，冻了十余年。","大雪下的正紧，林冲和差拨两个，在路上又没买酒吃处，早来到草料场外。看时，一周遭有些黄土墙，两扇大门，推开看里面时，七八间草房做着仓B271，四下里都是马草堆，中间两座草厅。到那厅里，只见那老军在里面向火。差拨说道：“管营差这个林冲来替你回天王堂看守。你可即使交割。”老军拿了钥匙，引着林冲，分付道：“仓B271内自有官司封记。这几堆草，一堆堆都有数目。”老军都点见了堆数，又引林冲到草厅上。老军收拾行李，临了说道：“火盆锅子碗碟，都借与你。”林冲道：“天王堂内，我也有在那里。你要便拿了去。”老军指壁上挂一个大葫芦说道：“你若买酒吃时，只出草场，投东大路去三二里，便有市井。”老军自和差拨回营里来。只说林冲就床上放了包裹被卧，就坐下生些焰火起来。屋边有一堆柴炭，拿几块来，生在地炉里。仰面看那草屋时，四下里崩坏了，又被朔风吹撼，摇振得动。林冲道：“这屋如何过得一冬？待雪晴了，去城中唤个泥水匠来修理。”向了一回火，觉得身上寒冷。寻思：“却才老军所说，五里路外有那市井，何不去沽些酒来吃？”便去包里取些碎银子，把花枪挑了酒葫芦，将火炭盖了，取毡笠子戴上，拿了钥匙，出来把草厅门拽上。出到大门首，把两扇草场门反拽上锁了。带了钥匙，信步投东。雪地里踏着碎琼乱玉，迤B053背着北风而行。那雪正下得紧。行不上半里多路，看见一所古庙。林冲顶礼道：“神明庇佑，改日来烧钱纸。”又行了一回，望见一簇人家。林冲住脚看时，见篱笆中挑着一个草帚儿在露天里。林冲迳到店里。主人道：“客人那里来？”林冲道：“你认得这个葫芦么？”主人看了道：“这葫芦是草料场老军的。”林冲道：“如何便认的？”店主道：“既是草料场看守大哥，且请少坐。天气寒冷，且酌三杯，权当接风。”店家切一盘熟牛肉，B023一壶热酒，请林冲吃。又自买了些牛肉，又吃了数杯，就又买了一葫芦酒，包了那两块牛肉，留下碎银子，把花枪挑了酒葫芦，怀内揣了牛肉，叫声相扰，便出篱笆门，依旧迎着朔风回来。看那雪到晚越下的紧了。古时有个书生，做了一个词，单题那贫苦的恨雪：","广莫严风刮地，这雪儿下的正好。扯絮挦绵，裁几片大如栲栳。见林间竹屋茅茨，争些儿被他压倒。富室豪家，却言道压瘴犹嫌少。向的是兽炭红炉，穿的是绵衣絮袄。手B07E梅花，唱道国家祥瑞，不念贫民些小。高卧有幽人，吟咏多诗草。","再说林冲踏着那瑞雪，迎着北风，飞也似奔到草场门口，开了锁入内看时，只叫得苦。原来天理昭然，佑护善人义士。因这场大雪，救了林冲的性命。那两间草厅，已被雪压倒了。林冲寻思：“怎地好？”放下花枪、葫芦在雪里，恐怕火盆内有火炭延烧起来。搬开破壁子，探半身入去摸时，火盆内火种，都被雪水浸灭了。林冲把手床上摸时，只拽的一条絮被。林冲钻将出来，见天色黑了。寻思：“又没打火处，怎生安排？”想起：“离了这半里路上，有个古庙，可以安身。我且去那里宿一夜。等到天明，却做理会。”把被卷了，花枪挑着酒葫芦，依旧把门拽上锁了，望那庙里来。入的庙门，再把门掩上，傍边止有一块大石头，掇将过来靠了门。入的里面看时，殿上做着一尊金甲山神。两边一个判官，一个小鬼。侧边推着一堆纸。团团看来，又没邻舍，又无庙主。林冲把枪和酒葫芦放在纸堆上，将那条絮被放开，先取下毡笠子，把身上雪都抖了，把上盖白布衫脱将下来。早有五分湿了。和毡笠放在供桌上。把被扯来盖了半截下身。却把葫芦冷酒提来便吃。就将怀中牛肉下酒。正吃时，只听得外面必必剥剥地爆响。林冲跳起身来，就壁缝里看时，只见草料场里火，刮刮杂杂烧着。看那火时，但见：","一点灵台，五行造化，丙丁在世传流。无明心内，灾祸起沧州。烹铁鼎能成万物。铸金丹还与重楼。思今古，南方离位，荧惑最为头。绿窗B272焰烬；隔花深处，掩映钓鱼舟。鏖兵赤壁，公瑾喜成谋。李晋王醉存馆驿，田单在即墨驱牛。周褒姒骊山一笑，因此戏诸侯。","当时张见草场内火起，四下里烧着，林冲便拿枪，却待开门来救火，只听得前面有人说将话来。林冲就伏在庙听时，是三个人脚步响，且奔庙里来。用手推门，却被林冲靠住了，推也推不开。三人在庙檐下立地看火。数内一个道：“这条计好么？”一个应道：“端的亏管营、差拨两位用心。回到京师，禀过太尉，都保你二位做大官。这番张教头没的推故。”那人道：“林冲今番直吃我们对付了。高衙内这病必然好了。”又一个道：“张教头那厮，三回五次托人情去说：‘你的女婿殁了。’张教头越不肯应承。因此衙内病患看看重了。太尉特使俺两个央  二位干这件事。不想而今完备了。”又一个道：“小人直爬入墙里去，四下草堆上点了十来个火把，待走那里去？”那一个道：“这早晚烧个八分过了。”又听一个道：“便逃得性命时，烧了大军草料场，也得个死罪。”又一个道：“我们回城里去罢。”一个道：“再看一看，拾得他一两块骨头回京府里见太尉和衙内时，也道我们也能会干事。”林冲听那三个人时，一个是差拨，一个是陆虞候，一个是富安。林冲道：“天可怜见林冲”若不是倒了草厅，我准定被这厮们烧死了！”轻轻把石头掇开，挺着花枪，一手拽开庙门，大喝一声：“泼贼那里去！”三个人急要走时，惊得呆了，正走不动。林冲举手，肐察的一枪，先戳倒差拨。陆虞候叫声饶命，吓的慌了手脚，走不动。那富安走不到十来步，被林冲赶上，后心只一枪，又戳倒了。翻身回来，陆虞候却才行的三四步。林冲喝声道：“好贼！你待那里去？”批胸只一提，丢翻在雪地上，把枪搠在地里，用脚踏住胸脯，身边取出那口刀来，便去陆谦脸上阁着，喝道：“泼贼！我自来又和你无什么冤仇，你如何这等害我！正是‘杀人可恕，情理难容。’”陆虞候告道：“不干小人事，太尉差遣，不敢不来。”林冲骂道：“奸贼，我与你自幼相交，今日倒来害我，怎不干你事！且吃我一刀。”把陆谦上身衣服扯开，把尖刀向心窝里只一剜，七窍迸出血来。将心肝提在手里。回头看时，差拨正爬将起来要走。林冲按住喝道：“你这厮原来也恁的歹，且吃我一刀。”又早把头割下来，挑在枪上。回来把富安、陆谦头都割下来。把尖刀插了，将三个人头发结做一处，提入庙里来，都摆在山神面前供桌上，再穿了白布衫，系了胳膊，把毡笠子带上，将葫芦里冷酒都吃尽了。被与葫芦都丢了不要。提了枪，便出庙门投东去。走不到三五里，早见近村人家，都拿着水桶钩子来救火。林冲道：“你们快去救应，我去报官了来。”提着枪，只顾走。那雪越下的猛。但见：","凛凛严凝雾气昏，空中祥瑞降纷纷。须臾四野难分路，顷刻千山不见痕。银世界，玉乾坤，望中隐隐接昆仑。若还下到三更后，彷佛填平玉帝门。","林冲投东去了两个更次，身上单寒，当不过那冷。在雪地里看时，离的草场远了。只见前面疏林深处，树木交杂，远远地数间草屋，被雪压着。破壁缝里透出火光来。林冲迳投那草屋来。推开门，只见那中间坐着一个老庄家，周围坐着四五个小庄家向火。地炉里面焰焰寺烧着柴火。林冲走到面前，叫道：“众位拜揖。小人是牢城营差使人，被雪打湿了衣裳，借此火烘一烘，望乞方便。”庄客道：“你自烘便了，何妨得。”林冲烘着身上湿衣服，略有些干，只见火炭边煨着一个瓮儿，里面透出酒香。林冲便道：“小人身边有些碎银子，望烦回些酒吃。”老庄客道：“我们每夜轮流看米囤，如今四更天气正冷，我们这几个吃，尚且不勾，那得回与你。休要指望。”林冲又道：“胡乱只回三五碗与小人B023寒。”老庄家道：“你那人休缠，休缠！”林冲闻得酒香，越要吃，说道：“没奈何回些罢。”众庄客道：“好意着你烘衣裳向火，便来要酒吃。去便去，不去时，将来吊在这里。”林冲怒道：“这厮们好无道理！”把手中枪看着块焰焰着的火柴头，望老庄家脸上只一挑将起来，又把枪去火炉里只一搅，那老庄家的髭须焰焰的烧着。众庄客都跳将起来。林冲把枪杆乱打。老庄家先走了，庄家们都动惮不得，被林冲赶打一顿，都走了。林冲道：“都去了，老爷快活吃酒。”土坑上却有两个椰瓢，取一个下来，倾那瓮酒来吃了一会。剩了一半，提了枪，出门便走。一步高，一步低，浪浪跄跄，捉脚不住。走不过一里路，被朔风一掉，随着那山涧边倒了，那里挣得起来。凡醉人一倒，便起不得。醉倒在雪地上。却说众庄客引了二十余人，拖枪拽棒，都奔草屋下看时，不见了林冲。却寻着踪迹赶将来。只见倒在雪地里。庄客齐道：“你却倒在这里。”花枪丢在一边。众庄客一发上手，就地拿起林冲来，将一条索缚了。趁五更时分，把林冲解投那个去处来。不是别处，有分教：蓼儿洼前后摆数千只战舰艨艟，水浒寨中左右列百十个英雄好汉。搅扰得道君皇帝盘龙椅上魂惊，丹凤楼中胆裂。正是：说时杀气侵人冷，讲处悲风透骨寒。毕竟看林冲被庄客解投甚处来？且听下回分解。"],"cpLength":6184},"xsh-03":{"chapterId":"xsh-03","bookId":"xsh","fileIndex":2,"number":3,"title":"第三卷　卖油郎独占花魁","paragraphs":["年少争夸风月，场中波浪偏多。有钱无貌意难和，有貌无钱不可。就是有钱有貌，还须著意揣摩。知情识俏哥哥，此道谁人赛我。 这首词名为《西江月》，是风月机关中撮要之论。常言道：“妓爱俏，妈爱钞。”所以子弟行中，有了潘安般貌，邓通般钱，自然上和下睦，做得烟花寨内的大王，鸳鸯会上的主盟。然虽如此，还有个两字经儿，叫做帮衬。帮者，如鞋之有帮；衬者，如衣之有衬。但凡做小娘的，有一分所长，得人衬贴，就当十分。若有短处，曲意替他遮护，更兼低声下气，送暖俞寒，逢其所喜，避其所讳，以情度情，岂有不爱之理？言叫做帮衬。风月场中，只有会帮衬的最讨便宜，无貌而有貌，无钱而有钱。假如郑元和在卑田院做了乞儿，此时囊箧俱空，容颜非旧，李亚仙于雪天遇之，便动了一个恻隐之心，将绣襦包里，美食供养，与他做了夫妻。这岂是爱他之钱，恋他之貌？只为郑元和识趣知情，善于帮衬，所以亚仙心中舍他不得。你只看亚仙病中想马板肠汤吃，郑元和就把五花马杀了，取肠煮汤奉之。只这一节上，亚仙如何不念其情？后来郑元和中了状元，李亚仙封为国夫人。》打出万年策，卑田院变做了白玉楼。一床锦被遮盖，风月场中反为美谈。这是： 　　运退黄金失色，时来铁也生光。","话说大宋自太祖开基，太宗嗣位，历传真、仁、神、哲，共是七代帝王，都则偃武修文，民安国泰。到了徽宗道君皇帝，信任蔡京、高俅、杨戬、朱之徒，大兴苑囿，专务游乐，不以朝政为事。以致万民嗟怨，金虏乘之而起，把花锦般一个世界，弄得七零八落。直至二帝蒙尘，高宗泥马渡江，偏安一隅，天下分为南北，方得休息。其中数十年，百姓受了多少苦楚。正是：","甲马丛中立命，刀枪队里为家。","杀戮如同戏耍，抢夺便是生涯。 内中单表一人，乃汴梁城外安乐村居住，姓莘名善，浑家阮氏。夫妻两口，开个六陈铺儿。虽则粜米为生，一应麦豆茶酒油盐杂货，无所不备，家道颇颇得过。年过四旬，止生一女，小名叫做瑶琴。自小生得清秀，更且资性聪明。七岁上，送在村学中读书，日诵千言。十岁时，便能吟诗作赋，曾有一绝，为人传诵。诗云：","朱帘寂寂下金钩，香鸭沉沉冷画楼。","移枕怕惊鸳并宿，挑灯偏惜蕊双头。 到十二岁，琴棋书画，无所不通。若题起女工一事，飞针走线，出人意表。此乃天生令俐，非教习之所能也。莘善因为自家无子，要寻个养女婿来家靠老。只因女儿灵巧多能，难乎其配，所以求亲者颇多，都不曾许。不幸遇了金虏猖獗，把汴梁城围困，四方勤王之师虽多，宰相主了和议，不许厮杀，以致虏势愈甚，打破了京城，劫迁了二帝。那时城外百姓，一个个亡魂丧胆，携老扶幼，弃家逃命。却说莘善领著浑家阮氏和十二岁的女儿，同一般逃难的，背著包里，结队而走。","忙忙如丧家之犬，急急如漏网之鱼。担渴担饥担劳苦，此行谁是家乡？叫天叫地叫祖宗，惟愿不逢鞑虏。正是：宁为太平犬，莫作乱离人！正行之间，谁想鞑子到不曾遇见，却逢著一阵败残的官兵。他看见许多逃难的百姓，多背得有包里，假意呐喊道：“鞑子来了！”沿路放起一把火来。此时天色将晚，吓得众百姓落荒乱窜，你我不相顾。他就乘机抢掠。若不肯与他，就杀害了。这是乱中生乱，苦上加苦。却说莘氏瑶琴被乱军冲突，跌了一交，爬起来，不见了爹娘，不敢叫唤，躲在道傍古墓之中过了一夜。到天明，出外看时，但见满目风沙，死尸路。昨日同时避难之人，都不知所往。瑶琴思念父母，痛哭不已。欲待寻访，又不认得路径，只得望南而行。哭一步，捱一步，约莫走了二里之程。心上又苦，腹中又饥，望见土房一所，想必其中有人，欲待求乞些汤饮。及至向前，却是破败的空屋，人口俱逃难去了。瑶琴坐于土墙之下，哀哀而哭。","自古道：“无巧不成话。”恰好有一人从墙下而过。那人姓卜名乔，正是莘善的近邻，平昔是个游手游食、不守本分，掼吃白食、用白钱的主儿，人都称他是卜大郎。也是被官军冲散了同夥，今日独自而行。听得啼哭之声，慌忙来看。瑶琴自小相认，今日患难之际，举目无亲，见了近邻，分明见了亲人一般，即忙收泪，起身相见，问道：“卜大叔，可曾见我爹妈么？”卜乔心中暗想：“昨日被官军抢去包里，正没盘缠。天生这碗衣饭，送来与我，正是奇货可居。”便扯个谎道：“你爹和妈，寻你不见，好生痛苦，如今前面去了，吩咐我道：‘倘或见我女儿，千万带了他来，送还了我。’许我厚谢。”瑶琴虽是聪明，正当无可奈何之际，君子可欺以其方，遂全然不疑，随著卜乔便走，正是：情知不是伴，事急且相随。","卜乔将随身带的乾粮，把些与他吃了，吩咐道：“你爹妈连夜走的。若路上不能相遇，直要过江到建康府，方可相会。一路上同行，我权把你当女儿，你权叫我做爹。不然，只道我收留迷失子女，不当稳便。”瑶琴依允。从此陆路同步，水路同舟，爹女相称。到了建康府，路上又闻得金兀术四太子，引兵渡江，眼见得建康不得宁息。又闻得康王即位，已在杭州驻跸，改名临安，遂趁船到润州。过了苏、常、嘉、湖，直到临安地面，暂且饭店中居住，也亏卜乔，自汴京至临安，三千余里，带那莘瑶琴下来，身边藏下些散碎银两，都用尽了，连身上外盖衣服，脱下准了店钱，止剩得莘瑶琴一件活货，欲行出脱。访得西湖上烟花王九妈家要讨养女，遂引九妈到店中，看货还钱。九妈见瑶琴生得标致，讲了财礼五十两。卜乔兑足了银子，将瑶琴送到王家。原来卜乔有智，在王九妈前，只说：“瑶琴是我亲生之女，不幸到你门户人家，须是款款的教训，他自然从顺，不要性急。”在瑶琴面前，又说：“九妈是我至亲，权时把你寄顿他家，待我从容访知你爹妈下落，再来领你。”以此瑶琴欣然而去。","可怜绝世聪明女，堕落烟花罗网中。王九妈新讨了瑶琴，将他浑身衣服，换个新鲜，藏于曲楼深处，终日好茶好饭，去将息他，好言好语，去温暖他。瑶琴既来之，则安之。住了几日，不见卜乔回信，思量爹妈，噙著两行珠泪，问九妈道：“卜大叔怎不来看我？”九妈道：“哪个卜大叔？”瑶琴道：“便是引我到你家的那个卜大郎。”九妈道：“他说是你的亲爹。”瑶琴道：“他姓卜，我姓莘。”遂把汴梁逃难，失散了爹妈，中迂遇见了卜乔，引到临安，并卜乔哄他的说话，细述一遍。九妈道：“原来恁地，你是个孤身女儿，无脚蟹，我索性与你说明罢；那姓卜的把你卖在我家，得银五十两去了。我们是门户人家，靠著粉头过活。家中虽有三四个养女，并没个出色的。爱你生得齐整，把做个亲女儿相待。待你长成之时，包你穿好吃好，一生受用。”瑶琴听说，方知被卜乔所骗，放声大哭。九妈劝解，良久方止。自此九妈将瑶琴改做王美，一家都称为美娘，教他吃吹弹歌舞，无不尽善。长成一十四岁，娇艳非常。临安城中，这些当豪公子慕其容貌，都备著厚礼求见。也有爱清标的，闻得他写作俱高，求诗求字的，日不离门。弄出天大的名声出来，不叫他美娘，叫他做花魁娘子。西湖上子弟编出一支《挂枝儿》，单道那花魁娘子的好处：","小娘中，谁似得王美儿的标致，又会写，又会画，又会做诗，吹弹歌舞都余事。常把西湖比西子，就是西子比他也还不如。哪个有福的汤著他身儿，也情愿一个死。只因王美有了个盛名，十四岁上，就有人来讲梳弄。一来王美不肯，二来王九妈把女儿做金子看成，见他心中不允，分明奉了一道圣旨，并不敢违拗。又过了一年，王美年方十五。原来门户中梳弄，也有个规矩。十三岁太早，谓之试花。皆因鸨儿爱财，不顾痛苦；那子弟也只专个虚名，不得十分畅快取乐。十四岁谓之开花。此时天癸已至，男施女受，也算当时了。到十五谓之摘花。在平常人家，还算年小，惟有门户人家，以为过时。王美此时未曾梳弄，西湖上子弟，又编出一支》来： 王美儿，似木瓜，空好看，十五岁，还不曾与人汤一汤。有名无实成何干。便不是石女，也是二行子的娘。若还有个好好的，羞羞也，如何熬得这些时痒。","王九妈听得这些风声，怕坏了门面，来劝女儿接客。王美执意不肯，说道：“要我会客时，除非见了亲生爹妈。他肯做主时，方才使得。”王九妈心里又恼他，又不里得难为他。捱了好些时。偶然有个金二员外，大富之家，情愿出三百两银子，梳弄美娘。九妈得了这主大财，心生一计，与金二员外商议：若要他成就，除非如此如此。金二员外意会了。其日八月十五日，只说请王美湖看潮，请至舟中。三四个帮闲，俱是会中之人，猜拳行令，做好做歉，将美娘灌得烂醉如泥。扶到王九妈家楼中，卧于床上，不省人事。此时天气和暖，又没几层衣服。妈儿亲手伏侍，剥得他赤条条，任凭金二员外行事。美娘梦中觉痛醒将转来，已被金二员外耍得够了，欲待挣扎，争奈手足俱软，繇他轻薄了一回。直待绿暗红飞，方始雨收云散。正是：","雨中花蕊方开罢，镜里娥眉不似前。","五鼓时，美娘酒醒，已知鸨儿用计，破了身子。自怜红频命薄，遭此强横，起来解手，穿了衣服，自在床边一个斑竹榻上，朝著里壁睡了，暗暗垂泪。金二员外来亲近他时，被他劈头劈脸，抓有几个血痕。金二员外好生没趣，捱得天明，对妈儿说声：“我去也。”妈要留他时，已自出门去了。从来梳弄的子弟，早起时，妈儿进房贺喜，行户中都来称贺，还要吃几日喜酒。那子弟多则住一二月，最少也住半月二十日。只有金二员外侵早出门，是从来未有之事。王九妈连叫诧异，披衣起身上楼，只见美娘卧于榻上，满眼流泪。九妈要哄他上行，连声招许多不是。美娘只不开口。九妈只得下楼去了。美娘哭了一日，茶饭不沾。从此托病，不肯下楼，连客也不肯会面了。九妈心下焦燥，欲待把他凌虐，又恐他烈性不从，反冷了他的心肠；欲待繇他，本是要他赚钱，若不接客时，就养到一百岁也没用。踌躇数日，无计可施。忽然想起，有个结义妹子，叫做刘四妈，时常往来。他能言快语，与美娘甚说得著，何不接取他来，下个说词？若得他回心转意，大大的烧个利市。当下叫保儿去请刘四妈到前楼坐下，诉以衷情。刘四妈道：“老身是个女随何，雌陆贾，说得罗汉思情，嫦娥想嫁。这件事都在老身身上。”九妈道：“若得如此，做姐的情愿与你磕头。你多吃杯茶去，省得说话时口乾。”刘四妈道：“老身天生这副海口，便说到明日，还不乾哩。”刘四妈吃了几杯茶，转到后楼，只见楼门紧闭。刘四妈轻轻的叩了一下，叫声：“侄女！”美娘听得是四妈声音，便来开门。两下相见了，四妈靠桌朝下而坐，美娘傍坐相陪。四妈看他桌上铺著一幅细绢，才画得个美人的脸儿，还未曾著色。四妈称赞道：“画得好，真是巧手！九阿姐不知怎生样造化，偏生遇著你这一个伶俐女儿，又好人物，又好技艺，就是堆上几千两黄金，满临安走遍，可寻山个对儿么？”美娘道：“休得见笑！今日甚风吹得姨娘到来？”刘四妈道：“老身时常要来看你，只为家务在身，不得空闲。闻得你恭喜梳弄了，今日偷空而来，特特与九阿姐叫喜。”美儿听得提起“梳弄”二字，满脸通红，低著头不来答应。刘四妈知他害羞，便把椅儿掇上一步，将美娘的手儿牵著，叫声：“我儿，做小娘的，不是个软壳鸡蛋，怎的这般嫩得紧？似你恁地怕羞，如何赚得大主银子？”美娘道：“我要银子做甚？”四妈道：“我儿，你便不要银子，做娘的，看得你长大成人，难道不要出本？自古道，靠山吃山，靠水吃水。九阿姐家有几个粉头，哪一个赶得上你的脚跟来？一园瓜，只看得你是个瓜种，九阿姐待你也不比其他。你是聪明伶俐的人，也须识些轻重。闻得你自梳弄之后，一个客也不肯相接。是甚么意儿？都像你的意时，一家人口，似蚕一般，哪个把桑叶喂他？做娘的抬举你一分，你也要与他争口气儿，莫要反讨众丫头们批点。”美娘道：“繇他批点，怕怎的！”刘四妈道：“阿呀！批点是个小事，你可晓得门户中的行径么？”美娘道：“行径便怎的？”刘四妈道：“我们门户人家，吃著女儿，用著女儿。侥幸讨得一个像样的，分明是大户人家置了一所良田美产。年纪幼小时，巴不得风吹得大；到得梳弄过后，便是田产成熟，日日指望花利到手受用。前门迎新，后门送旧，张郎送米，李郎送柴，往来热闹，才是个出名的姊妹行家。”美娘道：“羞答答，我不做这样事！”刘四妈掩著口，格的笑了一声，道：“不做这样事，可是繇得你的？一家之中，有妈妈做主。做小娘的若不依他教训，动不动一顿皮鞭，打得你不生不死。那时不怕你不走他的路儿。九阿姐一向不难为你，只可惜你聪明标致，从小娇美的，要惜你的廉耻，存你的体面。方才告诉我许多话，说你不识好歹，放著鹅毛不知轻，顶著磨子不知重，心下好生不，教老身来劝你。你若执意不从，惹他性起，一时翻过脸来，骂一顿，打一顿，你待走上天去！凡事只怕个起头若打破了头时，朝一顿，暮一顿，那时熬这些痛苦不过，只得接客，却不把千金声价弄得低微了？还要被姊妹中笑话。依我说，吊桶已自落在他井里，挣不起了。不如千欢万喜，倒在娘的怀里，落得自己快活。”","美娘道：“奴是好人家儿女，误落风尘，倘得姨娘主张从良，胜造九级浮图。若要我倚门献笑，送旧迎新，宁甘一死，决不情愿。”刘四妈道：“我儿，从良是个有志气的事，怎么说道不该！只是从良也有几等不同。”美娘道：“从良有甚不同之处？”","刘四妈道：“有个真从良，有个假从良，有个苦从良，有个乐从良，有个趁好的从良，有个没奈何的从良，有个了从良，有个不了的从良。我儿，耐心听我分说：“如何叫做真从良？大凡才子必须佳人，佳人必须才子，方成佳配。然而好事多磨，往往求之不得。幸然两下相逢，你贪我爱，割舍不下。一个愿讨，一个愿嫁。好像捉对的蚕蛾，死也不放。这个谓之真从良。怎么叫做假从良？有等子弟爱著小娘，小娘却不爱那子弟。晓得小娘心肠不对他，偏要娶他回去。拚著一主大钱，动了妈儿的火，不怕小娘不肯。勉强进门，心中不顺，故意不守家规，小则撒泼放肆，大则公然偷汉。人家容留不得，多则一年，少则半载，依旧放他出来，为娼接客。把从良二字，只当个赚钱的题目。这个谓之假从良。","“如何叫做苦从良？”一般样子弟爱小娘，小娘不爱那子弟，却被他以势凌之。妈儿惧祸，已自许了。做小娘的，身不繇主，含泪而行。一入侯门，如海之深，家法又严，抬头不得。半妾半婢，忍死度日。这个谓之苦从良。如何叫做乐从良？做小娘的，正当择人之际，偶然相交个子弟，见他情性温和，家道富足，又且大娘子乐善，无男无女，指望他日过门，与他生育，就有主母之分。以此嫁他，图个日前安逸，日后出身，这个谓之乐从良。","“如何叫做趁好的从良？做小娘的，风花雪月，受用已够，趁这盛名之下，求之者众，任我拣择个十分满意的嫁他，急流勇退，及早回头，不致受人怠慢。这个谓之趁好的从良。如何叫做没奈何的从良？做小娘的，原无从良之意，或因官司逼迫，或因强棋欺瞒，又或因债负太多，将来赔偿不起，别口气，不论好歹，得嫁便嫁，买静求安，藏身之法，这谓之没奈何的从良。“如何叫做了从良？小娘半老之际，风波历尽，刚好遇个老成的孤老，两下志同道合，收绳卷索，白头到老。这个谓之了从良。如何叫做不了的从良？一般你贪我爱，火热的跟他，却是一时之兴，没有个长算。或者尊长不容，或者大娘妒忌，闹了几场，发回妈家，追取原价；又有个家道凋零，养他不活，苦守不过，依旧出来赶趁，这谓之不了的从良。”","美娘道：“如今奴家要从良，还是怎地好？”刘田无道：“我儿，老身教你个万全之策。美娘道：“若蒙教导，死不忘恩。”刘四妈道：“从良一事，入门为净。况且你身子己被人捉弄过了，就是今夜嫁人，叫不得个黄花女儿。千错万错，不该落于此地。这就是你命中所招了。做娘的费了一片心机，若不帮他几年，趁过千把银子，怎肯放你出门？还有一件，你便要从良，也须拣个好主儿。这些臭嘴臭脸的，难道就跟他不成？你如今一个客也不接，晓得哪个该从，哪个不该从？假如你执意不肯接客，做娘的没奈何，寻个肯出钱的主儿，卖你去做妾，这也叫做从良。那主儿或是年老的，或是貌丑的，或是一字不识的村牛，你却不肮脏了一世！比著把你撂在水里，还有扑通的一声响，讨得旁人叫一声可惜。依著老身愚见，还是俯从人愿，凭著做娘的接客。似你恁般才貌，等闲的料也不敢相扳，无非是王孙公子，贵客豪门，也不辱莫了你。一来风花雪月，趁著年少受用，二来作成妈儿起个家事，三来使自己也积趱些私房，免得日后求人。过了十年五载，遇个知心著意的，说得来，话得著，那时老身与你做媒，好模好样的嫁去，做娘的也放得你下了，可不两得其便？”美娘听说，微笑而不言。刘四妈已知美娘心中活动了，便道：“老身句句是好话，你依著老身的话时，后来还当感激我哩。”说罢起身。王九妈立在楼门之外，一句句都听得的。美娘送刘四妈出房门，劈面撞著了九妈，满面羞惭，缩身进去。王九妈随著刘四妈，再到前楼坐下。刘四妈道：“侄女十分执意，被老身右说左说，一块硬铁看看熔做热汁。你如今快快寻个复帐的主儿，他必然肯就。那时做妹子的再来贺喜。”王九妈连连称谢。是日备饭相待，尽醉而别。后来西湖上子弟们又有支》，单说那刘四妈说词一节： 刘四妈，你的嘴舌儿好不利害！便是女随何，雌陆贾，不信有这大才。说著长，道著短，全没些破败。就是醉梦中，被你说得醒；就是聪明的，被你说得呆，好个烈性的姑姑，也被你说得他心地改。","再说王美娘自听了刘四妈一席话儿，思之有理。以后有客求见，欣然相接。复帐之后，宾客如市。捱三顶五，不得空闲，声价愈重。每一晚白银十两，兀自你争我夺。王九妈赚了若干钱钞，欢喜无限。美娘也留心畏拣个知心著意的，急切难得。正是：","易求无价宝，难得有情郎。 话分两头。却说临安城清波门外，有个开油店的朱十老，三年前过继一个小厮，也是汴京逃难来的，姓秦名重，母亲早丧，父亲秦良，十三岁上将他卖了，自己在上天竺去做香火。朱十老因年老无嗣，又新死了妈妈，把秦重做亲子看成，改名朱重，在店中学做卖油生理。初时父子坐店甚好，后因十老得了腰痛的病，十眠九坐，劳碌不得，另招个伙计，叫做邢权，在店相帮。 光阴似箭，不觉四年有余。朱重长成一十七岁，生得一表人才。虽然已冠，尚未娶妻。那朱十老家有个侍女。叫做兰花，年已二十之外，存心看上了朱小官人，几遍的倒下钩子去勾搭他。谁知朱重是个老实人，又且兰花龌龊丑陋，朱重也看不上眼，以此落花有意，流水无情。那兰花见勾搭朱小官人不上，别寻主顾，就去勾搭那伙计邢权。邢权是望四之人，没有老婆，一拍就上。两个暗地偷情，不止一次，反怪朱小官人碍眼，思量寻事赶他出门。邢权与兰花两个里应外合，使心设计。兰花便在朱十老面前，假意撇清说；“小官人几番调戏，好不老实！”朱十老平时与兰花也有一手，未免有拈酸之意。邢权又将店中卖下的银子藏过，在朱十老面前说道：“朱小官在外赌博，不长进，柜里银子几次短少，都是他偷去了。”初次朱十老还不信，接连几次，朱十老年老糊涂，没有主意，就唤朱重过来，责骂了一场。","朱重是个聪明的孩子，已知邢权与兰花的计较，欲待分辨，若起是非不小，万一老者不听，枉做恶人。心生一计，对朱十老说道：“店中生意淡薄，不消得二人。如今让邢主管坐店，孩儿情愿挑担子出去卖油。卖得多少，每日纳还，可不是两重生意？”朱十老心下也有许可之意，又被邢权说道：“他不是要挑担出去，几年上偷银子做私房，身边积趱有余了，又怪你不与他定亲，心下怨怅，不愿在此相帮，要讨个出场，自去娶老婆，做人家去。”朱十老叹口气道：“我把他做亲儿看成，他却如此歹意！皇天不佑！罢，罢，不是自身骨血，到底黏连不上，繇去罢！”遂将三两银子把与朱重，打发出门。寒夏衣服和被窝都教他拿去。这也是朱十老好处。朱重料他不肯收留，拜了四拜，大哭而别。正是：","孝己杀身因谤语，申生丧命为谗言。","亲生儿子犹如此，何怪螟蛉受枉冤。","原来秦良上天竺做香火，不曾对儿子说知。朱重出了朱十老之门，在众安桥下赁了一间小小房儿，放下被窝等件，买巨镇儿镇了门，便往长街短巷，访求父亲。连走几日，全没消息。没奈何，只得放下。在朱十老家四年，赤心忠良，并无一毫私蓄，只有临行时打发这三两银子，不够本钱，做什么生意好？左思右量，只有油行买卖是热间。这些油坊多曾与他识熟，还去挑个卖油担子，是个稳足的道路。当下置办了油担家伙，剩下的银两，都交付与油坊取油。那油坊里认得朱小官是个老实好人，况且小小年纪，当初坐店，今朝挑担上街，都因邢伙计挑拨他出来，心中甚是不平。有心扶持他，只拣窨清的上好净油与他，签子上又明让他些。朱重得了这些便宜，自己转卖与人，也放些宽，所以他的油比别人分外容易出脱。每日所赚的利息，又且俭吃俭用，积下东西来，置办些日用家业，及身上衣服之类，并无妄废。心中只有一件事未了，牵挂著父亲，思想：“向来叫做朱重，谁知我是姓秦！倘或父亲来寻访之时，也没有个因由。”遂复姓为秦。说话的，假如上一等人，有前程的，要复本姓，或具札子奏过朝廷，或关白礼部、太学、国学等衙门，将册籍改正，众所共知。一个卖油的，复姓之时，谁人晓得？他有个道理，把盛油的桶儿，一面大大写个“秦”字，一面写“汴梁”二字，将油桶做个标识，使人一览而知。以此临安市上，晓得他本姓，都呼他为秦卖油。","时值二月天气，不暖不寒，秦重闻知昭庆寺僧人，要起个九昼夜功德，用油必多，遂挑了油担来寺中卖油。那此和尚们也闻知秦卖油之名，他的油比别人又好又贱，单单作成他。所以一连这九日，秦重只在昭庆寺走动。正是：","刻薄不钱，忠厚不折本。","这一日是第九日了。秦重在寺出脱了油，挑了空担出寺。其日天气晴明，游人如蚁。秦重绕河而行，遥望十景塘桃红柳绿，湖内画船箫鼓，往来游玩，观之不足，玩之有余。走了一回，身子困倦，转到昭庆寺右边，望个宽处，将担子放下，坐在一块石上歇脚。近侧有个人家，面湖而住，金漆篱门，里面朱栏内，一丛细竹。未知堂室何如，先见门庭清整。只见里面三四个戴巾的从内而出，一个女娘后面相送。到了门首，两下把手一拱，说声请了，那女娘竟进去了。秦重定睛观之，此女容频娇丽，体态轻盈，目所未睹，准准的呆子半晌，身子都酥麻了。他原是个老实小官，不知有烟花行径，心中疑惑，正不知是什么人家。方正疑思之际，只见门内又走出个中年的妈妈，同著一个垂发的丫头，倚门闲看。那妈妈一眼瞧著油担，便道：“阿呀！，方才要去买油，正好有油担子在这里，何不与他买些？”那丫鬟取了油瓶也来，走到油担子边，叫声：“卖油的！”秦重方才知觉，回言道：“没有油了！妈妈要用油时，明日送来。”那丫鬟也认得几个字，看见油桶上写个“秦”字，就对妈妈道：“那卖油的姓秦。”妈妈也听得人闲讲，有个秦卖油，做生意甚是忠厚，遂吩咐秦重道：“我家每日要油用，你肯挑来时，与你个主顾。”秦重道：“承妈妈作成，不敢有误。”那妈妈与丫鬟进去了。秦重心中想道：“这妈妈不知是那女娘的甚么人？我每日到他家卖油，莫说赚他利息，图个饱看那女良一回，也是前生福分。”正欲挑担起身，只见两个轿夫，抬著一顶青绢幔的轿子，后边跟著两小厮，飞也似跑来，到了其家门首，歇下轿子。那小厮走进里面去了。秦重道：“却又作怪！看他接甚么人？”少顷之间，只见两个丫鬟，一个捧著猩红的毡包，一个拿著湘妃竹攒花的拜匣，都交付与轿夫，放在轿座之下。那两个小厮手中，一个抱著琴囊，一个捧著几个手卷，腕上挂碧玉箫一枝，跟著起初的女娘出来。女娘上了轿，轿夫抬起望旧路而去；丫鬟小厮，俱随轿步行。秦重又得亲炙一番，心中愈加疑惑，挑了油担子，怏怏的去。","不过几步，只见临河有一个酒馆。秦重每常不吃酒，今日见了这女娘，心下又欢喜，又气闷；将担子放下，走进酒馆，拣个小座头坐下。酒保问道：“客人还是请客，还是独酌？”秦重道：“那边金漆篱门内是什么人家？”酒保道：“这是齐衙内的花园，如今王九妈住下。”秦重道：“方才看见有个小娘子上轿，是什么人？”酒保道：“这是有名的粉头，叫做王美娘，人都称为花魁娘子。他原是汴京人，流落在此。吹弹歌舞，琴棋书画，件件皆精。来往的都是大头儿，要十两放光，才宿一夜哩，可知小可的也近他不得。当初住在涌金门外，因楼房狭窄，齐舍人与他相厚，半载之前，把这花园借与他住。”秦重听得说是汴京人，触了个乡里之念，心中更有一倍光景。吃了数杯，还了酒钱，挑了担子，一路走，一路的肚中打稿道：“世间有这样美貌的女子，落于娼家，岂不可惜！”又自家暗笑道：“若不落于娼家，我卖油的怎生得见！”又想一回，越发痴起来了，道：“人生一世，草生一秋。若得这等美人搂抱了睡一夜，死也甘心。”又想一回道：“呸！我终日挑这油担子，不过日进分文，怎么想这等非分之事！正是癞虾蟆想著天鹅肉吃，如何到口！”又想一回道：“他相交的，都是公子王孙，我卖油的，纵有了银子，料他也不肯接我。”又想一回道：“我闻得做老鸨的，专要钱钞。就是个乞儿，有了银子，他也就肯接了，何况我做生意的，青青白白之人？若有了银子，怕他不接！只是哪里来这几两银子？”一路上胡思乱想，自言自语。你道天地间有这等痴人，一个小经纪的，本钱只有三两，却要把十两银子去嫖那名妓，可不是个春梦！自古道：“有志者事竟成。”被他千思万想，想出一个计策来。他道：“从明日为始，逐日将本钱扣出，余下的积趱上去。一日积得一分，一年也有三两六钱之数，只消三年，这事便成了；若一日积得二分，只消得得年半；若再多得些，一年也差不多了。”想来想去，不觉走到家里，开锁进门。只因一路上想著许多闲事，回来看了自家的睡铺，惨然无欢，连夜饭也不要吃，便上了床。这一夜翻来覆去，牵挂著美人，哪里睡得著。 　　只因月貌花容，引起心猿意马。","捱到天明，爬起来，就装了油担，煮早饭吃了，匆匆挑了王妈妈家去。进了门却不敢直入，舒著头，往里面张望，王妈妈恰才买菜。秦重识得声音，叫声：“王妈妈。”九妈往外一张，见是秦卖油，笑道：“好忠厚人，困然不失信。”便叫他挑担进，来称了一瓶，约有五斤多重。公道还钱，秦重井不争论。王九妈甚是欢喜，道：“这瓶油只勾我家两日用；但隔一日，你便送来，我不往别处去买了。”秦重应诺，挑担而出，只恨不曾遇见花魁娘子：“且喜扳下主顾，少不得一次不见，二次见，二次不见，二次见。只是一件，特为王九妈一家挑这许多路来，不是做生意的勾当。这昭庆寺是顺路，今日寺中虽然不做功德，难道寻常不用油的？我且挑担去问他。若扳得各房头做个主顾，只消走钱塘门这一路，那一担油尽勾出脱了。”秦重挑担到寺内问时，原来各房和尚也正想著秦卖油。来得正好，多少不等，各各买他的油。秦重与各房约定，也是间一日便送油来用。这一日是个双日。自此日为始，但是单日，秦重别街道上做买卖；但是双日，就走钱塘门这一路。一出钱塘门，先到王九妈家里，以卖油为名，去看花魁娘子。有一日会见，也有一日不会见。不见时费了一场思想，便见时也只添了一层思想。正是：","天长地欠有时尽，此恨此情无尽期。","再说秦重到了王九妈家多次，家中大大小小，没一个不认得是秦卖油。时光迅速，不觉一年有余。日大日小，只拣足色细丝，或积三分，或积二分，再少也积下一分，凑得几钱，又打换大块头。日积月累，有了一大包银子，零星凑集，连自己也不知多少。","其日是单日，又值大雨，秦重不出去做买卖，积了这一大包银子，心中也自喜欢：“趁今日空闲，我把他上一上天平，见个数目。”打个油伞，走到对门倾银铺里，借天平兑银。那银匠好不轻薄，想著：“卖油的多少银子，要架天平？只把个五两头等子与他，还怕用不著头纽哩。”秦重把银包子解开，都是散碎银两。大凡成锭的见少，散碎的就见多。银匠是小辈，眼孔极浅，见了许多银子，别是一番面目，想道：“人不可貌相，海水不可斗量。”慌忙架起天平，搬出若大若小许多法马。秦重尽包而兑，一厘不多，一厘不少，刚刚一十六两之数，上秤便是一斤。秦重心下想道：“除去了三两本钱，余下的做一夜花柳之费，还是有余。”又想道：“这样散碎银子，怎好出手！拿出来也被人看低了！见成倾银店中方便，何不倾成锭儿，还觉冠冕。”当下兑足十两，倾成一个足色大锭，再把一两八钱，倾成水丝一小锭。剩下四两二钱之数，拈一小块，还了火钱，又将几钱银子，置下镶鞋净袜，新褶了一顶万字头巾。回到家中，把衣服浆洗得乾乾净净，买几根安息香，薰了又薰。拣个晴明好日，侵早打扮起来。","虽非富贵豪华客，也是风流好后生。","秦重打扮得齐齐整整，取银两藏于袖中，把房门锁了，一迳望王九妈家而来。那一时好不高兴。及至到了门首，愧心复萌，想道：“时常挑了担子在他家卖油，今日忽地去做嫖客，如何开口？”正在踌躇之际，只听得呀的一声门响，王九妈走将出来，见了秦重，便道：“秦小官今日怎的不做生意，打扮得恁般济楚，往哪里去贵干？”","事到其间，秦重只得老著脸，上前作揖。妈妈也不免还礼。秦重道：“小可并无别事，专来拜望妈妈。”那鸨儿是老积年，见貌辨色，见秦重恁般装束，又说拜望，“一定是看上了我家哪个丫头，要嫖一夜，或是会一个房。虽然不是个大势主菩萨，搭在篮里便是菜，捉在篮里便是蟹，赚他钱把银子买葱菜，也是好的。”便满脸堆下笑来，道：“秦小官拜望老身，必有好处。”秦重道：“小可有句不识进退的言语，只是不好昁齿。”王九妈道：“但说何妨，且请到里面客座里细讲。”秦重为卖油虽曾到王家整百次，这客座里交椅，还不曾与他屁股做个相识，今日是个会面之始。 王九妈到了客座，不免分宾而，坐对昅内里唤茶。少顷，丫鬟托出茶来，看时，却是秦卖油。正不知什么缘故，妈妈恁般相待，格格低了头只是笑。王九妈看见，喝道：“有甚好笑！对客全没些规矩！”丫鬟止住笑，放了茶杯自去。王九妈方才开言问道：“秦小官有甚话，要对老身说？”秦重道：“没有别话，要在妈妈宅上请一位姐姐吃一杯酒儿。”九妈道：“难道吃寡酒？一定要嫖了。你是个老实人，几时动这风流之兴？”秦重道：“小可的积诚，也非止一日。”九妈道：“我家这几个姐姐，都是你认得的，不知你中意哪一位？”秦重道：“别个都不要，单单要与花魁娘子相处一宵。”九妈只道取笑他，就变了脸道：“你出言无度！莫非奚落老娘么？”秦重道：“小可是个老实人，岂有虚情？”九妈道：“粪桶也有两个耳朵，你岂不晓得我家美儿的身价！倒了你卖油的灶，还不够半夜歇钱哩，不如将就拣一个适兴罢。”秦重把颈一缩，舌头一伸，道：“恁的好卖弄！不敢动问，你家花魁娘子一夜歇钱要几千两？”九妈见他说耍话，却又回嗔作喜，带笑而言道：“哪要许多！只要得十两敲丝。其他东道杂费，不在其内。”秦重道：“原来如此，不为大事。”袖中摸出这秃秃里一大锭放光细丝银子，递与鸨儿道：“这一锭十两重，足色足数，请妈妈收。”又摸出一小锭来，也递与鸨儿，又道：“这一小锭，重有二两，相烦备个小东。望妈妈成就小可这件好事，生死不忘，日后再有孝顺。”九妈见了这锭大银，已自不忍释手，又恐怕一时高兴，日后没了本钱，心中懊悔，也要尽他一句才好。”便道：“这十两银子，做经纪的人，积趱不易，还要三思而行。”秦重道：“小可主意已定，不要你老人家费心。”","九妈把这两锭银子收于袖中，道：“是便是了，还有许多烦难哩。”秦重道：“妈妈是一家之主，有甚烦难？”九妈道：“我家美儿，往来的都是王孙公子，富室豪家，真个是‘谈笑有鸿儒，往来无白丁’。他岂不认得你是做经纪的秦小官，如何肯接你？”秦重道：“但凭妈妈怎的委曲宛转，成全其事，大恩不敢有忘！”九妈见他十分坚心，眉头一皱，计上心来，扯开笑口道：“老身已替你排下计策，只看你缘法如何。做得成，不要喜；做不成，不要怪。美儿昨日在李学士家陪酒，还未曾回；今日是黄衙内约下游湖；明日是张山人一班清客，邀他做诗社；后日是韩尚书的公子，数日前送下东道在这里。你且到大后日来看。还有句话，这几日你且不要来我家卖油，预先留下个体面。又有句话，你穿昅一身的布衣布裳，不像个上等嫖客，再来时，换件绸缎衣服，教这些丫鬟们认不出你是秦小官。老娘也好与你装谎。”秦重道：“小可一一理会得。”说罢，作别出门，且歇这三日生理，不去卖油，到典铺里买了一件见成半新半旧的绸衣，穿在身上，到街坊闲走，演习斯文模样。正是：","未识花院行藏，先习孔门规矩。丢过那三日不题。到第四日，起个清早，便到王九妈家去。去得太早，门还未开，意欲转一转再来。这番装扮希奇，不敢到昭庆寺去，死怕和尚们批点，且十景塘散步。良久又踅转去，王九妈家门已开了。那门前却安顿得有轿马，门内有许多仆从，在那里闲坐。秦重虽然老实，心下到也乖巧，且不进门，悄悄的招那马夫问道：“这轿马是谁家的？”马夫道：“韩府里来接公子的。”秦重己知韩公子夜来留宿，此持还未曾别，重复转身，到一个饭店之中，吃了些见成茶饭，又坐了一回，方才到王家探信。","只见门前轿马已自去了。进得门时，王九妈迎著，便道：“老身得罪，今日又不得工夫了。恰才韩公子拉去东庄赏早梅。他是个长嫖，老身不好违拗。闻得说来日还要到灵隐寺，访个棋师赌棋哩。齐衙内又来约过两三次了。这是我家房主，又是辞不得的。他来时，或三日五日的住了去，连老身也定不得个日子。秦小官，你真个要嫖，只索耐心再等几日。不然，前日的尊赐，分毫不动，要便奉还。”秦重道：“只怕妈妈不作成。若还迟，终无失，就是一万年，小可也情愿等著。”九妈道：“恁地时，老身便好张主！”秦重作别，方欲起身，九妈又道：“秦小官人，老身还有句话。你下次若来讨信，不要早了。约莫申牌时分，有各没客，老身把个实信与你。倒是越晏些越好。这是老身的妙用，你休错怪。”秦重连声道：“不敢，不敢！”这一日秦重不曾做买卖。次日，整理油担，挑往别处去生理，不走钱塘门一路。每日生意做完，傍晚时分就打扮齐整，到王九妈家探信，只是不得功夫。又空走了一月有余。那一日是十二月十五，大雪方霁，西风过后，积雪成冰，好不寒冷，却喜地下乾燥。秦重做了大半日买卖，如前妆扮，又去探信。王九妈笑容可掬，迎著道：“今日你造化，已是九分九厘了。”秦重道：“这一厘是欠著甚么？”九妈道：“这一厘么？正主儿还不在家。”秦重道：“可回来么？”九妈道：“今日是俞太尉家赏雪，筵席就备在湖船之内。俞太尉是七十岁的老人家，风月之事，已是是没份。原说过黄昏送来。你且到新人房里，吃杯烫风酒，慢慢的等他。”秦重道：“烦妈妈引路。”王九妈引著秦重，弯弯曲曲，走过许多房头，到一个所在，不是楼房，却是个平屋三间，甚是高爽。左一间是丫鬟的空房，一般有床榻桌椅之类，却是备官铺的；右一间是花魁娘子卧室，锁著在那里。两旁又有耳房。中间客座上面，挂一幅名人山水，香几上博山古铜炉，烧著龙涎香饼，两旁书桌，摆设些古玩，壁上贴许多诗稿。秦重愧非文人，不敢细看。心下想道：“外房如此整齐，内室铺陈，必然华丽。今夜尽我受用，十两一夜，也不为多。”九妈让秦小官坐于客位，自己主位相陪。少顷之间，丫鬟掌灯过来，抬下一张八仙桌儿，六碗时新果子，一架攒盒佳肴美酝，未曾到口，香气扑人。九妈执盏相劝道：“今日众小女都有客，老身只得自陪，请开怀畅饮几杯。”秦重酒量本不高，况兼正事在心，只吃半杯。吃了一会，便推不饮。九妈道：“秦小官想饿了，且用些饭再吃酒。”丫鬟捧著雪花白米饭，一吃一添，放于秦重面前，就是一盏杂和汤。鸨儿量高，不用饭，以酒相陪。秦重吃了一碗，就放箸。九妈道：“夜长哩，再请些。”秦重又添了半碗。丫鬟提个行灯来说：“浴汤热了，请客官洗浴。”秦重原是洗过澡来的，不敢推托，只得又到浴堂，肥皂香汤，洗了一遍，重复穿衣入坐。九妈命撤去肴盒，用暖锅下酒。此时黄昏已晚，昭庆寺里的钟都撞过了，美娘尚未回来。","玉人何处贪欢耍？等得情郎望眼穿！ 常言道：“等人心急。”秦重不见婊子回家，好生气闷。却被鸨儿夹七夹八，说些风话劝酒，不觉又过了一更天气。只听外面热闹闹的，却是花魁娘子回家，丫鬟先来报了。九妈连忙起身出迎，秦重也离坐而立。只见美娘吃得大醉，侍女扶将进来，到于门首，醉眼蒙胧。看见房中灯烛辉煌，杯盘狼藉，立住脚问道：“谁在这里吃酒？”九娘道：“我儿，便是我向日与你说的那秦小官人。他心中慕你，多时的送过礼来。因你不得工夫，担搁他一月有余了。你今日幸而得空，做娘的留他在此伴你。”美娘道：“临安郡中，并不闻说起有甚么秦小官人，我不去接他。”转身便走。九妈双手托开，即忙拦住道：“他是个至诚好人，娘不误你。”美娘只得转身，才跨进房门，抬头一看那人，有些面善，一时醉了，急切叫不出来，便道：“娘，这个人我认得他的，不是有名称的子弟，接了他，被人笑话。”九妈道：“我儿，这是涌金门内开缎铺的秦小官人。当初我们住在涌金门时，想你也曾会过，故此面善。你莫识认错了。做娘的见他来意志诚，一时许了他，不好失信。你看做娘的面上，胡乱留他一晚。做娘的晓得不是了，明日却与你陪礼。”一头说，一头推著美娘的肩头向前。美娘拗妈妈不过，只得进房相见。正是：","千般难出虔婆口，万般难脱虔婆手。","饶君纵有万千般，不如跟著虔婆走。","这些言语，秦重一句句都听得，佯为不闻。美娘万福过了，坐于侧首，仔细看著秦重，好生疑惑，心里甚是不悦，嘿嘿无言。唤丫鬟将热酒来，斟著大锺。鸨儿只道他敬客，却自家一饮而尽。九妈道：“我儿醉了，少吃些么！”美儿那里依他，答应道：“我不醉！”一连吃上十来杯。这是酒后之酒，醉中之醉，自觉立脚不住。唤丫鬟开了卧房，点上银，也不卸头，也不解带，瀀脱了毰，和衣上床，倒身而卧。鸨儿见女儿如此做作，甚不过意，对秦重道：“小女平日惯了，他专会使性。今日他心中不知为甚么有些不自在，却不干你事，休得见怪！”秦重道：“小可岂敢！”鸨儿又劝了秦重几杯酒，秦重再三告止。鸨儿送入房，向耳傍吩咐道：“那人醉了，放温存些。”又叫道：“我儿起来，脱了衣服，好好的睡。”美娘已在梦中，全不答应。鸨身只得去了。","丫鬟收拾了杯盘之类，抹了桌子，叫声：“秦小官人，安置罢。”秦重道：“有热茶要一壶。”丫鬟泡了一壶浓茶，送进房里，带转房门，自去耳房中安歇。秦重看美娘时，面对里床，睡得正熟，把锦被压于身下。秦重想酒醉之人，必然怕冷，又不敢惊醒他。忽见栏杆上又放著一床大红丝的锦被，轻轻的取下，盖在美娘身上，把银灯挑得亮亮的，取了这壶热茶，脱鞋上床，捱在美娘身边，左手抱著茶壶在怀，右手搭在美娘身上，眼也不敢闭一闭。正是：","未曾握雨携云，也算偎香倚玉。 却说美娘睡到半夜，醒将转来，自觉酒力不胜，胸中似有满溢之状。爬起来，坐在被窝中，垂著头，只管打乾哕。秦重慌忙也坐起来，知他要吐，放下茶壶，用抚摩其背。良久，美娘喉间忍不住了，说时迟，那时快，美娘放开喉咙便吐。秦重怕污了被窝，把自己的道袍袖子张开，罩在他嘴上。美娘不知所以，尽情一呕，呕毕，还闭著眼，讨茶嗽口。秦重下床，将道袍轻轻脱下，放在地平之上；摸茶壶还是暖的，斟上一瓯香喷喷的浓茶，递与美娘。美娘连吃了二碗，胸中虽然略觉豪燥，身子兀自倦怠，仍旧倒下，向里睡去了。秦重脱下道袍，将吐下一袖的腌，重重里著，放于床侧，依然上床，拥抱似初。","美娘那一觉直睡到天明方醒，覆身转来，见傍边睡著一人，问道：“你是哪个？”秦重答道：“小可姓秦。”美娘想起夜来之事，恍恍惚惚，不甚记得真了，便道：“我夜来好醉！”秦重道：“也不甚醉。”又问：“可曾仕么？”秦重道：“不曾。”美娘道：“这样还好。”又想一想道：“我记得曾吐过的，又记得曾吃过茶来，难道做梦不成？”秦重方才说道：“是曾吐来。小可见小娘子多了杯酒，也防著要吐，把茶壶暖在怀里。小娘子果然仕后讨茶，小可斟上，蒙小娘子不，饮了两瓯。”美娘大惊道：“脏巴巴的，吐在哪里？”秦重道：“恐怕小娘子污了被褥，是小可把袖子盛了。”美娘道：“如今在哪里？”秦重道：“连衣服里著，藏过在那里。”美娘道：“可惜坏了你一件衣服。”秦重道：“这是小可的衣服，有幸得沾小娘子的余沥。”美娘听说，心下想道：“有这般识趣的人！”心里已有四五分欢喜了。 此时天色大明，美娘起身，下床小解，看著秦重，猛然想起是秦卖油，遂问道：“你实对我说，是甚么样人？为何昨夜在此？”秦重道：“承花魁娘子下问，小子怎敢妄言。小可实是常来宅上卖油的秦重。”遂将初次看见送客，又看见上轿，心下想慕之极，及积趱嫖钱之事，备细述了一遍，“夜来得亲近小娘子一夜，三生有幸，心满意足。”美娘听说，愈加可怜，道：“我昨夜酒醉，不曾招接得你。你乾折了多少银子，莫不懊悔？”秦重道：“小娘子天上神仙，小可惟恐伏侍不周，但不见责，已为万幸，况敢有非意之望！”美娘道：“你做经纪的人，积下些银两，何不留下养家？此地不你来往的。”秦重道：“小可单只一身，并无妻小。”美娘顿了一顿，便道：“你今日去了，他日还来么？”秦重道：“只这昨宵相亲一夜，已慰生平，岂敢又作痴想！”美娘想道：“难得这好人，又忠厚，又老实，又且知情识趣，隐恶扬，千百中难遇此一人。可惜是市井之辈，若是衣冠子弟，情愿委身事之。”","正在沉吟之际，丫鬟捧洗脸水进来，又是两碗姜汤。秦重洗了脸，因夜来未曾脱帻，不用梳头，呷了几口姜汤，便要告别。美娘道：“少住不妨，还有话说。”秦重道：“小可仰慕花魁娘子，在傍多站一刻，也是好的。但为人岂不自揣！夜来在此，实是大胆，惟恐他人知道，有玷芳名，还是早些去了安稳。”美娘点了一点头，打发丫鬟出房，忙忙的开了减妆，取出二十两银子，送与秦重道：“昨夜难为你，这银两奉为资本，莫对人说。”秦重哪里肯受。美娘道：“我的银子，来路容易。这些须酬你一宵之情，休得固逊。若本钱缺少，异日还有助你之处。那件污秽的衣服，我叫丫鬟湔洗乾净了还你罢。”秦重道：“粗衣不烦小娘子费心，小可自会湔洗。只是领赐不当。”美娘道：“说哪里话！”将银子在秦重袖内，推他转身。秦重料难推却，只得受了，深深作揖，卷了脱下这件龌龊道袍，走出房门，打从鸨儿房前经过，鸨儿看见，叫声：“妈妈！秦小官去了。”王九妈正在净桶上解手，口中叫道：“秦小官，如何去得恁早？”秦重道：“有些贱事，改日特来称谢。”","来说秦重去了，且说美娘与秦重虽然没点相干，见他一片诚心，去后好不过意。这一日因害酒，辞了客在家将息。千个万个孤老都不想，倒把秦重整整的想一日。有诗为证：","俏冤家，须不是串花家的子弟，你是个做经纪本分人儿，哪匡你会温存，能软款，知心知意。料你不是个使性的，料你不是个薄情的。几番待放下思量也，又不觉思量起。 话分两头，再说邢权在朱十老家，与兰花情热，见朱十老病废在床，全无顾忌。十老发作了几场，两个商量出一条计策来，俟夜静更深，将店中资本席卷，双双的逃之夭夭，不知去向。次日天明，十老方知。央及邻里，出了个失单，寻访数日，并无动静，深悔当日不合为邢权所惑，逐了朱重。如今日久见人心，闻知朱重赁居众安桥下，挑挑担卖油，不如仍旧收拾他回来，老死有有靠，只怕他记恨在心。教邻舍好生劝他回家，但记好，莫记恶。秦重一闻此言，即日收拾了家伙，搬回十老家里。相见之间，痛哭了一场。十老将所存囊橐，尽数交付秦重。秦重自家又有二十余两本钱，重整店面，坐柜卖油。因在朱家，仍称朱重，不用秦字。不上一月，十老病重，医治不痊，呜呼哀哉。朱重捶胸大恸，如亲父一般，殡殓成服，七七做了些好事。朱家祖坟在清波门外，朱重举丧安葬，事事成礼。邻里皆称其厚德。事定之后，仍先开店。原来这油铺是个老店，从来生意原好；却被邢权刻剥存私，将主顾弄断了多少。今见朱小官在店，谁家不来作成？所以生理比前越盛。朱重单身独自，急切要寻个老成帮手。有个惯做中人的，叫做金中，忽一日引著一个五十余岁的人来。原来那人正是莘善，在汴梁城外安乐村居住。因那年避乱南奔，被官兵冲散了女儿瑶琴，夫妻两口，凄凄惶惶，东逃西窜，胡乱的过了几年。今日闻临安兴旺，南渡人民，大半安插在彼，诚恐女儿流落此地，特来寻访，又没消息。身边盘缠用尽，欠了饭钱，被饭店中终日赶逐，无可奈何，偶然听见金中说起朱家油铺，要寻个卖油帮手。自己曾开过六陈铺子，卖油之事，都则在行。况朱小官原是汴京人，又是乡里。故此央金中引荐到来。朱重问了备细，乡人见乡人，不觉感伤。“既然没处没奔，你老夫妻两口，只住在我身边，只当个乡亲相处，慢慢的访著令爱消息，再作区处。”当下取两贯钱把与莘善，去还了饭钱，连浑家阮氏也领将来，与朱重相见了，收拾一间空房，安顿他老夫妇在内。两口儿也尽心竭力，内外相帮。朱重甚是欢喜。光阴似箭，不觉一年有余。多有人见朱小官年长未娶，家道又好，做人又志诚，情愿白白把女儿送他为妻。朱重因见了花魁娘子，十分容貌，等闲的不看在眼，立心要访求个出色的女子，方才肯成亲。以此日复一日，担搁下去。正是：","曾观沧海难为水，除却巫山不是云。","再说王美娘在九妈家，盛名之下，朝欢暮乐真个口厌肥甘，身嫌锦绣。虽然如此，每遇不如意之处，或是子弟们任情使性，吃醋挑槽，或自己病中醉后，半夜三更，没人疼热，就想起秦小官人的好处来，只恨无缘再会。也是桃花运尽，合当变更，一年之后，生出一段事端来。 却说临安城中，有个吴八公子，父亲吴岳，见为福州大守。这吴八公子，打从父亲任上回来，广有金银，平昔间也喜赌钱吃酒，三瓦两舍走动。闻得花魁娘子之名，未曾识面，屡屡遣人来约，欲要嫖他。王美娘闻他气质不好，不愿相接，托故推辞，非止一次。那吴八公子也曾和著闲汉们亲到王九妈家几番，都不曾会。其时清明节届，家家扫墓，处处踏青，美娘因连日游春困倦，且是积下许多诗画之债，未曾完得，吩咐家中：“一应客来，都与我辞去。”闭了房门，焚起一炉好香，摆设文房四宝，方欲举笔，只听得外面沸腾，却是吴八公子，领著十余个狠仆，来接美娘游湖。因见鸨儿每次回他，在中堂行凶，打家打伙，直闹到美娘房前，只见房门锁闭。原来妓家有个回客法儿，小娘躲在房内，却把房门反锁，支吾客人，只推不在。那老实的就被他哄过了。吴公子是惯家，这些套子，怎地瞒得？吩咐家人扭断了锁，把房门一脚踢开。美娘躲身不迭，被公子看见，不由分说，教两个家人，左右牵手，从房内直拖出房外来，口中兀自乱嚷乱骂。王九妈欲待上前陪礼解劝，看见势头不好，只得闪过。家中大小，躲得没半个影儿。","吴家狼仆牵著美娘，出了王家大门，不管他弓鞋窄小，望街上飞跑；八公子在后，扬扬得意。直到西湖口，将美娘下了湖船，方才放手。美娘十二岁到王家，锦绣中养成，珍宝般供养，何曾受恁般凌贱。下了船，对著船头，掩面大哭。吴八公子见了，放下面皮，气忿忿的像关云长单刀赴会，一把交椅，朝外而坐，狼仆侍立于傍。面吩咐开船，一面数一数二的发作一个不住：“小贱人，小娼根，不受人抬举！再哭时，就讨打了！”美娘哪里怕他，哭之不已。船至湖心亭，吴八公子吩咐摆盒在亭子内，自己先上去了，却吩咐家人：“叫那小贱人来陪酒。”美娘抱住了栏杆，哪里肯去？只是嚎哭。吴八公子也觉没兴，自己吃了几杯淡酒，收拾下船，自来扯美娘。美娘双脚乱跳，哭声愈高。八公子大怒，教狼仆拔去簪珥。美娘蓬著头，跑到船头上，就要投水，被家童们扶住。公子道：“你撒赖便怕你不成！就是死了，也只费得我几两银子，不为大事。只是送你一条性命，也是罪过。你住了啼哭时，我就放回去，不难为你。”美听说放他回去，真个住了哭。八公子吩咐移船到清波门外僻静之处，将美娘毰脱下，去其里脚，露出一对金莲，如两条玉歟相似。教狼仆扶他上岸，骂道：“小贱人！你有本事，自走回家，我却没人相送。”说罢，一篙子湪鍈，再向湖中而去。正是：","焚琴煮鹤从来有，惜玉怜香几个知！","美娘赤了脚，寸步难行，思想：“自己才貌两全，只为落于风尘，受此轻贱。平昔枉自结识许多王孙贵客，急切用他不著，受了这般凌辱。就是回去，如何做人？到不如一死为高。只是死得没些名目，枉自享个盛名，到此地位，看著村庄妇人，也胜我十二分。这都是刘四妈这个嘴，哄我落坑堕堑，致有今日！自古红颜薄命，亦未必如我之甚！”越思越苦，放声大哭。","事有偶然，却好朱重那日到清波门外朱十老的坟上，祭扫过了，打发祭物下船，自己步回，从此经过。闻得哭声，上前看时，虽然蓬头垢面，那玉貌花容，从来无两，如何不认得！吃了一惊，道：“花魁娘子，如何这般模样？”美娘哀哭之际，听得声音厮熟，止啼而看，原来正是知情识趣的秦小官。美娘当此之际，如见亲人，不觉倾心吐胆，告诉他一番。朱重心中十分疼痛，亦为之流泪。袖中带得有白绫汗巾一条，约有五尺多长，取出劈半扯开，奉与美娘里脚，亲手与他拭泪。又与他挽起青丝，再三把好言宽解。等待美娘哭定，忙去唤个暖轿，请美娘坐了，自己步送，直到王九妈家。 九妈不得女儿消息，在四处打探，慌迫之际，见秦小官送女儿回来，分明送一颗夜明珠还他，如何不喜！况且鸨儿一向不见秦重挑油上门，多曾听得人说，他承受了朱家的店业，手头活动，体正又比前不同，自然刮目相得。又见女儿这等模样，问其缘故，已知女儿吃了大苦，全亏弓秦小官。深深拜谢，设酒相待。日已向晚，秦重略饮数杯，起身作别。美娘如何肯放，道；“我一向有于你，恨不得你见面，今日定然不放你空去。”鸨儿也来扳留。秦重喜出望外。是夜，美娘吹弹歌舞，曲尽生平之技，奉承秦重。秦重如做了一个游仙好梦，喜得魄荡魂消，手舞足蹈。夜深酒阑，二人相挽就寝。云雨之事，其美满更不必言： 一个是足力后生，一个是惯情女子。这边说三年怀想，费几多役梦劳魂；那边说一夜相思，喜侥幸皮贴肉。一个谢前番帮衬，合今番恩上加恩；一个谢今夜总成，比前夜爱中添爱。红粉妓倾翻粉盒，罗帕留痕。卖油郎打泼油瓶，被窝沾湿。可笑村儿乾折本，作成小子弄风梳。","云雨已罢，美娘道：“我有句心腹之言与你说，你休得推托！”秦重道：“小娘子若用得著小可时，就赴汤蹈火，亦所不辞，岂有推托之理？”美娘道：“我要嫁你。”秦重笑道：“小娘子就嫁一万个，也还数不到小可头上，休得取笑，枉自折了小可的食料。”美娘道：“这话实是真心，怎说取笑二字！我自十四岁被妈妈灌醉，梳弄过了。此时便要从良，只为未曾相处得人，不辨好歹，恐误了终身大事。以后相处的虽多，都是豪华之辈，酒色之徒。但知买笑追欢的乐意，哪有怜香惜玉的真心。看来看去，只有你是个志诚君子，浫蹹你尚未娶亲。若不嫌我烟花贱质，情愿举案齐眉，白头奉侍。你若不允之时，我就将三尺白罗，死于君前，振白我一片诚心，也强如昨日死于村郎之手，没名没目，惹人笑话。”说罢，呜呜的哭将起来。秦重道：“小娘子休得悲伤。小可承小娘子错爱，将天就地，求之不得，岂敢推托？只是小娘子千金声价，小可家贫力薄，如何摆布，也是力不从心了。”美娘道：“这却不妨。不瞒你说，我只为从良一事，预先积趱些东西，寄顿在外。赎身之费，一亮不费你心力。”秦重道：“就是小娘子自己赎身，平昔住惯了高堂大厦，享用了锦衣玉食，在小可家，如何过活？”美娘道：“布衣蔬食，死而无怨。”秦重道：“小娘子虽然，只怕妈妈不从。”美娘道路：“我自有道理。”如此如此，这般这般，两个直说到天明。 原来黄翰林的衙内，韩尚书的公子，齐太尉的舍人，这几个相知的人家，美良都寄顿得有箱笼。美娘只推要用，陆续取到，密地约下秦重，教他收置在家。然后一乘轿子，抬到刘四妈家，诉以从良之事。刘四妈道：“此事老身前日原说过的。只是年纪还早，又不知你要从哪一个？”美娘道：“姨娘，你莫管是甚人，少不得依著姨娘的言语，是个直从良，乐从良，了从良；不是那不真，不假，不了，不绝的勾当。只要姨娘肯开口时，不愁妈妈不允。做侄女的没别孝顺只有十两金子，奉与姨娘，胡乱打些钗子；是必在妈妈前做个方便。事成之时，媒礼在外。”刘四妈看见这金子，笑得眼儿没缝，便道：“自家儿女，又是美事，如何要你的东西！这金子权时领下，只当与你收藏。此事都在老身身上。只是你的娘，把你当个摇钱树，等闲也不轻放你出去。怕不要千把银子。那主儿可是肯出手的么？也得老身见他一见，与他讲道方好。”美娘道：“姨良莫管问事，只当你侄女自家赎身便了。”刘四妈道：“妈妈可晓得你到我家来？”美娘道路：“不晓得。”四妈道：“你且在我家便饭，待老身先到你家，与妈妈讲。讲得通时，然后来报你。” 刘四妈雇乘轿子，抬到王九妈家，九妈相迎入内。刘四妈问起吴八公子之事，九妈告诉了一遍。四妈道：“我们行户人家，到是养成个半低不高的丫头，尽可赚钱，又且安稳，不论甚么客就接了，倒是日日不空的。侄女只为声名大了，好似一块鳖鱼落地，马蚁儿都要钻他。虽然热闹，却也不得自在。说便许多一夜，也只是个虚名。那些王孙公子来一遍，动不动有几个帮闲，连宵达且，好不费事。跟随的人又不少，个个要奉承得他好。有些不到之处，口里就出粗，哩罗的骂人，还要弄损你家伙，又不好告诉他家主，受了若干闷气。浖獴山人墨客，诗社棋社，少不得一月之内，又有几日官身。这些富贵子弟，你争我夺，依了张家，违了李家，一边喜，少不得一边怪了。就是吴八公子这一个风波，吓杀人的，万一失差，却不连本送了？官宦人家，和他打官司不成！只索忍气吞声。今日还亏著你家时运高，太平没事，一个霹雳空中过去了。倘然山高水低，悔之无及。妹子闻得吴八公子不怀好意，还要到你家索闹。侄女的性气又不好，不肯奉承人。第一是这件，乃是个惹祸之本。”九妈道：“便是这件，老身常是担忧。就是这八公子，也是有名有称的人，又不是微贱之人。这丫头抵死不肯接他，惹出这场寡气。当初他年纪小时，还听人教训。如今有了个虚名，被这些富贵子弟夸他奖他，惯了他性情，骄了他气质，动不动自作自主。逢著客来，他要接便接，他若不情愿时，便是九牛也休想牵得他转。”刘四妈道：“做小娘的略有些身分，都则如此。”","王九妈道：“我如今与你商议：倘若有个肯出钱的，不如卖了他去，到得乾净，省得终身担著鬼胎过日。”刘四妈道：“此言甚妙。卖了他一个，就讨得五六个。若凑巧撞得著相应的，十来个也讨得的。这等便宜事，口何不做！”王九妈道：“老身也曾算计过来：那些有势有力的不出钱，专要讨人便宜；及至肯出几两银子的，女儿又嫌好道歉，做张做智的不肯。若有好主儿，妹子做媒，作成则个。倘若这丫头不肯时节，还求你撺掇。这丫头做娘的话也不听，只你说得他信。话得他转。”刘四妈呵呵大笑道：“做妹子的此来，正为与侄做媒。你要许多银子便肯放他出门？”九妈道：“妹子，你是明理的人。我们这行户例，只有贱买，哪有贱卖？况且美儿数年盛名满临安，谁不知他是花魁娘子，难道三百四百，就容他走动？少不得要他千金。”刘四妈道：“待妹子去讲。若肯出这个数目，做妹子的便来多口。若合不著时，就不来了。”临行时，又故意问道：“侄女今日在哪里？”王九妈道：“不要说起，自从那日吃了吴八公子的亏，怕他还来淘气，终日里抬个轿子，各宅去分诉。前日在齐太尉家，昨日在黄翰林家，今日又不知在哪家去了。”刘四妈道：“有了你老人家做主，按定了坐盘星，也不容侄女不肯。万一不肯时，做妹子自会劝他。只是寻得主顾来，你却莫要捉班做势。”九妈道：“一言既出，并无他说。”九妈送至门首。刘四妈叫声噪，上轿去了。这才是：","数黑论黄雌陆贾，说长话短女随何。","若还都像虔婆口，尺水能兴万丈波。 刘四妈回到家中，与美娘说道：“我对你妈妈如此说，这般讲，你妈妈已自肯了。只要银子见面，这事立地便成。”美娘道：“银子已曾办下，明日姨娘千万到我家来，玉成其事，不要冷了场，改日又费讲。”四妈道：“既然约定，老身自然到宅。”美娘别了刘四妈，回家一子不题。","次日，午牌时分，刘四妈果然来了。王九妈问道：“所事口何！”四妈道：“十有八九，只不曾与侄女说过。”四妈来到美娘房中，两下相叫了，讲了一回说话。四妈道：“你的主儿到了不曾？那话儿在哪里？”美娘指著床头道：“在这几只皮箱里。”美娘把五六只皮箱一时都开了，五十两一封，搬出十三四封来，又把些金珠宝玉算价，足勾千金之数。把个刘四妈惊得眼中出火，口内流涎，想道：“小小年纪，这等有肚肠！不知如何设处，积下许多东西？我家这几个粉头，一般接客，赶得著他哪里！不要说不会生发，就是有几文钱在荷包里，闲时买瓜子磕，买糖儿吃，两条脚布破了，还要做妈的与他买布哩。偏生九阿姐造化，讨得著，年时赚了若干钱钞，临出门还有这一主大财，又是取诸宫中，不劳余力。”这是心中暗想之语，却不曾说出来。美娘见刘四妈沉吟，只道作难索谢，慌忙又取出四匹潞绸，两股宝钗，一对凤头玉簪，放在桌上，道：“这几件东西，奉与姨娘为伐柯之敬。”利四妈欢天喜地对王九妈说道：“侄女情愿自家赎身，一般身价，并不短少分毫。比著孤老卖身更好。省得闲汉们从中说合，费酒费浆，还要加一加二的谢他。” 王九妈听得说女儿皮箱内有许多东西，到有个然之色。你道却是为何！世间只有鸨儿的狠，做小娘的设法些东西，都送到他手里，才是快活。也有做些私房在箱笼内，鸨儿晓得些风声，专等女儿出门，开锁钥，翻箱倒笼取个罄空。只为美娘盛名下，相交都是大头儿，替做娘的挣得钱钞，又且性格有些古怪，等闲不敢触犯，故此卧房里面，鸨儿的脚也不搠进去。谁知他如此有钱。刘四妈见九妈颜色不善，便猜著了，连忙道：“九阿姐，你休得三心两意。这些东西，就是侄女自家积下的，也不是你本分之钱。他若肯花费时，也花费了。或是他不长进，把来津贴了得意的孤老，你也哪里知道！这还是他做家的好处。况且小娘自己手中没有钱钞，临到从良之际，难道赤身赶他出门？少不得头上脚下都要收拾得光鲜，等他好去别人家做人。如今他自家拿得出这些东西，料然一丝一线不费你的心。这一主银子，是你完完全全鳖在腰跨里的。他就赎身出去，怕不是你女儿？倘然他挣得好时，时朝月节，怕他不来孝顺你？就是嫁了人时，他又没有亲爹亲娘，你也还去做得著他的外婆，受用处正有哩。”只这一套话，说得王九妈心中爽然，当下应允。刘四妈就去搬出银子，一封封兑过，交付与九妈，又把这些金珠宝玉，逐件指物作价，对九妈说道：“这都是做妹子的故意估下他些价钱。若换与人，还便宜得几十两银子。”王九妈虽同是个鸨儿，到是个老实头儿，凭刘四妈说话，无有不纳。","刘四妈见王九妈收了这主东西，便叫亡八写了婚书，交忖与美儿。美儿道：“趁姨娘在此，奴家就拜别了爹妈出门，借姨娘家住一两日，择吉从良，未知姨娘允否？”刘四妈得了美娘许多谢礼，生怕九妈翻悔，巴不得美娘出他他门，完成一事，说道：“正该如此。”当下美娘收拾了房中自己的梳台拜匣，皮箱铺盖之类。但是鸨儿家中之物，一毫不动。收拾已完，随著四妈出房，拜别了假爹假妈，和那姨娘行中，都相叫了。王九妈一般哭了几声。美娘唤人挑了行李，欣然上轿，同刘四妈到刘家去。四妈出一间幽静的好房，顿下美娘行李。众小娘都来与美娘叫喜。是晚，朱重差莘善到刘四妈家讨信，已知美娘赎身出来。择了吉日，笙箫鼓乐娶亲。刘四妈就做大媒送亲，朱重与花魁娘子花烛洞房，欢喜无限。","虽然旧事风流，不减新婚佳趣。","次日，莘善老夫妇请新人相见，各各相认，吃了一惊。问起根由，至亲三口，抱头而哭。朱重方才认得是丈人丈母。请他上坐，夫妻二人，重新拜见。亲邻闻知，无不骇然。是日，整备筵席，庆贺两重之喜，饮酒尽欢而散。三朝之后，美娘教丈夫备下几副厚礼，分送旧相知各宅，以酬其寄顿箱笼之恩，并报他从良信息。此是美娘有始有终处。王九妈、刘四妈家，各有礼物相送，无不感激。满月之后，美娘将箱笼打开，内中都有黄白之资，吴绫蜀锦，何止百计，共有三千余金，都将匙钥交付丈夫，慢慢的买房置产，整顿家当。油铺生理，都是丈人莘善管理。不上一年，把家业挣得花锦般相似，驱奴使婢，甚有气象。","朱重感谢天地神明保佑之德，发心于各寺庙喜舍合殿油烛一套，供琉璃灯油三个月；斋弁沐浴，亲往拈香礼拜。先从昭庆寺起，其他灵隐、法相、净慈、天竺等寺，以次而行。","就中单说天竺寺，是观音大士的香火，有上天竺、中天竺、下天竺，三处香火俱盛，却是山路，不通舟楫。朱重叫从人挑了一担香烛，三担清油，自己乘轿而往。先到上天竺来。寺僧迎接上殿，老香火秦公点烛添香。此时朱重居移气，养移体，仪容魁岸，非复幼时面目，秦公哪里认得他是儿子。只因油桶上有个大大的“秦”字，又有“汴梁”二字，心中甚以为奇。。也是天然凑巧。刚刚到上天竺，偏用著这两只油桶。朱重拈香已毕，秦公托出茶盘，主僧奉茶。秦公问道：“不敢动问施主，这油桶上为何有此三字？”朱重听得问声，带著汴梁人的土音，忙问道：“老香火，你问他怎么？莫非也是汴梁人么？”秦公道：“正是。”朱重道：“你姓甚名谁？为何在此出家？共有几年了？”秦公把自己乡里，细细告诉：“芋年上避兵来此，因无活计，将十三岁的儿秦重，过继与朱家。如今有八年之远。一向为年老多病，不曾下山问得信息。”朱重一把抱住，放声大哭道：“孩儿便是秦重。向在朱家挑油买卖。正为要访求父亲下落，故此于油桶上，写“汴梁秦”三字，做个标识。谁知此地相逢！真乃天与其便！”众僧见他父子别了八年，今朝重会，各各称奇。朱重这一日，就歇在上天竺，与父亲同宿，各叙情节。","次日，取出中天竺、下天竺两个疏头换过。内中朱重，仍改做秦重，复了本姓。两处烧香礼拜已毕，转到上天竺，要请父亲回家，安乐供养。秦公出家已久，吃素持斋，不愿随儿子回家。秦重道路：“父亲别了八年，孩儿缺侍奉。况孩儿新娶媳妇，也得他拜见公公方是。”秦公只得依允。秦重将轿子让与父亲乘坐，自己步行，直到家中。秦重取出一套新衣，与父亲换了，中堂设坐，同安莘氏双双参拜。亲家莘公、亲母阮氏，齐来见礼。","此日大排筵席。秦公不肯开荤，素酒素食。次日，邻里敛财称贺。一则新婚，二则新娘子家眷团圆，三则父子重逢，四则秦小官归宗复姓，共是四重大喜。一连又吃了几日喜酒。秦公不愿家居，思想上天竺故处清净出家。秦重不敢违亲之志，将银二百两，于上天竺另造净室一所，送父亲到彼居住。其日用供给，按月送去。每十日亲往候问一次。每一季同莘氏往候一次。那秦公活到八十余，端坐而化。遗命葬于本山。此是后话。","却说秦重和莘氏，夫妻偕老，生下两孩儿，俱读书成名。至今风月中市语，凡夸人善于帮衬，都叫做“秦小官”，又叫“卖油郎”。有诗为证： 　　春来处处百花新，蜂蝶纷纷竞采春。","堪爱豪家多子弟，风流不及卖油人。"],"cpLength":24699},"xsh-11":{"chapterId":"xsh-11","bookId":"xsh","fileIndex":10,"number":11,"title":"第十一卷　苏小妹三难新郎","paragraphs":["聪明男子做公卿，女子聪明不出身。","若许裙钗应科举，女儿那见逊公卿。","自混沌初辟，乾道成男，坤道成女，虽则造化无私，却也阴阳分位。阳动阴静，阳施阴受，阳外阴内。所以男子主四方之事，女子主一室之事。主四方之事的，顶冠束带，谓之丈夫；出将入相，无所不为；须要博古通今，达权知变。主一室之事的，三绺梳头，两截穿衣。一日之计，止无过饔飧井臼；终身之计，止无过生男育女。所以大家闺女，虽曾读书识字，也只要他识些姓名，记些帐目。他又不应科举，不求名誉，诗文之事，全不相干。然虽如此，各人资性不同。有等愚蠢的女子，教他识两个字，如登天之难。有等聪明的女子，一般过目成诵，不教而能。吟诗与李、杜争强，作赋与班、马斗胜。这都是山川秀气，偶然不钟于男而钟于女。且如汉有曹大家，他是个班固之妹，代兄续成汉史。又有个蔡琰，制《胡笳十八拍》，流传后世。晋时有个谢道韫，与诸兄咏雪，有柳絮随风之句，诸兄都不及他。唐时有个上官婕妤，中宗皇帝教他品第朝臣之诗，臧否一一不爽。至于大宋妇人，出色的更多。就中单表一个叫作李易安，一个叫作朱淑真。他两个都是闺阁文章之伯，女流翰苑之才。论起相女配夫，也该对个聪明才子。争奈月下老错注了婚籍，都嫁了无才无学之人，每每怨恨之情，形于笔札。有诗为证：","鸥鹭鸳鸯作一池，曾知羽翼不相宜！","东君不与花为主，何似休生连理枝！","那李易安有《伤秋》一篇，调寄《声声慢》：","寻寻觅觅，冷冷清清，凄凄惨惨戚戚。乍暖还寒时候，正难将息。三杯两盏淡酒，怎敌他晚来风力！雁过也，总伤心，却是旧时相识。满地黄花堆积，憔悴损，如今有谁 忺摘。守着窗儿，独自怎生得黑！梧桐更兼细雨，到黄昏，点点滴滴，这次第怎一个愁字了得！","朱淑真时值秋间，丈夫出外，灯下独坐无聊，听得窗外雨声滴点，吟成一绝：","哭损双眸断尽肠，怕黄昏到又昏黄。那堪细雨新秋夜，一点残灯伴夜长！","后来刻成诗集一卷，取名《断肠集》。","说话的，为何单表那两个嫁人不着的？只为如今说一个聪明女子，嫁着一个聪明的丈夫，一唱一和，遂变出若干的话文。正是：","说来文士添佳兴，道出闺中作美谈。","话说四川眉州，古时谓之蜀郡，又曰嘉州，又曰眉山。山有蟆顺、峨眉，水有岷江、环湖，山川之秀，钟于人物。生出个博学名儒来，姓苏，名洵，字允明，别号老泉。当时称为老苏。老苏生下两个孩儿，大苏小苏。大苏名轼，字子瞻，别号东坡；小苏名辙，字子由，别号颖滨。二子都有文经武纬之才，博古通今之学，同科及第，名重朝廷，俱拜翰林学士之职。天下称他兄弟，谓之二苏。称他父子，谓之三苏。这也不在话下。更有一桩奇处，那山川之秀，偏萃于一门。两个儿子未为希罕，又生个女儿，名曰小妹，其聪明绝世无双，真个闻一知二，问十答十。因他父兄都是个大才子，朝谈夕讲，无非子史经书，目见耳闻，不少诗词歌赋。自古道：近朱者赤，近墨者黑。况且小妹资性过人十倍，何事不晓。十岁上随父兄居于京师寓中，有绣球花一树，时当春月，其花盛开。老泉赏玩了一回，取纸笔题诗，才写得四句，报说：“门前客到！”老泉阁笔而起。小妹闲步到父亲书房之内，看见桌上有诗四句： 　　天巧玲珑玉一邱，迎眸烂熳总清幽。白云疑向枝间出，明月应从此处留。","小妹览毕，知是咏绣球花所作，认得父亲笔迹，遂不待思索，续成后四句云：","瓣瓣折开蝴蝶翅，团团围就水晶球。假饶借得香风送，何羡梅花在陇头。","小妹题诗依旧放在桌上，款步归房。老泉送客出门，复转书房，方欲续完前韵，只见八句已足，读之词意俱美。疑是女儿小妹之笔，呼而问之，写作果出其手。老泉叹道：“可惜是个女子！若是个男儿，可不又是制科中一个有名人物！”自此愈加珍爱其女，恣其读书博学，不复以女工督之。看看长成一十六岁，立心要妙选天下才子，与之为配。急切难得。忽一日，宰相王荆公着堂候官请老泉到府与之叙话。原来王荆公，讳安石，字介甫。初及第时，大有贤名。平时常不洗面，不脱衣，身上虱子无数。老泉恶其不近人情，异日必为奸臣，曾作《辨奸论》以讥之，荆公怀恨在心。后来见他大苏、小苏连登制科，遂舍怨而修好。老泉亦因荆公拜相，恐妨二子进取之路，也不免曲意相交。正是：","古人结交在意气，今人结交为势利。从来势利不同心，何如意气交情深。 是日，老泉赴荆公之召，无非商量些今古，议论了一番时事，遂取酒对酌，不觉忘怀酩酊。荆公偶然夸能：“小儿王雱，读书只一遍，便能背诵。”老泉带酒答道：“谁家儿子读两遍！”荆公道：“到是老夫失言，不该班门弄斧。”老泉道：“不惟小儿只一遍，就是小女也只一遍。”荆公大惊道：“只知令郎大才，却不知有令爱。眉山秀气，尽属公家矣！”老泉自悔失言，连忙告退。荆公命童子取出一卷文字，递与老泉道：“此乃小儿王 雱窗课，相烦点定。”老泉纳于袖中，唯唯而出。回家睡至半夜，酒醒，想起前事：“不合自夸女孩儿之才。今介甫将儿子窗课属吾点定，必为求亲之事。这头亲事，非吾所愿，却又无计推辞。”沉吟到晓，梳洗已毕，取出王 雱所作，次第看之，真乃篇篇锦绣，字字珠玑，又不觉动了个爱才之意。“但不知女儿缘分如何？我如今将这文卷与女传观之，看他爱也不爱。”遂隐下姓名，分付丫鬟道：“这卷文字，乃是个少年名士所呈，求我点定。我不得闲暇，转送与小姐，教他到批阅完时，速来回话。”丫鬟将文字呈上小姐，传达太老爷分付之语。小妹滴露研朱，从头批点，须臾而毕。叹道：“好文字！此必聪明才子所作。但秀气泄尽，华而不实，恐非久长之器。”遂于卷面批云：","新奇藻丽，是其所长；含蓄雍容，是其所短。取巍科则有余，享大年则不足。","后来王雱十九岁中了头名状元，未几夭亡。可见小妹知人之明，这是后话。却说小妹写罢批语，叫丫鬟将文卷纳还父亲。老泉一见大惊：“这批语如何回复得介甫！必然取怪。”一时污损了卷面，无可奈何，却好堂候官到门：“奉相公钧旨，取昨日文卷，面见太爷，还有话禀。”老泉此时，手足无措，只得将卷面割去，重新换过，加上好批语，亲手交堂候官收讫。堂候官道：“相公还分付过，有一言动问：贵府小姐曾许人否？倘未许人，相府愿谐秦晋。”老泉道：“相府请亲，老夫岂敢不从。只是小女貌丑，恐不足当金屋之选。相烦好言达上，但访问自知，并非老夫推托。”堂候官领命，回复荆公。荆公看见卷面换了，已有三分不悦。又恐怕苏小姐容貌真个不扬，不中儿子之意，密地差人打听。原来苏东坡学士，常与小姐互相嘲戏。东坡是一嘴胡子，小妹嘲云：","口角几回无觅处，忽闻毛里有声传。","小妹额颅凸起，东坡答嘲云：","未出庭前三五步，额头先到画堂前。","小妹又嘲东坡下颏之长云：","去年一点相思泪，至今流不到腮边。","东坡因小妹双眼微抠，复答云：","几回拭脸深难到，留却汪汪两道泉。","访事的得了此言，回复荆公，说：“苏小姐才调委实高绝，若论容貌，也只平常。”荆公遂将姻事阁起不题。然虽如此，却因相府求亲一事，将小妹才名播满了京城。以后闻得相府亲事不谐，慕名来求者，不计其数。老泉都教呈上文字，把与女孩儿自阅。也有一笔涂倒的，也有点不上两三句的。就中只有一卷，文字做得好。看他卷面写有姓名，叫做秦观。小妹批四句云： 　　今日聪明秀才，他年风流学士。可惜二苏同时，不然横行一世。 这批语明说秦观的文才，在大苏小苏之间，除却二苏，没人及得。老泉看了，已知女儿选中了此人。分付门上：“但是秦观秀才来时，快请相见。余的都与我辞去。”谁知众人呈卷的，都在讨信，只有秦观不到。却是为何？那秦观秀才字少游，他是扬州府高邮人。腹饱万言，眼空一世。生平敬服的，只有苏家兄弟，以下的都不在意。今日慕小妹之才，虽然衔玉求售，又怕损了自己的名誉，不肯随行逐队，寻消问息。老泉见秦观不到，反央人去秦家寓所致意，少游心中暗喜。又想道：“小妹才名得于传闻，未曾面试，又闻得他容貌不扬，额颅凸出，眼睛凹进，不知是何等鬼脸？如何得见他一面，方才放心。”打听得三月初一日，要在岳庙烧香，趁此机会，改换衣装，觑个分晓。正是：","眼见方为的，传闻未必真。若信传闻语，枉尽世间人。","从来大人家女眷入庙进香，不是早，定是夜。为甚么？早则人未来，夜则人已散。秦少游到三月初一日五更时分，就起来梳洗，打扮个游方道人模样：头裹青布唐巾，耳后露两个石碾的假玉环儿，身穿皂布道袍，腰系黄绦，足穿净袜草履，项上挂一串拇指大的数珠，手中托一个金漆钵盂，侵早就到东岳庙前伺候。天色黎明，苏小姐轿子已到。少游走开一步，让他轿子入庙，歇于左廊之下。小妹出轿上殿，少游已看见了。虽不是妖娆美丽，却也清雅幽闲，全无俗韵。“但不知他才调真正如何？”约莫焚香已毕，少游却循廊而上，在殿左相遇。少游打个问讯云：","小姐有福有寿，愿发慈悲。","小妹应声答云：","道人何德何能，敢求布施！","少游又问讯云：","愿小姐身如药树，百病不生。","小妹一头走，一头答应：","随道人口吐莲花，半文无舍。","少游直跟到轿前，又问讯云：","小娘子一天欢喜，如何撒手宝山？","小妹随口又答云：","风道人恁地贪痴，那得随身金穴！","小妹一头说，一头上轿。少游转身时，口中喃出一句道：“‘风道人’得对‘小娘子’，万千之幸！”小妹上了轿，全不在意。跟随的老院子，却听得了，怪这道人放肆，方欲回身寻闹，只见廊下走出一个垂髫的俊童，对着那道人叫道：“相公这里来更衣。”那道人便前走，童儿后随。老院子将童儿肩上悄地捻了一把，低声问道：“前面是那个相公？”童儿道：“是高邮秦少游相公。”老院子便不言语。回来时，就与老婆说知了。这句话就传入内里，小妹才晓得那化缘的道人是秦少游假妆的，付之一笑，嘱付丫鬟们休得多口。","话分两头。且说秦少游那日饱看了小妹容貌不丑，况且应答如响，其才自不必言。择了吉日，亲往求亲，老泉应允，少不得下财纳币。此是二月初旬的事。少游急欲完婚，小妹不肯。他看定秦观文字，必然中选。试期已近，欲要象简乌纱，洞房花烛，少游只得依他。到三月初三礼部大试之期，秦观一举成名，中了制科。到苏府来拜丈人，就禀复完婚一事。因寓中无人，欲就苏府花烛。老泉笑道：“今日挂榜，脱白挂绿，便是上吉之日，何必另选日子。只今晚便在小寓成亲，岂不美哉！”东坡学士从旁赞成。是夜与小妹双双拜堂，成就了百年姻眷。正是：","聪明女得聪明婿，大登科后小登科。","其夜月明如昼。少游在前厅筵宴已毕，方欲进房，只见房门紧闭，庭中摆着小小一张桌儿，桌上排列纸墨笔砚，三个封儿，三个盏儿，一个是玉盏，一个是银盏，一个是瓦盏。青衣小鬟守立旁边。少游道：“相烦传语小姐，新郎已到，何不开门？”丫鬟道：“奉小姐之命，有三个题目在此，三试俱中式，方准进房。这三个纸封儿便是题目在内。”少游指着三个盏道：“这又是甚的意思？”丫鬟道：“那玉盏是盛酒的，那银盏是盛茶的，那瓦盏是盛寡水的。三试俱中，玉盏内美酒三杯，请进香房。两试中了，一试不中，银盏内清茶解渴，直待来宵再试。一试中了，两试不中，瓦盏内呷口淡水，罚在外厢读书三个月。”少游微微冷笑道：“别个秀才来应举时，就要告命题容易了，下官曾应过制科，青钱万选，莫说三个题目，就是三百个，我何惧哉！”丫鬟道：“俺小姐不比寻常盲试官，之乎者也应个故事而已。他的题目好难哩！第一题，是绝句一首，要新郎也做一首，合了出题之意，方为中式。第二题四句诗，藏着四个古人，猜得一个也不差，方为中式。到第三题，就容易了，止要做个七字对儿，对得好便得饮美酒进香房了。”少游道：“请第一题。”丫鬟取第一个纸封拆开，请新郎自看。少游看时，封着花笺一幅，写诗四句道：","铜铁投洪冶，蝼蚁上粉墙。阴阳无二义，天地我中央。","少游想道：“这个题目，别人做定猜不着。则我曾假扮做云游道人，在岳庙化缘，去相那苏小姐。此四句乃含着‘化缘道人’四字，明明嘲我。”遂于月下取笔写诗一首于题后云：","化工何意把春催？缘到名园花自开。道是东风原有主，人人不敢上花台。","丫鬟见诗完，将第一幅花笺褶做三叠，从窗隙中塞进，高叫道：“新郎交卷，第一场完。”小妹览诗，每句顶上一字，合之乃“化缘道人”四字，微微而笑。少游又开第二封看之，也是花笺一幅，题诗四句：","强爷胜祖有施为，凿壁偷光夜读书。缝线路中常忆母，老翁终日倚门闾。","少游见了，略不凝思，一一注明。第一句是孙权，第二句是孔明，第三句是子思，第四句是太公望。丫鬟又从窗隙递进。少游口虽不语，心下想道：“两个题目，眼见难我不倒，第三题是个对儿，我五六岁时便会对句，不足为难。”再拆开第三幅花笺，内出对云：","闭门推出窗前月。 初看时觉道容易，仔细思来，这对出得尽巧。若对得平常了，不见本事。左思右想，不得其对。听得谯楼三鼓将阑，构思不就，愈加慌迫。却说东坡此时尚未曾睡，且来打听妹夫消息。望见少游在庭中团团而步，口里只管吟哦“闭门推出窗前月”七个字，右手做推窗之势。东坡想道：“此必小妹以此对难之，少游为其所困矣！我不解围，谁为撮合？”急切思之，亦未有好对。庭中有花缸一只，满满的贮着一缸清水，少游步了一回，偶然倚缸看水。东坡望见，触动了他灵机，道：“有了！”欲待教他对了，诚恐小妹知觉，连累妹夫体面，不好看相。东坡远远站着咳嗽一声，就地下取小小砖片，投向缸中。那水为砖片所激，跃起几点，扑在少游面上。水中天光月影，纷纷淆乱。少游当下晓悟，遂援笔对云：","投石冲开水底天。 丫鬟交了第三遍试卷，只听呀的一声，房门大开，内又走出一个侍儿，手捧银壶，将美酒斟于玉盏之内，献上新郎，口称：“才子请满饮三杯，权当花红赏劳。”少游此时意气扬扬，连进三盏，丫鬟拥入香房。这一夜，佳人才子，好不称意。正是：","欢娱嫌夜短，寂寞恨更长。","自此夫妻和美，不在话下。后少游宦游浙中，东坡学士在京，小妹思想哥哥，到京省视。东坡有个禅友，叫做佛印禅师，尝劝东坡急流勇退。一日寄长歌一篇，东坡看时，却也写得怪异，每二字一连，共一百三十对字。你道写的是甚字？","野野鸟鸟啼啼时时有有思思春春气气桃桃花花发发满满","枝枝莺莺雀雀相相呼呼唤唤岩岩畔畔花花红红似似锦锦","屏屏堪堪看看山山秀秀丽丽山山前前烟烟雾雾起起清清","浮浮浪浪促促潺潺湲湲水水景景幽幽深深处处","好好追追游游傍傍水水花花似似雪雪梨梨花花光光皎皎","洁洁玲玲珑珑似似坠坠银银花花折折最最好好柔柔茸茸","溪溪畔畔草草青青双双蝴蝴蝶蝶飞飞来来到到落落花花","林林里里鸟鸟啼啼叫叫不不休休为为忆忆春春光光好好","杨杨柳柳枝枝头头春春色色秀秀时时常常共共饮饮春春","浓浓酒酒似似醉醉闲闲行行春春色色里里相相逢逢竞竞","忆忆游游山山水水心心息息悠悠归归去去来来休休役役","东坡看了两三遍，一时念将不出，只是沉吟。小妹取过，一览了然，便道：“哥哥，此歌有何难解！待妹子念与你听。”即时朗诵云： 　　野鸟啼，野鸟啼时时有思。","有思春气桃花发，春气桃花发满枝。","满枝莺雀相呼唤，莺雀相呼唤岩畔。","岩畔花红似锦屏，花红似锦屏堪看。","堪看山山秀丽，秀丽山前烟雾起。","山前烟雾起清浮，清浮浪促潺湲水。","浪促潺湲水景幽，景幽深处好，深处好追游。","追游傍水花，傍水花似雪。","似雪梨花光皎洁，梨花光皎洁玲珑。","玲珑似坠银花折，似坠银花折最好。","最好柔茸溪畔草，柔茸溪畔草青青。","双双蝴蝶飞来到，蝴蝶飞来到落花。","落花林里鸟啼叫，林里鸟啼叫不休。","不休为忆春光好，为忆春光好杨柳。","杨柳枝枝春色秀，春色秀时常共饮。","时常共饮春浓酒，春浓酒似醉。","似醉闲行春色里，闲行春色里相逢。","相逢竞忆游山水，竞忆游山水心息。","心息悠悠归去来，归去来休休役役。","东坡听念，大惊道：“吾妹敏悟，吾所不及！若为男子，官位必远胜于我矣！”遂将佛印原写长歌，并小妹所定句读，都写出来，做一封儿寄与少游。因述自己再读不解，小妹一览而知之故。少游初看佛印所书，亦不能解。后读小妹之句，如梦初觉，深加愧叹。答以短歌云： 　　未及梵僧歌，词重而意复。字字如联珠，行行如贯玉。","想汝惟一览，顾我劳三复。裁诗思远寄，因以真类触。","汝其审思之，可表予心曲。","短歌后制成叠字诗一首，却又写得古怪：","思伊久阻归期","静忆","转漏闻时离别","少游书信到时，正值东坡与小妹在湖上看采莲。东坡先拆书看了，递与小妹，问道：“汝能解否？”小妹道：“此诗乃仿佛印禅师之体也。”即念云：","静思伊久阻归期，久阻归期忆别离。忆别离时闻漏转，时闻漏转静思伊。 东坡叹道：“吾妹真绝世聪明人也！今日采莲胜会，可即事各和一首，寄与少游，使知你我今日之游。”东坡诗成，小妹亦就。小妹诗云：","莲人在绿杨津","采一","玉嗽声歌新阙","东坡诗云：","花归去马如飞","赏酒","暮已时醒微力","照少游诗念出，小妹叠字诗，道是：","采莲人在绿杨津，在绿杨津一阙新。一阙新歌声嗽玉，歌声嗽玉采莲人。","东坡叠字诗，道是：","赏花归去马如飞，去马如飞酒力微。酒力微醒时已暮，醒时已暮赏花归。","二诗寄去，少游读罢，叹赏不已。其夫妇酬和之诗甚多，不能详述。后来少游以才名被征为翰林学士，与二苏同官。一时郎舅三人，并居史职，古所希有。于是宣仁太后亦闻苏小妹之才，每每遣内官赐以绢帛或饮馔之类，索他题咏。每得一篇，宫中传诵，声播京都。其后小妹先少游而卒，少游思念不置，终身不复娶云。有诗为证：","文章自古说三苏，小妹聪明胜丈夫。","三难新郎真异事，一门秀气世间无。"],"cpLength":6893},"xsh-18":{"chapterId":"xsh-18","bookId":"xsh","fileIndex":17,"number":18,"title":"第十八卷　施润泽滩阙遇友","paragraphs":["还带曾消纵理纹，返金种得桂枝芬。","从来阴骘能回福，举念须知有鬼神。","这首诗引着两个古人阴骘的故事。第一句说：“还带曾消纵理纹。”乃唐朝晋公裴度之事。那裴度未遇时，一贫如洗，功名蹭蹬，就一风鉴，以决行藏。那相士说：“足下功名事，且不必问。更有句话，如不见怪，方敢直言。”斐度道：“小生因在迷途，故求指示，岂敢见怪！”相士道：“足下螣蛇纵理纹入口，数年之间，必致饿死沟渠。”连相钱俱不肯受。裴度是个知命君子，也不在其意。","一日，偶至香山寺闲游。只见供卓上光华耀目，近前看时，乃是一围宝带。裴度检在手中，想道：“这寺乃冷落所在，如何却有这条宝带？”翻阅了一回，又想道：“必有甚贵人，到此礼佛更衣。祗候们不小心，遗失在此，定然转来寻觅。”乃坐在廓庑下等候。不一时，见一女子走入寺来，慌慌张张，径望殿上而去。向供卓上看了一看，连声叫苦，哭倒于地。裴度走向前问道：“小娘子因何恁般啼泣？”那女子道：“妾父被人陷于大辟，无门伸诉。妾日至此恳佛阴祐，近日幸得从轻赎锾。妾家贫无措，遍乞高门，昨得一贵人矜怜，助一宝带。","妾以佛力所致，适携带呈于佛前，稽首叩谢。因赎父心急，竟忘收此带，仓忙而去。行至半路方觉。急急赶来取时，已不知为何人所得。今失去这带，妾父料无出狱之期矣！”说罢又哭。裴度道：“小娘子不必过哀，是小生收得，故在此相候。”","把带递还。那女子收泪拜谢：“请问姓字，他日妾父好来叩谢。”","裴度道：“小娘子有此冤抑，小生因在贫乡，不能少助为愧。","还人遗物，乃是常事，何足为谢！”不告姓名而去。","过了数日，又遇向日相士，不觉失惊道：“足下曾作何好事来？”裴度答云：“无有。”相士道：“足下今日之相，比先大不相牟。阴德纹大见，定当位极人臣，寿登耄耋，富贵不可胜言。”斐度当时犹以为戏语。后来果然出将入相，历事四朝，封为晋国公，年享上寿。有诗为证：纵理纹生相可怜，香山还带竟安然。","淮西荡定功英伟，身系安危三十年。","第二句说是：“返金种得桂枝芬。”乃五代窦禹钧之事。那窦禹钧，蓟州人氏，官为谏议大夫，年三十而无子。夜梦祖父说道：“汝命中已该绝嗣，寿亦只在明岁。及早行善，或可少延。”禹钧唯唯。他本来是个长者，得了这梦，愈加好善。","一日薄暮，于延庆寺侧，拾得黄金三十两、白金二百两。至次日清早，便往寺前守候。少顷，见一后生涕泣而来。禹钧迎住问之。后生答道：“小人父亲身犯重罪，禁于狱中，小人遍恳亲知，共借白金二百两、黄金三十两。昨将去赎父，因主库者不在而归，为亲戚家留款，多吃了杯酒，把东西遗失。","今无以赎父矣！”窦公见其言已合银数，乃袖中摸出还之，道：“不消着急，偶尔拾得在此，相候久矣。”这后生接过手，打开看时，分毫不动，叩头泣谢。窦公扶起，分外又赠银两而去。其他善事甚多，不可枚举。一夜，复梦祖先说道：“汝合无子无寿。今有还金阴德种种，名挂天曹，特延算三纪，赐五子显荣。”窦公自此愈积阴功，后果连生五子：长仪，次俨，三侃，四偁，五僖，俱仕宋为显官。窦公寿至八十二，沐浴相别亲戚，谈笑而卒。安乐老冯道有诗赠之云：燕山窦十郎，教子有义方。 灵椿一株老，丹桂五枝芳。","说话的，为何道这两桩故事？只因亦有一人曾还遗金，后来虽不能如二公这等大富大贵，却也免了一个大难，享个大大家事。正是：种瓜得瓜，种豆得豆。一切祸福，自作自受。 说这苏州府吴江县离城七十里，有个乡镇，地名盛泽，镇上居民稠广，土俗淳朴，俱以蚕桑为业。男女勤谨，络纬机抒之声，通宵彻夜。那市上两岸绸丝牙行，约有千百余家，远近村坊织成绸匹，俱到此上市。四方商贾来收买的，蜂攒蚁集，挨挤不开，路途无伫足之隙；乃出产锦绣之乡，积聚绫罗之地。江南养蚕所在甚多，惟此镇处最盛。有几句口号为证：东风二月暖洋洋，江南处处蚕桑忙。蚕欲温和桑欲干，明如良玉发奇光。缲成万缕千丝长，大筐小筐随络床。美人抽绎沾唾香，一经一纬机杼张。咿咿轧轧谐宫商，花开锦簇成匹量。莫忧八口无餐粮，朝来镇上添远商。","且说嘉靖年间，这盛泽镇上有一人，姓施名复，浑家喻氏，夫妻两口，别无男女。家中开张绸机，每年养几筐蚕儿，妻络夫织，甚好过活。这镇上都是温饱之家，织下绸匹，必积至十来匹，最少也有五六匹，方才上市。那大户人家积得多的便不上市，都是牙行引客商上门来买。施复是个小户儿，本钱少，织得三四匹，便去上市出脱。一日，已积了四匹，逐匹把来方方折好，将个布袱儿包裹，一径来到市中。只见人烟辏集，语话喧阗，甚是热闹。施复到个相熟行家来卖，见门首拥着许多卖绸的，屋里坐下三四个客商。主人家贴在柜身里，展看绸匹，估喝价钱。施复分开众人，把绸递与主人家。主人家接来，解开包袱，逐匹翻看一过，将秤准了一准，喝定价钱，递与一个客人道：“这施一官是忠厚人，不耐烦的，把些好银子与他。”那客人真个只拣细丝称准，付与施复。施复自己也摸出等子来准一准，还觉轻些，又争添上一二分，也就罢了。讨张纸包好银子，放在兜肚里，收了等子包袱，向主人家拱一拱手，叫声有劳，转身就走。","行不上半箭之地，一眼觑见一家街沿之下，一个小小青布包儿。施复趱步向前，拾起袖过，走到一个空处，打开看时，却是两锭银子，又有三四件小块，兼着一文太平钱儿。把手攧一攧，约有六两多重。心中欢喜道：“今日好造化！拾得这些银子，正好将去凑做本钱。”连忙包好，也揣在兜肚里，望家中而回。一头走，一头想：“如今家中见开这张机，尽勾日用了。有了这银子，再添上一张机，一月出得多少绸，有许多利息。这项银子，譬如没得，再不要动他。积上一年，共该若干，到来年再添上一张，一年又有多少利息。算到十年之外，便有千金之富。那时造什么房子，买多少田产。”正算得熟滑，看看将近家中，忽地转过念头，想道：“这银两若是富人掉的，譬如牯牛身上拔根毫毛，打什么紧，落得将来受用；若是客商的，他抛妻弃子，宿水餐风，辛勤挣来之物，今失落了，好不烦恼！如若有本钱的，他拚这帐生意扯直，也还不在心上；傥然是个小经纪，只有这些本钱，或是与我一般样苦挣过日，或卖了绸，或脱了丝，这两锭银乃是养命之根，不争失了，就如绝了咽喉之气，一家良善，没甚过活，互相埋怨，必致鬻身卖子，傥是个执性的，气恼不过，肮脏送了性命，也未可知。我虽是拾得的，不十分罪过，但日常动念，使得也不安稳。就是有了这银子，未必真个便营运发积起来。一向没这东西，依原将就过了日子。不如原往那所在，等失主来寻，还了他去，到得安乐。”随复转身而去，正是：多少恶念转善，多少善念转恶。","劝君诸善奉行，但是诸恶莫作。","当下施复来到拾银之处，靠在行家柜边，等了半日，不见失主来寻。他本空心出门的，腹中渐渐饥饿，欲待回家吃了饭再来，犹恐失主一时间来，又不相遇，只得忍着等候。少顷，只见一个村庄后生，汗流满面，闯进行家，高声叫道：“主人家，适来银子忘记在柜上，你可曾检得么？”主人家道：“你这人好混帐！早上交银子与了你，这时节却来问我，你若忘在柜上时，莫说一包，再有几包也有人拿去了。”那后生连把脚跌道：“这是我的种田工本，如今没了，却怎么好？”施复问道：“约莫有多少？”那后生道：“起初在这里卖的丝银六两二钱。”施复道：“把什么包的？有多少件数？”那后生道：“两整锭，又是三四块小的，一个青布银包包的。”施复道：“恁样，不消着急。我拾得在此，相候久矣。”便去兜肚里摸出来，递与那人。那人连声称谢，接过手，打开看时，分毫不动。","那时往来的人，当做奇事，拥上一堆，都问道：“在那里拾的？”施复指道：“在这阶沿头拾的。”那后生道：“难得老哥这样好心，在此等候还人。若落在他人手里，安肯如此！如今到是我拾得的了。情愿与老哥各分一半。”施复道：“我若要，何不全取了，却分你这一半？”那后生道：“既这般，送一两谢仪与老哥买果儿吃。”施复笑道：“你这人是个呆子！六两三两都不要，要你一两银子何用！”那后生道：“老哥，银子又不要，何以相报？”众人道：“看这位老兄，是个厚德君子，料必不要你报。不若请到酒肆中吃三杯，见你的意罢了。”","那后生道：“说得是。”便来邀施复同去。施复道：“不消得，不消得，我家中有事，莫要担阁我工夫。”转身就走。那后生留之不祝众人道：“你这人好造化！掉了银子，一文钱不费，便捞到手。”那后生道：“便是，不想世间原有这等好人。”把银包藏了，向主人说声打搅，下阶而去。众人亦赞叹而散。也有说：“施复是个呆的，拾了银子不会将去受用，却呆站着等人来还。”也有说：“这人积此阴德，后来必有好处。”不题众人。","且说施复回到家里，浑家问道：“为甚么去了这大半日？”","施复道：“不要说起，将到家了，因着一件事，复身转去，担阁了这一回。”浑家道：“有甚事担阁？”施复将还银之事，说向浑家。浑家道：“这件事也做得好。自古道：‘横财不富命穷人。’傥然命里没时，得了他反生灾作难，到未可知。”施复道：“我正为这个缘故，所以还了他去。”当下夫妇二人，不以拾银为喜，反以还银为安。衣冠君子中，多有见利忘义的，不意愚夫愚妇到有这等见识。","从来作事要同心，夫唱妻和种德深。","万贯钱财如粪土，一分仁义值千金。","自此之后，施复每年养蚕，大有利息，渐渐活动。那育蚕有十体、二光、八宜等法，三息五广之忌。第一要择蚕种。蚕种好，做成茧小而明厚坚细，可以缫丝。如蚕种不好，但堪为绵纩，不能缫丝，其利便差数倍。第二要时运。有造化的，就蚕种不好，依般做成丝茧；若造化低的，好蚕种，也要变做绵茧。北蚕三眠，南蚕俱是四眠。眠起饲叶，各要及时。又蚕性畏寒怕热，惟温和为得候。昼夜之间，分为四时。","朝暮类春秋，正昼如夏，深夜如冬，故调护最难。江南有谣云：做天莫做四月天，蚕要温和麦要寒。","秧要日时麻要雨，采桑娘子要晴干。","那施复一来蚕种拣得好，二来有些时运，凡养的蚕，并无一个绵茧，缫下丝来，细员匀紧，洁净光莹，再没一根粗节不匀的。每筐蚕，又比别家分外多缫出许多丝来。照常织下的绸拿上市去，人看时光彩润泽，都增价竞买，比往常每匹平添钱方银子。因有这些顺溜，几年间，就增上三四张绸机，家中颇颇饶裕。里中遂庆个号儿叫做施润泽。却又生下一个儿子，寄名观音大士，叫做观保，年才二岁，生得眉目清秀，到好个孩子。 话休烦絮。那年又值养蚕之时，才过了三眠，合镇阙了桑叶，施复家也只勾两日之用，心下慌张，无处去买。大率蚕市时，天色不时阴雨，蚕受了寒湿之气，又食了冷露之叶，便要僵死，十分之中，就只好存其半。这桑叶就有余了。那年天气温暖，家家无恙，叶遂短阙。且说施复正没处买桑叶，十分焦躁，忽见邻家传说洞庭山余下桑叶甚多，合了十来家过湖去买。施复听见，带了些银两，把被窝打个包儿，也来趁船。这时已是未牌时候，开船摇橹，离了本镇。过了平望，来到一个乡村，地名滩阙。这去处在太湖之傍，离盛泽有四十里之远。天已傍晚，过湖不及，遂移舟进一小港泊住，稳缆停桡，打点收拾晚食，却忘带了打火刀石。众人道：“那个上涯去取讨个火种便好？”施复却如神差鬼使一般，便答应道：“待我去。”取了一把麻骨，跳上岸来。见家家都闭着门儿。你道为何天色未晚，人家就闭了门？那养蚕人家，最忌生人来冲。从蚕出至成茧之时，约有四十来日，家家紧闭门户，无人往来。任你天大事情，也不敢上门。","当下施复走过几家，初时甚以为怪，道：“这些人家，想是怕鬼拖了人去，日色还在天上，便都闭了门。”忽地想起道：“呸！自己是老看蚕，到忘记了这取火乃养蚕家最忌的。却兜揽这帐！如今那里去讨？”欲待转来，又想道：“方才不应承来，到也罢了，若空身回转，教别个来取得时，反是老大没趣；或者有家儿不养蚕的也未可知。”依旧又走向前去。只见一家门儿半开半掩，他也不管三七廿一，做两步跨到檐下，却又不敢进去。站在门外，舒颈望着里边，叫声：“有人么？”里边一个女人走出来，问道！笆裁慈耍俊笔└绰媾阕判Φ溃骸按竽镒樱","嗲蟾龌鸲！备救说溃骸罢馐苯冢鹑思沂遣豢系摹Ｖ晃壹颐患苫洹１愕愀鲇肽阋膊环恋谩！笔└吹溃骸叭绱耍嘈涣耍奔唇楣堑萦耄救私庸郑サ愠龌鹄础? 施复接了，谢声打搅，回身便走。走不上两家门面，背后有人叫道：“那取火的转来，掉落东西了。”施复听得，想道：“却不知掉了甚的？”又复走转去。妇人说道：“你一个兜肚落在此了。”递还施复。施复谢道：“难得大娘子这等善心。”","妇人道：“何足为谢！向年我丈夫在盛泽卖丝，落掉六两多银子，遇着个好人拾得，住在那里等候。我丈夫寻去，原封不动，把来还了，连酒也不要吃一滴儿。这样人方是真正善心人！”施复见说，却与他昔年还银之事相合，甚是骇异，问道：“这事有几年了？”妇人把指头扳算道：“已有六年了。”施复道：“不瞒大娘子说，我也是盛泽人，六年前也曾拾过一个卖丝客人六两多银子，等候失主来寻，还了去。他要请我，也不要吃他的。但不知可就是大娘子的丈夫？”妇人道：“有这等事！待我教丈夫出来，认一认可是？”施复恐众人性急，意欲不要，不想手中麻骨火将及点完，乃道：“大娘子，相认的事甚缓，求得个黄同纸去引火时，一发感谢不荆”妇人也不回言，径往里边去了。顷刻间，同一个后生跑出来。彼此睁眼一认，虽然隔了六年，面貌依然。正是昔年还银义士。正是：一叶浮萍归大海，人生何处不相逢。","当下那后生躬身作揖道：“常想老哥，无从叩拜，不想今日天赐下顾。”施复还礼不迭。二人作过揖，那妇人也来见个礼。后生道：“向年承老哥厚情，只因一时仓忙，忘记问得尊姓大号住处。后来几遍到贵镇卖丝，问主人家，却又不相认。","四面寻访数次，再不能遇见，不期到在敝乡相会。请里面坐。” 施复道：“多承盛情垂念，但有几个朋友，在舟中等候火去作晚食，不消坐罢。”后生道：“何不一发请来？”施复道：“岂有此理！”后生道：“既如此，送了火去来坐罢。”便教浑家取个火来，妇人即忙进去。后生问道：“老哥尊姓大号？今到那里去？”施复道：“小子姓施名复，号润泽。今因缺了桑叶，要往洞庭山去买。”后生道：“若要桑叶，我家尽有，老哥今晚住在寒舍，让众人自去。明日把船送到宅上，可好么？”施复见说他家有叶，好不欢喜，乃道：“若宅上有时，便省了小子过湖，待我回覆众人自去。”妇人将出火来，后生接了，说：“我与老哥同去。”又分付浑家，快收拾夜饭。 当下二人拿了火来至船边，把火递上船去。众人一个个眼都望穿，将施复埋怨道：“讨个火什么难事！却去这许多时？”","施复道：“不要说起，这里也都看蚕，没处去讨。落后相遇着这位相熟朋友，说了几句话，故此迟了，莫要见怪！”又道：“这朋友偶有叶余在家中，我已买下，不得相陪列位过湖了。","包袱在舱中，相烦拿来与我。”众人检出付与。那后生便来接道：“待我拿罢！”施复叫道：“列位，暂时抛撇，归家相会。”","别了众人，随那后生转来，乃问道：“适来忙促，不曾问得老哥贵姓大号。”答道：“小子姓朱名恩，表德子义。”施复道：“今年贵庚多少？”答道：“二十八岁。”施复道：“恁样，小子叨长老哥八年！”又问：“令尊令堂同居么？”朱恩道：“先父弃世多年，止有老母在堂，今年六十八岁了，吃一口长素。” 二人一头说，不觉已至门首。朱恩推开门，请施复屋里坐下。那卓上已点得灯烛。朱恩放下包裹道：“大嫂快把茶来。”","声犹未了，浑家已把出两杯茶，就门帘内递与朱恩。朱恩接过来，递一杯与施复，自己拿一杯相陪，又问道：“大嫂，鸡可曾宰么？”浑家道：“专等你来相帮。”朱恩听了，连忙把茶放下，跳起身要去捉鸡。原来这鸡就罩在堂屋中左边。施复即上前扯住道：“既承相爱，即小菜饭儿也是老哥的盛情，何必杀生！况且此时鸡已上宿，不争我来又害他性命，于心何忍！”朱恩晓得他是个质直之人，遂依他说，仍复坐下道：“既如此说，明日宰来相请。”叫浑家道：“不要宰鸡了，随分有现成东西，快将来吃罢，莫饿坏了客人。酒烫热些。”","施复道：“正是忙日子，却来蒿恼。幸喜老哥家没忌讳还好。”朱恩道：“不瞒你说，旧时敝乡这一带，第一忌讳是我家，如今只有我家无忌讳。”施复道：“这却为何？”朱恩道：“自从那年老哥还银之后，我就悟了这道理。凡事是有个定数，断不由人，故此绝不忌讳，依原年年十分利息。乃知人家都是自己见神见鬼，全不在忌讳上来。妖由人兴，信有之也。” 施复道：“老哥是明理之人，说得极是。”朱恩又道：“又有一节奇事，常年我家养十筐蚕，自己园上叶吃不来，还要买些。","今年看了十五筐，这园上桑又不曾增一棵两棵，如今够了自家，尚余许多，却好又济了老哥之用。这桑叶却像为老哥而生，可不是个定数？”施复道：“老哥高见，甚是有理。就如你我相会，也是个定数。向日你因失银与我识面，今日我亦因失物，尊嫂见还。方才言及前情，又得相会。”朱恩道：“看起来，我与老哥乃前生结下缘分，才得如此。意欲结为兄弟，不知尊意若何？”施复道：“小子别无兄弟，若不相弃，可知好哩。”当下二人就堂中八拜为交，认为兄弟。施复又请朱恩母亲出来拜见了。朱恩重复唤浑家出来，见了结义伯伯。一家都欢欢喜喜。","不一时，将出酒肴，无非鱼肉之类。二人对酌。朱恩问道：“大哥有几位令郎？”施复答道：“只有一个，刚才二岁，不知贤弟有几个？”朱恩道：“止有一个女儿，也才二岁。”便教浑家抱出来，与施复观看。朱恩又道：“大哥，我与你兄弟之间，再结个儿女亲家何如？”施复道：“如此最好，但恐家寒攀陪不起。”朱恩道：“大哥何出此言！”两下联了姻事，愈加亲热。杯来盏去，直饮至更余方止。 朱恩寻扇板门，把凳子两头阁着，支个铺儿在堂中右边，将荐席铺上。施复打开包裹，取出被来丹好。朱恩叫声安置，将中门闭上，向里面去了。施复吹息灯火，上铺卧下，翻来覆去，再睡不着。只听得鸡在笼中不住吱吱喳喳，想道：“这鸡为甚么只管咭 F？”约莫一个更次，众鸡忽然乱叫起来，却像被什么咬住一般。施复只道是黄鼠狼来偷鸡，霍地立起身，将衣服披着急来看这鸡。说时迟，那时快，才下铺，走不上三四步，只听得一时响亮，如山崩地裂，不知甚东西打在铺上，把施复吓得半步也走不动。","且说朱恩同母亲浑家正在那里饲蚕，听得鸡叫，也认做黄鼠狼来偷，急点火出来看。才动步，忽听见这一响，惊得跌足叫苦道：“不好了！是我害了哥哥性命也！怎么处？”飞奔出来。母妻也惊骇，道：“坏了，坏了！”接脚追随。朱恩开了中门，才跨出脚，就见施复站在中间，又惊又喜道：“哥哥，险些儿吓杀我也！亏你如何走得起身，脱了这祸？”施复道：“若不是鸡叫得慌，起身来看，此时已为虀粉矣。不知是甚东西打将下来？”朱恩道：“乃是一根车轴阁在上边，不知怎地却掉下来？”将火照时，那扇门打得粉碎，凳子都跌倒了。","车轴滚在壁边，有巴斗粗大。施复看了，伸出舌头缩不上去。","此时朱恩母妻见施复无恙，已自进去了。那鸡也寂然无声。朱恩道：“哥哥起初不要杀鸡，谁想就亏他救了性命。”二人遂立誓戒了杀生。有诗为证：昔闻杨宝酬恩雀，今见施君报德鸡。","物性有知皆似此，人情好杀复何为？","当下朱恩点上灯烛，卷起铺盖，取出稻草，就地上打个铺儿与施复睡了。到次早起身，外边却已下雨。吃过早饭，施复便要回家。朱恩道：“难得大哥到此！须住一日，明早送回。”","施复道：“你我正在忙时，总然留这一日，各不安稳，不如早些得我回去，等在闲时，大家宽心相叙几日。”朱恩道：“不妨得！譬如今日到洞庭山去了，住在这里话一日儿。”朱恩母亲也出来苦留，施复只得住下。到已牌时分，忽然作起大风，扬沙拔木，非常利害。接着风就是一阵大雨。朱恩道：“大哥，天遣你遇着了我，不去得还好。他们过湖的，有些担险哩。”","施复道：“便是。不想起这等大风，真个好怕人子！”那风直吹至晚方息。雨也止了。施复又住了一宿，次日起身时，朱恩桑叶已采得完备。他家自有船只，都装好了。吃了饭，打点起身。施复意欲还他叶钱，料道不肯要的，乃道：“贤弟，想你必不受我叶钱，我到不虚文了。但你家中脱不得身，送我去便担阁两日工夫，若有人顾一个摇去，却不两便？”朱恩道：“正要认着大哥家中，下次好来往，如何不要我去？家中也不消得我。”施复见他执意要去，不好阻挡，遂作别朱恩母妻，下了船。朱恩把船摇动，刚过午，就到了盛泽。","施复把船泊住，两人搬桑叶上岸。那些邻家也因昨日这风，却担着愁担子，俱在门首等侯消息，见施复到时，齐道：“好了，回来也！”急走来问道：“他们那里去了不见？共买得几多叶？”施复答道：“我在滩阙遇着亲戚家，有些余叶送我，不曾同众人过湖。”众人俱道：“好造化，不知过湖的怎样光景哩？”施复道：“料然没事。”众人道：“只愿如此便好。”","施复就央几个相熟的，将叶相帮搬到家里，谢声有劳，众人自去。浑家接着，道：“我正在这里忧你，昨日恁样大风，不知如何过了湖？”施复道：“且过来见了朱叔叔，慢慢与你细说。”朱恩上前深深作揖，喻氏还了礼。施复道：“贤弟请坐，大娘快取茶来，引孩子来见丈人。”喻氏从不曾见过朱恩，听见叫他是贤弟，又称他是孩子丈人，心中惑突，正不知是兀谁，忙忙点出两杯茶，引出小厮来。施复接过茶，递与朱恩，自己且不吃茶，便抱小厮过来，与朱恩看。朱恩见生得清秀，甚是欢喜，放下茶，接过来抱在手中。这小厮却如相熟的一般，笑嘻嘻全不怕生。施复向浑家说道：“这朱叔叔便是向年失银子的，他家住在滩阙。”喻氏道：“原来就是向年失银的。如何却得相遇？”施复乃将前晚讨火落了兜肚，因而言及，方才相会留住在家，结为兄弟。又与儿女联姻，并不要宰鸡，亏鸡警报，得免车轴之难。所以不曾过湖，今日将叶送回。前后事细细说了一遍。喻氏又惊又喜，感激不尽，即忙收拾酒肴款待。","正吃酒间，忽闻得邻家一片哭声。施复心中怪异，走出来问时，却是昨日过湖买叶的翻了船，十来个人都淹死了，只有一个人得了一块船板，浮起不死，亏渔船上救了回来报信，施复闻得，吃这惊不小，进来学向朱恩与浑家听了，合掌向天称谢，又道：“若非贤弟相留，我此时亦在劫中矣。”朱恩道：“此皆大哥平昔好善之报，与我何干！”施复留朱恩住了一宿。到次早，朝膳已毕，施复道：“本该留贤弟闲玩几日，便是晓得你家中事忙，不敢担误在此。过了蚕事，然后来相请。”朱恩道：“这里原是不时往来的，何必要请。”施复又买两盒礼物相送。朱恩却也不辞，别了喻氏，解缆开船。施复送出镇上，方才分手。正是：只为还金恩义重，今朝难舍弟兄情。","且说施复是年蚕丝利息比别年更多几倍，欲要又添张机儿，怎奈家中窄隘，摆不下机床。大凡人时运到来，自然诸事遇巧。施复刚愁无处安放机床，恰好间壁邻家住着两间小房，连年因蚕桑失利，嫌道住居风水不好，急切要把来出脱，正凑了施复之便。那邻家起初没售主时，情愿减价与人。及至施复肯与成交，却又道方员无真假，比原价反要增厚，故意作难刁蹬，真徵个心满意足，方才移去。那房子还拆得如马坊一般。","施复一面唤匠人修理，一而择吉铺设机床，自己将把锄头去垦机坑。约摸锄了一尺多深，忽锄出一块大方砖来，揭起砖时，下面圆圆一个坛口，满满都是烂米。施复说道：“可惜这一坛米，如何却埋在地下？”又想道：“上边虽然烂了，中间或者还好。”丢了锄头，把手去捧那烂米，还不上一寸，便露出一搭雪白的东西来。举目看时，不是别件，却是腰间细两头趽，凑心的细丝锭儿。施复欲待运动，恐怕被匠人们撞见，沸扬开去，急忙原把土泥掩好，报知浑家。直至晚上，匠人去后，方才搬运起来，约有千金之数。夫妻们好不欢喜！施复因免了两次大难，又得了这注财乡，愈加好善。凡力量做得的好事，便竭力为之；做不得的，他也不敢勉强，因此里中随有长者之名。夫妻依旧省吃俭用，昼夜营运。不上十年，就长有数千金家事。又买了左近一所大房居住，开起三四十张绸机，又讨几房家人小厮，把个家业收拾得十分完美。儿子观保，请个先生在家，教他读书，取名德胤，行聘礼定了朱恩女儿为媳。俗语说得好：六亲合一运。那朱恩家事也颇颇长起。二人不时往来，情分胜如嫡亲。","话休烦絮。且说施复新居房子，别屋都好，惟有厅堂摊塌坏了，看看要倒，只得兴工改造。他本寒微出身，辛苦作家惯了，不做财主身分，日逐也随着做工的搬瓦弄砖，拿水提泥。众人不晓得他是勤俭，都认做借意监工，没一个敢怠惰偷力。工作半月有余，择了吉日良机，立柱上梁。众匠人都吃利市酒去了，止存施复一人，两边检点，柱脚若不平准的，便把来垫稳。看到左边中间柱脚歪料，把砖去垫。偏有这等作怪的事，左垫也不平，右垫又不稳，索性拆开来看，却原来下面有块三角沙石，尖头正向着上边，所以垫不平。乃道：“这些匠工精鸟帐！这块石怎么不去了，留在下边？”便将手去一攀，这石随手而起。拿开石看时，到吃一惊！下面雪白的一大堆银子，其锭大小不一；上面有几个一样大的，腰间都束着红绒，其色甚是鲜明。又喜又怪。喜的是得这一大注财物，怪的是这几锭红绒束的银子，他不知藏下几多年了，颜色还这般鲜明。当下不管好歹，将衣服做个兜儿，抓上许多，原把那块石盖好，飞奔进房，向床上倒下。喻氏看见，连忙来问：“是那里来的？”施复无暇答应，见儿子也在房中，即叫道：“观保快同我来！”口中便说，脚下乱跑。喻氏即解其意。父子二人来至外边，教儿子看守，自己分几次搬完。这些匠人酒还吃未完哩。","施复搬完了，方与浑家说知其故。夫妻三人好不喜！把房门闭上，将银收藏，约有二千余金。红绒束的，止有八锭，每锭准准三两。收拾已完，施复要拜天地，换了巾帽长衣，开门出来。那些匠人，手忙脚乱，打点安柱上梁。见柱脚倒乱，乃道：“这是谁个弄坏了？又要费一番手脚。”施复道：“你们垫得不好，须还要重整一整。”工人知是家长所为，谁敢再言。","流水自去收拾，那晓其中奥妙。施复仰天看了一看，乃道：“此时正是卯时了，快些竖起来。”众匠人闻言，七手八脚。一会儿便安下柱子，抬梁上去。里边托出一大盘抛梁馒首，分散众人。邻里们都将着果酒来与施复把盏庆贺。施复因掘了藏，愈加快活，分外兴头，就吃得个半醺。正是：人逢喜事精神爽，月到中秋分外明。","施复送客去后，将巾帽长衣脱下，依原随身短衣，相帮众人。到巳牌时分，偶然走至外边，忽见一个老儿庞眉白发，年约六十已外，来到门首，相了一回，乃问道：“这里可是施家么？”施复道：“正是，你要寻那个？”老儿道：“要寻你们家长，问句话儿。”施复道：“小子就是。老翁有甚话说？请里面坐了。”那老儿听见就是家主，把他上下只管瞧看，又道：“你真个是么？”施复笑道：“我不过是平常人，那个肯假！”老儿举一举手，道：“老汉不为礼了，乞借一步话说。”拉到半边，问道：“宅上可是今日卯时上梁安柱么？”施复道：“正是。”","老儿又道：“官人可曾在左边中间柱下得些财采？”施复见问及这事，心下大惊，想道：“他却如何晓得？莫不是个仙人！”","因道着心事，不敢隐瞒，答道：“果然有些。”老儿又道：“内中可有八个红绒束的锭么？”施复一发骇异，乃道：“有是有的，老翁何由知得这般详细？”老儿道：“这八锭银子，乃是老汉的，所以知得。”施复道：“既是老翁的，如何却在我家柱下？” 那老儿道：“有个缘故。老汉叫做薄有寿，就住在黄江南镇上，止有老荆两口，别无子女。门首开个糕饼馒头等物点心铺子，日常用度有余，积至三两，便倾成一个锭儿。老荆孩子气，把红绒束在中间，无非尊重之意。因墙卑室浅，恐露人眼目，缝在一个暖枕之内，自谓万无一失。积了这几年，共得八锭，以为老夫妻身后之用，尽有余了。不想今早五鼓时分，老汉梦见枕边走出八个白衣小厮，腰间俱束红绦，在床前商议道：‘今日卯时，盛泽施家竖柱安梁，亲族中应去的，都已到齐了。我们也该去矣。’有一个问道：‘他们都在那一个所在？’一个道：‘在左边中间柱下。’说罢，往外便走。有一个道：‘我们住在这里一向，如不别而行，觉道忒薄情了。’遂俱复转身向老汉道：‘久承照管，如今却要抛撇，幸勿见怪！’那时老汉梦中，不认得那八个小厮是谁，也不晓得是何处来的，问他道：‘八位小官人是几时来的？如何都不相认？’小厮答道：‘我们自到你家，与你只会得一面，你就把我们撇在脑后，故此我们便认得你，你却不认得我。’又指腰间红绦道：‘这还是初会这次，承你送的，你记得了么？’老汉一时想不着几时与他的，心中止挂欠无子，见其清秀，欲要他做个干儿，又对他道：‘既承你们到此，何不住在这里，父子相看，帮我做个人家？怎么又要往别处去？’八个小厮笑道：‘你要我们做儿子，不过要送终之意。但我们该旺处去的。你这老官儿消受不起。’道罢，一齐往外而去。老汉此时觉道睡在床上，不知怎地身子已到门首，再三留之，头也不回，惟闻得说道：‘天色晏了，快走罢。’一齐乱跑。老汉追将上去，被草根绊了一交，惊醒转来，与老荆说知，因疑惑这八锭银子作怪。到早上拆开枕看时，都已去了。欲要试验此梦，故特来相访，不想果然。”","施复听罢，大惊道：“有这样奇事！老翁不必烦恼，同我到里面来坐。”薄老道：“这事已验，不必坐了。”施复道：“你老人家许多路来，料必也饿了，见成点心吃些去也好。”这薄老儿见留他吃点心，到也不辞，便随进来。只见新竖起三间堂屋，高大宽敞，木材巨壮，众匠人一个个乒乒乓乓，耳边惟闻斧凿之声，比平常愈加用力。你道为何这般勤谨？大凡新竖屋那日，定有个犒劳筵席，利市赏钱。这些匠人打点吃酒要钱，见家主进来，故便假殷勤讨好。薄老儿看着如此热闹，心下嗟叹道：“怪道这东西歉我消受他不起，要望旺处去，原来他家恁般兴头！咦，这银子却也势利得狠哩！”不一时，来至一小客座中，施复请他坐下，急到里边向浑家说知其事。喻氏亦甚怪异，乃对施复道：“这银子既是他送终之物，何不把来送还，做个人情也好。”施复道：“正有此念，故来与你商量。”","喻氏取出那八锭银子，把块布包好。施复袖了，分付讨些酒食与他吃，复到客座中摸出包来，道：“你看，可是那八锭么？”薄老儿接过打开一看，分毫不差，乃道：“正是这八个怪物！”那老儿把来左翻右相，看了一回，对着银子说道：“我想你缝在枕中，如何便会出来？黄江泾到此有十里之远，人也怕走，还要趁个船儿，你又没有脚，怎地一回儿就到了这里？”口中便说，心下又转着苦挣之难，失去之易，不觉眼中落下两点泪来。施复道：“老翁不必心伤！小子情愿送还，赠你老人家百年之用。”薄老道：“承官人厚情。但老汉无福享用，所以走了。今若拿去，少不得又要走的，何苦讨恁般烦恼吃！”施复道：“如今乃我送你的，料然无妨。”薄老只把手来摇道：“不要，不要！老汉也是个知命的，勉强来，一定不妙。”施复因他坚执不要，又到里边与浑家商议。喻氏道：“他虽不要，只我们心上过意不去。”又道：“他或者消受这十锭不起，一二锭量也不打紧。”施复道：“他执意一锭也不肯要。”喻氏道：“我有个道理在此。把两锭裹在馒头里，少顷送与他作点心，到家看见，自然罢了，难道又送来不成？”施复道：“此见甚妙。”","喻氏先支持酒肴出去。薄老坐了客位，施复对面相陪。薄老道：“没事打搅官人，不当人子！”施复道：“见成菜酒，何足挂齿！”当下三杯两盏，吃了一回。薄老儿不十分会饮，不觉半醉。施复讨饭与他吃饭，将要起身作谢，家人托出两个馒头。施复道：“两个粗点心，带在路上去吃。”薄老道：“老汉酒醉饭饱，连夜饭也不要吃了，路上如何又吃点心？”施复道：“总不吃，带回家去便了。”薄老儿道：“不消得，不消得！","老汉家中做这项生意的，日逐自有，官人留下赏人罢。”施复把来推在袖里道：“我这馒头馅好，比你铺中滋味不同。将回去吃，便晓得。”那老儿见其意殷勤，不好固辞，乃道：“没甚事到此，又吃又袖，罪过，罪过！”拱拱手道：“多谢了！”","往外就走。施复送出门前，那老儿自言自语道：“来便来了，如今去不知可就有便船？”施复见他醉了，恐怕遗失了这两个馒头，乃道：“老翁，不打紧，我家有船，教人送你回去。”那老儿点头道：“官人，难得你这样好心！可知有恁般造化！”施复唤个家人，分忖道：“你把船送这大伯子回去，务要送至家中，认了住处，下次好去拜访。”家人应诺。 薄老儿相辞下船，离了镇上，望黄江泾而去。那老儿因多了几杯酒，一路上问长问短，十分健谈。不一时已到，将船泊住，扶那老儿上岸，送到家中。妈妈接着，便问：“老官儿，可有这事么？”老儿答道：“千真万真。”口中便说，却去袖里摸出那两个馒头，递与施复家人道：“大官宅上事忙，不留吃茶了，这馒头转送你当茶罢。”施家人答道：“我官人特送你老人家的，如何却把与我？”薄老道：“你官人送我，已领过他的情了。如今送你，乃我之情，你不必固拒。”家人再三推却不过，只得受了，相别下船，依旧摇回。到自己河下，把船缆好，拿着馒头上岸。恰好施复出来，一眼看见，问道：“这馒头我送薄老官的，你如何拿了回来？”答道：“是他转送小人当茶，再三推辞不脱，勉强受了他的。”施复暗笑道：“原来这两锭银那老儿还没福受用，却又转送别人。”想道：“或者到是那人造化，也未可知。”乃分忖道：“这两个馒头滋味，比别的不同，莫要又与别人！”答应道：“小人晓得。”","那人来到里边寻着老婆，将馒头递与，还未开言说是那里来的，被伙伴中叫到外边吃酒去了。原来那人已有两个儿女，正害着疳膨食积病症。当下婆娘接在手中，想道：“若被小男女看见，偷去吃了，到是老大利害，不如把去大娘换些别样点心哄他罢。”即便走来向主母道：“大娘，丈夫适才不知那里拿这两个馒头，我想小男女正害肚腹病，傥看见偷吃了，这病却不一发加重！欲要求大娘换甚不伤脾胃的点心哄那两个男女。”说罢，将馒头放在卓上。喻氏不知其细，遂拣几件付与他去，将馒头放过。少顷，施复进来，把薄老转与家人馒头之事，说向浑家，又道：“谁想到是他的造化！”喻氏听了，乃知把来换点心的就是，答道：“元来如此，却也奇异！”便去拿那两个馒头，递与施复道：“你拍这馒头来看。”","施复不知何意，随手拍开，只听得卓上当的一响，举目看时，乃是一锭红绒束的银子，问道：“馒头如何你又取了他的？”喻氏将那婆娘来换点心之事说出。夫妻二人，不胜嗟叹。方知银子赶人，麾之不去；命里无时，求之不来。施复因怜念薄老儿，时常送些钱米与他，到做了亲戚往来。死后，又买块地儿殡葬。后来施德胤长大，娶朱恩女儿过门，夫妻孝顺。施复之富，冠于一镇。夫妇二人，各寿至八十外，无疾而终。至今子孙蕃衍，与滩阙朱氏世为姻谊云。有诗为证：六金还取事虽微，感德天心早鉴知。","滩阙巧逢恩义报，好人到底得便宜。"],"cpLength":13743},"xyj-01":{"chapterId":"xyj-01","bookId":"xyj","fileIndex":0,"number":1,"title":"第一回　灵根育孕源流出　心性修持大道生","paragraphs":["诗曰：　　混沌未分天地乱，茫茫渺渺无人见。","自从盘古破鸿蒙，开辟从兹清浊辨。","覆载群生仰至仁，发明万物皆成善。　　欲知造化会元功，须看西游释厄传。","盖闻天地之数，有十二万九千六百岁为一元。将一元分为十二会，乃子、丑、寅、卯、辰、巳、午、未、申、酉、戌、亥之十二支也。每会该一万八百岁。且就一日而论：子时得阳气，而丑则鸡鸣；寅不通光，而卯则日出；辰时食后，而巳则挨排；日午天中，而未则西蹉；申时晡而日落酉；戌黄昏而人定亥。譬于大数，若到戌会之终，则天地昏蒙而万物否矣。再去五千四百岁，交亥会之初，则当黑暗，而两间人物俱无矣，故曰混沌。又五千四百岁，亥会将终，贞下起元，近子之会，而复逐渐开明。邵康节曰：“冬至子之半，天心无改移。一阳初动处，万物未生时。”到此，天始有根。再五千四百岁，正当子会，轻清上腾，有日，有月，有星，有辰。日、月、星、辰，谓之四象。故曰，天开于子。又经五千四百岁，子会将终，近丑之会，而逐渐坚实。易曰：“大哉乾元！至哉坤元！万物资生，乃顺承天。”至此，地始凝结。再五千四百岁，正当丑会，重浊下凝，有水，有火，有山，有石，有土。水、火、山、石、土谓之五形。故曰，地辟于丑。又经五千四百岁，丑会终而寅会之初，发生万物。历曰：“天气下降，地气上升；天地交合，群物皆生。”至此，天清地爽，阴阳交合。再五千四百岁，正当寅会，生人，生兽，生禽，正谓天地人，三才定位。故曰，人生于寅。","感盘古开辟，三皇治世，五帝定伦，世界之间，遂分为四大部洲：曰东胜神洲，曰西牛贺洲，曰南赡部洲，曰北俱芦洲。这部书单表东胜神洲。海外有一国土，名曰傲来国。国近大海，海中有一座山，唤为花果山。此山乃十洲之祖脉，三岛之来龙，自开清浊而立，鸿蒙判后而成。真个好山！有词赋为证。赋曰：　　势镇汪洋，威宁瑶海。势镇汪洋，潮涌银山鱼入穴；威宁瑶海，波翻雪浪蜃离渊。木火方隅高积上，东海之处耸崇巅。丹崖怪石，削壁奇峰。丹崖上，彩凤双鸣；削壁前，麒麟独卧。峰头时听锦鸡鸣，石窟每观龙出入。林中有寿鹿仙狐，树上有灵禽玄鹤。瑶草奇花不谢，青松翠柏长春。仙桃常结果，修竹每留云。一条涧壑藤萝密，四面原堤草色新。正是百川会处擎天柱，万劫无移大地根。那座山，正当顶上，有一块仙石。其石有三丈六尺五寸高，有二丈四尺围圆。三丈六尺五寸高，按周天三百六十五度；二丈四尺围圆，按政历二十四气。上有九窍八孔，按九宫八卦。四面更无树木遮阴，左右倒有芝兰相衬。盖自开辟以来，每受天真地秀，日精月华，感之既久，遂有灵通之意。内育仙胞，一日迸裂，产一石卵，似圆球样大。因见风，化作一个石猴，五官俱备，四肢皆全。便就学爬学走，拜了四方。目运两道金光，射冲斗府。惊动高天上圣大慈仁者玉皇大天尊玄穹高上帝，驾座金阙云宫灵霄宝店，聚集仙卿，见有金光焰焰，即命千里眼、顺风耳开南天门观看。二将果奉旨出门外，看的真，听的明。须臾回报道：“臣奉旨观听金光之处，乃东胜神洲海东傲来小国之界，有一座花果山，山上有一仙石，石产一卵，见风化一石猴，在那里拜四方，眼运金光，射冲斗府。如今服饵水食，金光将潜息矣。”玉帝垂赐恩慈曰：“下方之物，乃天地精华所生，不足为异。”","那猴在山中，却会行走跳跃，食草木，饮涧泉，采山花，觅树果；与狼虫为伴，虎豹为群，獐鹿为友，猕猿为亲；夜宿石崖之下，朝游峰洞之中。真是“山中无甲子，寒尽不知年。”一朝天气炎热，与群猴避暑，都在松阴之下顽耍。你看他一个个：","跳树攀枝，采花觅果；抛弹子，邷么儿；跑沙窝，砌宝塔；赶蜻蜓，扑八蜡；参老天，拜菩萨；扯葛藤，编草帓；捉虱子，咬又掐；理毛衣，剔指甲；挨的挨，擦的擦；推的推，压的压；扯的扯，拉的拉，青松林下任他顽，绿水涧边随洗濯。一群猴子耍了一会，却去那山涧中洗澡。见那股涧水奔流，真个似滚瓜涌溅。古云：“禽有禽言，兽有兽语。”众猴都道：“这股水不知是那里的水。我们今日赶闲无事，顺涧边往上溜头寻看源流，耍子去耶！”喊一声，都拖男挈女，呼弟呼兄，一齐跑来，顺涧爬山，直至源流之处，乃是一股瀑布飞泉。但见那：","一派白虹起，千寻雪浪飞；海风吹不断，江月照还依。","冷气分青嶂，馀流润翠微；潺湲名瀑布，真似挂帘帷。","众猴拍手称扬道：“好水！好水！原来此处远通山脚之下，直接大海之波。”又道：“那一个有本事的，钻进去寻个源头出来，不伤身体者，我等即拜他为王。”连呼了三声，忽见丛杂中跳出一名石猴，应声高叫道：“我进去！我进去！”好猴！也是他：","今日芳名显，时来大运通；有缘居此地，王遣入仙宫。","你看他瞑目蹲身，将身一纵，径跳入瀑布泉中，忽睁睛抬头观看，那里边却无水无波，明明朗朗的一架桥梁。他住了身，定了神，仔细再看，原来是座铁板桥。桥下之水，冲贯于石窍之间，倒挂流出去，遮闭了桥门。却又欠身上桥头，再走再看，却似有人家住处一般，真个好所在。但见那：","翠藓堆蓝，白云浮玉，光摇片片烟霞。虚窗静室，滑凳板生花。乳窟龙珠倚挂，萦回满地奇葩。锅灶傍崖存火迹，樽罍靠案见肴渣。石座石床真可爱，石盆石碗更堪夸。又见那一竿两竿修竹，三点五点梅花。","几树青松常带雨，浑然相个人家。","看罢多时，跳过桥中间，左右观看，只见正当中有一石碣。碣上有一行楷书大字，镌着“花果山福地，水帘洞洞天。”石猴喜不自胜，急抽身往外便走，复瞑目蹲身，跳出水外，打了两个呵呵道：“大造化！大造化！”众猴把他围住，问道：“里面怎么样？水有多深？”石猴道：“没水！没水！原来是一座铁板桥。桥那边是一座天造地设的家当。”众猴道：“怎见得是个家当？”石猴笑道：“这股水乃是桥下冲贯石桥，倒挂下来遮闭门户的。桥边有花有树，乃是一座石房。房内有石窝、石灶、石碗、石盆、石床、石凳。中间一块石碣上，镌着‘花果山福地，水帘洞洞天。’真个是我们安身之处。里面且是宽阔，容得千百口老小。我们都进去住也，省得受老天之气。这里边：","刮风有处躲，下雨好存身。霜雪全无惧，雷声永不闻。","烟霞常照耀，祥瑞每蒸熏。松竹年年秀，奇花日日新。”","众猴听得，个个欢喜，都道：“你还先走，带我们进去，进去！”石猴却又瞑目蹲身，往里一跳，叫道：“都随我进来！进来！”那些猴有胆大的，都跳进去了；胆小的，一个个伸头缩颈，抓耳挠腮，大声叫喊，缠一会，也都进去了。跳过桥头，一个个抢盆夺碗，占灶争床，搬过来，移过去，正是猴性顽劣，再无一个宁时，只搬得力倦神疲方止。石猿端坐上面道：“列位呵，‘人而无信，不知其可。’你们才说有本事进得来，出得去，不伤身体者，就拜他为王。我如今进来又出去，出去又进来，寻了这一个洞天与列位安眠稳睡，各享成家之福，何不拜我为王？”众猴听说，即拱伏无违。一个个序齿排班，朝上礼拜，都称“千岁大王”。自此，石猴高登王位，将“石”字儿隐了，遂称美猴王。有诗为证。诗曰：　　三阳交泰产群生，仙石胞含日月精。","借卵化猴完大道，假他名姓配丹成。","内观不识因无相，外合明知作有形。","历代人人皆属此，称王称圣任纵横。美猴王领一群猿猴、猕猴、马猴等，分派了君臣佐使，朝游花果山，暮宿水帘洞，合契同情，不入飞鸟之丛，不从走兽之类，独自为王，不胜欢乐。是以：　　春采百花为饮食，夏寻诸果作生涯。　　秋收芋栗延时节，冬觅黄精度岁华。","美猴王享乐天真，何期有三五百载。一日，与群猴喜宴之间，忽然忧恼，堕下泪来。众猴慌忙罗拜道：“大王何为烦恼？”猴王道：“我虽在欢喜之时，却有一点儿远虑，故此烦恼。”众猴又笑道：“大王好不知足！我等日日欢会，在仙山福地，古洞神州，不伏麒麟辖，不伏凤凰管，又不伏人间王位所拘束，自由自在，乃无量之福，为何远虑而忧也？”猴王道：“今日虽不归人王法律，不惧禽兽威服，将来年老血衰，暗中有阎王老子管着，一旦身亡，可不枉生世界之中，不得久住天人之内？”众猴闻此言，一个个掩面悲啼，俱以无常为虑。","只见那班部中，忽跳出一个通背猿猴，厉声高叫道：“大王若是这般远虑，真所谓道心开发也！如今五虫之内，惟有三等名色，不伏阎王老子所管。”猴王道：“你知那三等人？”猿猴道：“乃是佛与仙与神圣三者，躲过轮回，不生不灭，与天地山川齐寿。”猴王道：“此三者居于何所？”猿猴道：“他只在阎浮世界之中，古洞仙山之内。”猴王闻之，满心欢喜，道：“我明日就辞汝等下山，云游海角，远涉天涯，务必访此三者，学一个不老长生，常躲过阎君之难。”噫！这句话，顿教跳出轮回网，致使齐天大圣成。众猴鼓掌称扬，都道：“善哉！善哉！我等明日越岭登山，广寻些果品，大设筵宴送大王也。”","次日，众猴果去采仙桃，摘异果，刨山药，□「左“属”右“立刀”」黄精，芝兰香蕙，瑶草奇花，般般件件，整整齐齐，摆开石凳石桌，排列仙酒仙肴。但见那：","金丸珠弹，红绽黄肥。金丸珠弹腊樱桃，色真甘美；红绽黄肥熟梅子，味果香酸。鲜龙眼，肉甜皮薄；火荔枝，核小囊红。林檎碧实连枝献，枇杷缃苞带叶擎。兔头梨子鸡心枣，消渴除烦更解酲。香桃烂杏，美甘甘似玉液琼浆；脆李杨梅，酸荫荫如脂酸膏酪。红囊黑子熟西瓜，四瓣黄皮大柿子。石榴裂破，丹砂粒现火晶珠；芋栗剖开，坚硬肉团金玛瑙。胡桃银杏可传茶，椰子葡萄能做酒。榛松榧柰满盘盛，橘蔗柑橙盈案摆。熟煨山药，烂煮黄精，捣碎茯苓并薏苡，石锅微火漫炊羹。人间纵有珍馐味，怎比山猴乐更宁？群猴尊美猴王上坐，各依齿肩排于下边，一个个轮流上前，奉酒，奉花，奉果，痛饮了一日。次日，美猴王早起，教：“小的们，替我折些枯松，编作筏子，取个竹竿作篙，收拾些果品之类，我将去也。”果独自登筏，尽力撑开，飘飘荡荡，径向大海波中，趁天风，来渡南赡部洲地界。这一去，正是那：","天产仙猴道行隆，离山驾筏趁天风。","飘洋过海寻仙道，立志潜心建大功。","有分有缘休俗愿，无忧无虑会元龙。","料应必遇知音者，说破源流万法通。也是他运至时来，自登木筏之后，连日东南风紧，将他送到西北岸前，乃是南赡部洲地界。持篙试水，偶得浅水，弃了筏子，跳上岸来，只见海边有人捕鱼、打雁、挖蛤、淘盐。他走近前，弄个把戏，妆个□「上左“齿”右“可”，下“女”」虎，吓得那些人丢筐弃网，四散奔跑。将那跑不动的拿住一个，剥了他衣裳，也学人穿在身上，摇摇摆摆，穿州过府，在市尘中，学人礼，学人话。朝餐夜宿，一心里访问佛仙神圣之道，觅个长生不老之方。见世人都是为名为利之徒，更无一个为身命者。正是那：","争名夺利几时休？早起迟眠不自由！","骑着驴骡思骏马，官居宰相望王侯。","只愁衣食耽劳碌，何怕阎君就取勾？","继子荫孙图富贵，更无一个肯回头！","猴王参访仙道，无缘得遇。在于南赡部洲，串长城，游小县，不觉八九年馀。忽行至西洋大海，他想着海外必有神仙。独自个依前作筏，又飘过西海，直至西牛贺洲地界。登岸偏访多时，忽见一座高山秀丽，林麓幽深。他也不怕狼虫，不惧虎豹，登山顶上观看。果是好山：","千峰开戟，万仞开屏。日映岚光轻锁翠，雨收黛色冷含青。枯藤缠老树，古渡界幽程。奇花瑞草，修竹乔松。修竹乔松，万载常青欺福地；奇花瑞草，四时不谢赛蓬瀛。幽鸟啼声近，源泉响溜清。重重谷壑芝兰绕，处处巉崖苔藓生。起伏峦头龙脉好，必有高人隐姓名。","正观看间，忽闻得林深之处，有人言语，急忙趋步，穿入林中，侧耳而听，原来是歌唱之声。歌曰：","“观棋柯烂，伐木丁丁，云边谷口徐行，卖薪沽酒，狂笑自陶情。苍迳秋高，对月枕松根，一觉天明。认旧林，登崖过岭，持斧断枯藤。","收来成一担，行歌市上，易米三升。更无些子争竞，时价平平，不会机谋巧算，没荣辱，恬淡延生。相逢处，非仙即道，静坐讲黄庭。”美猴王听得此言，满心欢喜道：“神仙原来藏在这里！”急忙跳入里面，仔细再看，乃是一个樵子，在那里举斧砍柴。但看他打扮非常：","头上戴箬笠，乃是新笋初脱之箨。身上穿布衣，乃是木绵捻就之纱。腰间系环绦，乃是老蚕口吐之丝。足下踏草履，乃是枯莎搓就之爽。手执衠钢斧，担挽火麻绳。扳松劈枯树，争似此樵能！","猴王近前叫道：“老神仙！弟子起手。”那樵汉慌忙丢了斧，转身答礼道：“不当人！不当人！我拙汉衣食不全，怎敢当‘神仙’二字？”猴王道：“你不是神仙，如何说出神仙的话来？”樵夫道：“我说甚么神仙话？”猴王道：“我才来至林边，只听的你说：‘相逢处非仙即道，静坐讲黄庭。’黄庭乃道德真言，非神仙而何？”樵夫笑道：“实不瞒你说，这个词名做满庭芳，乃一神仙教我的。那神仙与我舍下相邻。他见我家事劳苦，日常烦恼，教我遇烦恼时，即把这词儿念念。一则散心，二则解困。我才有些不足处思虑，故此念念。不期被你听了。”猴王道：“你家既与神仙相邻，何不从他修行？学得个不老之方？却不是好？”樵夫道：“我一生命苦，自幼蒙父母养育至八九岁，才知人事，不幸父丧，母亲居孀。再无兄弟姊妹，只我一人，没奈何，早晚侍奉。如今母老，一发不敢抛离。却又田园荒芜，衣食不足，只得斫两束柴薪，挑向市尘之间，货几文钱，籴几升米，自炊自造，安排些茶饭，供养老母，所以不能修行。”","猴王道：“据你说起来，乃是一个行孝的君子，向后必有好处。但望你指与我那神仙住处，却好拜访去也。”樵夫道：“不远，不远。此山叫做灵台方寸山。山中有座斜月三星洞。那洞中有一个神仙，称名须菩提祖师。那祖师出去的徒弟，也不计其数，见今还有三四十人从他修行。你顺那条小路儿，向南行七八里远近，即是他家了。”猴王用手扯住樵夫道：“老兄，你便同我去去。若还得了好处，决不忘你指引之恩。”樵夫道：“你这汉子，甚不通变。我方才这般与你说了，你还不省？假若我与你去了，却不误了我的生意？老母何人奉养？我要斫柴，你自去，自去。”","猴王听说，只得相辞。出深林，找上路径，过一山坡，约有七八里远，果然望见一座洞府。挺身观看，真好去处！但见：　　烟霞散彩，日月摇光。千株老柏，万节修篁。千株老柏，带雨半空青冉冉；万节修篁，含烟一壑色苍苍。门外奇花布锦，桥边瑶草喷香。石崖突兀青苔润，悬壁高张翠藓长。时闻仙鹤唳，每见凤凰翔。仙鹤唳时，声振九皋霄汉远；凤凰翔起，翎毛五色彩云光。玄猿白鹿随隐见，金狮玉象任行藏。细观灵福地，真个赛天堂！又见那洞门紧闭，静悄悄杳无人迹。忽回头，见崖头立一石牌，约有三丈馀高、八尺馀阔，上有一行十个大字，乃是“灵台方寸山，斜月三星洞”。美猴王十分欢喜道：“此间人果是朴实。果有此山此洞。”看勾多时，不敢敲门。且去跳上松枝梢头，摘松子吃了顽耍。　　少顷间，只听得呀的一声，洞门开处，里面走出一个仙童，真个丰姿英伟，像貌清奇，比寻常俗子不同。但见他：　　髽髻双丝绾，宽袍两袖风。貌和身自别，心与相俱空。","物外长年客，山中永寿童。一尘全不染，甲子任翻腾。","那童子出得门来，高叫道：“甚么人在此搔扰？”猴王扑的跳下树来，上前躬身道：“仙童，我是个访道学仙之弟子，更不敢在此搔扰。”仙童笑道：“你是个访道的么？”猴王道：“是。”童子道：“我家师父，正才下榻，登坛讲道。还未说出原由，就教我出来开门。说：‘外面有个修行的来了，可去接待接待。’想必就是你了？”猴王笑道：“是我，是我。”童子道：“你跟我进来。”","这猴王整衣端肃，随童子径入洞天深处观看：一层层深阁琼楼，一进进珠宫贝阙，说不尽那静室幽居，直至瑶台之下。见那菩提祖师端坐在台上，两边有三十个小仙侍立台下。果然是：","大觉金仙没垢姿，西方妙相祖菩提；","不生不灭三三行，全气全神万万慈。","空寂自然随变化，真如本性任为之；","与天同寿庄严体，历劫明心大法师。　　美猴王一见，倒身下拜，磕头不计其数，口中只道：“师父！师父！我弟子志心朝礼！志心朝礼！”祖师道：“你是那方人氏？且说个乡贯姓名明白，再拜。”猴王道：“弟子东胜神洲傲来国花果山水帘洞人氏。”祖师喝令：“赶出去！他本是个撒诈捣虚之徒，那里修甚么道果！”猴王慌忙磕头不住道：“弟子是老实之言，决无虚诈。”祖师道：“你既老实，怎么说东胜神洲？那去处到我这里，隔两重大海，一座南赡部洲，如何就得到此？”猴王叩头道：“弟子飘洋过海，登界游方，有十数个年头，方才访到此处。”　　祖师道：“既是逐渐行来的也罢。你姓甚么？”猴王又道：“我无性。人若骂我，我也不恼；若打我，我也不嗔，只是陪个礼儿就罢了。一生无性。”祖师道：“不是这个性。你父母原来姓甚么？”猴王道：“我也无父母。”祖师道：“既无父母，想是树上生的？”猴王道：“我虽不是树生，却是石里长的。我只记得花果山上有一块仙石，其年石破，我便生也。”祖师闻言，暗喜道：“这等说，却是天地生成的。你起来走走我看。”猴王纵身跳起，拐呀拐的走了两遍。祖师笑道：“你身躯虽是鄙陋，却像个食松果的猢狲。我与你就身上取个姓氏，意思教你姓‘猢’。猢字去了个兽傍，乃是古月。古者，老也；月者，阴也。老阴不能化育，教你姓‘狲’倒好。狲字去了兽傍，乃是个子系。子者，儿男也；系者，婴细也。正合婴儿之本论。教你姓‘孙’罢。”猴王听说，满心欢喜，朝上叩头道：“好！好！好！今日方知姓也。万望师父慈悲！既然有姓，再乞赐个名字，却好呼唤。”祖师道：“我门中有十二个字，分派起名到你乃第十辈之小徒矣。”猴王道：“那十二个字？”祖师道：“乃广、大、智、慧、真、如、性、海、颖、悟、圆、觉十二字。排到你，正当‘悟’字。与你起个法名叫做‘孙悟空’好么？”猴王笑道：“好！好！好！自今就叫做孙悟空也！”正是：鸿蒙初辟原无姓，打破顽空须悟空。　　毕竟不之向后修些甚么道果，且听下回分解。"],"cpLength":6985},"xyj-14":{"chapterId":"xyj-14","bookId":"xyj","fileIndex":13,"number":14,"title":"第十四回　心猿归正　六贼无踪","paragraphs":["诗曰：佛即心兮心即佛，心佛从来皆要物。若知无物又无心，便是真如法身佛。法身佛，没模样，一颗圆光涵万象。无体之体即真体，无相之相即实相。非色非空非不空，不来不向不回向。无异无同无有无，难舍难取难听望。内外灵光到处同，一佛国在一沙中。一粒沙含大千界，一个身心万法同。知之须会无心诀，不染不滞为净业。善恶千端无所为，便是南无释迦叶。却说那刘伯钦与唐三藏惊惊慌慌，又闻得叫声师父来也。","众家僮道：“这叫的必是那山脚下石匣中老猿。”太保道：“是他！是他！”三藏问：“是甚么老猿？”太保道：“这山旧名五行山，因我大唐王征西定国，改名两界山。先年间曾闻得老人家说：","‘王莽篡汉之时，天降此山，下压着一个神猴，不怕寒暑，不吃饮食，自有土神监押，教他饥餐铁丸，渴饮铜汁。自昔到今，冻饿不死。’这叫必定是他。长老莫怕，我们下山去看来。”三藏只得依从，牵马下山。行不数里，只见那石匣之间，果有一猴，露着头，伸着手，乱招手道：“师父，你怎么此时才来？来得好！来得好！救我出来，我保你上西天去也！”这长老近前细看，你道他是怎生模样：尖嘴缩腮，金睛火眼。头上堆苔藓，耳中生薜萝。鬓边少发多青草，颔下无须有绿莎。眉间土，鼻凹泥，十分狼狈，指头粗，手掌厚，尘垢余多。还喜得眼睛转动，喉舌声和。 　　语言虽利便，身体莫能那。正是五百年前孙大圣，今朝难满脱天罗。","这太保诚然胆大，走上前来，与他拔去了鬓边草，颔下莎，问道：“你有甚么说话？”那猴道：“我没话说，教那个师父上来，我问他一问。”三藏道：“你问我甚么？”那猴道：“你可是东土大王差往西天取经去的么？”三藏道：“我正是，你问怎么？”那猴道：“我是五百年前大闹天宫的齐天大圣，只因犯了诳上之罪，被佛祖压于此处。前者有个观音菩萨，领佛旨意，上东土寻取经人。我教他救我一救，他劝我再莫行凶，归依佛法，尽殷勤保护取经人，往西方拜佛，功成后自有好处。故此昼夜提心，晨昏吊胆，只等师父来救我脱身。我愿保你取经，与你做个徒弟。”","三藏闻言，满心欢喜道：“你虽有此善心，又蒙菩萨教诲，愿入沙门，只是我又没斧凿，如何救得你出？”那猴道：“不用斧凿，你但肯救我，我自出来也。”三藏道：“我自救你，你怎得出来？” 　　那猴道：“这山顶上有我佛如来的金字压帖。你只上出去将帖儿揭起，我就出来了。”三藏依言，回头央浼刘伯钦道：“太保啊，我与你上出走一遭。”伯钦道：“不知真假何如！”那猴高叫道：“是真！决不敢虚谬！”伯钦只得呼唤家僮，牵了马匹。他却扶着三藏，复上高山，攀藤附葛，只行到那极巅之处，果然见金光万道，瑞气千条，有块四方大石，石上贴着一封皮，却是“唵、嘛、呢、叭、、吽”六个金字。三藏近前跪下，朝石头，看着金字，拜了几拜，望西祷祝道：“弟子陈玄奘，特奉旨意求经，果有徒弟之分，揭得金字，救出神猴，同证灵山；若无徒弟之分，此辈是个凶顽怪物，哄赚弟子，不成吉庆，便揭不得起。”祝罢，又拜。拜毕，上前将六个金字轻轻揭下。只闻得一阵香风，劈手把压帖儿刮在空中，叫道：“吾乃监押大圣者。今日他的难满，吾等回见如来，缴此封皮去也。”吓得个三藏与伯钦一行人，望空礼拜。径下高山，又至石匣边，对那猴道：“揭了压帖矣，你出来么。”那猴欢喜，叫道：“师父，你请走开些，我好出来，莫惊了你。”伯钦听说，领着三藏，一行人回东即走。走了五七里远近，又听得那猴高叫道：“再走！再走！”三藏又行了许远，下了山，只闻得一声响亮，真个是地裂山崩。众人尽皆悚惧，只见那猴早到了三藏的马前，赤淋淋跪下，道声“师父，我出来也！”对三藏拜了四拜，急起身，与伯钦唱个大喏道：“有劳大哥送我师父，又承大哥替我脸上薅草。”谢毕，就去收拾行李，扣背马匹。","那马见了他，腰软蹄矬，战兢兢的立站不住。盖因那猴原是弼马温，在天上看养龙马的，有些法则，故此凡马见他害怕。","三藏见他意思，实有好心，真个象沙门中的人物，便叫：","“徒弟啊，你姓甚么？”猴王道：“我姓孙。”三藏道：“我与你起个法名，却好呼唤。”猴王道：“不劳师父盛意，我原有个法名，叫做孙悟空。”三藏欢喜道：“也正合我们的宗派。你这个模样，就象那小头陀一般，我再与你起个混名，称为行者，好么？”悟空道：“好！好！好！”自此时又称为孙行者。那伯钦见孙行者一心收拾要行，却转身对三藏唱个喏道：“长老，你幸此间收得个好徒，甚喜甚喜，此人果然去得。我却告回。”三藏躬身作礼相谢道：“多有拖步，感激不胜。回府多多致意令堂老夫人，令荆夫人，贫僧在府多扰，容回时踵谢。”伯钦回礼，遂此两下分别。","却说那孙行者请三藏上马，他在前边，背着行李，赤条条，拐步而行。不多时，过了两界山，忽然见一只猛虎，咆哮剪尾而来，三藏在马上惊心。行者在路旁欢喜道：“师父莫怕他，他是送衣服与我的。”放下行李，耳朵里拔出一个针儿，迎着风，幌一幌，原来是个碗来粗细一条铁棒。他拿在手中，笑道：“这宝贝，五百余年不曾用着他，今日拿出来挣件衣服儿穿穿。”你看他拽开步，迎着猛虎，道声“业畜！那里去！”那只虎蹲着身，伏在尘埃，动也不敢动动。却被他照头一棒，就打的脑浆迸万点桃红，牙齿喷几点玉块，唬得那陈玄奘滚鞍落马，咬指道声“天哪！天哪！刘太保前日打的斑斓虎，还与他斗了半日；今日孙悟空不用争持，把这虎一棒打得稀烂，正是强中更有强中手！”","行者拖将虎来道：“师父略坐一坐，等我脱下他的衣服来，穿了走路。”三藏道：“他那里有甚衣服？”行者道：“师父莫管我，我自有处置。”好猴王，把毫毛拔下一根，吹口仙气，叫“变！”变作一把牛耳尖刀，从那虎腹上挑开皮，往下一剥，剥下个囫囵皮来，剁去了爪甲，割下头来，割个四四方方一块虎皮，提起来，量了一量道：“阔了些儿，一幅可作两幅。”拿过刀来，又裁为两幅。收起一幅，把一幅围在腰间，路旁揪了一条葛藤，紧紧束定，遮了下体道：“师父，且去！且去！到了人家，借些针线，再缝不迟。”他把条铁棒，捻一捻，依旧象个针儿，收在耳里，背着行李，请师父上马。","两个前进，长老在马上问道：“悟空，你才打虎的铁棒，如何不见？”行者笑道：“师父，你不晓得。我这棍，本是东洋大海龙宫里得来的，唤做天河镇底神珍铁，又唤做如意金箍棒。当年大反天宫，甚是亏他。随身变化，要大就大，要小就小。刚才变做一个绣花针儿模样，收在耳内矣。但用时，方可取出。”三藏闻言暗喜。又问道：“方才那只虎见了你，怎么就不动动，让自在打他，何说？悟空道：“不瞒师父说，莫道是只虎，就是一条龙，见了我也不敢无礼。我老孙，颇有降龙伏虎的手段，翻江搅海的神通，见貌辨色，聆音察理，大之则量于宇宙，小之则摄于毫毛！变化无端，隐显莫测。剥这个虎皮，何为稀罕？见到那疑难处，看展本事么！”三藏闻得此言，愈加放怀无虑，策马前行。师徒两个走着路，说着话，不觉得太阳星坠，但见：焰焰斜辉返照，天涯海角归云。千出鸟雀噪声频，觅宿投林成阵。野兽双双对对，回窝族族群群。一勾新月破黄昏，万点明星光晕。","行者道：师父走动些，天色晚了。那壁厢树木森森，想必是人家庄院，我们赶早投宿去来。”三藏果策马而行，径奔人家，到了庄院前下马。行者撇了行李，走上前，叫声“开门！开门！”那里面有一老者，扶筇而出，唿喇的开了门，看见行者这般恶相，腰系着一块虎皮，好似个雷公模样，唬得脚软身麻，口出谵语道：","“鬼来了！鬼来了！”三藏近前搀住叫道：“老施主，休怕。他是我贫僧的徒弟，不是鬼怪。”老者抬头，见了三藏的面貌清奇，方然立定，问道：“你是那寺里来的和尚，带这恶人上我门来？”","三藏道：“我贫僧是唐朝来的，往西天拜佛求经，适路过此间，天晚，特造檀府借宿一宵，明早不犯天光就行。万望方便一二。”老者道：“你虽是个唐人，那个恶的却非唐人。”悟空厉声高呼道：“你这个老儿全没眼色！唐人是我师父，我是他徒弟！ 　　我也不是甚糖人蜜人，我是齐天大圣。你们这里人家，也有认得我的，我也曾见你来。”那老者道：“你在那里见我？”悟空道：","“你小时不曾在我面前扒柴？不曾在我脸上挑菜？”老者道：“这厮胡说！你在那里住？我在那里住？我来你面前扒柴挑菜！” 　　悟空道：“我儿子便胡说！你是认不得我了，我本是这两界山石匣中的大圣。你再认认看。”老者方才省悟道：“你倒有些象他，但你是怎么得出来的？”悟空将菩萨劝善、令我等待唐僧揭贴脱身之事，对那老者细说了一遍。老者却才下拜，将唐僧请到里面，即唤老妻与儿女都来相见，具言前事，个个欣喜。又命看茶，茶罢，问悟空道：“大圣啊，你也有年纪了？”悟空道：“你今年几岁了？”老者道：“我痴长一百三十岁了。”行者道：“还是我重子重孙哩！我那生身的年纪，我不记得是几时，但只在这山脚下，已五百余年了。”老者道：“是有，是有。我曾记得祖公公说，此山乃从天降下，就压了一个神猴。只到如今，你才脱体。","我那小时见你，是你头上有草，脸上有泥，还不怕你；如今脸上无了泥，头上无了草，却象瘦了些，腰间又苫了一块大虎皮，与鬼怪能差多少？”","一家儿听得这般话说，都呵呵大笑。这老儿颇贤，即今安排斋饭。饭后，悟空道：“你家姓甚？”老者道：“舍下姓陈。”三藏闻言，即下来起手道：“老施主，与贫僧是华宗。”行者道：“师父，你是唐姓，怎的和他是华宗？”三藏道：“我俗家也姓陈，乃是唐朝海州弘农郡聚贤庄人氏。我的法名叫做陈玄奘。只因我大唐太宗皇帝赐我做御弟三藏，指唐为姓，故名唐僧也。”那老者见说同姓，又十分欢喜。行者道：“老陈，左右打搅你家。我有五百多年不洗澡了，你可去烧些汤来，与我师徒们洗浴洗浴，一发临行谢你。”那老儿即令烧汤拿盆，掌上灯火。师徒浴罢，坐在灯前，行者道：“老陈，还有一事累你，有针线借我用用。”那老儿道：“有，有，有。”即教妈妈取针线来，递与行者。行者又有眼色，见师父洗浴，脱下一件白布短小直裰未穿，他即扯过来披在身上，却将那虎皮脱下，联接一处，打一个马面样的折子，围在腰间，勒了藤条，走到师父面前道：“老孙今日这等打扮，比昨日如何？”三藏道：“好！好！好！这等样，才象个行者。”三藏道：“徒弟，你不嫌残旧，那件直裰儿，你就穿了罢。”悟空唱个喏道：“承赐！承赐！”他又去寻些草料喂了马。此时各各事毕，师徒与那老儿，亦各归寝。","次早，悟空起来，请师父走路。三藏着衣，教行者收拾铺盖行李。正欲告辞，只见那老儿，早具脸汤，又具斋饭。斋罢，方才起身。三藏上马，行者引路，不觉饥餐渴饮，夜宿晓行，又值初冬时候，但见那：霜凋红叶千林瘦，岭上几株松柏秀。未开梅蕊散香幽，暖短昼，小春候，菊残荷尽山茶茂。寒桥古树争枝斗，曲涧涓涓泉水溜。淡云欲雪满天浮，朔风骤，牵衣袖，向晚寒威人怎受？师徒们正走多时，忽见路旁唿哨一声，闯出六个人来，各执长枪短剑，利刃强弓，大咤一声道：“那和尚！那里走！赶早留下马匹，放下行李，饶你性命过去！”唬得那三藏魂飞魄散，跌下马来，不能言语。行者用手扶起道：“师父放心，没些儿事，这都是送衣服送盘缠与我们的。”三藏道：“悟空，你想有些耳闭？他说教我们留马匹、行李，你倒问他要甚么衣服、盘缠？”行者道：“你管守着衣服、行李、马匹，待老孙与他争持一场，看是何如。”三藏道：“好手不敌双拳，双拳不如四手。他那里六条大汉，你这般小小的一个人儿，怎么敢与他争持？”","行者的胆量原大，那容分说，走上前来，叉手当胸，对那六个人施礼道：“列位有甚么缘故，阻我贫僧的去路？”那人道： 　　“我等是剪径的大王，行好心的山主。大名久播，你量不知，早早的留下东西，放你过去；若道半个不字，教你碎尸粉骨！”行者道：“我也是祖传的大王，积年的山主，却不曾闻得列位有甚大名。”那人道：“你是不知，我说与你听：一个唤做眼看喜，一个唤做耳听怒，一个唤做鼻嗅爱，一个唤作舌尝思，一个唤作意见欲，一个唤作身本忧。”悟空笑道：“原来是六个毛贼！你却不认得我这出家人是你的主人公，你倒来挡路。把那打劫的珍宝拿出来，我与你作七分儿均分，饶了你罢！”那贼闻言，喜的喜，怒的怒，爱的爱，思的思，欲的欲，忧的忧，一齐上前乱嚷道：“这和尚无礼！你的东西全然没有，转来和我等要分东西！” 　　他轮枪舞剑，一拥前来，照行者劈头乱砍，乒乒乓乓，砍有七八十下。悟空停立中间，只当不知。那贼道：“好和尚！真个的头硬！”行者笑道：“将就看得过罢了！你们也打得手困了，却该老孙取出个针儿来耍耍。”那贼道：“这和尚是一个行针灸的郎中变的。我们又无病症，说甚么动针的话！”行者伸手去耳朵里拔出一根绣花针儿，迎风一幌，却是一条铁棒，足有碗来粗细，拿在手中道：“不要走！也让老孙打一棍儿试试手！”唬得这六个贼四散逃走，被他拽开步，团团赶上，一个个尽皆打死。剥了他的衣服，夺了他的盘缠，笑吟吟走将来道：“师父请行，那贼已被老孙剿了。”三藏道：“你十分撞祸！他虽是剪径的强徒，就是拿到官司，也不该死罪；你纵有手段，只可退他去便了，怎么就都打死？这却是无故伤人的性命，如何做得和尚？出家人扫地恐伤蝼蚁命，爱惜飞蛾纱罩灯。你怎么不分皂白，一顿打死？全无一点慈悲好善之心！早还是山野中无人查考；若到城市，倘有人一时冲撞了你，你也行凶，执着棍子，乱打伤人，我可做得白客，怎能脱身？”悟空道：“师父，我若不打死他，他却要打死你哩。”三藏道：“我这出家人，宁死决不敢行凶。我就死，也只是一身，你却杀了他六人，如何理说？此事若告到官，就是你老子做官，也说不过去。”行者道：“不瞒师父说，我老孙五百年前，据花果山称王为怪的时节，也不知打死多少人。假似你说这般到官，倒也得些状告是。”三藏道：“只因你没收没管，暴横人间，欺天诳上，才受这五百年前之难。今既入了沙门，若是还象当时行凶，一味伤生，去不得西天，做不得和尚！忒恶！忒恶！”原来这猴子一生受不得人气，他见三藏只管绪绪叨叨，按不住心头火发道：“你既是这等，说我做不得和尚，上不得西天，不必惩般绪咶恶我，我回去便了！”那三藏却不曾答应，他就使一个性子，将身一纵，说一声“老孙去也！”三藏急抬头，早已不见，只闻得呼的一声，回东而去。撇得那长老孤孤零零，点头自叹，悲怨不已，道：“这厮！这等不受教诲！我但说他几句，他怎么就无形无影的，径回去了？罢！罢！罢！也是我命里不该招徒弟，进人口！如今欲寻他无处寻，欲叫他叫不应，去来！","去来！”正是舍身拚命归西去，莫倚旁人自主张。","那长老只得收拾行李，捎在马上，也不骑马，一只手柱着锡杖，一只手揪着缰绳，凄凄凉凉，往西前进。行不多时，只见山路前面，有一个年高的老母，捧一件绵衣，绵衣上有一顶花帽。三藏见他来得至近，慌忙牵马，立于右侧让行。那老母问道：“你是那里来的长老，孤孤凄凄独行于此？”三藏道：“弟子乃东土大唐奉圣旨往西天拜活佛求真经者。”老母道：“西方佛乃大雷音寺天竺国界，此去有十万八千里路。你这等单人独马，又无个伴侣，又无个徒弟，你如何去得！”三藏道：“弟子日前收得一个徒弟，他性泼凶顽，是我说了他几句，他不受教，遂渺然而去也。”老母道：“我有这一领绵布直裰，一顶嵌金花帽，原是我儿子用的。他只做了三日和尚，不幸命短身亡。我才去他寺里，哭了一场，辞了他师父，将这两件衣帽拿来，做个忆念。长老啊，你既有徒弟，我把这衣帽送了你罢。”三藏道：“承老母盛赐，但只是我徒弟已走了，不敢领受。”老母道：“他那厢去了？”三藏道：“我听得呼的一声，他回东去了。”老母道：“东边不远，就是我家，想必往我家去了。我那里还有一篇咒儿，唤做定心真言，又名做紧箍儿咒。你可暗暗的念熟，牢记心头，再莫泄漏一人知道。我去赶上他，叫他还来跟你，你却将此衣帽与他穿戴。他若不服你使唤，你就默念此咒，他再不敢行凶，也再不敢去了。”三藏闻言，低头拜谢。那老母化一道金光，回东而去。三藏情知是观音菩萨授此真言，急忙撮土焚香，望东恳恳礼拜。拜罢，收了衣帽，藏在包袱中间，却坐于路旁，诵习那定心真言。来回念了几遍，念得烂熟，牢记心胸不题。","却说那悟空别了师父，一筋斗云，径转东洋大海。按住云头，分开水道，径至水晶宫前。早惊动龙王出来迎接，接至宫里坐下，礼毕、龙王道：“近闻得大圣难满，失贺！想必是重整仙山，复归古洞矣。”悟空道：“我也有此心性，只是又做了和尚了。”龙王道：“做甚和尚？”行者道：“我亏了南海菩萨劝善，教我正果，随东土唐僧，上西方拜佛，皈依沙门，又唤为行者了。”","龙王道：“这等真是可贺！可贺！这才叫做改邪归正，惩创善心。","既如此，怎么不西去，复东回何也？”行者笑道：“那是唐僧不识人性。有几个毛贼剪径，是我将他打死，唐僧就绪绪叨叨，说了我若干的不是，你想老孙，可是受得闷气的？是我撇了他，欲回本山，故此先来望你一望，求钟茶吃。”龙王道：“承降！承降！”","当时龙子龙孙即捧香茶来献。","茶毕，行者回头一看，见后壁上挂著一幅圯桥进履的画儿。行者道：“这是甚么景致？”龙王道：“大圣在先，此事在后，故你不认得。这叫做圯桥三进履。”行者道：“怎的是三进履？”","龙王道：“此仙乃是黄石公，此子乃是汉世张良。石公坐在圯桥上，忽然失履于桥下，遂唤张良取来。此子即忙取来，跪献于前。如此三度，张良略无一毫倨傲怠慢之心，石公遂爱他勤谨，夜授天书，着他扶汉。后果然运筹帷幄之中，决胜千里之外。太平后，弃职归山，从赤松子游，悟成仙道。大圣，你若不保唐僧，不尽勤劳，不受教诲，到底是个妖仙，休想得成正果。”悟空闻言，沉吟半晌不语。龙王道：“大圣自当裁处，不可图自在，误了前程。”悟空道：“莫多话，老孙还去保他便了。”龙王欣喜道： 　　“既如此，不敢久留，请大圣早发慈悲，莫要疏久了你师父。”行者见他催促请行，急耸身，出离海藏，驾着云，别了龙王。正走，却遇着南海菩萨。菩萨道：“孙悟空，你怎么不受教诲，不保唐僧，来此处何干？”慌得个行者在云端里施礼道：“向蒙菩萨善言，果有唐朝僧到，揭了压帖，救了我命，跟他做了徒弟。他却怪我凶顽，我才闪了他一闪，如今就去保他也。”菩萨道：“赶早去，莫错过了念头。”言毕各回。","这行者，须臾间看见唐僧在路旁闷坐。他上前道：“师父！","怎么不走路？还在此做甚？”三藏抬头道：“你往那里去来？教我行又不敢行，动又不敢动，只管在此等你。”行者道：“我往东洋大海老龙王家讨茶吃吃。”三藏道：“徒弟啊，出家人不要说谎。你离了我，没多一个时辰，就说到龙王家吃茶？”行者笑道：","“不瞒师父说，我会驾筋斗云，一个筋斗有十万八千里路，故此得即去即来。”三藏道：“我略略的言语重了些儿，你就怪我，使个性子丢了我去。象你这有本事的，讨得茶吃；象我这去不得的，只管在此忍饿，你也过意不去呀！”行者道：“师父，你若饿了，我便去与你化些斋吃。”三藏道：“不用化斋。我那包袱里，还有些干粮，是刘太保母亲送的，你去拿钵盂寻些水来，等我吃些儿走路罢。”行者去解开包袱，在那包裹中间见有几个粗面烧饼，拿出来递与师父。又见那光艳艳的一领绵布直裰，一顶嵌金花帽，行者道：“这衣帽是东土带来的？”三藏就顺口儿答应道：“是我小时穿戴的。这帽子若戴了，不用教经，就会念经；这衣服若穿了，不用演礼，就会行礼。”行者道：“好师父，把与我穿戴了罢。”三藏道：“只怕长短不一，你若穿得，就穿了罢。”行者遂脱下旧白布直裰，将绵布直裰穿上，也就是比量着身体裁的一般，把帽儿戴上。三藏见他戴上帽子，就不吃干粮，却默默的念那紧箍咒一遍。行者叫道：“头痛！头痛！”那师父不住的又念了几遍，把个行者痛得打滚，抓破了嵌金的花帽。","三藏又恐怕扯断金箍，住了口不念。不念时，他就不痛了。伸手去头上摸摸，似一条金线儿模样，紧紧的勒在上面，取不下，揪不断，已此生了根了。他就耳里取出针儿来，插入箍里，往外乱捎。三藏又恐怕他捎断了，口中又念起来，他依旧生痛，痛得竖蜻蜓，翻筋斗，耳红面赤，眼胀身麻。那师父见他这等，又不忍不舍，复住了口，他的头又不痛了。行者道：“我这头，原来是师父咒我的。”三藏道：“我念得是紧箍经，何曾咒你？”行者道：","“你再念念看。”三藏真个又念，行者真个又痛，只教：“莫念！莫念！念动我就痛了！这是怎么说？”三藏道：“你今番可听我教诲了？”行者道：“听教了！”“你再可无礼了？”行者道：“不敢了！”他口里虽然答应，心上还怀不善，把那针儿幌一幌，碗来粗细，望唐僧就欲下手，慌得长老口中又念了两三遍，这猴子跌倒在地，丢了铁棒，不能举手，只教：“师父！我晓得了！再莫念！再莫念！”三藏道：“你怎么欺心，就敢打我？”行者道：“我不曾敢打，我问师父，你这法儿是谁教你的？”三藏道：“是适间一个老母传授我的。”行者大怒道：“不消讲了！这个老母，坐定是那个观世音！他怎么那等害我！等我上南海打他去！”三藏道：","“此法既是他授与我，他必然先晓得了。你若寻他，他念起来，你却不是死了？”行者见说得有理，真个不敢动身，只得回心，跪下哀告道：“师父！这是他奈何我的法儿，教我随你西去。我也不去惹他，你也莫当常言，只管念诵。我愿保你，再无退悔之意了。”三藏道：“既如此，伏侍我上马去也。”那行者才死心塌地，抖擞精神，束一束绵布直裰，扣背马匹，收拾行李，奔西而进。毕竟这一去，后面又有甚话说，且听下回分解。"],"cpLength":8507},"xyj-27":{"chapterId":"xyj-27","bookId":"xyj","fileIndex":26,"number":27,"title":"第二十七回　尸魔三戏唐三藏　圣僧恨逐美猴王","paragraphs":["却说三藏师徒，次日天明，收拾前进。那镇元子与行者结为兄弟，两人情投意合，决不肯放，又安排管待，一连住了五六日。那长老自服了草还丹，真似脱胎换骨，神爽体健。他取经心重，那里肯淹留，无已，遂行。","师徒别了上路，早见一座高山。三藏道：“徒弟，前面有山险峻，恐马不能前，大家须仔细仔细。”行者道：“师父放心，我等自然理会。”好猴王，他在那马前，横担着棒，剖开山路，上了高崖，看不尽：峰岩重叠，涧壑湾环。虎狼成阵走，麂鹿作群行。","无数獐豝钻簇簇，满山狐兔聚丛丛。千尺大蟒，万丈长蛇。大蟒喷愁雾，长蛇吐怪风。道旁荆棘牵漫，岭上松楠秀丽。薜萝满目，芳草连天。影落沧溟北，云开斗柄南。万古常含元气老，千峰巍列日光寒。那长老马上心惊，孙大圣布施手段，舞着铁棒，哮吼一声，唬得那狼虫颠窜，虎豹奔逃。师徒们入此山，正行到嵯峨之处，三藏道：“悟空，我这一日，肚中饥了，你去那里化些斋吃？”行者陪笑道：“师父好不聪明。这等半山之中，前不巴村，后不着店，有钱也没买处，教往那里寻斋？”三藏心中不快，口里骂道：“你这猴子！想你在两界山，被如来压在石匣之内，口能言，足不能行，也亏我救你性命，摩顶受戒，做了我的徒弟。怎么不肯努力，常怀懒惰之心！”行者道：“弟子亦颇殷勤，何尝懒惰？”三藏道：“你既殷勤，何不化斋我吃？我肚饥怎行？况此地山岚瘴气，怎么得上雷音？”行者道：“师父休怪，少要言语。我知你尊性高傲，十分违慢了你，便要念那话儿咒。你下马稳坐，等我寻那里有人家处化斋去。”行者将身一纵，跳上云端里，手搭凉篷，睁眼观看。可怜西方路甚是寂寞，更无庄堡人家，正是多逢树木少见人烟去处。看多时，只见正南上有一座高山，那山向阳处，有一片鲜红的点子。行者按下云头道：","“师父，有吃的了。”那长老问甚东西，行者道：“这里没人家化饭，那南山有一片红的，想必是熟透了的山桃，我去摘几个来你充饥。”三藏喜道：“出家人若有桃子吃，就为上分了，快去！” 　　行者取了钵盂，纵起祥光，你看他觔斗幌幌，冷气飕飕，须臾间，奔南山摘桃不题。","却说常言有云：山高必有怪，岭峻却生精。果然这山上有一个妖精，孙大圣去时，惊动那怪。他在云端里，踏着阴风，看见长老坐在地下，就不胜欢喜道：“造化！造化！几年家人都讲东土的唐和尚取大乘，他本是金蝉子化身，十世修行的原体。","有人吃他一块肉，长寿长生。真个今日到了。”那妖精上前就要拿他，只见长老左右手下有两员大将护持，不敢拢身。他说两员大将是谁？说是八戒、沙僧。八戒、沙僧虽没甚么大本事，然八戒是天蓬元帅，沙僧是卷帘大将，他的威气尚不曾泄，故不敢拢身。妖精说：“等我且戏他戏，看怎么说。”","好妖精，停下阴风，在那山凹里，摇身一变，变做个月貌花容的女儿，说不尽那眉清目秀，齿白唇红，左手提着一个青砂罐儿，右手提着一个绿磁瓶儿，从西向东，径奔唐僧。圣僧歇马在山岩，忽见裙钗女近前。翠袖轻摇笼玉笋，湘裙斜拽显金莲。 　　汗流粉面花含露，尘拂峨眉柳带烟。仔细定睛观看处，看看行至到身边。三藏见了，叫：“八戒，沙僧，悟空才说这里旷野无人，你看那里不走出一个人来了？”八戒道：“师父，你与沙僧坐着，等老猪去看看来。”那呆子放下钉钯，整整直裰，摆摆摇摇，充作个斯文气象，一直的觌面相迎。真个是远看未实，近看分明，那女子生得：冰肌藏玉骨，衫领露酥胸。柳眉积翠黛，杏眼闪银星。月样容仪俏，天然性格清。体似燕藏柳，声如莺啭林。","半放海棠笼晓日，才开芍药弄春晴。那八戒见他生得俊俏，呆子就动了凡心，忍不住胡言乱语，叫道：“女菩萨，往那里去？手里提着是甚么东西？”分明是个妖怪，他却不能认得。那女子连声答应道：“长老，我这青罐里是香米饭，绿瓶里是炒面筋，特来此处无他故，因还誓愿要斋僧。”八戒闻言，满心欢喜，急抽身，就跑了个猪颠风，报与三藏道：“师父！吉人自有天报！师父饿了，教师兄去化斋，那猴子不知那里摘桃儿耍子去了。桃子吃多了，也有些嘈人，又有些下坠。你看那不是个斋僧的来了？”唐僧不信道：“你这个夯货胡缠！我们走了这向，好人也不曾遇着一个，斋僧的从何而来！”八戒道：“师父，这不到了？”","三藏一见，连忙跳起身来，合掌当胸道：“女菩萨，你府上在何处住？是甚人家？有甚愿心，来此斋僧？”分明是个妖精，那长老也不认得。那妖精见唐僧问他来历，他立地就起个虚情，花言巧语来赚哄道：“师父，此山叫做蛇回兽怕的白虎岭，正西下面是我家。我父母在堂，看经好善，广斋方上远近僧人，只因无子，求福作福，生了奴奴，欲扳门第，配嫁他人，又恐老来无倚，只得将奴招了一个女婿，养老送终。”三藏闻言道：“女菩萨，你语言差了。圣经云：父母在，不远游，游必有方。你既有父母在堂，又与你招了女婿，有愿心，教你男子还，便也罢，怎么自家在山行走？又没个侍儿随从。这个是不遵妇道了。”","那女子笑吟吟，忙陪俏语道：“师父，我丈夫在山北凹里，带几个客子锄田。这是奴奴煮的午饭，送与那些人吃的。只为五黄六月，无人使唤，父母又年老，所以亲身来送。忽遇三位远来，却思父母好善，故将此饭斋僧，如不弃嫌，愿表芹献。”三藏道：","“善哉！善哉！我有徒弟摘果子去了，就来，我不敢吃。假如我和尚吃了你饭，你丈夫晓得，骂你，却不罪坐贫僧也？”那女子见唐僧不肯吃，却又满面春生道：“师父啊，我父母斋僧，还是小可；我丈夫更是个善人，一生好的是修桥补路，爱老怜贫。但听见说这饭送与师父吃了，他与我夫妻情上，比寻常更是不同。”三藏也只是不吃，旁边却恼坏了八戒。那呆子努着嘴，口里埋怨道：“天下和尚也无数，不曾象我这个老和尚罢软！现成的饭三分儿倒不吃，只等那猴子来，做四分才吃！”他不容分说，一嘴把个罐子拱倒，就要动口。","只见那行者自南山顶上，摘了几个桃子，托着钵盂，一筋斗，点将回来，睁火眼金睛观看，认得那女子是个妖精，放下钵盂，掣铁棒，当头就打。唬得个长老用手扯住道：“悟空！你走将来打谁？”行者道：“师父，你面前这个女子，莫当做个好人。","他是个妖精，要来骗你哩。”三藏道：“你这猴头，当时倒也有些眼力，今日如何乱道！这女菩萨有此善心，将这饭要斋我等，你怎么说他是个妖精？”行者笑道：“师父，你那里认得！老孙在水帘洞里做妖魔时，若想人肉吃，便是这等：或变金银，或变庄台，或变醉人，或变女色。有那等痴心的，爱上我，我就迷他到洞里，尽意随心，或蒸或煮受用；吃不了，还要晒干了防天阴哩！师父，我若来迟，你定入他套子，遭他毒手！”那唐僧那里肯信，只说是个好人。行者道：“师父，我知道你了，你见他那等容貌，必然动了凡心。若果有此意，叫八戒伐几棵树来，沙僧寻些草来，我做木匠，就在这里搭个窝铺，你与他圆房成事，我们大家散了，却不是件事业？何必又跋涉，取甚经去！”那长老原是个软善的人，那里吃得他这句言语，羞得个光头彻耳通红。三藏正在此羞惭，行者又发起性来，掣铁棒，望妖精劈脸一下。那怪物有些手段，使个解尸法，见行者棍子来时，他却抖擞精神，预先走了，把一个假尸首打死在地下。唬得个长老战战兢兢，口中作念道：“这猴着然无礼！屡劝不从，无故伤人性命！”行者道：“师父莫怪，你且来看看这罐子里是甚东西。”沙僧搀着长老，近前看时，那里是甚香米饭，却是一罐子拖尾巴的长蛆，也不是面筋，却是几个青蛙、癞虾蟆，满地乱跳。长老才有三分儿信了，怎禁猪八戒气不忿，在旁漏八分儿唆嘴道：“师父，说起这个女子，他是此间农妇，因为送饭下田，路遇我等，却怎么栽他是个妖怪？哥哥的棍重，走将来试手打他一下，不期就打杀了；怕你念甚么《紧箍儿咒》，故意的使个障眼法儿，变做这等样东西，演幌你眼，使不念咒哩。”","三藏自此一言，就是晦气到了：果然信那呆子撺唆，手中捻诀，口里念咒，行者就叫：“头疼！头疼！莫念！莫念！有话便说。”唐僧道：“有甚话说！出家人时时常要方便，念念不离善心，扫地恐伤蝼蚁命，爱惜飞蛾纱罩灯。你怎么步步行凶，打死这个无故平人，取将经来何用？你回去罢！”行者道：“师父，你教我回那里去？”唐僧道：“我不要你做徒弟。”行者道：“你不要我做徒弟，只怕你西天路去不成。”唐僧道：“我命在天，该那个妖精蒸了吃，就是煮了，也算不过。终不然，你救得我的大限？","你快回去！”行者道：“师父，我回去便也罢了，只是不曾报得你的恩哩。”唐僧道：“我与你有甚恩？”那大圣闻言，连忙跪下叩头道：“老孙因大闹天宫，致下了伤身之难，被我佛压在两界山，幸观音菩萨与我受了戒行，幸师父救脱吾身，若不与你同上西天，显得我知恩不报非君子，万古千秋作骂名。”原来这唐僧是个慈悯的圣僧，他见行者哀告，却也回心转意道：“既如此说，且饶你这一次，再休无礼。如若仍前作恶，这咒语颠倒就念二十遍！”行者道：“三十遍也由你，只是我不打人了。”却才伏侍唐僧上马，又将摘来桃子奉上。唐僧在马上也吃了几个，权且充饥。","却说那妖精，脱命升空。原来行者那一棒不曾打杀妖精，妖精出神去了。他在那云端里，咬牙切齿，暗恨行者道：“几年只闻得讲他手段，今日果然话不虚传。那唐僧已此不认得我，将要吃饭。若低头闻一闻儿，我就一把捞住，却不是我的人了？","不期被他走来，弄破我这勾当，又几乎被他打了一棒。若饶了这个和尚，诚然是劳而无功也，我还下去戏他一戏。”","好妖精，按落阴云，在那前山坡下，摇身一变，变作个老妇人，年满八旬，手拄着一根弯头竹杖，一步一声的哭着走来。八戒见了，大惊道：“师父！不好了！那妈妈儿来寻人了！”唐僧道：","“寻甚人？”八戒道：“师兄打杀的，定是他女儿。这个定是他娘寻将来了。”行者道：“兄弟莫要胡说！那女子十八岁，这老妇有八十岁，怎么六十多岁还生产？断乎是个假的，等老孙去看来。”好行者，拽开步，走近前观看，那怪物：假变一婆婆，两鬓如冰雪。走路慢腾腾，行步虚怯怯。弱体瘦伶仃，脸如枯菜叶。 　　颧骨望上翘，嘴唇往下别。老年不比少年时，满脸都是荷叶摺。","行者认得他是妖精，更不理论，举棒照头便打。那怪见棍子起时，依然抖擞，又出化了元神，脱真儿去了，把个假尸首又打死在山路之下。唐僧一见，惊下马来，睡在路旁，更无二话，只是把《紧箍儿咒》颠倒足足念了二十遍。可怜把个行者头，勒得似个亚腰儿葫芦，十分疼痛难忍，滚将来哀告道：“师父莫念了！","有甚话说了罢！”唐僧道：“有甚话说！出家人耳听善言，不堕地狱。我这般劝化你，你怎么只是行凶？把平人打死一个，又打死一个，此是何说？”行者道：“他是妖精。”唐僧道：“这个猴子胡说！就有这许多妖怪！你是个无心向善之辈，有意作恶之人，你去罢！”行者道：“师父又教我去，回去便也回去了，只是一件不相应。”唐僧道：“你有甚么不相应处？”八戒道：“师父，他要和你分行李哩。跟着你做了这几年和尚，不成空着手回去？你把那包袱里的甚么旧褊衫，破帽子，分两件与他罢。”行者闻言，气得暴跳道：“我把你这个尖嘴的夯货！老孙一向秉教沙门，更无一毫嫉妒之意，贪恋之心，怎么要分甚么行李？”唐僧道：“你既不嫉妒贪恋，如何不去？”行者道：“实不瞒师父说，老孙五百年前，居花果山水帘洞大展英雄之际，收降七十二洞邪魔，手下有四万七千群怪，头戴的是紫金冠，身穿的是赭黄袍，腰系的是蓝田带，足踏的是步云履，手执的是如意金箍棒，着实也曾为人。自从涅槃罪度，削发秉正沙门，跟你做了徒弟，把这个金箍儿勒在我头上，若回去，却也难见故乡人。师父果若不要我，把那个《松箍儿咒》念一念，退下这个箍子，交付与你，套在别人头上，我就快活相应了，也是跟你一场。莫不成这些人意儿也没有了？”唐僧大惊道：“悟空，我当时只是菩萨暗受一卷《紧箍儿咒》，却没有甚么松箍儿咒。”行者道：“若无《松箍儿咒》，你还带我去走走罢。”长老又没奈何道：“你且起来，我再饶你这一次，却不可再行凶了。”行者道：“再不敢了，再不敢了。”又伏侍师父上马，剖路前进。","却说那妖精，原来行者第二棍也不曾打杀他。那怪物在半空中，夸奖不尽道：“好个猴王，着然有眼！我那般变了去，他也还认得我。这些和尚，他去得快，若过此山，西下四十里，就不伏我所管了。若是被别处妖魔捞了去，好道就笑破他人口，使碎自家心，我还下去戏他一戏。”好妖怪，按耸阴风，在山坡下摇身一变，变成一个老公公，真个是：白发如彭祖，苍髯赛寿星，耳中鸣玉磬，眼里幌金星。手拄龙头拐，身穿鹤氅轻。数珠掐在手，口诵南无经。唐僧在马上见了，心中欢喜道：“阿弥陀佛！西方真是福地！那公公路也走不上来，逼法的还念经哩。” 　　八戒道：“师父，你且莫要夸奖，那个是祸的根哩。”唐僧道：“怎么是祸根？”八戒道：“行者打杀他的女儿，又打杀他的婆子，这个正是他的老儿寻将来了。我们若撞在他的怀里呵，师父，你便偿命，该个死罪；把老猪为从，问个充军；沙僧喝令，问个摆站；那行者使个遁法走了，却不苦了我们三个顶缸？”行者听见道：“这个呆根，这等胡说，可不唬了师父？等老孙再去看看。”","他把棍藏在身边，走上前迎着怪物，叫声：“老官儿，往那里去？","怎么又走路，又念经？”那妖精错认了定盘星，把孙大圣也当做个等闲的，遂答道：“长老啊，我老汉祖居此地，一生好善斋僧，看经念佛。命里无儿，止生得一个小女，招了个女婿，今早送饭下田，想是遭逢虎口。老妻先来找寻，也不见回去，全然不知下落，老汉特来寻看。果然是伤残他命，也没奈何，将他骸骨收拾回去，安葬茔中。”行者笑道：“我是个做吓虎的祖宗，你怎么袖子里笼了个鬼儿来哄我？你瞒了诸人，瞒不过我！我认得你是个妖精！”那妖精唬得顿口无言。行者掣出棒来，自忖思道：“若要不打他，显得他倒弄个风儿；若要打他，又怕师父念那话儿咒语。”又思量道：“不打杀他，他一时间抄空儿把师父捞了去，却不又费心劳力去救他？还打的是！就一棍子打杀他，师父念起那咒，常言道，虎毒不吃儿。凭着我巧言花语，嘴伶舌便，哄他一哄，好道也罢了。”好大圣，念动咒语叫当坊土地、本处山神道：“这妖精三番来戏弄我师父，这一番却要打杀他。你与我在半空中作证，不许走了。”众神听令，谁敢不从？都在云端里照应。那大圣棍起处，打倒妖魔，才断绝了灵光。","那唐僧在马上，又唬得战战兢兢，口不能言。八戒在旁边又笑道：“好行者！风发了！只行了半日路，倒打死三个人！”唐僧正要念咒，行者急到马前，叫道：“师父，莫念！莫念！你且来看看他的模样。”却是一堆粉骷髅在那里。唐僧大惊道：“悟空，这个人才死了，怎么就化作一堆骷髅？”行者道：“他是个潜灵作怪的僵尸，在此迷人败本，被我打杀，他就现了本相。他那脊梁上有一行字，叫做白骨夫人。”唐僧闻说，倒也信了，怎禁那八戒旁边唆嘴道：“师父，他的手重棍凶，把人打死，只怕你念那话儿，故意变化这个模样，掩你的眼目哩！”唐僧果然耳软，又信了他，随复念起。行者禁不得疼痛，跪于路旁，只叫：“莫念！莫念！有话快说了罢！”唐僧道：“猴头！还有甚说话！出家人行善，如春园之草，不见其长，日有所增；行恶之人，如磨刀之石，不见其损，日有所亏。你在这荒郊野外，一连打死三人，还是无人检举，没有对头；倘到城市之中，人烟凑集之所，你拿了那哭丧棒，一时不知好歹，乱打起人来，撞出大祸，教我怎的脱身？你回去罢！”行者道：“师父错怪了我也。这厮分明是个妖魔，他实有心害你。我倒打死他，替你除了害，你却不认得，反信了那呆子谗言冷语，屡次逐我。常言道，事不过三。我若不去，真是个下流无耻之徒。我去我去！去便去了，只是你手下无人。”唐僧发怒道：“这泼猴越发无礼！看起来，只你是人，那悟能、悟净就不是人？”那大圣一闻得说他两个是人，止不住伤情凄惨，对唐僧道声：“苦啊！你那时节，出了长安，有刘伯钦送你上路；到两界山，救我出来，投拜你为师，我曾穿古洞，入深林，擒魔捉怪，收八戒，得沙僧，吃尽千辛万苦。今日昧着惺惺使糊涂，只教我回去：这才是鸟尽弓藏，兔死狗烹！罢罢罢！但只是多了那《紧箍儿咒》。”唐僧道：“我再不念了。”行者道：“这个难说。若到那毒魔苦难处不得脱身，八戒沙僧救不得你，那时节，想起我来，忍不住又念诵起来，就是十万里路，我的头也是疼的；假如再来见你，不如不作此意。”唐僧见他言言语语，越添恼怒，滚鞍下马来，叫沙僧包袱内取出纸笔，即于涧下取水，石上磨墨，写了一纸贬书，递于行者道：“猴头！执此为照，再不要你做徒弟了！如再与你相见，我就堕了阿鼻地狱！”","行者连忙接了贬书道：“师父，不消发誓，老孙去罢。”他将书摺了，留在袖中，却又软款唐僧道：“师父，我也是跟你一场，又蒙菩萨指教，今日半途而废，不曾成得功果，你请坐，受我一拜，我也去得放心。”唐僧转回身不睬，口里唧唧哝哝的道：“我是个好和尚，不受你歹人的礼！”大圣见他不睬，又使个身外法，把脑后毫毛拔了三根，吹口仙气，叫“变！”即变了三个行者，连本身四个，四面围住师父下拜。那长老左右躲不脱，好道也受了一拜。","大圣跳起来，把身一抖，收上毫毛，却又吩咐沙僧道：“贤弟，你是个好人，却只要留心防着八戒言语，途中更要仔细。倘一时有妖精拿住师父，你就说老孙是他大徒弟。西方毛怪，闻我的手段，不敢伤我师父。”唐僧道：“我是个好和尚，不题你这歹人的名字，你回去罢。”那大圣见长老三番两复，不肯转意回心，没奈何才去。你看他：噙泪叩头辞长老，含悲留意嘱沙僧。","一头拭迸坡前草，两脚蹬翻地上藤。上天下地如轮转，跨海飞山第一能。顷刻之间不见影，霎时疾返旧途程。你看他忍气别了师父，纵筋斗云，径回花果山水帘洞去了。独自个凄凄惨惨，忽闻得水声聒耳，大圣在那半空里看时，原来是东洋大海潮发的声响。一见了，又想起唐僧，止不住腮边泪坠，停云住步，良久方去。毕竟不知此去反复何如，且听下回分解。"],"cpLength":7079},"ysmy-01":{"chapterId":"ysmy-01","bookId":"ysmy","fileIndex":0,"number":1,"title":"第一卷　蒋兴哥重会珍珠衫","paragraphs":["仕至千钟非员，年过七十常稀，浮名身后有谁知？万事空花游戏。休逞少年狂荡，莫贪花酒便宜。脱离烦恼是和非，随分支闲得意。 这首词名为《西汇月》，是动人安分守己，随缘作乐，莫为酒、色、财、气四宇，损却精神，亏了行止。求快活时非快活，得便宜处失便宜。说起那四宇中，总到不得那“色”宇利害。眼是情媒，心为欲种，起手时，牵肠挂肚：过后去，丧魄悄魂。假如墙花路柳，偶然适兴，无损于事。若是生心设计，败俗伤风，只图自己一时欢乐，却不顾他人的百年思义，假如你有娇妻爱妾，别人调戏上了，你心下如何？古人有四句道得好：","心或可昧，","天道不差移。","我不淫人妇，","人不淫我妻。看官，则今日我说“珍珠衫”这套词话，可见果报不爽，好教少年子弟做个榜样。话中单表一人，姓蒋，名德，小宇兴哥，乃湖广襄阳府枣阳县人氏。父亲叫做蒋世泽，从小走熟广东，做客买卖。因为丧了妻房罗氏，止遗下这兴哥，年方九岁，别无男女。这蒋世泽割舍不下，又绝不得广东的衣食道路，千思百计，无可奈何，只得带那九岁的孩子同行作伴，就教他学些乖巧。这孩子虽则年小，生得眉清目秀，齿白唇红：行步端庄，言辞敏捷。职明赛过读书家，伶俐不输长大汉。人人晚做粉孩儿，个个羡他无价宝。蒋世泽怕人妒忌，一路上不说是嫡亲儿子，只说是内侄罗小官人。原来罗家也是走广东的，蒋家只走得一代，罗家到走过三代了。那边客店牙行，都与罗家世代相识，如自己亲善一般。这蒋世泽做客，起头也还是丈人罗公领他走起的。因罗家近来屡次遭了屈官司，家道消乏，好几年不曾走动。这些客店牙行见了蒋世泽，那一遍不动问罗家消息，好生牵挂。今番见蒋世泽带个孩子到来，问知是罗家小官人，且是生得十分清秀，应对聪明，想着他祖父三辈交情，如今又是第四辈了，那一个不欢喜！闲话休题。","却说蒋兴哥跟随父亲做客，走了几遍，学得伶俐乖巧，生意行中，百般都会，父亲也喜不自胜。何期到一十七岁上，父亲一病身亡，且喜刚在家中，还不做客造之鬼。兴哥哭了一场，兔不得揩千泪眼，整理大事。摈硷之外，做些功德超度，自不必说。七七四十九日内，内外宗亲，都来吊孝。本县有个王公，正是兴哥的新岳丈，也来上门祭奠，少不得蒋门亲戚陪待叙话。中间说起兴哥少年老成，这般大事，亏他独力支持，因话随话间，就有人撺掇道：“王老亲翁，如今令爱也长成了，何不乘凶完配，教他夫妇作伴，也好过日。”王公未肯应承，当日相别去了，众亲戚等安葬事毕，又去撺掇兴哥，兴哥初时也不肯，却被撺掇了几番，自想孤身无伴，只得应允。央原媒人往王家去说，王公只是推辞，说道：“我家也要备些薄薄妆奁，一时如何来得？况且孝未期年，于礼有碍，便要成亲，且待小样之后再议。”媒人回话，兴哥见他说得正理，也不相强。","光阴如箭，不觉周年己到。兴哥祭过了父亲灵位，换去粗麻衣服，再央媒人王家去说，方才依允。不隔几日，六礼完备，娶了新妇进门。有《西汇月》为证：","孝幕翻成红幕，色衣换去麻衣。画楼结彩烛光辉，和卺花筵齐备。那羡妆奁富盛，难求丽色娇妻。今宵云雨足欢娱，来日人称恭喜。 说这新妇是王公最幼之女，小名晚做三大儿，因他是七月七日生的，又晚做三巧儿。王公先前嫁过的两个女儿，都是出色标致的。枣阳县中，人人称羡，造出四句口号，道是：天下妇人多，王家美色寡。有人娶着他，胜似为附马。常言道：“做买卖不着，只一时：讨老婆不着，是一世。”若干官宦大户人家，单拣门户相当，或是贪他嫁资丰厚，不分皂白，定了亲事。后来娶下一房奇丑的媳妇，十亲九眷面前，出来相见，做公婆的好没意思。又且丈夫心下不喜，未免私房走野。偏是丑妇极会管老公，若是一般见识的，便要反目：若使顾僧体面，让他一两遍，他就做大起来。有此数般不妙，所以蒋世泽闻知王公惯生得好女儿，从小便送过财礼，定下他幼女与儿子为婚。今日娶过门来，果然娇资艳质，说起来，比他两个胡儿加倍标致。正是：","吴宫西子不如，楚国南威难赛。若比水月观音，一样烧香礼拜。","蒋兴哥人才本自齐整，又娶得这房美色的浑家，分明是一对玉人，良工琢就，男欢女爱，比别个夫妻更胜十分。三朝之后，依先换了些浅色衣服，只推制中，不与外事，专在楼上与浑家成双捉对，朝暮取乐。真个行坐不离，梦魂作伴。自古苦日难熬，欢时易过，暑往寒来，早己孝服完满，起灵除孝，不在话下。 兴哥一日间想起父亲存日广东生理，如今担阁三年有余了，那边还放下许多客帐，不曾取得。夜间与浑家商议，欲要去走一道。浑家初时也答应道该去，后来说到许多路程，恩爱夫妻，何忍分离？不觉两泪交流。兴哥也自割舍不得，两下凄惨一场，又丢开了。如此己非一次。光阴茬再，不觉又攘过了二年。那时兴哥决意要行，瞒过了浑家，在外面暗暗收拾行李。拣了个上吉的日期，五日前方对浑家说知，道：“常言‘坐吃山空’，我夫妻两口，也要成家立业，终不然抛了这行衣食道路？如今这二月天气不寒不暖，不上路更待何时？”浑家料是留他不住了，只得问道：“丈夫此去几时可回？”兴哥道：“我这番出外，甚不得己，好歹一年便回，宁可第二遍多去几时罢了。”浑家指着楼前一棵椿树道：“明年此树发芽，便盼着官人回也。”说罢，泪下如雨。兴哥把衣袖督他揩拭，不觉自己眼泪也挂下来。两下里怨离惜别，分外恩情，一言难尽。到第五日，夫妇两个啼啼哭哭，说了一夜的说话，索性不睡了。五更时分，兴哥便起身收拾，将祖遗下的珍珠细软，都交付与浑家收管。自己只带得本钱银两、帐目底本及随身衣服、铺陈之类，又有预备下送礼的人事，都装叠得停当。原有两房家人，只带一个后生些的去：留一个老成的在家，听浑家使唤，买办日用。两个婆娘，专管厨下。又有两个丫头，一个叫暗云，一个叫暖雪，专在楼中伏待，不许远离。分付停当了，对浑家说道：“娘子耐心度日。地方轻薄子弟不少，你又生得美貌，莫在门前窥瞰，招风揽火。”浑家道：“官人放心，早去早回。”两下掩泪而别。正是：世上万般哀苦事，无非死别与生高 兴哥上路，心中只想着浑家，整日的不瞅不睬。不一日，到了广东地方，下了客店。这伙旧时相识，都来会面，兴哥送了些人事。排家的治酒接风，一连半月二十日，不得空闲。兴哥在家时，原是淘虚了身子，一路受些劳碌，到此未免饮食不节，得了个疟疾，一夏不好，秋间转成水痢。每日请医切脉，服药调治，直延到秋尽，方得安痊。把买卖都担阁了，眼见得一年回去不成。正是：只为蝇头微利，抛却鸳被良缘。兴哥虽然想家，到得日久，索性把念头放慢了。不题兴哥做客之事。","且说这里浑家王三巧儿，自从那日丈夫分付了，果然数月之内，目不窥户，足不下楼。光阴似箭，不觉残年将尽，家家户户，闹轰轰的暖火盆，放爆竹，吃合家欢耍子。三巧儿触景伤情，图想丈夫，这一夜好生凄楚！正合古人的四句诗，道是：","腊尽愁难尽，春归人未归。朝来嗔寂寞，不肯试新衣。明日正月初一日，是个岁朝。暗云、暖雪两个丫头，一力劝主母在前楼去看看街坊景象。原来蒋家住宅前后通连的两带楼房，第一带临着大街，第二带方做卧室，三巧儿闲常只在第二带中坐卧。这一日被丫头头们撺掇不过，只得从边厢里走过前楼，分付推开窗子，把帘儿放下，三口儿在帘内观看。这日街坊上好不闹杂！三巧儿道：“多少东行西走的人，偏没个卖卦先生在内！若有时，晚他来卜问官人消息也好。”暗云道：“今日是岁朝，人人要闲耍的，那个出来卖卦？”暖雪叫道：“娘！限在我两个身上，五日内包晚一个来占卦便了。”","早饭过后，暖雪下楼小解，忽听得街上当当的敲晌。晌的这件东西，晚做“报君知”，是瞎子卖卦的行头。暖雪等不及解完，慌忙检了裤腰，跑出门外，叫住了瞎先生。拨转脚头，一口气跑上楼来，报知主母。三巧几分付，晚在楼下坐启内坐着，讨他课钱，通陈过了，走下楼梯，听他剖断。那瞎先生占成一卦，问是何用。那时厨下两个婆娘，听得热闹，也都跑将来了，督主母传语道：“这卦是问行人的。”瞎先生道：“可是妻问夫么？”婆娘道：“正是。”先生道：“青龙治世，财爻发动。若是妻问夫，行人在半途，金帛千箱有，风波一点无。青龙属木，木旺于春，立春前后，己动身了。月尽月初，必然回家，更兼十分财采。”三巧儿叫买办的，把三分银子打发他去，欢天喜地，上楼去了。真所谓“望梅止渴”、“画讲充饥”。","大凡人不做指望，到也不在心上：一做指望，便痴心妄想，时刻难过。三巧儿只为信了卖封先生之语，一心只想丈大回来，从此时常走向前楼，在帘内东张西望。直到二月初旬，椿树抽芽，不见些儿动静。三巧儿思想丈夫临行之约，愈加心慌，一日几遍，向外探望。也是合当有事，遇着这个俊俏后生。正是：有缘千里能相会，无缘对面不相逢。这个俊俏后生是谁？原来不是本地，是徽州新安县人氏，姓陈，名商，小名叫做大喜哥，后来改口呼为大郎。年方二十四岁，且是生得一表人物，虽胜不得宋玉、潘安，也不在两人之下。这大郎也是父母双亡，凑了二三千金本钱，来走襄阳贩籴些米豆之类，每年常走一遍。他下处自在城外，偶然这日进城来，要到大市街汪朝奉典铺中间个家信。那典铺正在蒋家对门，因此经过。你道怎生打扮？头上带一项苏样的百技鬃帽，身上穿一件鱼肚白的湖纱道袍，又恰好与蒋兴哥平昔穿着相像。三巧儿远远瞧见，只道是他丈夫回了，揭开帘子，定眼而看。陈大郎抬头，望见楼上一个年少的美妇人，目不转睛的，只道心上欢喜了他，也对着楼上丢个眼色。谁知两个都错认了。三巧儿见不是丈夫，羞得两颊通红，忙忙把窗儿拽转，跑在后楼，靠着床沿上坐地，几自心头突突的跳个不住。谁知陈大郎的一片精魂，早被妇人眼光儿摄上去了。回到下处，心心念念的放他不下，肚里想道：“家中妻子，虽是有些颜色，怎比得妇人一半！欲待通个情款，争奈无门可入。若得谋他一宿，就消花这些本钱，也不枉为人在世。”叹了几口气，忽然想起大市街东巷，有个卖珠子的薛婆，曾与他做过交易。这婆子能言快语，况且日逐串街走巷，那一家不认得，须是与他商议，定有道理。","这一夜番来覆去，勉强过了。次日起个清早，只推有事，讨些凉水梳洗，取了一百两银子，两大锭金子，急急的跑进城来。这叫做：欲求生受用，须下死工夫。陈大郎进城，一径来到大市街东巷，去敲那薛婆的门。薛婆蓬着头，正在天井里拣珠子，听得敲门，一头收过珠包，一头问道：“是谁？”才听说出“徽州陈”三字，慌忙开门请进，道：“老身未曾梳洗，不敢为礼了。大官人起得好早！有何贵干？”陈大郎道：“特特而来，若退时，怕不相遇。”薛婆道：“可是作成老身出脱些珍珠首饰么？”陈大郎道：“珠子也要买，还有大买卖作成你。”薛婆道：“老身除了这一行货，其余都不熟惯。”陈大郎道：“这里可说得话么？”薛婆便把大门关上，请他到小阁儿坐着，问道：“大官人有何分付？”大郎见四下无人．便向衣袖里模出银子，解开布包，摊在桌上，道：“这一百两白银，干娘收过了，方才敢说。”婆子不知高低，那里肯受。大郎道：“莫非嫌少？”慌忙又取出黄灿灿的两锭金子，也放在桌上，道：“这十两金子，一并奉纳。若干娘再不收时，便是故意推调了。今日是我来寻你，非是你来求我。只为这桩大买卖，不是老娘成不得，所以特地相求。便说做不成时，这金银你只管受用。终不然我又来取讨，日后再没相会的时节了？我陈商不是恁般小样的人！”","看官，你说从来做牙婆的那个个贪钱钞？见了这股黄白之物，如何不动火？薛婆当时满脸堆下笑来，便道：“大官人休得错怪，老身一生不曾要别人一厘一毫不明不白的钱财。今日既承大官人分付，老身权且留下：若是不能效劳，依据日奉纳。”说罢，将金锭放银包内，一齐包起，叫声：“老身大胆了。”拿向卧房中藏过，忙踅出来，道：“大官人，老身且不敢称谢，你且说甚么买卖，用着老身之处？”大郎道：“急切要寻一件救命之宝，是处都无，只大市街上一家人家方有，特央干娘去借借。”婆子笑将起来道：“又是作怪！老身在这条巷中住过二十多年，不曾闻大市街有甚救命之宝。大官人你说，有宝的还是谁家？”大郎道：“敝乡里汪三朝奉典铺对门高楼子内是何人之宅？”婆子想了一回，道：“这是本地蒋兴哥家里，他男子出外做客，一年多了，止有女眷在家。”大郎道：“我这救命之宝，正要问他女善借借。”便把椅儿掇近了婆子身边，向他诉出心腹，如此如此。","婆子听罢，连忙摇首道：“此事太难！蒋兴哥新娶这房娘子，不上四年，夫妻两个如鱼似水，寸步不离。如今投奈何出去了，这小胡子足不下楼，甚是贞节。因兴哥做人有些古怪，容易嗔嫌，老身辈从不曾上他的阶头。连这小娘子面长面短，老身还不认得，如何应承得此事？方才所赐，是老身薄福，受用不成了。”陈大郎听说，慌忙双膝跪下。婆子去扯他时，被他两手拿住衣袖，紧紧核定在椅上，动掸不得。口里说：“我陈商这条性命，都在干娘身上。你是必思量个妙计，作成我入马，救我残生。事成之日，再有白金百两相酬。若是推阻，即今便是个死。”慌得婆子没理会处，连声应道：“是，是！莫要折杀老身，大官人请起，老身有话讲。”陈大郎方才起身，拱手道：“有何妙策，作速见教。”薛婆道：“此事须从容图之，只要成就，莫论岁月。若是限时限日，老身决难奉命。”陈大郎道：“若果然成就，便退几日何妨。只是计将支出？”薛婆道：“明日不可太早，不可太退，早饭后，相约在汪三朝奉典铺中相会。大官人可多带银两，只说与老身做买卖，其间自有道理。若是老身这两只脚跨进得蒋家门时，便是大官人的造化。大官人便可急回下处，莫在他门首盘桓，被人识破，误了大事。讨得三分机会，老身自来回复。”陈大郎道：“谨依尊命。”唱了个肥喏，欣然开门而去。正是：未曾灭项兴刘，先见筑坛拜将。","当日无话。到次日，陈大郎穿了一身齐整衣服，取上三四百两银子，放在个大皮匣内，晚小郎背着，跟随到大市街汪家典铺来。瞧见对门楼窗紧闭，料是妇人不在，便与管典的拱了手，讨个木凳儿坐在门前，向东而望。不多时，只见薛婆抱着一个蔑丝箱儿来了。陈大郎晚住，问道：“箱内何物？”薛婆道：“珠宝首饰，大官人可用么？”大郎道：“我正要买。”薛婆进了典铺，与管典的相见了，叫声聒噪，便把箱儿打开。内中有十来包珠子，又有几个小匣儿，都盛着新样簇花点翠的首饰，奇巧动人，光灿夺目。陈大郎拣几吊极粗极白的珠子，和那些簪珥之类，做一堆儿放着，道：“这些我都要了。”婆子便把眼儿瞅着，说道：“大官人要用时尽用，只怕不肯出这样大价钱。”陈大郎己自会意，开了皮匣，把这些银两白华华的，摊做一台，高声的叫道：“有这些银子，难道买你的货不起。”此时邻舍闲汉己自走过七八个人，在铺前站着看了。婆子道：“老身取笑，岂敢小觑大官人。这银两须要仔细，请收过了，只要还得价钱公道便好。”两下一边的讨价多，一边的还钱少，差得天高地远。那讨价的一口不移，这里陈大郎拿着东西，又不放手，又不增添，故意走出屋檐，件件的翻覆认看，言真道假、弹斤佑两的在日光中恒耀。惹得一市人都来观看，不住声的有人喝采。婆子乱嚷道：“买便买，不买便罢，只管担阉人则甚！”陈大郎道：“怎么不买？”两个又论了一番价。正是：只因酬价争钱口，惊动如花似玉人。","王三巧儿听得对门喧嚷，不觉移步前楼，推窗偷看。只见珠光闪烁，宝色辉煌，甚是可爱。又见婆子与客人争价不定，便分付丫鬟去晚那婆子，借他东西看看。暗云领命，走过街去，把薛婆衣抉一扯，道：“我家娘请你。”婆子故意问道：“是谁家？”暗云道：“对门蒋家。”婆子把珍珠之类，劈手夺将过来，忙忙的包了，道：“老身没有许多空闲与你歪缠！”陈大郎道：“再添些卖了罢。”婆子道：“不卖，不卖！像你这样价钱，老身卖去多时了。”一头说，一头放入箱儿里，依先关锁了，抱着便走。暗云道：“我督你老人家拿罢。”婆子道：“不消。”头也不回，径到对门去了。陈大郎心中暗喜，也收拾银两，别了管典的，自回下处。正是：眼望捷族旗，耳听好消息。","暗云引薛婆上楼，与三巧儿相见了。婆子看那妇人，心下想道：“真天人也！怪不得陈大郎心迷，若我做男子，也要浑了。”当下说道：“老身久闻大娘贤慧，但恨无缘拜识。”三巧儿问道：“你老人家尊姓？”婆子道：“老身姓薛，只在这里东巷住，与大娘也是个邻里。”三巧儿道：“你方才这些东西，如何不卖？”婆子笑道：“若不卖时，老身又拿出来怎的？只笑那下路客人，空自一表人才，不识货物。”说罢便去开了箱儿，取出几件簪珥，递与那妇人看，叫道：“大娘，你道这样首饰，便工钱也费多少！他们还得忒不像样，教老身在主人家面前，如何台得许多消乏？”又把几串珠子提将起来道：“这般头号的货，他们还做梦哩。”三巧儿问了他讨价、还价，便道：“真个亏你些儿。”婆子道：“还是大家宝眷，见多识广，比男子汉眼力到胜十倍。”三巧儿晚丫鬟看茶，婆子道：“不扰茶了。老身有件要紧的事，欲往西街走走，遇着这个客人，缠了多时，正是：‘买卖不成，担误工程’。这箱儿连锁放在这里，权烦大娘收拾。巷身暂去，少停就来。”说罢便走。三巧儿叫暗云送他下楼，出门向西去了。 三巧儿心上爱了这几件东西，专等婆子到来酬价，一连五日不至。到第六日午后，忽然下一场大雨。雨声未绝，砰砰的敲门声响。三巧儿晚丫鬟开看，只见薛婆衣衫半湿，提个破伞进来，口儿道：“睛千不肯走，直待雨淋头。”把伞儿放在楼梯边，走上楼来万福道：“大娘，前晚失信了。”三巧儿慌忙答礼道：“这几日在那里去了？”婆子道：“小女托赖，新添了个外甥。老身去看看，留住了几日，今早方回。半路上下起雨来，在一个相识人家借得把伞，又是破的，却不是晦气！”三巧儿道：“你老人家几个儿女？”婆子道：“只一个儿子，完婚过了。女儿到有四个，这是我第四个了，嫁与徽州朱八朝奉做偏房，就在这北门外开盐店的。”三巧儿道：“你老人家女儿多，不把来当事了。本乡本士少什么一夫一妇的，怎舍得与异乡人做小？”婆子道：“大娘不知，到是异乡人有情怀。虽则偏房，他大娘子只在家里，小女自在店中，呼奴使婶，一般受用。老身每遍去时，他当个尊长看待，更不怠慢。如今养了个儿子，愈加好了。”三巧儿道：“也是你老人家造化，嫁得着。”","说罢，恰好暗云讨茶上来，两个吃了。婆子道：“今日雨天没事，老身大胆，敢求大娘的首饰一看，看些巧样儿在肚里也好。”三巧儿道：“也只是平常生活，你老人家莫笑话。”就取一把钥匙，开了箱笼，陆续搬你老人家莫笑话。”就取一把钥匙，开了箱笼，陆续搬出许多级、细、缨络之类。薛婆看了，夸美不尽，道：“大娘有恁般珍异，把老身这几件东西，看不在眼了。”三巧儿道：“好说，我正要与你老人家请个实价。”婆子道：“娘子是识货的，何消老身费嘴。”三巧儿把东西检过，取出薛婆的篾丝箱儿来，放在桌上，将钥匙递与婆子道：“你老人家开了，检看个明白。”婆子道：“大娘成精细了。”当下开了箱儿，把东西逐件搬出。三巧儿品评价钱，都不甚远。婆子并不争论，欢欢喜喜的道：“恁地，便不枉了人。老身就少赚几贯钱，也是快活的。”三巧儿道：“只是一件，目下凑不起价钱，只好现奉一半。等待我家官人回来，一并清楚，他也只在这几日回了。”婆子道：“便迟几日，也不妨事。只是价钱上相让多了，银水要足纹的。”三巧儿道：“这也小事。”便把心爱的几件首饰及珠子收起，晚暗云取杯见成酒来，与老人家坐坐。","婆子道：“造次如何好搅扰？”三巧儿道：“时常清闲，难得你老人家到此作伴扳话。你老人家若不嫌怠慢，时常过来走走。”婆子道：“多谢大娘错爱，老身家里当不过嘈杂，像宅上又忒清闲了。”三巧儿道：“你家儿子做甚生意？”婆子道：“也只是接些珠宝客人，每日的讨酒讨浆，刮的人不耐烦。老身亏杀各宅们走动，在家时少，还好。若只在六尺地上转，怕不燥死了人。”三巧儿道：“我家与你相近，不耐烦时，就过来闲话。”婆子道：“只不敢频频打搅。”三巧儿道：“老人家说那里话。”只见两个丫鬟轮番的走动，摆了两副杯著，两碗腊鸡，两碗腊肉，两碗鲜鱼，连果碟素菜，共一十六个碗。婆子道：“如何盛设！”三巧儿道：“见成的，休怪怠慢。”说罢，斟酒递与婆子，婆子将杯回敬，两下对坐而饮。原来三巧儿酒量尽去得，那婆子又是酒壶酒瓮，吃起酒来，一发相投了，只恨会面之晚。那日直吃到傍晚，刚刚雨止，婆子作谢要回。三巧儿又取出大银钟来，劝了几钟。又陪他吃了晚饭。说道：“你老人家再宽坐一时，我将这一半价钱付你去。”婆子道：“天晚了。大娘请自在，不争这一夜儿，明日却来领罢。连这篾丝箱儿，老身也不拿去了，省得路上泥滑滑的不好走。”三巧儿道：“明日专专望你。”婆子作别下楼，取了破伞，出门去了。正是：世间只有虔婆嘴，哄动多多少少人。","却说陈大郎在下处呆等了几日，并无音信。见这日天雨，料是婆子在家，拖泥带水的进城来问个消息，又不相值。自家在酒肆中吃了三杯，用了些点心，又到薛婆门首打听，只是未回。看看天晚，却待转身，只见婆子一脸春色，脚略斜的走入巷来。陈大郎迎着他，作了揖，问道：“所言如何？”婆子摇手道：“尚早。如今方下种，还没有发芽哩。再隔五六年，开花结果，才到得你口。你莫在此探头探脑，老娘不是管闲事的。”陈大郎见他醉了，只得转去。 次日，婆子买了些时新果子、鲜鸡、鱼、肉之类，晚个厨子安排停当，装做两个盒子，又买一瓮上好的酽酒，央间壁小二姚了，来到蒋家门首。三巧儿这日不见婆子到来，正数暗云开门出来探望，恰好相遇。婆子教小二姚在楼下，先打发他去了。暗云己自报知主母。三巧儿把婆子当个员客一般，直到楼梯一边迎他上去。婆子千思万谢的福了一回，便道：“今日老身偶有一杯水酒，将来与大娘消遣。”三巧儿道：“到要你老人家赡钞，不当受了。”婆子央两个丫鬟搬将上来，摆做一桌子。三巧儿道：“你老人家忒迂阔了，恁般大弄起来。”婆子笑道：“小户人家，备不出甚么好东西，只当一茶奉献。”暗云便去取杯著，暖雪便吹起水火炉来。霎时酒暖，婆子道：“今日是老身薄意，还请大娘转坐客位。”三巧儿道：“虽然相扰，在寒舍岂有此理？”两下谦让多时，薛婆只得坐了客席。这是第三次相聚，更觉熟分了。饮酒中间，婆子问道：“官人出外好多时了还不回，亏他撇得大娘下。”三巧儿道：“便是，说过一年就转，不知怎地担阁了？”婆子道：“依老身说，放下了恁般如花似玉的娘子，便博个堆金积玉也不为罕。”婆子又道：“大凡走江湖的人，把客当家，把家当客。比如我第四个女婿宋八朝奉，有了小女，朝欢暮乐，那里想家？或三年四年，才回一遍。住不上一两个月，又来了。家中大娘子督他担孤受寡，那晓得他外边之事？”三巧儿道：“我家官人到不是这样人。”婆子道：“老身只当闲话讲，怎敢将天比地？”当日两个猜谜掷色，吃得酩酊而别。","第三日，同小二来取家火，就领这一半价钱。三巧又留他吃点心。从此以后，把那一半赊钱为由，只做问兴哥的消息，不时行走，这婆子俐齿伶牙，能言快语，又半痴不颠的，惯与丫鬟们打诨，所以上下都欢喜他。三巧儿一日不见他来，便觉寂寞，叫老家人认了薛婆家里，早晚常去请他，所以一发来得勤了。世间有四种人惹他不得，引起了头，再不好绝他。是那四种？游方僧道、乞弓、闲汉、牙婆。上三种人犹可，只有牙婆是穿房入户的，女眷们怕冷静时，十个九个到要扳他来往。今日薛婆本是个不善之人，一般甜言软语，三巧儿遂与他成了至交，时刻少他不得。正是：画虎画皮难画骨，知人知面不知心。 陈大郎几遍讨个消息，薛婆只回言尚早。其时五月中旬，天渐炎热。婆子在三巧儿面前，偶说起家中蜗窄，又是朝西房子，夏月最不相宜，不比这楼上高敝风凉。三巧儿道：“你老人家若撇得家下，到此过夜也好。”婆子道：“好是好，只怕官人回来。”三巧儿道：“他就回，料道不是半夜三更。”婆子道：“大娘不嫌蒿恼，老身惯是掗相知的，只今晚就取铺陈过来，与大娘作伴，何如？”三巧儿道：“铺陈尽有，也不须拿得。你老人家回覆家里一声，索性在此过了一夏家去不好？”婆子真个对家里儿子媳妇说了，只带个梳匣儿过来。三巧儿道：“你老人家多事，难道我家油梳子也缺了，你又带来怎地？”婆子道：“老身一生怕的是同汤洗脸，合具梳头。大娘怕没有精致的梳具，老身如何敢用？其他胡儿们的，老身也怕用得，还是自家带了便当。只是大娘分付在那一门房安歇？”三巧儿指着床前一个小小藤榻儿，道：“我预先排下你的卧处了，我两个亲近些，夜间睡不着好讲些闲话。”说罢，检出一项青纱帐来，教婆子自家挂了，又同吃了一会酒，方才歇息。两个丫鬟原在床前打铺相伴，固有了婆子，打发他在间壁房里去睡。","从此为始，婆子日间出去串街做买卖，黑夜便到蒋家歇宿。时常携壶挚磕的殷勤热闹，不一而足。床榻是丁宇样铺下的，虽隔着帐子，却像是一头同睡。夜间絮絮叼叼，你问我答，凡街坊秽亵之谈，无所不至。这婆子或时装醉作风起来，到说起自家少年时偷汉的许多情事，去勾动那妇人的春心。害得那妇人娇滴滴一副嫩脸，红了又白，白了又红。婆子己知妇人心活，只是那话儿不好启齿。","光阴迅速，又到七月初七日了，正是三巧儿的生日。婆子清早备下两盘盒礼，与他做生。三巧儿称谢了，留他吃面。婆子道：“老身今日有些穷忙，晚上来陪大娘，看牛郎织女做亲。”说罢自去了。下得阶头不几步，正遇着陈大郎。路上不好讲话，随到个僻静巷里。陈大郎攒着两眉，埋怨婆子道：“干娘，你好慢心肠！春去夏来，如今又立过秋了。你今日也说尚早，明日也说尚早，却不知我度日如年。再延攘几日，他丈夫回来，此事便付东流，却不活活的害死我也！阴司去少不得与你索命。”婆子道：“你且莫喉急，老身正要相请，来得恰好。事成不成，只在今晚，须是依我而行。如此如此，这般这般。全要轻轻悄悄，莫带累人。”陈大郎点头道：“好计，好计！事成之后，定当厚报。”说罢，欣然而去。正是：排成窃玉偷香阵，费尽携云握雨心。","却说薛婆约定陈大郎这晚成事。午后细雨微茫，到晚却没有星月。婆子黑暗里引着陈大郎埋伏在左近，自己却去敲门。暗云点个纸灯儿，开门出来。婆子故意把衣袖一模，说道：“失落了一条临清汗巾儿。胡胡，劳你大家寻一寻。”哄得暗云便把灯向街上照去。这里婆于捉个空，招着陈大郎一溜溜进门来，先引他在楼梯背后空处伏着。婆子便叫道：“有了，不要寻了。”暗云道：“恰好火也没了，我再去点个来照你。”婆子道：“走熟的路，不消用火。”两个黑暗里关了门，模上楼来。三巧儿问道：“你没了什么东西？”婆子袖里处出个小帕儿来，道：“就是这个冤家，虽然不值甚钱，是一个北京客人送我的，却不道礼轻人意重。”三巧儿取笑道：“莫非是你老相交送的表记。”婆子笑道：“也差不多。”当夜两个耍笑饮酒。婆子道：“酒看尽多，何不把些赏厨下男女？也教他闹轰轰，像个节夜。”三巧儿真个把四碗菜，两壶酒，分付丫鬟，拿下楼去。那两个婆娘，一个汉子，吃了一回，各去歇息不题。再说婆子饮酒中间问道：“官人如何还不回家？”三巧儿道：“便是算来一年半了。”婆子道：“牛郎织女，也是一年一会，你比他到多隔了半年。常言道一品官，二品客。做客的那一处没有风花雪月？只苦了家中娘子。”三巧儿叹了口气，低头不语。婆子道：“是老身多嘴了。今夜牛女佳期，只该饮酒作乐，不该说伤情话儿。”说罢，便斟酒去劝那妇人。约莫半酣，婆子又把酒去劝两个丫鬟，说道：“这是牛郎织女的喜酒，劝你多吃几杯，后日嫁个恩爱的老公，寸步不离。”两个丫鬟被缠不过，勉强吃了，各不胜酒力，东倒西歪。三巧几分付关了楼门，发放他先睡。他两两个自在吃酒。","婆子一头吃，口里不住的说啰说皂道：“大娘几岁上嫁的？”三巧儿道：“十七岁。”婆子道：“破得身退，还不吃亏：我是十三岁上就破了身。”三巧儿道：“嫁得恁般早？”婆子道：“论起嫁，到是十八岁了。不瞒大娘说，因是在间壁人家学针指，被他家小官人调诱，一时间贪他生得俊俏，就应承与他偷了。初时好不疼痛，两三遍后，就晓得快活。大娘你可也是这般么？”三巧儿只是笑。婆子又道：“那话儿到是不晓得滋昧的到好，尝过的便丢不下，心坎里时时发痒。日里还好，夜间好难过哩。”三巧儿道：“想你在娘家时阅人多矣，亏你怎生充得黄花女儿嫁去？”婆子道：“我的老娘也晓得些影像，生怕出丑，教我一个童女方，用石榴皮、生矾两昧，煎汤洗过，那东西就揪疮紧了。我只做张做势的叫疼，就遮过了。”三巧儿道：“你做女儿时，夜间也少不得独睡。”婆子道：“还记得在娘家时节，哥哥出外，我与嫂嫂一头同睡，两下轮番在肚子上学男子汉的行事。”三巧儿道：“两个女人做对，有甚好处？”婆子走过三巧儿那边，挨肩坐了，说道：“大娘，你不知，只要大家知音，一般有趣，也撤得火。”三巧儿举手把婆子肩胛上打一下，说道：“我不信，你说谎。”婆了见他欲心己动，有心去挑拨他，又道：“老身今年五十二岁了，夜间常痴性发作，打熬不过，亏得你少年老成。”三巧儿道：“你老人家打熬不过，终不然还去打汉子？”婆子道：“败花枯柳，如今那个要我了？不瞒大娘说，我也有个自取其乐，救急的法儿。”三巧儿道：“你说谎，又是甚么法儿？”婆子道：“少停到床上睡了，与你细讲。”","说罢，只见一个飞蛾在灯上旋转，婆子便把扇来一扑，故意扑灭了灯，叫声：“阿呀！老身自去点灯来。”便去开楼门。陈大郎己自走上楼梯，伏在门边多时了。一都是婆干预先设下的圈套。婆子道：“忘带个取灯儿去了。”又走转来，便引着陈大郎到自己榻上伏着。婆子下楼去了一回，复上来道：“夜深了，厨下火种都熄了，怎么处？”三巧儿道：“我点灯睡？惯了，黑魆魆地，好不怕人！”婆道：“老身伴你一床睡何如？”三巧儿正要问他救急的法儿，应道：“甚好。”婆子道：“大娘，你先上床，我关了门就来。”三巧儿先脱了衣服，床上去了，叫道：“你老人家快睡罢。”婆子应道：“就来了。”却在榻上拖陈大郎上来，赤条条的耸在三巧儿床上去。三巧儿模着身子，道：“你老人家许多年纪，身上恁般光滑！”那人并不回言，钻进被里，就捧着妇人做嘴，妇人还认是婆子，双手相抱。那人要地腾身而上，就千起事来。那妇人一则多了杯酒，醉眼膜陇：二则被婆子挑拨，春心飘荡，到此不暇致详，凭他轻薄： 一个是闰中怀春的少妇，一个是客邸慕色的才郎。一个打熬许久，如文君初遇相如：一个盼望多时，如必正初谐陈女。分明久旱受甘雨，胜似他乡遇放知。","陈大郎是走过风月场的人，颠鸾倒风，曲尽其趣，弄得妇人魂不附体。云雨毕后，三巧儿方问道：“你是谁？”陈大郎把楼下相逢，如此相幕，如此苦央薛婆用计，细细说了：“今番得遂平生，便死瞑目。”婆子走到床间，说道：“不是老身大胆，一来可怜大娘青春独宿，二来要救陈郎性命。你两个也是宿世姻缘，非千老身之事。”三巧儿道：“事己如此，万一我丈夫知觉，怎么好？”婆子道：“此事你知我知，只买定了暗云、暖雪两个丫头，不许他多嘴，再有谁人漏泄？在老身身上，管成你夜夜欢娱，一些事也没有。只是日后不要忘记了老身。”三巧儿到此，也顾不得许多了，两个又狂荡起来，直到五更鼓绝，天色将明，两个几自不舍。婆子催促陈大郎起身，送他出门去了。自此无夜不会，或是婆子同来，或是汉子自来。两个丫鬟被婆子甜话儿偎他，又把利害话儿吓他，又教主母赏他几件衣服，汉子到时，不时把些零碎银子赏他们买果儿吃，骗得欢欢喜喜，己自做了一路。夜来明去，一出一入，都是两个丫鬟迎送，全无阻隔。真个是你贪我爱，如胶似漆，胜如夫妇一般。陈大郎有心要结识这妇人，不时的制办好衣服、好首饰送他，又督他还了欠下婆子的一半价钱。又将一百两银子谢了婆子。往来半年有余，这汉子约有千金之费。三巧儿也有三十多两银子的东西，送那婆子。婆子只为图这些不义之财，所以肯做牵头。这都不在话下。","古人云：“天下无不散的筵席。”才过十五元宵夜，又是清明三月天。陈大郎思想蹬陀了多时生意，要得还乡。夜来与妇人说知，两下思深义重，各不相舍。妇人到情愿收拾了些细软，跟随汉子逃走，去做长久夫妻。陈大郎道：“使不得。我们相交始末，都在薛婆肚里。就是主人家吕公，见我每夜进城，难道没有些疑惑？况客船上人多，瞒得那个？两个丫鬟又带去不得。你丈夫回来，跟究出情由，怎肯千休？娘子权且耐心，到明年此时，我到此觅个僻薄下处，悄悄通个信儿与你，那时两口儿同走，神鬼不觉，却不安稳？”妇人道：“万一你明年不来，如何？”陈大郎就设起誓来。妇人道：“既然你有真心，奴家也决不相负。你若到了家乡，倘有便人，托他捎个书信到薛婆处，也教奴家放意。”陈大郎这“我自用心，不消分付。”","又过几日，陈大郎雇下船只，装载粮食完备，又来与妇人作别。这一夜倍加眷恋，两下说一会，哭一会，又狂荡一会，整整的一夜不曾合眼。到五更起身，妇人便去开箱，取出一件宝贝，叫做“珍珠衫”，递与陈大郎道：“这件衫儿，是蒋门祖传之物，暑天若穿了他，清凉透骨。此去天道渐热，正用得着。奴家把与你做个记念，穿了此衫，就如奴家贴体一般。”陈大郎哭得出声不得，软做一堆。妇人就把衫儿亲手与汉子穿下，叫丫鬟开了门户，亲自送他出门。再三珍重而别。诗曰：","昔年含泪别夫郎，今日悲啼送所欢。堪恨妇人多水性，招来野鸟胜文鸾。","话分两头。却说陈大郎有了这珍珠衫儿，每日贴体穿着，便夜间脱下，也放在被窝中同睡，寸步不离。一路遇了顺风，不两月行到苏州府枫桥地面。那枫桥是柴米牙行聚处，少不得投个主家脱货，不在话下。忽一日，赴个同乡人的酒席。席上遇个襄阳客人，生得风流标致。那人非别，正是蒋兴哥。原来兴哥在广东贩了些珍珠、玳瑁、苏木、沉香之类，搭伴起身。那伙同伴商量，都要到苏州发卖。兴哥久闻得“上说天堂，下说苏杭”，好个大马头所在，有心要去走一遍，做这一回买卖，方才回去。还是去年十月中到苏州的。因是隐姓为商，都称为罗小官人，所以陈大郎更不疑惑。他两个萍水相逢，年相若貌相似，谭吐应对之间，彼此敬慕。即席间问了下处，互相拜望，两下遂成知己，不时会面。","兴哥讨完了客帐，欲待起身，走到陈大郎寓所作别，大郎置酒相待，促膝谈心，甚是款洽。此时五月下旬，天气炎热。两个解衣饮酒，陈大郎露出珍珠衫来。兴哥心中骇异，又不好认他的，只夸奖此衫之美。陈大郎恃了相知，便问道：“员县大市街有个蒋兴哥家，罗兄可认得否？”兴哥到也乖巧，回道：“在下出外日多，里中虽晓得有这个人，并不相认，陈兄为何问他？”陈大郎道：“不瞒兄长说，小弟与他有些瓜葛。”便把三巧儿相好之情，台诉了一遍。扯着衫儿看了，眼泪汪汪道：“此衫是他所赠。兄长此去，小弟有封书信，奉烦一寄，明日侵早送到员寓。”兴哥口里答应道：“当得，当得。”心下沉吟：“有这等异事！现在珍珠衫为证，不是个虚话了。”当下如针刺肚，推放不饮，急急起身别去。","回到下处，想了又恼，恼了又想，恨不得学个缩地法儿，顷刻到家连夜收拾，次早便上船要行。只见岸上一个人气吁吁的赶来，却是陈大郎。亲把书信一大包，递与兴哥，叮嘱千万寄去。气得兴哥面如士色，说不得，话不得，死不得，活不得。只等陈大郎去后，把书看时，面上写道：“此书烦寄大市街东巷薛妈妈家。”兴哥性起，一手扯开，却是八尺多长一条桃红绉纱汗巾。又有个纸糊长匣儿，内羊脂玉风头簪一根。书上写道：“微物二件，烦干娘转寄心爱娘子三巧儿亲收，聊表记念。相会之期，准在来春。珍重，珍重。”兴哥大怒，把书扯得粉碎，撇在河中：提起玉簪在船板上一损，折做两段。一念想起道：“我好糊涂！何不留此做个证见也好。”便捡起簪儿和汗巾，做一包收拾，催促开船。 急急的赶到家乡，望见了自家门首，不觉堕下泪来。想起：“当初夫妻何等恩爱，只为我贪着蝇头微利，撇他少年守寡，弄出这场丑来，如今悔之何及！”在路上性急，巴不得赶回。及至到了，心中又苦又恨，行一步，懒一步。进得自家门里，少不得忍住了气，勉强相见。兴哥并无言语，三巧儿自己心虚，觉得满脸惭愧，不敢殷勤上前扳话。兴哥搬完了行李，只说去看看丈人丈母，依旧到船上住了一晚。次早回家，向三巧儿说道：“你的爹娘同时害病，势甚危骂。昨晚我只得住下，看了他一夜。他心中只牵挂着你，欲见一面。我己雇下轿子在门首，你可作速回去，我也随后就来。”三巧儿见丈夫一夜不回，心里正在疑虑：闻说爹娘有病，却认真了，如何不慌？慌忙把箱笼上匙钥递与丈夫，晚个婆娘跟了，上轿而去。兴哥叫住了婆娘，向袖中模出一封书来，分付他送与王公：“送过书，你便随轿回来。”","却说三巧儿回家，见爹娘双双无恙，吃了一惊。王公见女儿不接而回，也自骇然。在婆子手中接书，拆开看时，却是休书一纸。上写道：“立休书人蒋德，系襄阳府枣阳县人。从幼凭媒聘定王氏为妻。岂期过门之后，本妇多有过失，正合七出之条。因念夫妻之情，不忍明言，情愿退还本宗，听凭改嫁，并无异言，休书是实。成化二年月日，手掌为记。”书中又包着一条桃红汗巾，一技打折的羊脂玉风头簪。王公看了大惊，叫过女儿问其缘故。三巧儿听说丈夫把他休了，一言不发，啼哭起来。王公气忿忿的一径跟到女婿家来，蒋兴哥连忙上前作揖。王公回礼，便问道：“贤婿，我女儿是清清白白嫁到你家的，如今有何过失，你便把他休了？须还我个明白。”蒋兴哥道：“小婿不好说得，但问令爱便知。”王公道：“他只是啼哭，不肯开口，教我肚里好闷！小女从幼聪慧，料不到得犯了淫盗。若是小小过失，你可也看老汉薄面，恕了他罢。你两个是七八岁上定下的夫妻，完婚后并不曾争论一遍两遍，且是和顺。你如今做客才回，又不曾住过三朝五日，有什么破绽落在你眼里？你直如此狠毒，也被人笑话，说你无情无义。”蒋兴哥道：“丈人在上，小婿也不敢多讲。家下有祖遗下珍珠衫一件，是令爱收藏，只问他如今在否。若在时，半宇休题：若不在，只索休怪了。”王公忙转身回家，问女儿道：“你丈夫只问你讨什么珍珠衫，你端的拿与何人去了？”那妇人听得说着了他紧要的关目，羞得满脸通红，开不得口，一发号陶大哭起来，慌得王公没做理会处。王婆劝道：“你不要只管啼哭，实实的说个真情与爹妈知道，也好与你分割。”妇人那里肯说，悲悲咽咽，哭一个不住。王公只得把休书和汗巾、善于，都付与王婆，教他慢慢的偎着女儿，问他个明白。","王公心中纳闷，走到邻家闲话去了。王婆见女儿哭得两眼赤肿，生怕苦坏了他，安慰了几句言语，走往厨房下去暖酒，要与女儿消愁。三巧儿在房中独坐，想着珍珠衫泄漏的缘故，好生难解！这汗巾簪子，又不知那里来的。沉吟了半晌道：“我晓得了。这折簪是镜破钗分之意：这条汗巾，分明教我悬梁自尽。他念夫妻之惰，不忍明言，是要全我的廉耻。可怜四年恩爱，一旦决绝，是我做的不是，负了丈夫恩情。便活在人间，料没有个好日，不如绕死，到得干净。”说罢，又哭了一回，把个坐几子填高，将汗巾兜在梁上，正欲自缢。也是寿数未绝，不曾关上房门。险好王婆暖得一壶好酒走进房来，见女儿安排这事，急得他手忙脚乱，不放酒壶，便上前去拖拽。不期一脚踢番坐几子，娘儿两个跌做一团，酒壶都泼翻了。王婆爬起来，扶起女儿，说道：“你好短见！二十多岁的人，一朵花还没有开足，怎做这没下梢的事？莫说你丈夫还有回心转意的日子，便真个休了，恁般容貌，怕投人要你？少不得别选良姻，图个下半世受用。你且放心过日子去，休得愁闷。”王公回家，知道女儿寻死，也劝了他一番，又瞩付王婆用心提防。过了数日，三巧儿投奈何，也放下了念头。正是：","夫妻本是同林鸟，大限来时各自飞。","再说蒋兴哥把两条索子，将晴云、暖雪捆缚起来，拷问情由。那丫头初时抵赖，吃打不过，只得从头至尾，细细招将出来。己知都是薛婆勾引，不千他人之事。到明朝，兴哥领了一伙人，赶到薛婆家里，打得他雪片相似，只饶他拆了房子。薛婆情知自己不是，躲过一边，并没一人敢出头说话。兴哥见他如此，也出了这口气。回去晚个牙婆，将两个丫头都卖了。楼上细软箱笼，大小共十六只，写三十二条封皮，打叉封了，更不开动。这是甚意儿？只因兴哥夫妇，本是十二分相爱的。虽则一时休了，心中好生痛切。见物思人，何忍开看？ 话分两头说。却说南京有个吴杰进土，除授广东潮阳县知县。水路上任，打从襄阳经过。不曾带家小，有心要择一美妾。路看了多少女子，并不中意。闻得枣阳县王公之女，大有颜色，一县闻名。出五十金财礼，央媒议亲。王公到也乐从，只怕前婿有言，亲到蒋家，与兴哥说知。兴哥并不阻当。临嫁之夜，兴哥顾了人夫，将楼上十六个箱笼，原封不动，连匙钥送到吴知县船上，交割与三巧儿，当个赡嫁。妇人心上到过意不去。旁人晓得这事，也有夸兴哥做人忠厚的，也有笑他痴呆的，还有骂他没志气的，止是人心不同。","闲话休题。再说陈大郎在苏州脱货完了，回到新交，一心只想着三巧儿。朝暮看了这件珍珠衫，长吁短叹。老婆平氏心知这衫儿来得蹊跷，等丈夫睡着，悄悄的偷去，藏在天花板上。陈大郎早起要穿时，不见了衫儿，与老婆取讨。平氏那里肯认。急得陈大郎性发，倾箱倒筐的寻个遍，只是不见，便破口骂老婆起来。惹得老婆啼啼哭哭，与他争嚷，闹炒了两三日。陈大郎情怀撩乱，忙忙的收拾银两，带个小郎，再望襄阳旧路而进。将近枣阳，不期遇了一伙大盗，将本钱尽皆劫去，小郎也被他杀了。陈商眼快，走向船梢舵上伏着，幸免残生。思想还乡不得，且到旧寓住下，待会了三巧儿，与他借些东西，再图恢复。叹了一口气，只得离船上岸。","走到枣阳城外主人吕公家，台诉其事，又道：“如今要央卖珠子的薛婆，与一个相识人家借些本钱营运。”吕公道：“大郎不知，那婆子为勾引蒋兴哥的浑家，做了些丑事。去年兴哥回来，问浑家讨什么‘珍珠衫’。原来浑家赠与情人去了，无言回答。兴哥当时休了浑家回去，如今转嫁与南京吴进土做第二房夫人了。那婆子被蒋家打得个片瓦不留，婆子安身不牢，也搬在隔县去了。”陈大郎听得这话，好似一桶冷水没头淋下。这一惊非小，当夜发寒发热，害起病来。这病又是郁症，又是相思症，也带些怯症，又有些惊症，床上卧了两个多月，翻翻覆覆只是不愈。连累主人家小厮，伏待得不耐烦。陈大郎心上不安，打熬起精神，写成家书一封。请主人来商议，要觅个便人捎信在家中，取些盘缠，就要个亲人来看觑同回。这几句正中了主人之意。恰好有个相识的承差，奉上司公文要往徽宁一路。水陆驿递，极是快的。吕公接了陈大郎书札，又督他应出五钱银子，送与承差，央他乘便寄去。果然的“自行由得我，官差急如火”，不勾几日，到了新交县。问到陈商家里，送了家书，那承差飞马去了。正是：只为千金书信，又成一段姻缘。","话说平氏拆开家信，果是丈夫笔迹，写道：“陈商再拜，贤妻平氏见宇：别后襄阳遇盗，劫资杀仆。某受惊患病，见卧旧寓吕家，两月不愈。宇到可央一的当亲人，多带盘缠，速来看视。伏枕草草”。平氏看了，半信半疑，想道：“前番回家，亏折了千金资本。据这件珍珠衫，一定是邪路上来的。今番又推被盗，多讨盘缠，怕是假话。”又想道：“他要个的当亲人，速来看视，必然病势利害。这话是真，也未可知。如今央谁人去好？”左思右想，放心不下。与父亲平老朝奉商议。收拾起细软家私，带了陈旺夫妇，就请父亲作伴，雇个船只，亲往襄阳看丈夫去。到得京口，平老朝奉痰火病发，央人送回去了。平氏引着男女，上水前进。不一日，来到枣阳城外，问着了旧主人吕家。原来十日前，陈大郎己放了。吕公赡些钱钞，将就入硷。平氏哭倒在地，良久方醒。慌忙换了孝服，再三向吕公说，欲待开棺一见，另买副好棺材，重新硷过。吕公执意不肯。平氏投奈何，只得买木做个外棺包裹，请僧做法事超度，多焚莫资。吕公己自索了他二十两银子谢仪，随他闹炒，并不言语。","有余，平氏要选个好日子，扶枢而回。吕公见这妇人年少姿色，料是守寡不终，又且囊中有物。思想儿子吕二，还没有亲事，何不留住了他，完其好事，可不两便？吕公买酒请了陈旺，央他老婆委曲进言，许以厚谢。陈旺的老婆是个蠢货，那晓得什么委曲？不顾高低，一直的对主母说了。平氏大怒，把他骂了一顿，连打几个耳光子，连主人家也数落了几句。吕公一场没趣，敢怒而不敢言。正是：羊肉馒头没的吃，空教惹得一身骚。吕公使去撺掇陈旺逃走。陈旺也思量没甚好处了，与老婆商议，教他做脚，里应外合，把银两首饰，偷得罄尽，两一儿连夜走了。吕公明知其情，反埋怨平氏道：不该带这样歹人出来，幸而偷了自家主母的东西，若偷了别家的，可不连累人！又嫌这灵柩碍他生理，教他快些抢去。又道后生寡妇，在此住居不便，催促他起身。平氏被逼不过，只得别赁下一间间房子住了。雇人把灵枢移来，安顿在内。这凄凉景象，自不必说。 间壁有个张七嫂，为人甚是活动。听得平氏啼哭，时常走来劝解。平氏又时常央他典卖几件衣服用度，极感其意。不勾几月，衣服都典尽了。从小学得一手好针线，思量要到个大户人家，教习女红度日，再作区处。正与张七嫂商量这话，张七嫂道：“老身不好说得，这大户人家，不是你少年人走动的。死的没福自死了，活的还要做人，你后面日子正长哩。终不然做针线娘了得你下半世？况且名声不好，被人看得轻了。还有一件，这个灵柩如何处置，也是你身上一件大事。便出赁房钱，终久是不了之局。”平氏道：“奴家也都虑到，只是无计可施了。”张七嫂道：“老身到有一策，娘子莫怪我说。你千里离乡，一身孤寡，手中又无半钱，想要搬这灵枢回去，多是虚了。莫说你衣食不周，到底难守：便多守得几时，亦有何益？依老身愚见，莫若趁此青年美貌，寻个好对头，一夫一妇的随了他去。得些财礼，就买块士来葬了丈夫，你的终身又有所托，可不生死无憾？”平氏见他说得近理，沉吟了一会，叹口气道：“罢，罢，奴家卖身葬夫，旁人也笑我不得。”张七嫂道：“娘子若定了主意时，老身现有个主儿在此。年纪与娘子相近，人物齐整，又是大富之家。”平氏道：“他既是富家，怕不要二婚的。”张七嫂道：“他也是续弦了，原对老身说：不拘头婚二婚，只要人才出众。似娘子这般丰姿，怕不中意？”原来张七嫂曾受蒋兴哥之托，央他访一头好亲。因是前妻三巧儿出色标致，所以如今只要访个美貌的。那平氏容貌，虽不及得三巧儿，论起手脚伶俐，胸中烃渭，又胜似他。张七嫂次日就进城，与蒋兴哥说了。兴哥闻得是下路人，愈加欢喜。这里平氏分文财礼不要，只要买块好地殡葬丈夫要紧。张七嫂往来回复了几次，两相依允。","活休烦絮。却说平氏送了丈夫灵枢人士，祭奠毕了，大哭一场，兔不得起灵除孝。临期，蒋家送衣饰过来，又将他典下的衣服都赎回了。成亲之夜，一般大吹大擂，洞房花烛。正是：规矩熟闲虽旧事，恩情美满胜新婚。蒋兴哥见平氏举止端庄，甚相敬重。一日，从外而来，平氏正在打叠衣箱，内有珍珠衫一件。兴哥认得了，大惊问道：“此衫从何而来？”平氏道：“这衫儿来得跷蹊。”便把前夫如此张致，夫妻如此争嚷，如此赌气分别，述了一遍。又道：“前日艰难时，几番欲把他典卖。只愁来历不明，怕惹出是非，不敢露人眼目。连奴家至今，不知这物事那里来的。”兴哥道：“你前夫陈大郎名字，可叫做陈商？可是白淳面皮，没有须，左手长指甲的么？”平氏道：“正是。”蒋兴哥把舌头一伸，合掌对天道：“如此说来，天理昭彰，好怕人也！”平氏问其缘故，蒋兴哥道：“这件珍珠衫，原是我家旧物。你丈夫奸骗了我的妻子，得此衫为表记。我在苏州相会，见了此衫，始知其情，回来把王氏休了。谁知你丈夫客死。我今续弦，但闻是徽州陈客之妻，谁知就是陈商！却不是一报还一报！”平氏听罢，毛骨辣然。从此恩情愈骂。这才是“蒋兴哥重会珍珠衫”的正话。诗曰： 天理昭昭不可欺，两妻交易孰便宜？分明欠债偿他利，百岁姻缘暂换时。","兴哥有了管家娘子，一年之后，又往广东做买卖。也是合当有事。一日到合浦县贩珠，价都讲定。主人家老儿只拣一粒绝大的偷过了，再不承认。兴哥不忿，一把扯他袖子要搜。何期去得势重，将老儿拖翻在地，跌下便不做声。忙去扶时，气己断了。儿女亲邻，哭的哭，叫的叫，一阵的簇拥将来，把兴哥捉住。不巾分说，痛打一顿，关在空房里。连夜写了状词，只等天明，县主早堂，连人进状。县主准了，因这日有公事，分付把凶身锁押，次日候审。你道这县主是谁？姓吴名杰，南畿进土，正是三巧儿的晚老公。初选原在潮阳，上司因见他清廉，调在这合浦县采珠的所在做官。是夜，吴杰在灯下将准过的状词细阅。三巧儿正在旁边闲看，偶见宋福所台人命一词，凶身罗德，枣阳县客人，不是蒋兴哥是谁？想起旧日恩情，不觉痛酸，哭台丈夫道：“这罗德是贱妾的亲哥，出嗣在母舅罗家的。不期客边，犯此大辟。官人可看妾之面，救他一命还乡。”县主道：“且看临审如何。若人命果真，教我也难宽有。”三巧儿两眼噙泪，跪下苦苦哀求。县主道：“你且莫忙，我自有道理。”明早出堂，三巧儿又扯住县主衣袖哭道：“若哥哥无救，贱妾亦当自尽，不能相见了。”","当日县主升堂，第一就问这起。只见宋福、宋寿弟兄两个，哭啼啼的与父亲执命，禀道：“因争珠怀恨，登时打闷，仆地身死。望爷爷做主。”县主问众千证口词，也有说打倒的，也有说推跌的。蒋兴哥辨道：“他父亲偷了小人的珠子，小人不忿，与他争论。他因年老脚锉（左足），自家跌死，不千小人之事。”县主问宋福道：“你父亲几岁了？”宋福道：“六十七岁了。”县主道：“老年人容易昏绝，未必是打。”宋福、宋寿坚执是打死的。县主道：“有伤无伤，须凭检验。既说打死，将尸发在漏泽园去，候晚堂听检。”原来宋家也是个大户，有体面的。老儿曾当过里长，儿子怎肯把父亲在尸场剔骨？两个双双即头道：“父亲死状，众目共见，只求爷爷到小人家里相验，不愿发检。”县主道：“若不见贴骨伤痕，凶身怎肯伏罪？没有尸格，如何申得上司过？”弟兄两个只是求台。县主发怒道：“你既不愿检，我也难问。”慌的地弟兄两个连连即头道：“但凭爷爷明断。”县主送：“望七之人，死是本等。倘或不因打死，屈害了一个平人，反增死者罪过。就是你做儿子的，巴得父亲到许多年纪，又把个不得善终的恶名与他，心中何忍？但打死是假，推仆是真，若不重罚罗德，也难出你的气。我如今教他披麻戴孝，与亲儿一般行礼：一应殡殓之费，都要他支持。你可服么？”弟兄两个道：“爷爷分付，小人敢不遵依。”兴哥见县主不用刑罚，断得干净，喜出望外。当下原、被台都即头称谢。县主道：“我也不写审单，着差人押出，待事完回话，把原词与你悄讫便了。”正是：","公堂造业真容易，要积阴功亦不难。试看今朝吴大尹，解冤释罪两家欢。却说三巧儿自丈夫出堂之后，如坐针毡，一闻得退衙，便迎住问个消息。县主道：“我如此如此断了，看你之面，一板也不曾责他。”三巧几千思万谢，又道：“妾与哥哥久别，渴思一会，问取爹娘消息。官人如何做个方便，使妾兄妹相见，此思不小。”县主道：“这也容易。”看官们，你道三巧儿被蒋兴哥休了，思断义绝，如何恁地用情？他夫妇原是十分恩爱的，因三巧儿做下不是，兴哥不得己而休之，心中几自不忍，所以改嫁之夜，把十六只箱笼，完完全全的赠他。只这一件，三巧儿的心肠，也不容不软了。今日他身处富贵，见兴哥落难，如何不救？这叫做知思报恩。再说蒋兴哥遵了县主所断，着实小心尽礼，更不惜费，宋家弟兄部没话了。丧葬事毕，差人押到县中回复。县主晚进私衙赐坐，说道：“尊舅这场官司，若非令妹再三哀恳，下官几乎得罪了。”兴哥不解其放，回答不出。少停茶罢，县主请入内书房，教小夫人出来相见。你道这番意外相逢，不像个梦景么？他两个也不行礼，也不讲话，紧紧的你我相抱，放声大哭。就是哭爹哭娘，从没见这般哀掺，连县主在旁，好生不忍，便道：“你两人且莫悲伤，我看你不像哥妹，快说真情，下官有处。”两个哭得半休不休的，那个肯说？却被县主盘问不过，三巧儿只得跪下，说道：“贱妾罪当万死，此人乃妾之前夫也。”蒋兴哥料瞒不得，也跪下来，将从前恩爱，及休妻再嫁之事，一一诉知。说罢，两人又哭做一团，连吴知县也堕泪不止，道：“你两人如此相恋，下官何忍拆开。幸然在此三年，不曾生育，即刻领去完聚。”两个插烛也似拜谢。县主即忙讨个小轿，送三巧儿出衙：又晚集人夫，把原来赡嫁的十六个箱笼抢去，都教兴哥收领：又差典吏一员，护送他夫妇出境。此乃吴知县之厚德。正是：","珠还合浦重生采，剑合丰城倍有神。堪羡吴公存厚道，食财好色竞何人！","此人向来艰子，后行取到吏部，在北京纳宠，连生三子，科第不绝，人都说阴德之报，这是后话。 再说蒋兴哥带了三巧儿回家，与平氏相见。论起初婚，王氏在前：只因休了一番，这平氏到是明媒正娶，又且平氏年长一岁，让平氏为正房，王氏反做偏房，两个妹妹相称。从此一夫二妇，团圆到老。有诗为证：","恩爱夫妻虽到头，妻还作妾亦堪羞。殃样果报无虚谬，腿尺青天莫远求。"],"cpLength":20901},"ysmy-16":{"chapterId":"ysmy-16","bookId":"ysmy","fileIndex":15,"number":16,"title":"第十六卷　范巨卿鸡黍死生交","paragraphs":["种树莫种垂杨枝，结交莫结轻薄儿。杨枝不耐秋风吹，轻薄易结还易离。君不见昨日书来两相忆，今日相逢不相识！不如杨杖犹可久，一度春风一回首。","这篇言语是《结交行》，言结交最难。今日说一个秀才，是汉明帝时人，姓张名劭，字元伯，是汝州南城人氏。家本农业，苦志读书；年一十五岁，不曾婚娶。其老母年近六旬，并弟张勤努力耕种，以供二膳。时汉帝求贤。劭辞老母，别兄弟，自负书囊，来到东都洛阳应举。在路非只一日。到洛阳不远，当日天晚，投店宿歇。是夜，常闻邻房有人声唤。劭至晚问店小二：“司壁声唤的是谁？“小二答道：“是一个秀才，害时症，在此将死。”劭曰：“既是斯文，当以看视之。”小二日：“瘟病过人，我们尚自不去看他：秀才，你休去！”劭曰：“死生育命，安有病能过人之理？吾须视之。”小二劝不住。劭乃推门而入，见一人仰面卧于土榻之上，面黄肌瘦，口内只：“救人！”劭见房中书囊、衣冠，都是应举的行动，遂扣头边而言曰：“君子勿忧，张劭亦是赴选之人。今见汝病至笃，吾竭力救之。药饵粥食，吾自供奉，且自宽心。”其人曰：“若君子救得我病，容当厚报。”劭随即挽人请医用药调治。早晚汤水粥食，劭自供给。","数日之后，汗出病减，渐渐将息，能起行立。劭问之，乃是楚州山阳人氏，姓范，名式，字巨卿，年四十岁。世本商贾，幼亡父母，有妻小。近弃商贾，来洛阳应举。比及范巨卿将息得无事了，误了试期。范曰：“今因式病，有误足下功名，甚不自安。”劭曰：“大丈夫以义气为重，功名富贾，乃微末耳，已有分定。何误之有？”范式自此与张劭情如骨肉，结为兄弟。式年长五岁，张劭拜范式为兄。","结义后，朝暮相随，不觉半年。范式思归，张劭与计算房钱，还了店家。二人同行。数日，到分路之处，张劭欲送范式。范式曰：“若如此，某又送回。不如就此一别，约再相会。”二人酒肆共饮，见黄花红叶，妆点秋光，以劭别离之兴。酒座司杯泛荣英，问酒家，方知是重阳佳节。范式曰：“吾幼亡父母，屈在商贾。经书虽则留心，亲为妻子所累。幸贤弟有老母在堂，汝母即吾母也。来年今日，必到贤弟家中，登堂拜母，以表通家之谊。”张劭曰：“但村落无可为款，倘蒙兄长不弃，当设鸡黍以持，幸勿失信。”范式曰：“焉肯失信于贤弟耶？”二人饮了数杯，不忍相舍。张劭拜别范式。范式去后，劭凝望堕泪；式亦回顾泪下，两各悒怏而去。有诗为证：","手采黄花泛酒后，殷勤先订隔年期。","临歧不忍轻分别，执手依依各泪垂。","且说张元伯到家，参见老母。母曰：“吾儿一去，音信不闻，令我悬望，如饥似渴。”张劭曰：“不孝男于途中遇山阳范巨卿，结为兄弟，以此逗留多时。”母曰：“巨卿何人也？”张劭备述详细。母曰：“功名事，皆分定。既逢信义之人结交，甚快我心。”少刻，弟归，亦以此事从头说知，各各欢喜。自此张劭在家，再攻书史，以度岁月。光阴迅速，渐近重阳。劭乃预先畜养肥鸡一只，杜酝浊酒。是曰早起，洒扫草堂；中设母座，旁列范巨卿位；遍插菊花于瓶中，焚信香于座上。呼弟宰鸡炊饭，以持巨卿。母曰：“山阳至此，迢递千里，恐巨卿未必应期而至。持其来，杀鸡末迟。”劭曰：“巨卿，信士也，必然今日至矣，安肯误鸡黍之约？入门便见所许之物，足见我之持久。如候巨卿来，而后宰之，不见我倦倦之意。”母曰：“吾儿之友，必是端士。”遂烹炮以持。是曰，天晴曰朗，万里无云。劭整其衣冠，独立庄门而望。看看近午，不见到来。母恐误了农桑，令张勤自去田头收割。张劭听得前村犬吠，又往望之，如此六七遭。因看红曰西沉，观出半轮新月，母出户令弟唤劭曰：“儿久立倦矣！今日莫非巨卿不来？且自晚膳。”劭谓弟曰：“汝岂知巨卿不至耶？若范兄不至，吾誓不归。汝农劳矣，可自歇息。”母弟再三劝归，劭终不许。","候至更深，各自歇息，劭倚门如醉如痴，风吹草木之声，莫是范来，皆自惊讶。看见银河耿耿，玉宇澄澄，渐至三更时分，月光都没了。隐隐见黑影中，一人随风而至。劭视之，乃巨卿也。再拜踊跃而大喜曰：“小弟自早直候至今，知兄非爽信也，兄果至矣。旧岁所约鸡黍之物，备之己久。路远风尘，别不曾有人同来？”便请至草堂，与老母相见。范式并不答话，径入草堂。张劭指座榻曰：“特设此位，专持兄来，兄当高座。”张劭笑容满面，再拜于地曰：“兄既远来，路途劳困，且未可与老母相见，杜酿鸡黍，聊且充饥。”言讫又拜。范式僵立不语，但以衫袖反掩其面。劭乃自奔入厨下，取鸡黍并酒，列于面前，再拜以进。曰：“酒看虽微，劭之心也，幸兄勿责。”但见范于影中，以手绰其气而不食。劭曰：“兄意莫不怪老母并弟不曾远接，不肯食之？容请母出与同伏罪。”范摇手止之。劭曰：“唤舍弟拜兄，若何？”范亦摇手而止之。劭曰：“兄食鸡黍后进酒，若何？”范蹙其眉，似教张退后之意。劭曰：“鸡黍不足以奉长者，乃劭当日之约，幸勿见嫌。”范曰：“弟稍退后，吾当尽情诉之。吾非阳世之人，乃阴魂也。”劭大惊曰：“兄何放出此言？”范曰：“自与兄弟相别之后，回家为妻子口腹之累，溺身商贾中，尘世滚滚，岁月匆匆，不觉又是一年。向曰鸡黍之约，非不挂心；近被蝇利所牵，忘其日期。今早邻右送荣英酒至，方知是重阳。忽记贤弟之约，此心口醉。山阳至此，千里之隔，非一日可到。若不如期，贤弟以我为何物？鸡黍之约，尚自爽信，何况大事乎？寻思无计。常闻古人有云：人不能行千里，魂能曰行干里。遂嘱咐妻子曰：‘吾死之后，且勿下葬，持吾弟张元伯至，方可入士。’嘱罢，自则而死。魂驾阴风，特来赴鸡黍之约。万望贤弟怜悯愚兄，恕其轻忽之过，鉴其凶暴之诚，不以千里之程，肯为辞亲，到山阳一见吾尸，死亦瞩目无憾矣。”言讫，泪如进泉，急离坐榻，下阶砌。劭乃趋步逐之，不觉忽踏了苍苔，颠倒于地。阴风拂面，不知巨卿所在。有诗为证：","风吹落月夜三更，千里幽魂叙旧盟。","只恨世人多负约，故将一死见乎生。张劭如梦如醉，放声大哭。那哭声，惊动母亲并弟，急起视之，见堂上陈列鸡黍酒果，张元伯昏倒于地。用水救醒，扶到堂上，半晌不能言，又哭至死。母问曰：“汝兄巨卿不来，有甚利害？何苦自哭如此！”劭曰：“巨卿以鸡黍之约，己死于非命矣。”母曰：“何以知之？”劭曰：“适司亲见巨卿到来，邀迎入坐，具鸡黍以迎。但见其不食，再三恳之。巨卿曰：为商贾用心，失忘了日期。今早方醒，恐负所约，遂自则而死。阴魂千里，特来一见。母可容儿亲到山阳葬兄之尸，儿明早收拾行李便行。”母哭曰：“古人有云：囚人梦赦，渴人梦浆。此是吾儿念念在心，故有此梦警耳。”劭曰：“非梦也，儿亲见来，酒食见在；逐之不得，忽然颠倒，岂是梦乎？巨卿乃诚信之士，岂妄报耶！”弟曰：“此末可信。如有人到山阳去，当问其虚实。”劭曰：“人禀天地而生，天地有五行，金、木、水、火、土，人则有五常，仁、义、礼、智、信以配之，惟信非同小可。仁所以配木，取其生意也。义所以配金，取其刚断也。礼所以配水，取其谦下也。智所以配火，取其明达也。信所以配土，取其重厚也。圣人云：‘大车无輗，小车无(车兀)，其何以行之哉？’又云：‘自古旨有死，民无信不立。’巨卿既己为信而死，吾安可不信而不去哉？弟专务农业，足可以奉老母。吾去之后，倍加恭敬；晨昏甘旨，勿使有失。”遂拜辞其母曰：“不孝男张劭，今为义兄范巨卿为信义而亡，须当往吊。己再三叮吟张勤，令侍养老母。母须早晚勉强饮食，勿以忧愁，自当善保尊体。劭于国不能尽忠，于家不能尽孝，徒生于天地之司耳。今当辞去，以全大信。”母曰：“吾儿去山阳，干里之遥，月余便回，何放出不利之语？”劭曰：“生如淳沤，死生之事，旦夕难保。”恸哭而拜。弟曰：“勤与兄同去，若何？”元伯曰：“母亲无人侍季，汝当尽力事母，勿令吾忧。”洒泪别弟，背一个小书囊，来早便行。有诗为证：","辞亲别弟到山阳，千里迢迢窖梦长。","岂为友朋轻骨肉？只因信义迫中肠。","沿路上饥不择食，寒不思衣。夜宿店舍，虽梦中亦哭。每曰早起赶程，恨不得身生两翼。行了数日，到了山阳。问巨卿何处住，径奔至其家门首。见门户锁着，问及邻人。邻人曰：“巨卿死己过二七，其妻扶灵枢，往郭外去下葬。送葬之人，尚自未回。”劭问了去处，奔至郭外，望见山林前新筑一所土墙，墙外有数十人，面面相觑，各有惊异之状。劭汗流如雨，走往观之。见一妇人，身披重孝。一子约有十七八岁，伏棺而哭。元伯大叫曰：“此处莫非范巨卿灵枢乎？”其妇曰：“来者莫非张元伯乎？”张曰：“张劭自来不曾到此，何以知名姓耶？”妇泣曰：“此夫主再一之遗言也。夫主范巨卿，自洛阳回，常谈贤叔盛德。前者重阳曰，夫主忽举止失措。对妻曰：‘我失却元伯之大信，徒生何益！常闻人不能行千里，吾宁死，不敢有误鸡黍之约。死后且不可葬，持元伯来见我尸，方可人士。今日己及二七，人劝云：“元伯不知何曰得来，先葬讫，后报知未晚。’因此扶枢到此。众人拽植入金井，并不能动，因此停住坟前，众都惊怪。见叔叔远来如此慌速，必然是也。”元怕乃哭倒于地。妇亦大恸，送殡之人，无不下泪。","元伯于囊中取钱，令买祭物，香烛纸帛，陈列于前。取出祭文，酹酒再拜，号泣而读。文曰： 维某年月曰，契弟张劭，谨以炙鸡絮酒，致祭于仁兄巨卿范君之灵曰：于维巨卿，气赁虹霓，义高云汉。幸倾盖于穷途，缔盍淳于荒店。黄花九日，肝瞩相盟；青剑三秋，头颅可断。堪怜月下凄凉，恍似曰司眷恋。弟今辞母，来寻碧水青松；兄亦嘱妻，仁望素车自练。故友那堪死别，谁将金石盟寒？大夫自是生轻，欲把昆吾锷按。历干百而不磨，期一言之必践。倘灵爽之忧存，料冥途之长伴。呜呼哀哉！尚飨。","元伯发棺视之，哭声恸地。回顾嫂曰：“兄为弟亡，岂能独生耶？囊中己具棺椁之费，愿嫂垂怜，不弃鄙贱，将劭葬于兄侧，乎生之大幸也。”嫂曰：“叔何放出此言也？”勋曰：“吾志己决，请勿惊疑。”言讫，掣佩刀自则而死。众皆惊愕，为之设祭，具衣棺营葬于巨卿墓中。 本州太守闻知，将此事表奏。明帝怜其信义深重，两生虽不登第，亦可褒赠，以励后人。范巨卿赠山阳伯，张元伯赠汝南伯。墓前建庙，号“信义之祠”，墓号“信义之墓。”旌表门闾。官给衣粮，以膳其子。巨卿子范纯绶，及第进士，官鸿胪寺卿。至今山阳古迹犹存，题咏极多。惟有无名氏《踏莎行》一词最好，词云：","千里途遥，隔年期远，片首相许心无变。宁将信义托游魂，堂中鸡黍空劳劝。月暗灯昏，泪痕如线，死生虽隔情何限。灵輀若候故人来，黄泉一笑重相见。"],"cpLength":4144}}};